-- Lo mínimo de Supabase para probar en un Postgres local: roles, auth.users y auth.uid() leyendo el JWT de la
-- sesión igual que PostgREST (request.jwt.claims). Solo para pruebas y desarrollo; en Supabase ya existe.
do $$ begin
  if not exists (select 1 from pg_roles where rolname = 'anon') then create role anon nologin; end if;
  if not exists (select 1 from pg_roles where rolname = 'authenticated') then create role authenticated nologin; end if;
  if not exists (select 1 from pg_roles where rolname = 'service_role') then create role service_role nologin bypassrls; end if;
end $$;

create schema if not exists auth;
create schema if not exists extensions;
create table if not exists auth.users (
  id    uuid primary key default gen_random_uuid(),
  email text unique
);

create or replace function auth.uid() returns uuid language sql stable as $$
  select nullif(nullif(current_setting('request.jwt.claims', true), '')::json->>'sub', '')::uuid
$$;
create or replace function auth.role() returns text language sql stable as $$
  select nullif(current_setting('request.jwt.claims', true), '')::json->>'role'
$$;

grant usage on schema auth, extensions to anon, authenticated, service_role;
grant execute on all functions in schema auth to anon, authenticated, service_role;

-- Storage de Supabase, solo las dos tablas que usan las políticas (en Supabase las crea la plataforma). Los archivos
-- en sí los guarda el emulador de scripts/supabase_local.py; aquí solo están sus filas, con RLS como en Supabase.
create schema if not exists storage;
create table if not exists storage.buckets (
  id                 text primary key,
  name               text not null unique,
  owner              uuid,
  public             boolean default false,
  file_size_limit    bigint,
  allowed_mime_types text[],
  created_at         timestamptz default now(),
  updated_at         timestamptz default now()
);
create table if not exists storage.objects (
  id               uuid primary key default gen_random_uuid(),
  bucket_id        text references storage.buckets (id),
  name             text,
  owner            uuid,
  owner_id         text,
  metadata         jsonb,
  created_at       timestamptz default now(),
  updated_at       timestamptz default now(),
  last_accessed_at timestamptz default now(),
  unique (bucket_id, name)
);
alter table storage.objects enable row level security;
alter table storage.buckets enable row level security;
grant usage on schema storage to anon, authenticated, service_role;
grant select, insert, update, delete on storage.objects to anon, authenticated, service_role;
grant select on storage.buckets to anon, authenticated, service_role;


alter table auth.users add column if not exists encrypted_password text;

-- =====================================================================
-- Corvex Nutrición · Fase 1: núcleo de negocio
-- Consultas (multi-clínica), miembros y roles, profesionales, horarios, ausencias, servicios, pacientes
-- (datos administrativos y sanitarios separados), citas, auditoría.
--
-- Reglas de acceso:
--  * Todas las tablas tienen RLS activado y ninguna política: desde fuera (anon / authenticated) no se leen ni se
--    escriben directamente. Todo pasa por funciones `security definer` que comprueban quién llama (auth.uid()),
--    a qué consulta pertenece y con qué rol, y dejan rastro en `auditoria`.
--  * Funciones que empiezan por `_`: internas, no se pueden llamar desde la API.
--  * Funciones `canal_*` y `motor_*`: solo service_role (n8n). El resto: usuarios con sesión (authenticated).
--  * Cada tabla lleva clinica_id y las claves foráneas son compuestas (clinica_id, id): la base de datos impide
--    enlazar una cita de una consulta con un paciente de otra.
-- =====================================================================

create schema if not exists extensions;   -- en Supabase ya existe
create extension if not exists pgcrypto with schema extensions;
create extension if not exists btree_gist with schema extensions;
create schema if not exists nutricion;
set search_path = nutricion, extensions, public;

-- ---------------------------------------------------------------- consultas y personas

create table clinicas (
  id                     uuid primary key default gen_random_uuid(),
  nombre                 text not null check (length(trim(nombre)) between 2 and 120),
  zona_horaria           text not null default 'Europe/Madrid',
  telefono               text,
  email                  text,
  direccion              text,
  web                    text,
  color                  text not null default '#2f7d5b' check (color ~ '^#[0-9a-fA-F]{6}$'),
  logo_path              text,
  -- Reglas de la agenda (se cambian desde Ajustes)
  paso_minutos           int  not null default 15 check (paso_minutos in (5, 10, 15, 20, 30, 60)),
  antelacion_minima_min  int  not null default 120 check (antelacion_minima_min between 0 and 10080),
  horas_minimas_cambio   int  not null default 24 check (horas_minimas_cambio between 0 and 336),
  max_citas_futuras      int  not null default 4 check (max_citas_futuras between 1 and 50),
  dias_reserva_max       int  not null default 120 check (dias_reserva_max between 7 and 730),
  precios_confirmados    boolean not null default false,  -- hasta que no se confirmen, la IA no da precios
  modo_envio             text not null default 'simulador' check (modo_envio in ('simulador', 'real')),
  creada_en              timestamptz not null default now()
);

create table profesionales (
  id               bigint generated always as identity primary key,
  clinica_id       uuid not null references clinicas (id) on delete cascade,
  nombre           text not null check (length(trim(nombre)) between 2 and 120),
  numero_colegiado text,
  especialidades   text[] not null default '{}',
  color            text not null default '#2f7d5b' check (color ~ '^#[0-9a-fA-F]{6}$'),
  email            text,
  telefono_avisos  text,
  enlace_online    text,              -- sala de videollamada para las consultas online
  activo           boolean not null default true,
  orden            int not null default 0,
  creado_en        timestamptz not null default now(),
  unique (clinica_id, id)
);

create table miembros (
  id             bigint generated always as identity primary key,
  clinica_id     uuid not null references clinicas (id) on delete cascade,
  user_id        uuid not null,                       -- auth.users.id
  nombre         text not null,
  email          text,
  rol            text not null check (rol in ('propietario', 'nutricionista', 'recepcion')),
  profesional_id bigint,
  activo         boolean not null default true,
  creado_en      timestamptz not null default now(),
  unique (clinica_id, user_id),
  foreign key (clinica_id, profesional_id) references profesionales (clinica_id, id)
);

create table servicios (
  id                 bigint generated always as identity primary key,
  clinica_id         uuid not null references clinicas (id) on delete cascade,
  nombre             text not null check (length(trim(nombre)) between 2 and 120),
  descripcion        text,                            -- explicación sencilla para el paciente
  tipo               text not null default 'revision'
                     check (tipo in ('primera_visita', 'revision', 'sesion_programa', 'otro')),
  especialidad       text,                            -- 'general', 'deportiva', 'clinica', 'vegetariana'...
  duracion_min       int not null default 45 check (duracion_min between 10 and 240),
  precio_centimos    int check (precio_centimos >= 0), -- null = no se informa del precio
  presencial         boolean not null default true,
  online             boolean not null default false,
  reservable_canales boolean not null default true,    -- la IA puede reservarlo por WhatsApp o teléfono
  activo             boolean not null default true,
  orden              int not null default 0,
  unique (clinica_id, id),
  unique (clinica_id, nombre),
  check (presencial or online)
);

create table profesional_servicios (
  clinica_id     uuid not null,
  profesional_id bigint not null,
  servicio_id    bigint not null,
  primary key (profesional_id, servicio_id),
  foreign key (clinica_id, profesional_id) references profesionales (clinica_id, id) on delete cascade,
  foreign key (clinica_id, servicio_id) references servicios (clinica_id, id) on delete cascade
);

-- Horario semanal: una fila por tramo (mañana y tarde son dos filas). La modalidad permite, por ejemplo,
-- dedicar los viernes por la tarde solo a consultas online.
create table horarios (
  id             bigint generated always as identity primary key,
  clinica_id     uuid not null,
  profesional_id bigint not null,
  dia_semana     int  not null check (dia_semana between 1 and 7),    -- 1 = lunes … 7 = domingo
  hora_inicio    time not null,
  hora_fin       time not null,
  modalidad      text not null default 'ambas' check (modalidad in ('ambas', 'presencial', 'online')),
  check (hora_fin > hora_inicio),
  foreign key (clinica_id, profesional_id) references profesionales (clinica_id, id) on delete cascade
);
create index horarios_prof on horarios (profesional_id, dia_semana);

-- Vacaciones, formaciones, festivos, "bloquea mi agenda el viernes por la tarde". profesional_id null = toda la consulta.
create table ausencias (
  id             bigint generated always as identity primary key,
  clinica_id     uuid not null references clinicas (id) on delete cascade,
  profesional_id bigint,
  inicio         timestamptz not null,
  fin            timestamptz not null,
  motivo         text,
  creada_por     uuid,
  creada_en      timestamptz not null default now(),
  check (fin > inicio),
  foreign key (clinica_id, profesional_id) references profesionales (clinica_id, id) on delete cascade
);
create index ausencias_rango on ausencias using gist (clinica_id, tstzrange(inicio, fin));

-- ---------------------------------------------------------------- pacientes

-- Datos administrativos: los ve todo el equipo (también recepción). El teléfono no es único: en una familia
-- varias personas pueden usar el mismo móvil; por eso los canales piden una segunda comprobación.
create table pacientes (
  id                     bigint generated always as identity primary key,
  clinica_id             uuid not null references clinicas (id) on delete cascade,
  nombre                 text not null check (length(trim(nombre)) between 1 and 80),
  apellidos              text,
  telefono               text,                        -- E.164 (+34600111222)
  email                  text,
  fecha_nacimiento       date,
  profesional_id         bigint,                      -- profesional asignado
  modalidad_preferida    text check (modalidad_preferida in ('presencial', 'online')),
  canal_preferido        text not null default 'whatsapp' check (canal_preferido in ('whatsapp', 'telefono', 'email')),
  acepta_comerciales     boolean not null default false,   -- separado de cualquier documentación asistencial
  comerciales_cambiado_en timestamptz,
  estado                 text not null default 'activo' check (estado in ('activo', 'inactivo', 'finalizado')),
  notas_admin            text,
  origen                 text not null default 'app' check (origen in ('app', 'whatsapp', 'telefono', 'portal')),
  creado_en              timestamptz not null default now(),
  creado_por             uuid,
  unique (clinica_id, id),
  check (telefono is not null or email is not null),
  foreign key (clinica_id, profesional_id) references profesionales (clinica_id, id) on delete set null (profesional_id)
);
create index pacientes_telefono on pacientes (clinica_id, telefono);
create index pacientes_nombre on pacientes (clinica_id, lower(nombre || ' ' || coalesce(apellidos, '')));

-- Datos sanitarios: solo propietario y nutricionistas. Tabla aparte para que nunca viajen con los administrativos.
create table pacientes_salud (
  paciente_id          bigint primary key,
  clinica_id           uuid not null,
  motivo_consulta      text,
  objetivos            text,
  antecedentes         text,
  alergias             text,
  intolerancias        text,
  medicacion           text,
  suplementos          text,
  habitos_alimentarios text,
  actividad_fisica     text,
  informacion_clinica  text,
  campos_extra         jsonb not null default '{}'::jsonb,   -- campos que configure cada profesional
  actualizado_en       timestamptz not null default now(),
  actualizado_por      uuid,
  foreign key (clinica_id, paciente_id) references pacientes (clinica_id, id) on delete cascade
);

-- ---------------------------------------------------------------- citas

create table citas (
  id                   bigint generated always as identity primary key,
  clinica_id           uuid not null references clinicas (id) on delete cascade,
  paciente_id          bigint not null,
  profesional_id       bigint not null,
  servicio_id          bigint not null,
  inicio               timestamptz not null,
  fin                  timestamptz not null,
  modalidad            text not null default 'presencial' check (modalidad in ('presencial', 'online')),
  estado               text not null default 'reservada'
                       check (estado in ('reservada', 'realizada', 'cancelada', 'no_asistida')),
  origen               text not null default 'app' check (origen in ('app', 'whatsapp', 'telefono', 'portal')),
  confirmada_en        timestamptz,                  -- el paciente ha confirmado que viene
  precio_centimos      int check (precio_centimos >= 0),
  motivo               text,                         -- motivo administrativo ("primera consulta", "revisión")
  notas                text,
  excepcion            text,                         -- si el equipo la puso saltándose una regla: cuál y por qué
  clave_idempotencia   text,                         -- reintentos de un canal: la misma clave no crea otra cita
  cancelada_en         timestamptz,
  cancelada_por        text check (cancelada_por in ('paciente', 'clinica')),
  motivo_cancelacion   text,
  creada_por           uuid,
  creada_en            timestamptz not null default now(),
  actualizada_en       timestamptz not null default now(),
  check (fin > inicio),
  unique (clinica_id, id),
  unique (clinica_id, clave_idempotencia),
  foreign key (clinica_id, paciente_id) references pacientes (clinica_id, id),
  foreign key (clinica_id, profesional_id) references profesionales (clinica_id, id),
  foreign key (clinica_id, servicio_id) references servicios (clinica_id, id),
  -- La propia base de datos impide dos citas del mismo profesional (o del mismo paciente) a la vez, aunque
  -- lleguen en el mismo segundo por WhatsApp, por teléfono y desde la agenda.
  constraint citas_sin_solape_profesional exclude using gist
    (profesional_id with =, tstzrange(inicio, fin) with &&) where (estado in ('reservada', 'realizada')),
  constraint citas_sin_solape_paciente exclude using gist
    (paciente_id with =, tstzrange(inicio, fin) with &&) where (estado in ('reservada', 'realizada'))
);
create index citas_clinica_inicio on citas (clinica_id, inicio);
create index citas_paciente on citas (paciente_id, inicio);

-- ---------------------------------------------------------------- auditoría

-- Quién hizo o miró qué. `detalle` lleva nombres de campos o estados, nunca contenido clínico.
create table auditoria (
  id           bigint generated always as identity primary key,
  clinica_id   uuid not null references clinicas (id) on delete cascade,
  cuando       timestamptz not null default now(),
  actor_tipo   text not null,          -- 'usuario', 'whatsapp', 'telefono', 'sistema', 'portal'
  actor_id     uuid,
  actor_nombre text,
  accion       text not null,
  entidad      text,
  entidad_id   text,
  paciente_id  bigint,
  detalle      jsonb not null default '{}'::jsonb
);
create index auditoria_clinica on auditoria (clinica_id, cuando desc);
create index auditoria_paciente on auditoria (clinica_id, paciente_id, cuando desc) where paciente_id is not null;

alter table clinicas              enable row level security;
alter table profesionales         enable row level security;
alter table miembros              enable row level security;
alter table servicios             enable row level security;
alter table profesional_servicios enable row level security;
alter table horarios              enable row level security;
alter table ausencias             enable row level security;
alter table pacientes             enable row level security;
alter table pacientes_salud       enable row level security;
alter table citas                 enable row level security;
alter table auditoria             enable row level security;

-- =====================================================================
-- Funciones internas
-- =====================================================================

-- Miembro que llama, comprobando consulta y rol. Lanza 42501 si no tiene permiso.
create function _miembro(p_clinica uuid, p_roles text[] default null) returns miembros
language plpgsql stable security definer set search_path = nutricion, extensions, pg_temp as $$
declare m miembros;
begin
  select * into m from miembros
  where clinica_id = p_clinica and user_id = auth.uid() and activo;
  if m.id is null then
    raise exception 'sin_acceso' using errcode = '42501';
  end if;
  if p_roles is not null and not (m.rol = any (p_roles)) then
    raise exception 'sin_permiso' using errcode = '42501', detail = 'rol ' || m.rol;
  end if;
  return m;
end;
$$;

create function _puede_salud(p_rol text) returns boolean language sql immutable as $$
  select p_rol in ('propietario', 'nutricionista')
$$;

-- Registra una acción. Quien actúa sale de la sesión (usuario), o de `nutricion.actor` si lo fija un canal o el motor.
create function _auditar(p_clinica uuid, p_accion text, p_entidad text default null, p_entidad_id text default null,
                         p_paciente bigint default null, p_detalle jsonb default '{}'::jsonb) returns void
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare
  v_tipo text := nullif(current_setting('nutricion.actor', true), '');
  v_nombre text;
begin
  if v_tipo is null then
    if auth.uid() is not null then
      v_tipo := 'usuario';
      select nombre into v_nombre from miembros where clinica_id = p_clinica and user_id = auth.uid();
    else
      v_tipo := 'sistema';
    end if;
  end if;
  insert into auditoria (clinica_id, actor_tipo, actor_id, actor_nombre, accion, entidad, entidad_id, paciente_id, detalle)
  values (p_clinica, v_tipo, auth.uid(), v_nombre, p_accion, p_entidad, p_entidad_id, p_paciente, coalesce(p_detalle, '{}'));
end;
$$;

create function _tz(p_clinica uuid) returns text language sql stable security definer
set search_path = nutricion, extensions, pg_temp as $$
  select coalesce((select zona_horaria from clinicas where id = p_clinica), 'Europe/Madrid')
$$;

-- "2026-10-26T13:00" en la hora de la consulta.
create function _local(p timestamptz, p_tz text) returns text language sql stable as $$
  select to_char(p at time zone p_tz, 'YYYY-MM-DD"T"HH24:MI')
$$;

-- Hora local de la consulta ("2026-10-26T13:00" o "2026-10-26 13:00") a timestamptz. Si ya trae zona, se respeta.
create function _desde_local(p text, p_tz text) returns timestamptz language plpgsql stable as $$
begin
  if p is null or trim(p) = '' then return null; end if;
  if p ~ '([zZ]|[+-]\d\d(:?\d\d)?)$' then return p::timestamptz; end if;
  return (replace(trim(p), 'T', ' ')::timestamp) at time zone p_tz;
end;
$$;

create function _hoy(p_tz text) returns date language sql stable as $$
  select (now() at time zone p_tz)::date
$$;

-- "lunes 26 de octubre a las 13:00", para que la IA no tenga que calcular fechas.
create function fecha_es(p timestamptz, p_tz text default 'Europe/Madrid') returns text language sql stable as $$
  select (array['lunes','martes','miércoles','jueves','viernes','sábado','domingo'])[extract(isodow from p at time zone p_tz)::int]
      || ' ' || extract(day from p at time zone p_tz)::int || ' de '
      || (array['enero','febrero','marzo','abril','mayo','junio','julio','agosto','septiembre','octubre','noviembre',
                'diciembre'])[extract(month from p at time zone p_tz)::int]
      || ' a las ' || to_char(p at time zone p_tz, 'HH24:MI')
$$;

-- Teléfono en formato internacional. Acepta "600 11 22 33", "0034600112233", "+34 600-112-233"...
create function normalizar_telefono(p text) returns text language plpgsql immutable as $$
declare d text := regexp_replace(coalesce(p, ''), '[^0-9+]', '', 'g');
begin
  if d = '' then return null; end if;
  if d like '00%' then d := '+' || substr(d, 3); end if;
  if d !~ '^\+' then
    if length(d) = 9 and d ~ '^[6789]' then d := '+34' || d; else d := '+' || d; end if;
  end if;
  if d !~ '^\+[1-9][0-9]{7,14}$' then return null; end if;
  return d;
end;
$$;

-- ¿Puede este profesional atender en ese tramo? Dentro de su horario (con la modalidad adecuada), sin ausencias y
-- sin otra cita. No mira antelación ni límites: eso lo deciden quien reserva (canal o equipo).
create function _libre(p_prof bigint, p_inicio timestamptz, p_fin timestamptz, p_modalidad text,
                       p_excluir_cita bigint default null) returns boolean
language sql stable security definer set search_path = nutricion, extensions, pg_temp as $$
  with p as (
    select pr.id, pr.clinica_id, c.zona_horaria as tz from profesionales pr join clinicas c on c.id = pr.clinica_id
    where pr.id = p_prof and pr.activo
  )
  select exists (select 1 from p)
     -- empieza y acaba el mismo día local, dentro de un tramo del horario
     and exists (
       select 1 from p join horarios h on h.profesional_id = p.id
       where h.dia_semana = extract(isodow from p_inicio at time zone p.tz)
         and (p_inicio at time zone p.tz)::date = (p_fin at time zone p.tz - interval '1 microsecond')::date
         and (p_inicio at time zone p.tz)::time >= h.hora_inicio
         and ((p_fin at time zone p.tz) - (p_inicio at time zone p.tz)::date) <= h.hora_fin::interval
         and (h.modalidad = 'ambas' or h.modalidad = p_modalidad))
     and not exists (
       select 1 from p join ausencias a on a.clinica_id = p.clinica_id
       where (a.profesional_id is null or a.profesional_id = p.id)
         and tstzrange(a.inicio, a.fin) && tstzrange(p_inicio, p_fin))
     and not exists (
       select 1 from citas c
       where c.profesional_id = p_prof and c.estado in ('reservada', 'realizada')
         and (p_excluir_cita is null or c.id <> p_excluir_cita)
         and tstzrange(c.inicio, c.fin) && tstzrange(p_inicio, p_fin))
$$;

-- Huecos libres para un servicio entre dos momentos. Si no se indica profesional, cada hora sale una vez con el
-- profesional preferido (el asignado al paciente, después el que menos citas tiene ese día).
create function _huecos(p_clinica uuid, p_servicio bigint, p_profesional bigint, p_desde timestamptz, p_hasta timestamptz,
                        p_modalidad text, p_preferido bigint default null, p_max int default 12, p_por_dia int default 4,
                        p_respetar_antelacion boolean default true)
returns table (inicio timestamptz, fin timestamptz, profesional_id bigint, profesional text)
language plpgsql stable security definer set search_path = nutricion, extensions, pg_temp as $$
declare
  c   clinicas;
  v_dur int;
  v_desde timestamptz;
begin
  select * into c from clinicas where id = p_clinica;
  select s.duracion_min into v_dur from servicios s where s.id = p_servicio and s.clinica_id = p_clinica and s.activo;
  if v_dur is null or c.id is null then return; end if;
  v_desde := case when p_respetar_antelacion
                  then greatest(p_desde, now() + make_interval(mins => c.antelacion_minima_min))
                  else greatest(p_desde, now()) end;
  if p_hasta <= v_desde then return; end if;

  return query
  with dias as (
    select d::date as dia
    from generate_series((v_desde at time zone c.zona_horaria)::date, (p_hasta at time zone c.zona_horaria)::date,
                         interval '1 day') d
  ), candidatos as (
    select pr.id as prof, pr.nombre, pr.orden, dd.dia,
           ((dd.dia + h.hora_inicio) at time zone c.zona_horaria) + make_interval(mins => c.paso_minutos * n) as ini
    from profesionales pr
    join profesional_servicios ps on ps.profesional_id = pr.id and ps.servicio_id = p_servicio
    join horarios h on h.profesional_id = pr.id and (h.modalidad = 'ambas' or h.modalidad = p_modalidad)
    join dias dd on extract(isodow from dd.dia) = h.dia_semana
    cross join lateral generate_series(
      0, floor((extract(epoch from (h.hora_fin - h.hora_inicio)) / 60 - v_dur) / c.paso_minutos)::int) n
    where pr.clinica_id = p_clinica and pr.activo and (p_profesional is null or pr.id = p_profesional)
  ), libres as (
    select k.* from candidatos k
    where k.ini >= v_desde and k.ini < p_hasta
      and _libre(k.prof, k.ini, k.ini + make_interval(mins => v_dur), p_modalidad)
  ), elegidos as (
    select distinct on (l.ini) l.ini, l.dia, l.prof, l.nombre
    from libres l
    order by l.ini, (l.prof = p_preferido) desc nulls last,
             (select count(*) from citas x where x.profesional_id = l.prof and x.estado = 'reservada'
                and (x.inicio at time zone c.zona_horaria)::date = l.dia),
             l.orden, l.prof
  ), repartidos as (
    select e.*, row_number() over (partition by e.dia order by e.ini) as n_dia from elegidos e
  )
  select r.ini, r.ini + make_interval(mins => v_dur), r.prof, r.nombre
  from repartidos r where r.n_dia <= greatest(p_por_dia, 1)
  order by r.ini limit greatest(least(p_max, 200), 1);
end;
$$;

create function _cita_json(p_cita bigint) returns jsonb
language sql stable security definer set search_path = nutricion, extensions, pg_temp as $$
  select jsonb_build_object(
    'id', ci.id, 'inicio', _local(ci.inicio, cl.zona_horaria), 'fin', _local(ci.fin, cl.zona_horaria),
    'fecha_texto', fecha_es(ci.inicio, cl.zona_horaria),
    'estado', ci.estado, 'modalidad', ci.modalidad, 'origen', ci.origen,
    'confirmada', ci.confirmada_en is not null,
    'paciente_id', ci.paciente_id, 'paciente', trim(pa.nombre || ' ' || coalesce(pa.apellidos, '')),
    'telefono', pa.telefono,
    'profesional_id', ci.profesional_id, 'profesional', pr.nombre,
    'servicio_id', ci.servicio_id, 'servicio', se.nombre, 'tipo', se.tipo,
    'precio', round(ci.precio_centimos / 100.0, 2),
    'motivo', ci.motivo, 'notas', ci.notas, 'excepcion', ci.excepcion,
    'enlace_online', case when ci.modalidad = 'online' then pr.enlace_online end)
  from citas ci
  join clinicas cl on cl.id = ci.clinica_id
  join pacientes pa on pa.id = ci.paciente_id
  join profesionales pr on pr.id = ci.profesional_id
  join servicios se on se.id = ci.servicio_id
  where ci.id = p_cita
$$;

-- Reserva común a la agenda y a los canales. Devuelve {ok, cita} o {ok:false, motivo}.
-- p_forzar (solo el equipo): permite saltarse horario, ausencias, antelación y límites, nunca un solape; queda
-- apuntado en `excepcion` con el motivo.
create function _reservar(p_clinica uuid, p_paciente bigint, p_servicio bigint, p_profesional bigint, p_inicio timestamptz,
                          p_modalidad text, p_origen text, p_clave text default null, p_forzar boolean default false,
                          p_motivo_excepcion text default null, p_notas text default null, p_motivo text default null)
returns jsonb language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare
  c        clinicas;
  s        servicios;
  pa       pacientes;
  v_mod    text;
  v_fin    timestamptz;
  v_prof   bigint;
  v_id     bigint;
  v_avisos text[] := '{}';
  v_restr  text;
begin
  select * into c from clinicas where id = p_clinica;
  if p_clave is not null then
    select id into v_id from citas where clinica_id = p_clinica and clave_idempotencia = p_clave;
    if v_id is not null then
      return jsonb_build_object('ok', true, 'repetida', true, 'cita', _cita_json(v_id));
    end if;
  end if;

  select * into s from servicios where id = p_servicio and clinica_id = p_clinica;
  if s.id is null or not s.activo then return jsonb_build_object('ok', false, 'motivo', 'servicio_no_existe'); end if;
  select * into pa from pacientes where id = p_paciente and clinica_id = p_clinica;
  if pa.id is null then return jsonb_build_object('ok', false, 'motivo', 'paciente_no_existe'); end if;

  v_mod := coalesce(p_modalidad, pa.modalidad_preferida, case when s.presencial then 'presencial' else 'online' end);
  if v_mod not in ('presencial', 'online') or (v_mod = 'presencial' and not s.presencial) or (v_mod = 'online' and not s.online) then
    return jsonb_build_object('ok', false, 'motivo', 'modalidad_no_disponible');
  end if;
  if p_inicio is null then return jsonb_build_object('ok', false, 'motivo', 'falta_hora'); end if;
  v_fin := p_inicio + make_interval(mins => s.duracion_min);

  -- La antelación mínima es para los canales (WhatsApp, teléfono, portal); el equipo puede dar cita para dentro de
  -- un rato. En el pasado solo como excepción (registrar a posteriori, como mucho 30 días atrás).
  if p_inicio < now() + make_interval(mins => case when p_origen = 'app' then 0 else c.antelacion_minima_min end) then
    if not p_forzar or p_inicio < now() - interval '30 days' then
      return jsonb_build_object('ok', false, 'motivo', 'hora_demasiado_pronto',
                                'antelacion_minima_min', c.antelacion_minima_min);
    end if;
    v_avisos := array_append(v_avisos, case when p_origen = 'app' then 'la hora ya ha pasado' else 'menos antelación de la habitual' end);
  end if;
  if p_inicio > now() + make_interval(days => c.dias_reserva_max) and not p_forzar then
    return jsonb_build_object('ok', false, 'motivo', 'demasiado_lejos', 'dias_reserva_max', c.dias_reserva_max);
  end if;
  if not p_forzar and (select count(*) from citas where paciente_id = p_paciente and estado = 'reservada'
                         and inicio > now()) >= c.max_citas_futuras then
    return jsonb_build_object('ok', false, 'motivo', 'demasiadas_citas', 'maximo', c.max_citas_futuras);
  end if;
  if exists (select 1 from citas where paciente_id = p_paciente and estado in ('reservada', 'realizada')
             and tstzrange(inicio, fin) && tstzrange(p_inicio, v_fin)) then
    return jsonb_build_object('ok', false, 'motivo', 'paciente_ya_tiene_cita_a_esa_hora');
  end if;

  if p_profesional is not null then
    if not exists (select 1 from profesionales where id = p_profesional and clinica_id = p_clinica and activo) then
      return jsonb_build_object('ok', false, 'motivo', 'profesional_no_existe');
    end if;
    if not exists (select 1 from profesional_servicios where profesional_id = p_profesional and servicio_id = p_servicio) then
      if not p_forzar then return jsonb_build_object('ok', false, 'motivo', 'profesional_no_hace_servicio'); end if;
      v_avisos := array_append(v_avisos, 'el profesional no tiene asignado este servicio');
    end if;
    if not _libre(p_profesional, p_inicio, v_fin, v_mod) then
      if not p_forzar then return jsonb_build_object('ok', false, 'motivo', 'hueco_no_disponible'); end if;
      if exists (select 1 from citas where profesional_id = p_profesional and estado in ('reservada', 'realizada')
                 and tstzrange(inicio, fin) && tstzrange(p_inicio, v_fin)) then
        return jsonb_build_object('ok', false, 'motivo', 'hueco_no_disponible');
      end if;
      v_avisos := array_append(v_avisos, 'fuera del horario o en una ausencia');
    end if;
    v_prof := p_profesional;
  else
    select pr.id into v_prof from profesionales pr
    join profesional_servicios ps on ps.profesional_id = pr.id and ps.servicio_id = p_servicio
    where pr.clinica_id = p_clinica and pr.activo and _libre(pr.id, p_inicio, v_fin, v_mod)
    order by (pr.id = pa.profesional_id) desc nulls last,
             (select count(*) from citas x where x.profesional_id = pr.id and x.estado = 'reservada'
                and (x.inicio at time zone c.zona_horaria)::date = (p_inicio at time zone c.zona_horaria)::date),
             pr.orden, pr.id
    limit 1;
    if v_prof is null then return jsonb_build_object('ok', false, 'motivo', 'hueco_no_disponible'); end if;
  end if;

  if array_length(v_avisos, 1) > 0 and nullif(trim(coalesce(p_motivo_excepcion, '')), '') is null then
    return jsonb_build_object('ok', false, 'motivo', 'falta_motivo_excepcion', 'avisos', to_jsonb(v_avisos));
  end if;

  begin
    insert into citas (clinica_id, paciente_id, profesional_id, servicio_id, inicio, fin, modalidad, origen,
                       precio_centimos, motivo, notas, excepcion, clave_idempotencia, creada_por)
    values (p_clinica, p_paciente, v_prof, p_servicio, p_inicio, v_fin, v_mod, p_origen, s.precio_centimos,
            left(nullif(trim(coalesce(p_motivo, '')), ''), 300), left(nullif(trim(coalesce(p_notas, '')), ''), 2000),
            case when array_length(v_avisos, 1) > 0
                 then array_to_string(v_avisos, '; ') || ' — ' || left(trim(p_motivo_excepcion), 300) end,
            p_clave, auth.uid())
    returning id into v_id;
  exception
    when exclusion_violation then
      get stacked diagnostics v_restr = constraint_name;
      return jsonb_build_object('ok', false, 'motivo',
        case when v_restr = 'citas_sin_solape_paciente' then 'paciente_ya_tiene_cita_a_esa_hora' else 'hueco_no_disponible' end);
    when unique_violation then
      -- El mismo reintento llegó dos veces a la vez: devolvemos la cita que se quedó.
      select id into v_id from citas where clinica_id = p_clinica and clave_idempotencia = p_clave;
      if v_id is null then raise; end if;
      return jsonb_build_object('ok', true, 'repetida', true, 'cita', _cita_json(v_id));
  end;

  update pacientes set profesional_id = v_prof where id = p_paciente and profesional_id is null;
  perform _auditar(p_clinica, 'reservar_cita', 'cita', v_id::text, p_paciente,
                   jsonb_build_object('origen', p_origen, 'excepcion', array_length(v_avisos, 1) > 0));
  return jsonb_build_object('ok', true, 'cita', _cita_json(v_id), 'avisos', to_jsonb(v_avisos));
end;
$$;

-- Cambio de hora (y opcionalmente de profesional o modalidad) de una cita reservada.
create function _cambiar(p_clinica uuid, p_cita bigint, p_inicio timestamptz, p_profesional bigint, p_modalidad text,
                         p_forzar boolean default false, p_motivo_excepcion text default null, p_canal boolean default false)
returns jsonb language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare
  c     clinicas;
  ci    citas;
  s     servicios;
  v_fin timestamptz;
  v_prof bigint;
  v_mod text;
  v_antes timestamptz;
  v_restr text;
  v_excepcion text;
begin
  select * into c from clinicas where id = p_clinica;
  select * into ci from citas where id = p_cita and clinica_id = p_clinica for update;
  if ci.id is null then return jsonb_build_object('ok', false, 'motivo', 'cita_no_existe'); end if;
  if ci.estado <> 'reservada' then return jsonb_build_object('ok', false, 'motivo', 'cita_no_modificable', 'estado', ci.estado); end if;
  select * into s from servicios where id = ci.servicio_id;
  v_mod := coalesce(p_modalidad, ci.modalidad);
  if (v_mod = 'presencial' and not s.presencial) or (v_mod = 'online' and not s.online) then
    return jsonb_build_object('ok', false, 'motivo', 'modalidad_no_disponible');
  end if;
  v_fin := p_inicio + make_interval(mins => s.duracion_min);
  if p_inicio is null then return jsonb_build_object('ok', false, 'motivo', 'falta_hora'); end if;
  if p_inicio < now() + make_interval(mins => case when p_canal then c.antelacion_minima_min else 0 end) and not p_forzar then
    return jsonb_build_object('ok', false, 'motivo', 'hora_demasiado_pronto');
  end if;
  if exists (select 1 from citas where paciente_id = ci.paciente_id and id <> ci.id and estado in ('reservada', 'realizada')
             and tstzrange(inicio, fin) && tstzrange(p_inicio, v_fin)) then
    return jsonb_build_object('ok', false, 'motivo', 'paciente_ya_tiene_cita_a_esa_hora');
  end if;

  if p_profesional is not null then
    v_prof := p_profesional;
    if not _libre(v_prof, p_inicio, v_fin, v_mod, ci.id) then
      if not p_forzar then return jsonb_build_object('ok', false, 'motivo', 'hueco_no_disponible'); end if;
      if nullif(trim(coalesce(p_motivo_excepcion, '')), '') is null then
        return jsonb_build_object('ok', false, 'motivo', 'falta_motivo_excepcion');
      end if;
      v_excepcion := 'fuera del horario o en una ausencia — ' || left(trim(p_motivo_excepcion), 300);
    end if;
  else
    -- Primero el mismo profesional; si no puede, otro que haga el servicio.
    select pr.id into v_prof from profesionales pr
    join profesional_servicios ps on ps.profesional_id = pr.id and ps.servicio_id = ci.servicio_id
    where pr.clinica_id = p_clinica and pr.activo and _libre(pr.id, p_inicio, v_fin, v_mod, ci.id)
    order by (pr.id = ci.profesional_id) desc, pr.orden, pr.id limit 1;
    if v_prof is null then return jsonb_build_object('ok', false, 'motivo', 'hueco_no_disponible'); end if;
  end if;

  v_antes := ci.inicio;
  begin
    update citas set inicio = p_inicio, fin = v_fin, profesional_id = v_prof, modalidad = v_mod,
                     confirmada_en = null, actualizada_en = now(),
                     excepcion = coalesce(v_excepcion, excepcion)
    where id = ci.id;
  exception when exclusion_violation then
    get stacked diagnostics v_restr = constraint_name;
    return jsonb_build_object('ok', false, 'motivo',
      case when v_restr = 'citas_sin_solape_paciente' then 'paciente_ya_tiene_cita_a_esa_hora' else 'hueco_no_disponible' end);
  end;
  perform _auditar(p_clinica, 'cambiar_cita', 'cita', ci.id::text, ci.paciente_id,
                   jsonb_build_object('antes', _local(v_antes, c.zona_horaria), 'despues', _local(p_inicio, c.zona_horaria)));
  return jsonb_build_object('ok', true, 'cita', _cita_json(ci.id));
end;
$$;

create function _cancelar(p_clinica uuid, p_cita bigint, p_por text, p_motivo text)
returns jsonb language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare ci citas;
begin
  select * into ci from citas where id = p_cita and clinica_id = p_clinica for update;
  if ci.id is null then return jsonb_build_object('ok', false, 'motivo', 'cita_no_existe'); end if;
  if ci.estado <> 'reservada' then return jsonb_build_object('ok', false, 'motivo', 'cita_no_modificable', 'estado', ci.estado); end if;
  update citas set estado = 'cancelada', cancelada_en = now(), cancelada_por = p_por,
                   motivo_cancelacion = left(nullif(trim(coalesce(p_motivo, '')), ''), 300), actualizada_en = now()
  where id = ci.id;
  perform _auditar(p_clinica, 'cancelar_cita', 'cita', ci.id::text, ci.paciente_id, jsonb_build_object('por', p_por));
  return jsonb_build_object('ok', true, 'cita', _cita_json(ci.id));
end;
$$;

-- Minutos de trabajo de un profesional un día (horario menos ausencias), para la ocupación.
create function _minutos_disponibles(p_prof bigint, p_dia date, p_desde timestamptz default null) returns int
language sql stable security definer set search_path = nutricion, extensions, pg_temp as $$
  -- Tramos del horario como multirango, menos todas las ausencias (aunque se solapen entre sí).
  with p as (select pr.id, pr.clinica_id, c.zona_horaria tz from profesionales pr join clinicas c on c.id = pr.clinica_id
             where pr.id = p_prof),
  trabajo as (
    select range_agg(tstzrange((p_dia + h.hora_inicio) at time zone p.tz, (p_dia + h.hora_fin) at time zone p.tz)) m
    from p join horarios h on h.profesional_id = p.id where h.dia_semana = extract(isodow from p_dia)
  ),
  fuera as (
    select range_agg(tstzrange(a.inicio, a.fin)) m
    from p join ausencias a on a.clinica_id = p.clinica_id and (a.profesional_id is null or a.profesional_id = p.id)
    where tstzrange(a.inicio, a.fin) && tstzrange(p_dia::timestamp at time zone p.tz, (p_dia + 1)::timestamp at time zone p.tz)
  )
  select coalesce(sum(extract(epoch from (upper(r) - lower(r))) / 60), 0)::int
  from trabajo, fuera, unnest((coalesce(trabajo.m, '{}'::tstzmultirange) - coalesce(fuera.m, '{}'::tstzmultirange))
                              * tstzmultirange(tstzrange(p_desde, null))) r
$$;

-- =====================================================================
-- API de la aplicación (usuarios con sesión)
-- =====================================================================

-- Alta de una consulta: quien la crea queda como propietario.
create function crear_clinica(p_nombre text, p_nombre_usuario text default null) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare v_id uuid; v_email text;
begin
  if auth.uid() is null then raise exception 'sin_sesion' using errcode = '42501'; end if;
  select email into v_email from auth.users where id = auth.uid();
  insert into clinicas (nombre) values (trim(p_nombre)) returning id into v_id;
  insert into miembros (clinica_id, user_id, nombre, email, rol)
  values (v_id, auth.uid(), coalesce(nullif(trim(p_nombre_usuario), ''), split_part(coalesce(v_email, 'Propietario'), '@', 1)),
          v_email, 'propietario');
  perform _auditar(v_id, 'crear_clinica', 'clinica', v_id::text);
  return jsonb_build_object('ok', true, 'clinica_id', v_id);
end;
$$;

create function mis_clinicas() returns jsonb
language sql stable security definer set search_path = nutricion, extensions, pg_temp as $$
  select coalesce(jsonb_agg(jsonb_build_object('id', c.id, 'nombre', c.nombre, 'rol', m.rol, 'color', c.color,
                                               'profesional_id', m.profesional_id, 'yo', m.nombre)
                            order by c.nombre), '[]'::jsonb)
  from miembros m join clinicas c on c.id = m.clinica_id
  where m.user_id = auth.uid() and m.activo
$$;

-- Todo lo que la aplicación necesita para arrancar: consulta, reglas, mi rol, profesionales, servicios, horarios.
create function configuracion(p_clinica uuid) returns jsonb
language plpgsql stable security definer set search_path = nutricion, extensions, pg_temp as $$
declare m miembros; c clinicas;
begin
  m := _miembro(p_clinica);
  select * into c from clinicas where id = p_clinica;
  return jsonb_build_object('ok', true,
    'clinica', to_jsonb(c),
    'yo', jsonb_build_object('nombre', m.nombre, 'rol', m.rol, 'profesional_id', m.profesional_id,
                             've_salud', _puede_salud(m.rol)),
    'profesionales', (select coalesce(jsonb_agg(jsonb_build_object(
        'id', p.id, 'nombre', p.nombre, 'numero_colegiado', p.numero_colegiado, 'especialidades', p.especialidades,
        'color', p.color, 'email', p.email, 'telefono_avisos', p.telefono_avisos, 'enlace_online', p.enlace_online,
        'activo', p.activo, 'orden', p.orden,
        'servicios', (select coalesce(jsonb_agg(ps.servicio_id), '[]'::jsonb) from profesional_servicios ps where ps.profesional_id = p.id),
        'horario', (select coalesce(jsonb_agg(jsonb_build_object('dia_semana', h.dia_semana,
                       'desde', to_char(h.hora_inicio, 'HH24:MI'), 'hasta', to_char(h.hora_fin, 'HH24:MI'),
                       'modalidad', h.modalidad) order by h.dia_semana, h.hora_inicio), '[]'::jsonb)
                    from horarios h where h.profesional_id = p.id))
      order by p.orden, p.id), '[]'::jsonb) from profesionales p where p.clinica_id = p_clinica),
    'servicios', (select coalesce(jsonb_agg(jsonb_build_object(
        'id', s.id, 'nombre', s.nombre, 'descripcion', s.descripcion, 'tipo', s.tipo, 'especialidad', s.especialidad,
        'duracion_min', s.duracion_min, 'precio', round(s.precio_centimos / 100.0, 2), 'presencial', s.presencial,
        'online', s.online, 'reservable_canales', s.reservable_canales, 'activo', s.activo, 'orden', s.orden)
      order by s.orden, s.id), '[]'::jsonb) from servicios s where s.clinica_id = p_clinica),
    'miembros', case when m.rol = 'propietario' then (select coalesce(jsonb_agg(jsonb_build_object(
        'id', x.id, 'nombre', x.nombre, 'email', x.email, 'rol', x.rol, 'profesional_id', x.profesional_id, 'activo', x.activo)
      order by x.id), '[]'::jsonb) from miembros x where x.clinica_id = p_clinica) end);
end;
$$;

create function guardar_clinica(p_clinica uuid, d jsonb) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare c clinicas;
begin
  perform _miembro(p_clinica, array['propietario']);
  select * into c from clinicas where id = p_clinica;
  update clinicas set
    nombre                = coalesce(nullif(trim(d->>'nombre'), ''), c.nombre),
    telefono              = case when d ? 'telefono' then nullif(trim(d->>'telefono'), '') else c.telefono end,
    email                 = case when d ? 'email' then nullif(trim(d->>'email'), '') else c.email end,
    direccion             = case when d ? 'direccion' then nullif(trim(d->>'direccion'), '') else c.direccion end,
    web                   = case when d ? 'web' then nullif(trim(d->>'web'), '') else c.web end,
    color                 = coalesce(d->>'color', c.color),
    logo_path             = case when d ? 'logo_path' then nullif(d->>'logo_path', '') else c.logo_path end,
    zona_horaria          = coalesce(d->>'zona_horaria', c.zona_horaria),
    paso_minutos          = coalesce((d->>'paso_minutos')::int, c.paso_minutos),
    antelacion_minima_min = coalesce((d->>'antelacion_minima_min')::int, c.antelacion_minima_min),
    horas_minimas_cambio  = coalesce((d->>'horas_minimas_cambio')::int, c.horas_minimas_cambio),
    max_citas_futuras     = coalesce((d->>'max_citas_futuras')::int, c.max_citas_futuras),
    dias_reserva_max      = coalesce((d->>'dias_reserva_max')::int, c.dias_reserva_max),
    precios_confirmados   = coalesce((d->>'precios_confirmados')::boolean, c.precios_confirmados)
  where id = p_clinica;
  perform _auditar(p_clinica, 'guardar_clinica', 'clinica', p_clinica::text,
                   null, jsonb_build_object('campos', (select jsonb_agg(k) from jsonb_object_keys(d) k)));
  return jsonb_build_object('ok', true);
end;
$$;

-- Añade o cambia un miembro del equipo. La persona tiene que haberse registrado antes con ese correo.
create function guardar_miembro(p_clinica uuid, d jsonb) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare v_user uuid; v_id bigint; yo miembros;
begin
  yo := _miembro(p_clinica, array['propietario']);
  if d ? 'id' then
    if (d->>'id')::bigint = yo.id and (coalesce(d->>'rol', 'propietario') <> 'propietario' or coalesce((d->>'activo')::boolean, true) = false) then
      return jsonb_build_object('ok', false, 'motivo', 'no_puedes_quitarte_propietario');
    end if;
    update miembros set
      nombre = coalesce(nullif(trim(d->>'nombre'), ''), nombre),
      rol = coalesce(d->>'rol', rol),
      profesional_id = case when d ? 'profesional_id' then (d->>'profesional_id')::bigint else profesional_id end,
      activo = coalesce((d->>'activo')::boolean, activo)
    where id = (d->>'id')::bigint and clinica_id = p_clinica returning id into v_id;
    if v_id is null then return jsonb_build_object('ok', false, 'motivo', 'miembro_no_existe'); end if;
  else
    select id into v_user from auth.users where lower(email) = lower(trim(d->>'email'));
    if v_user is null then return jsonb_build_object('ok', false, 'motivo', 'usuario_no_registrado'); end if;
    insert into miembros (clinica_id, user_id, nombre, email, rol, profesional_id)
    values (p_clinica, v_user, coalesce(nullif(trim(d->>'nombre'), ''), split_part(d->>'email', '@', 1)),
            lower(trim(d->>'email')), d->>'rol', (d->>'profesional_id')::bigint)
    on conflict (clinica_id, user_id) do update set rol = excluded.rol, activo = true,
      profesional_id = excluded.profesional_id
    returning id into v_id;
  end if;
  perform _auditar(p_clinica, 'guardar_miembro', 'miembro', v_id::text, null, jsonb_build_object('rol', d->>'rol'));
  return jsonb_build_object('ok', true, 'id', v_id);
end;
$$;

create function guardar_profesional(p_clinica uuid, d jsonb) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare v_id bigint := (d->>'id')::bigint;
begin
  perform _miembro(p_clinica, array['propietario']);
  if v_id is null then
    insert into profesionales (clinica_id, nombre, numero_colegiado, especialidades, color, email, telefono_avisos,
                               enlace_online, orden)
    values (p_clinica, trim(d->>'nombre'), nullif(trim(d->>'numero_colegiado'), ''),
            coalesce((select array_agg(x) from jsonb_array_elements_text(d->'especialidades') x), '{}'),
            coalesce(d->>'color', '#2f7d5b'), nullif(trim(d->>'email'), ''),
            normalizar_telefono(d->>'telefono_avisos'), nullif(trim(d->>'enlace_online'), ''),
            coalesce((d->>'orden')::int, 0))
    returning id into v_id;
  else
    update profesionales set
      nombre = coalesce(nullif(trim(d->>'nombre'), ''), nombre),
      numero_colegiado = case when d ? 'numero_colegiado' then nullif(trim(d->>'numero_colegiado'), '') else numero_colegiado end,
      especialidades = case when d ? 'especialidades'
                            then coalesce((select array_agg(x) from jsonb_array_elements_text(d->'especialidades') x), '{}')
                            else especialidades end,
      color = coalesce(d->>'color', color),
      email = case when d ? 'email' then nullif(trim(d->>'email'), '') else email end,
      telefono_avisos = case when d ? 'telefono_avisos' then normalizar_telefono(d->>'telefono_avisos') else telefono_avisos end,
      enlace_online = case when d ? 'enlace_online' then nullif(trim(d->>'enlace_online'), '') else enlace_online end,
      activo = coalesce((d->>'activo')::boolean, activo),
      orden = coalesce((d->>'orden')::int, orden)
    where id = v_id and clinica_id = p_clinica;
    if not found then return jsonb_build_object('ok', false, 'motivo', 'profesional_no_existe'); end if;
  end if;
  if d ? 'servicios' then
    delete from profesional_servicios where profesional_id = v_id;
    insert into profesional_servicios (clinica_id, profesional_id, servicio_id)
    select p_clinica, v_id, s.id from servicios s
    where s.clinica_id = p_clinica and s.id in (select x::bigint from jsonb_array_elements_text(d->'servicios') x);
  end if;
  if d ? 'horario' then
    -- Tramos del mismo día que se pisan: error claro en vez de huecos raros.
    if exists (select 1 from jsonb_array_elements(d->'horario') a, jsonb_array_elements(d->'horario') b
               where a <> b and a->>'dia_semana' = b->>'dia_semana'
                 and (a->>'desde')::time < (b->>'hasta')::time and (b->>'desde')::time < (a->>'hasta')::time) then
      raise exception 'horario_solapado' using errcode = '22023';
    end if;
    delete from horarios where profesional_id = v_id;
    insert into horarios (clinica_id, profesional_id, dia_semana, hora_inicio, hora_fin, modalidad)
    select p_clinica, v_id, (t->>'dia_semana')::int, (t->>'desde')::time, (t->>'hasta')::time, coalesce(t->>'modalidad', 'ambas')
    from jsonb_array_elements(d->'horario') t;
  end if;
  perform _auditar(p_clinica, 'guardar_profesional', 'profesional', v_id::text);
  return jsonb_build_object('ok', true, 'id', v_id);
end;
$$;

create function guardar_servicio(p_clinica uuid, d jsonb) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare v_id bigint := (d->>'id')::bigint; v_precio int;
begin
  perform _miembro(p_clinica, array['propietario']);
  v_precio := case when d ? 'precio' and nullif(d->>'precio', '') is not null
                   then round((replace(d->>'precio', ',', '.'))::numeric * 100)::int end;
  if v_id is null then
    insert into servicios (clinica_id, nombre, descripcion, tipo, especialidad, duracion_min, precio_centimos,
                           presencial, online, reservable_canales, orden)
    values (p_clinica, trim(d->>'nombre'), nullif(trim(d->>'descripcion'), ''), coalesce(d->>'tipo', 'revision'),
            nullif(d->>'especialidad', ''), coalesce((d->>'duracion_min')::int, 45), v_precio,
            coalesce((d->>'presencial')::boolean, true), coalesce((d->>'online')::boolean, false),
            coalesce((d->>'reservable_canales')::boolean, true), coalesce((d->>'orden')::int, 0))
    returning id into v_id;
  else
    update servicios set
      nombre = coalesce(nullif(trim(d->>'nombre'), ''), nombre),
      descripcion = case when d ? 'descripcion' then nullif(trim(d->>'descripcion'), '') else descripcion end,
      tipo = coalesce(d->>'tipo', tipo),
      especialidad = case when d ? 'especialidad' then nullif(d->>'especialidad', '') else especialidad end,
      duracion_min = coalesce((d->>'duracion_min')::int, duracion_min),
      precio_centimos = case when d ? 'precio' then v_precio else precio_centimos end,
      presencial = coalesce((d->>'presencial')::boolean, presencial),
      online = coalesce((d->>'online')::boolean, online),
      reservable_canales = coalesce((d->>'reservable_canales')::boolean, reservable_canales),
      activo = coalesce((d->>'activo')::boolean, activo),
      orden = coalesce((d->>'orden')::int, orden)
    where id = v_id and clinica_id = p_clinica;
    if not found then return jsonb_build_object('ok', false, 'motivo', 'servicio_no_existe'); end if;
  end if;
  perform _auditar(p_clinica, 'guardar_servicio', 'servicio', v_id::text);
  return jsonb_build_object('ok', true, 'id', v_id);
end;
$$;

-- Ausencias: el propietario las pone a cualquiera; un nutricionista, solo a sí mismo.
create function crear_ausencia(p_clinica uuid, d jsonb) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare m miembros; v_tz text := _tz(p_clinica); v_ini timestamptz; v_fin timestamptz; v_prof bigint; v_id bigint;
        v_afectadas jsonb;
begin
  m := _miembro(p_clinica, array['propietario', 'nutricionista']);
  v_prof := (d->>'profesional_id')::bigint;
  if m.rol = 'nutricionista' and (v_prof is null or v_prof is distinct from m.profesional_id) then
    raise exception 'sin_permiso' using errcode = '42501';
  end if;
  v_ini := _desde_local(d->>'inicio', v_tz);
  v_fin := _desde_local(d->>'fin', v_tz);
  if v_ini is null or v_fin is null or v_fin <= v_ini then return jsonb_build_object('ok', false, 'motivo', 'fechas_no_validas'); end if;
  insert into ausencias (clinica_id, profesional_id, inicio, fin, motivo, creada_por)
  values (p_clinica, v_prof, v_ini, v_fin, nullif(trim(d->>'motivo'), ''), auth.uid()) returning id into v_id;
  -- No movemos citas solas: se devuelven las que quedan dentro para que el equipo decida.
  select coalesce(jsonb_agg(_cita_json(c.id) order by c.inicio), '[]'::jsonb) into v_afectadas
  from citas c where c.clinica_id = p_clinica and c.estado = 'reservada'
    and (v_prof is null or c.profesional_id = v_prof) and tstzrange(c.inicio, c.fin) && tstzrange(v_ini, v_fin);
  perform _auditar(p_clinica, 'crear_ausencia', 'ausencia', v_id::text);
  return jsonb_build_object('ok', true, 'id', v_id, 'citas_afectadas', v_afectadas);
end;
$$;

create function borrar_ausencia(p_clinica uuid, p_id bigint) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare m miembros; a ausencias;
begin
  m := _miembro(p_clinica, array['propietario', 'nutricionista']);
  select * into a from ausencias where id = p_id and clinica_id = p_clinica;
  if a.id is null then return jsonb_build_object('ok', false, 'motivo', 'ausencia_no_existe'); end if;
  if m.rol = 'nutricionista' and a.profesional_id is distinct from m.profesional_id then
    raise exception 'sin_permiso' using errcode = '42501';
  end if;
  delete from ausencias where id = p_id;
  perform _auditar(p_clinica, 'borrar_ausencia', 'ausencia', p_id::text);
  return jsonb_build_object('ok', true);
end;
$$;

-- ---------------------------------------------------------------- pacientes

create function _paciente_json(p_id bigint) returns jsonb
language sql stable security definer set search_path = nutricion, extensions, pg_temp as $$
  select jsonb_build_object('id', p.id, 'nombre', p.nombre, 'apellidos', p.apellidos,
    'nombre_completo', trim(p.nombre || ' ' || coalesce(p.apellidos, '')),
    'telefono', p.telefono, 'email', p.email, 'fecha_nacimiento', p.fecha_nacimiento,
    'profesional_id', p.profesional_id, 'profesional', pr.nombre, 'modalidad_preferida', p.modalidad_preferida,
    'canal_preferido', p.canal_preferido, 'acepta_comerciales', p.acepta_comerciales, 'estado', p.estado,
    'notas_admin', p.notas_admin, 'origen', p.origen, 'alta', _local(p.creado_en, c.zona_horaria),
    'ultima_cita', (select _local(max(x.inicio), c.zona_horaria) from citas x where x.paciente_id = p.id
                      and x.estado in ('realizada', 'reservada') and x.inicio <= now()),
    'proxima_cita', (select _local(min(x.inicio), c.zona_horaria) from citas x where x.paciente_id = p.id
                       and x.estado = 'reservada' and x.inicio > now()))
  from pacientes p join clinicas c on c.id = p.clinica_id left join profesionales pr on pr.id = p.profesional_id
  where p.id = p_id
$$;

create function crear_paciente(p_clinica uuid, d jsonb) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare v_tel text := normalizar_telefono(d->>'telefono'); v_id bigint; v_dup jsonb;
begin
  perform _miembro(p_clinica);
  if nullif(trim(d->>'nombre'), '') is null then return jsonb_build_object('ok', false, 'motivo', 'falta_nombre'); end if;
  if d->>'telefono' is not null and trim(d->>'telefono') <> '' and v_tel is null then
    return jsonb_build_object('ok', false, 'motivo', 'telefono_no_valido');
  end if;
  if v_tel is null and nullif(trim(d->>'email'), '') is null then
    return jsonb_build_object('ok', false, 'motivo', 'falta_contacto');
  end if;
  -- Posible duplicado: mismo teléfono o correo y nombre parecido. Se avisa; el equipo decide.
  if not coalesce((d->>'forzar')::boolean, false) then
    select jsonb_agg(_paciente_json(p.id)) into v_dup from pacientes p
    where p.clinica_id = p_clinica
      and ((v_tel is not null and p.telefono = v_tel) or (lower(p.email) = lower(nullif(trim(d->>'email'), ''))))
      and lower(split_part(trim(p.nombre), ' ', 1)) = lower(split_part(trim(d->>'nombre'), ' ', 1));
    if v_dup is not null then return jsonb_build_object('ok', false, 'motivo', 'posible_duplicado', 'pacientes', v_dup); end if;
  end if;
  insert into pacientes (clinica_id, nombre, apellidos, telefono, email, fecha_nacimiento, profesional_id,
                         modalidad_preferida, canal_preferido, acepta_comerciales, comerciales_cambiado_en, notas_admin,
                         origen, creado_por)
  values (p_clinica, trim(d->>'nombre'), nullif(trim(d->>'apellidos'), ''), v_tel, nullif(lower(trim(d->>'email')), ''),
          nullif(d->>'fecha_nacimiento', '')::date, (d->>'profesional_id')::bigint, nullif(d->>'modalidad_preferida', ''),
          coalesce(nullif(d->>'canal_preferido', ''), 'whatsapp'), coalesce((d->>'acepta_comerciales')::boolean, false),
          case when (d->>'acepta_comerciales')::boolean then now() end, nullif(trim(d->>'notas_admin'), ''), 'app', auth.uid())
  returning id into v_id;
  perform _auditar(p_clinica, 'crear_paciente', 'paciente', v_id::text, v_id);
  return jsonb_build_object('ok', true, 'paciente', _paciente_json(v_id));
end;
$$;

create function editar_paciente(p_clinica uuid, p_id bigint, d jsonb) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare p pacientes; v_tel text;
begin
  perform _miembro(p_clinica);
  select * into p from pacientes where id = p_id and clinica_id = p_clinica for update;
  if p.id is null then return jsonb_build_object('ok', false, 'motivo', 'paciente_no_existe'); end if;
  if d ? 'telefono' then
    v_tel := normalizar_telefono(d->>'telefono');
    if nullif(trim(d->>'telefono'), '') is not null and v_tel is null then
      return jsonb_build_object('ok', false, 'motivo', 'telefono_no_valido');
    end if;
  else v_tel := p.telefono; end if;
  update pacientes set
    nombre = coalesce(nullif(trim(d->>'nombre'), ''), nombre),
    apellidos = case when d ? 'apellidos' then nullif(trim(d->>'apellidos'), '') else apellidos end,
    telefono = v_tel,
    email = case when d ? 'email' then nullif(lower(trim(d->>'email')), '') else email end,
    fecha_nacimiento = case when d ? 'fecha_nacimiento' then nullif(d->>'fecha_nacimiento', '')::date else fecha_nacimiento end,
    profesional_id = case when d ? 'profesional_id' then (d->>'profesional_id')::bigint else profesional_id end,
    modalidad_preferida = case when d ? 'modalidad_preferida' then nullif(d->>'modalidad_preferida', '') else modalidad_preferida end,
    canal_preferido = coalesce(nullif(d->>'canal_preferido', ''), canal_preferido),
    acepta_comerciales = coalesce((d->>'acepta_comerciales')::boolean, acepta_comerciales),
    comerciales_cambiado_en = case when (d->>'acepta_comerciales')::boolean is distinct from acepta_comerciales
                                     and d ? 'acepta_comerciales' then now() else comerciales_cambiado_en end,
    estado = coalesce(nullif(d->>'estado', ''), estado),
    notas_admin = case when d ? 'notas_admin' then nullif(trim(d->>'notas_admin'), '') else notas_admin end
  where id = p_id;
  perform _auditar(p_clinica, 'editar_paciente', 'paciente', p_id::text, p_id,
                   jsonb_build_object('campos', (select jsonb_agg(k) from jsonb_object_keys(d) k)));
  return jsonb_build_object('ok', true, 'paciente', _paciente_json(p_id));
end;
$$;

create function buscar_pacientes(p_clinica uuid, p_q text) returns jsonb
language plpgsql stable security definer set search_path = nutricion, extensions, pg_temp as $$
declare v_q text := lower(trim(coalesce(p_q, ''))); v_dig text := regexp_replace(coalesce(p_q, ''), '[^0-9]', '', 'g');
begin
  perform _miembro(p_clinica);
  if length(v_q) < 2 then return '[]'::jsonb; end if;
  return (select coalesce(jsonb_agg(_paciente_json(x.id) order by x.nombre), '[]'::jsonb) from (
    select p.id, p.nombre from pacientes p
    where p.clinica_id = p_clinica
      and (lower(p.nombre || ' ' || coalesce(p.apellidos, '')) like '%' || v_q || '%'
           or (length(v_dig) >= 3 and p.telefono like '%' || v_dig || '%')
           or lower(coalesce(p.email, '')) like '%' || v_q || '%')
    order by p.nombre limit 15) x);
end;
$$;

-- Ficha del paciente. Recepción recibe solo lo administrativo. Cada apertura queda registrada.
create function ficha_paciente(p_clinica uuid, p_id bigint) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare m miembros; v_tz text := _tz(p_clinica); v_salud jsonb;
begin
  m := _miembro(p_clinica);
  if not exists (select 1 from pacientes where id = p_id and clinica_id = p_clinica) then
    return jsonb_build_object('ok', false, 'motivo', 'paciente_no_existe');
  end if;
  if _puede_salud(m.rol) then
    select to_jsonb(s) - 'clinica_id' - 'paciente_id' into v_salud from pacientes_salud s where s.paciente_id = p_id;
  end if;
  perform _auditar(p_clinica, case when _puede_salud(m.rol) then 'ver_ficha_salud' else 'ver_ficha' end,
                   'paciente', p_id::text, p_id);
  return jsonb_build_object('ok', true,
    'paciente', _paciente_json(p_id),
    'salud', case when _puede_salud(m.rol) then coalesce(v_salud, '{}'::jsonb) end,
    've_salud', _puede_salud(m.rol),
    'citas', (select coalesce(jsonb_agg(_cita_json(c.id) order by c.inicio desc), '[]'::jsonb)
              from citas c where c.paciente_id = p_id),
    'resumen', (select jsonb_build_object(
        'realizadas', count(*) filter (where estado = 'realizada'),
        'proximas', count(*) filter (where estado = 'reservada' and inicio > now()),
        'canceladas', count(*) filter (where estado = 'cancelada'),
        'no_asistidas', count(*) filter (where estado = 'no_asistida'))
      from citas where paciente_id = p_id));
end;
$$;

create function guardar_salud(p_clinica uuid, p_id bigint, d jsonb) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
begin
  perform _miembro(p_clinica, array['propietario', 'nutricionista']);
  if not exists (select 1 from pacientes where id = p_id and clinica_id = p_clinica) then
    return jsonb_build_object('ok', false, 'motivo', 'paciente_no_existe');
  end if;
  insert into pacientes_salud as s (paciente_id, clinica_id, motivo_consulta, objetivos, antecedentes, alergias,
       intolerancias, medicacion, suplementos, habitos_alimentarios, actividad_fisica, informacion_clinica, campos_extra,
       actualizado_por)
  values (p_id, p_clinica, d->>'motivo_consulta', d->>'objetivos', d->>'antecedentes', d->>'alergias', d->>'intolerancias',
          d->>'medicacion', d->>'suplementos', d->>'habitos_alimentarios', d->>'actividad_fisica', d->>'informacion_clinica',
          coalesce(d->'campos_extra', '{}'::jsonb), auth.uid())
  on conflict (paciente_id) do update set
    motivo_consulta = case when d ? 'motivo_consulta' then excluded.motivo_consulta else s.motivo_consulta end,
    objetivos = case when d ? 'objetivos' then excluded.objetivos else s.objetivos end,
    antecedentes = case when d ? 'antecedentes' then excluded.antecedentes else s.antecedentes end,
    alergias = case when d ? 'alergias' then excluded.alergias else s.alergias end,
    intolerancias = case when d ? 'intolerancias' then excluded.intolerancias else s.intolerancias end,
    medicacion = case when d ? 'medicacion' then excluded.medicacion else s.medicacion end,
    suplementos = case when d ? 'suplementos' then excluded.suplementos else s.suplementos end,
    habitos_alimentarios = case when d ? 'habitos_alimentarios' then excluded.habitos_alimentarios else s.habitos_alimentarios end,
    actividad_fisica = case when d ? 'actividad_fisica' then excluded.actividad_fisica else s.actividad_fisica end,
    informacion_clinica = case when d ? 'informacion_clinica' then excluded.informacion_clinica else s.informacion_clinica end,
    campos_extra = case when d ? 'campos_extra' then excluded.campos_extra else s.campos_extra end,
    actualizado_en = now(), actualizado_por = auth.uid();
  perform _auditar(p_clinica, 'guardar_salud', 'paciente', p_id::text, p_id,
                   jsonb_build_object('campos', (select jsonb_agg(k) from jsonb_object_keys(d) k)));
  return jsonb_build_object('ok', true);
end;
$$;

-- Listas de pacientes para el panel y la sección Pacientes.
-- filtro: todos | activos | nuevos (desde p_desde) | sin_proxima (activos que ya vinieron y no tienen cita futura)
create function lista_pacientes(p_clinica uuid, p_filtro text default 'todos', p_desde date default null,
                                p_hasta date default null) returns jsonb
language plpgsql stable security definer set search_path = nutricion, extensions, pg_temp as $$
declare v_tz text := _tz(p_clinica);
begin
  perform _miembro(p_clinica);
  return (select coalesce(jsonb_agg(_paciente_json(p.id) order by p.nombre, p.id), '[]'::jsonb)
    from pacientes p
    where p.clinica_id = p_clinica
      and case p_filtro
        when 'activos' then p.estado = 'activo'
        when 'nuevos' then (p.creado_en at time zone v_tz)::date between coalesce(p_desde, _hoy(v_tz) - 30) and coalesce(p_hasta, _hoy(v_tz))
        when 'sin_proxima' then p.estado = 'activo'
             and exists (select 1 from citas c where c.paciente_id = p.id and c.estado = 'realizada')
             and not exists (select 1 from citas c where c.paciente_id = p.id and c.estado = 'reservada' and c.inicio > now())
        else true end);
end;
$$;

-- ---------------------------------------------------------------- agenda

create function agenda(p_clinica uuid, p_desde date, p_dias int default 1, p_profesional bigint default null) returns jsonb
language plpgsql stable security definer set search_path = nutricion, extensions, pg_temp as $$
declare v_tz text := _tz(p_clinica); v_dias int := least(greatest(coalesce(p_dias, 1), 1), 42);
begin
  perform _miembro(p_clinica);
  return jsonb_build_object('ok', true, 'dias', (
    select jsonb_agg(jsonb_build_object(
      'dia', dd.dia,
      'profesionales', (select coalesce(jsonb_agg(jsonb_build_object(
        'id', pr.id, 'nombre', pr.nombre, 'color', pr.color,
        'horario', (select coalesce(jsonb_agg(jsonb_build_object('desde', to_char(h.hora_inicio, 'HH24:MI'),
                       'hasta', to_char(h.hora_fin, 'HH24:MI'), 'modalidad', h.modalidad) order by h.hora_inicio), '[]'::jsonb)
                    from horarios h where h.profesional_id = pr.id and h.dia_semana = extract(isodow from dd.dia)),
        'ausencias', (select coalesce(jsonb_agg(jsonb_build_object('id', a.id, 'inicio', _local(a.inicio, v_tz),
                         'fin', _local(a.fin, v_tz), 'motivo', a.motivo, 'toda_la_consulta', a.profesional_id is null)
                       order by a.inicio), '[]'::jsonb)
                      from ausencias a where a.clinica_id = p_clinica and (a.profesional_id is null or a.profesional_id = pr.id)
                        and tstzrange(a.inicio, a.fin) && tstzrange(dd.dia::timestamp at time zone v_tz,
                                                                   (dd.dia + 1)::timestamp at time zone v_tz)),
        'citas', (select coalesce(jsonb_agg(_cita_json(c.id) order by c.inicio), '[]'::jsonb)
                  from citas c where c.profesional_id = pr.id and c.estado <> 'cancelada'
                    and (c.inicio at time zone v_tz)::date = dd.dia))
        order by pr.orden, pr.id), '[]'::jsonb)
        from profesionales pr where pr.clinica_id = p_clinica and pr.activo
          and (p_profesional is null or pr.id = p_profesional)),
      'canceladas', (select count(*) from citas c where c.clinica_id = p_clinica and c.estado = 'cancelada'
                       and (c.inicio at time zone v_tz)::date = dd.dia
                       and (p_profesional is null or c.profesional_id = p_profesional)))
      order by dd.dia)
    from (select p_desde + n as dia from generate_series(0, v_dias - 1) n) dd));
end;
$$;

create function huecos_disponibles(p_clinica uuid, p_servicio bigint, p_desde date, p_hasta date default null,
                                   p_profesional bigint default null, p_modalidad text default null,
                                   p_paciente bigint default null, p_max int default 30) returns jsonb
language plpgsql stable security definer set search_path = nutricion, extensions, pg_temp as $$
declare v_tz text := _tz(p_clinica); v_mod text; s servicios; v_pref bigint;
begin
  perform _miembro(p_clinica);
  select * into s from servicios where id = p_servicio and clinica_id = p_clinica;
  if s.id is null then return jsonb_build_object('ok', false, 'motivo', 'servicio_no_existe'); end if;
  v_mod := coalesce(p_modalidad, case when s.presencial then 'presencial' else 'online' end);
  select profesional_id into v_pref from pacientes where id = p_paciente and clinica_id = p_clinica;
  return jsonb_build_object('ok', true, 'duracion_min', s.duracion_min, 'modalidad', v_mod, 'huecos', (
    select coalesce(jsonb_agg(jsonb_build_object('inicio', _local(h.inicio, v_tz), 'fin', _local(h.fin, v_tz),
                                                 'fecha_texto', fecha_es(h.inicio, v_tz),
                                                 'profesional_id', h.profesional_id, 'profesional', h.profesional)
                              order by h.inicio), '[]'::jsonb)
    from _huecos(p_clinica, p_servicio, p_profesional, p_desde::timestamp at time zone v_tz,
                 (coalesce(p_hasta, p_desde + 6) + 1)::timestamp at time zone v_tz, v_mod, v_pref, p_max, 50, false) h));
end;
$$;

-- d: {paciente_id, servicio_id, inicio ("2026-10-26T10:00", hora local), profesional_id?, modalidad?, notas?, motivo?,
--     forzar?, motivo_excepcion?}
create function reservar_cita(p_clinica uuid, d jsonb) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
begin
  perform _miembro(p_clinica);
  return _reservar(p_clinica, (d->>'paciente_id')::bigint, (d->>'servicio_id')::bigint, (d->>'profesional_id')::bigint,
                   _desde_local(d->>'inicio', _tz(p_clinica)), nullif(d->>'modalidad', ''), 'app', nullif(d->>'clave', ''),
                   coalesce((d->>'forzar')::boolean, false), d->>'motivo_excepcion', d->>'notas', d->>'motivo');
end;
$$;

create function cambiar_cita(p_clinica uuid, p_cita bigint, d jsonb) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
begin
  perform _miembro(p_clinica);
  return _cambiar(p_clinica, p_cita, _desde_local(d->>'inicio', _tz(p_clinica)), (d->>'profesional_id')::bigint,
                  nullif(d->>'modalidad', ''), coalesce((d->>'forzar')::boolean, false), d->>'motivo_excepcion');
end;
$$;

create function cancelar_cita(p_clinica uuid, p_cita bigint, p_por text default 'clinica', p_motivo text default null)
returns jsonb language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
begin
  perform _miembro(p_clinica);
  if p_por not in ('paciente', 'clinica') then return jsonb_build_object('ok', false, 'motivo', 'valor_no_valido'); end if;
  return _cancelar(p_clinica, p_cita, p_por, p_motivo);
end;
$$;

-- Realizada / no asistida / volver a reservada (deshacer). Una cita futura no se puede dar por realizada.
create function marcar_cita(p_clinica uuid, p_cita bigint, p_estado text) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare ci citas;
begin
  perform _miembro(p_clinica);
  select * into ci from citas where id = p_cita and clinica_id = p_clinica for update;
  if ci.id is null then return jsonb_build_object('ok', false, 'motivo', 'cita_no_existe'); end if;
  if p_estado not in ('realizada', 'no_asistida', 'reservada') then
    return jsonb_build_object('ok', false, 'motivo', 'valor_no_valido');
  end if;
  if ci.estado = 'cancelada' then return jsonb_build_object('ok', false, 'motivo', 'cita_cancelada'); end if;
  if p_estado in ('realizada', 'no_asistida') and ci.inicio > now() then
    return jsonb_build_object('ok', false, 'motivo', 'cita_futura');
  end if;
  begin
    update citas set estado = p_estado, actualizada_en = now() where id = ci.id;
  exception when exclusion_violation then
    return jsonb_build_object('ok', false, 'motivo', 'hueco_no_disponible');
  end;
  perform _auditar(p_clinica, 'marcar_cita', 'cita', ci.id::text, ci.paciente_id,
                   jsonb_build_object('antes', ci.estado, 'despues', p_estado));
  return jsonb_build_object('ok', true, 'cita', _cita_json(ci.id));
end;
$$;

-- ---------------------------------------------------------------- panel

-- Estado del negocio. Los módulos que aún no existen devuelven null (la aplicación dice "se activa en la fase X"),
-- nunca un número inventado.
create function panel(p_clinica uuid, p_desde date default null, p_hasta date default null,
                      p_profesional bigint default null) returns jsonb
language plpgsql stable security definer set search_path = nutricion, extensions, pg_temp as $$
declare
  v_tz    text := _tz(p_clinica);
  v_hoy   date := _hoy(v_tz);
  v_desde date := coalesce(p_desde, date_trunc('month', _hoy(v_tz))::date);
  v_hasta date := coalesce(p_hasta, _hoy(v_tz));
  v_disp  int;
  v_ocup  int;
  v_libres_hoy int;
  m miembros;
begin
  m := _miembro(p_clinica);
  select coalesce(sum(_minutos_disponibles(pr.id, d::date)), 0) into v_disp
  from profesionales pr cross join generate_series(v_desde, v_hasta, interval '1 day') d
  where pr.clinica_id = p_clinica and pr.activo and (p_profesional is null or pr.id = p_profesional);
  select coalesce(sum(extract(epoch from (c.fin - c.inicio)) / 60), 0)::int into v_ocup
  from citas c where c.clinica_id = p_clinica and c.estado in ('reservada', 'realizada', 'no_asistida')
    and (c.inicio at time zone v_tz)::date between v_desde and v_hasta
    and (p_profesional is null or c.profesional_id = p_profesional);
  -- Tiempo libre que queda hoy: horario desde ahora, menos ausencias y menos lo ya reservado desde ahora.
  select greatest(coalesce(sum(_minutos_disponibles(pr.id, v_hoy, now())), 0)
           - coalesce((select sum(extract(epoch from (c.fin - greatest(c.inicio, now()))) / 60) from citas c
                       where c.clinica_id = p_clinica and c.estado in ('reservada', 'realizada') and c.fin > now()
                         and (c.inicio at time zone v_tz)::date = v_hoy
                         and (p_profesional is null or c.profesional_id = p_profesional)), 0), 0)::int
    into v_libres_hoy
  from profesionales pr where pr.clinica_id = p_clinica and pr.activo and (p_profesional is null or pr.id = p_profesional);

  return jsonb_build_object('ok', true, 'hoy', v_hoy, 'desde', v_desde, 'hasta', v_hasta,
    'agenda_hoy', (select jsonb_build_object(
        'consultas', count(*) filter (where c.estado <> 'cancelada'),
        'primeras_visitas', count(*) filter (where c.estado <> 'cancelada' and s.tipo = 'primera_visita'),
        'revisiones', count(*) filter (where c.estado <> 'cancelada' and s.tipo in ('revision', 'sesion_programa')),
        'confirmadas', count(*) filter (where c.estado = 'reservada' and c.confirmada_en is not null),
        'canceladas', count(*) filter (where c.estado = 'cancelada'),
        'minutos_libres', v_libres_hoy)
      from citas c join servicios s on s.id = c.servicio_id
      where c.clinica_id = p_clinica and (c.inicio at time zone v_tz)::date = v_hoy
        and (p_profesional is null or c.profesional_id = p_profesional)),
    'pacientes', jsonb_build_object(
        'nuevos', (select count(*) from pacientes where clinica_id = p_clinica
                     and (creado_en at time zone v_tz)::date between v_desde and v_hasta),
        'activos', (select count(*) from pacientes where clinica_id = p_clinica and estado = 'activo'),
        'sin_proxima', (select jsonb_array_length(lista_pacientes(p_clinica, 'sin_proxima'))),
        'con_programas_pendientes', null,
        'con_bonos_activos', null),
    'tareas', jsonb_build_object(
        'revisiones_por_programar', (select jsonb_array_length(lista_pacientes(p_clinica, 'sin_proxima'))),
        'formularios_sin_completar', null, 'planes_por_entregar', null, 'intervencion_humana', null,
        'documentos_por_firmar', null, 'pagos_pendientes', null),
    'indicadores', (select jsonb_build_object(
        'consultas_realizadas', count(*) filter (where c.estado = 'realizada'),
        'citas', count(*) filter (where c.estado <> 'cancelada'),
        'cancelaciones', count(*) filter (where c.estado = 'cancelada'),
        'ausencias', count(*) filter (where c.estado = 'no_asistida'),
        'revisiones_reservadas', count(*) filter (where c.estado <> 'cancelada' and s.tipo in ('revision', 'sesion_programa')),
        'minutos_disponibles', v_disp,
        'minutos_ocupados', v_ocup,
        'ocupacion_pct', case when v_disp > 0 then round(100.0 * v_ocup / v_disp, 1) end,
        'sesiones_pendientes', null,
        'ingresos', null)
      from citas c join servicios s on s.id = c.servicio_id
      where c.clinica_id = p_clinica and (c.inicio at time zone v_tz)::date between v_desde and v_hasta
        and (p_profesional is null or c.profesional_id = p_profesional)));
end;
$$;

-- Registros detrás de cada indicador del panel.
create function panel_citas(p_clinica uuid, p_clave text, p_desde date, p_hasta date, p_profesional bigint default null)
returns jsonb language plpgsql stable security definer set search_path = nutricion, extensions, pg_temp as $$
declare v_tz text := _tz(p_clinica);
begin
  perform _miembro(p_clinica);
  return (select coalesce(jsonb_agg(_cita_json(c.id) order by c.inicio), '[]'::jsonb)
    from citas c join servicios s on s.id = c.servicio_id
    where c.clinica_id = p_clinica and (c.inicio at time zone v_tz)::date between p_desde and p_hasta
      and (p_profesional is null or c.profesional_id = p_profesional)
      and case p_clave
        when 'consultas' then c.estado <> 'cancelada'
        when 'primeras_visitas' then c.estado <> 'cancelada' and s.tipo = 'primera_visita'
        when 'revisiones' then c.estado <> 'cancelada' and s.tipo in ('revision', 'sesion_programa')
        when 'confirmadas' then c.estado = 'reservada' and c.confirmada_en is not null
        when 'canceladas' then c.estado = 'cancelada'
        when 'realizadas' then c.estado = 'realizada'
        when 'no_asistidas' then c.estado = 'no_asistida'
        else false end);
end;
$$;

create function registro_auditoria(p_clinica uuid, p_paciente bigint default null, p_limite int default 200) returns jsonb
language plpgsql stable security definer set search_path = nutricion, extensions, pg_temp as $$
declare v_tz text := _tz(p_clinica);
begin
  perform _miembro(p_clinica, array['propietario']);
  return (select coalesce(jsonb_agg(jsonb_build_object('cuando', _local(a.cuando, v_tz), 'actor_tipo', a.actor_tipo,
            'actor', a.actor_nombre, 'accion', a.accion, 'entidad', a.entidad, 'entidad_id', a.entidad_id,
            'paciente_id', a.paciente_id, 'detalle', a.detalle) order by a.id desc), '[]'::jsonb)
    from (select * from auditoria where clinica_id = p_clinica and (p_paciente is null or paciente_id = p_paciente)
          order by id desc limit least(greatest(p_limite, 1), 1000)) a);
end;
$$;

-- =====================================================================
-- Permisos: solo se pueden llamar las funciones públicas, y solo con sesión
-- =====================================================================
create function _aplicar_permisos() returns void language plpgsql as $$
declare f record;
begin
  revoke all on all tables in schema nutricion from public, anon, authenticated;
  revoke all on all sequences in schema nutricion from public, anon, authenticated;
  grant usage on schema nutricion to anon, authenticated, service_role;
  grant all on all tables in schema nutricion to service_role;
  grant all on all sequences in schema nutricion to service_role;
  for f in select p.oid::regprocedure as firma, p.proname from pg_proc p
           join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'nutricion' loop
    execute format('revoke all on function %s from public, anon, authenticated', f.firma);
    execute format('grant execute on function %s to service_role', f.firma);
    if f.proname !~ '^(_|canal_|motor_|portal_)' then
      execute format('grant execute on function %s to authenticated', f.firma);
    end if;
    if f.proname ~ '^portal_' then
      execute format('grant execute on function %s to anon, authenticated', f.firma);
    end if;
  end loop;
  -- Las funciones de utilidad sin datos se pueden usar desde dentro de otras.
  grant execute on function fecha_es(timestamptz, text), normalizar_telefono(text) to authenticated;
end;
$$;
select _aplicar_permisos();


-- =====================================================================
-- Corvex Nutrición · Fase 2: automatización administrativa
-- Canales (WhatsApp y teléfono con IA), conversaciones, solicitudes para el equipo, plantillas, cola de envíos
-- idempotente (confirmaciones, recordatorios, avisos), formularios previos con enlace seguro, lista de espera.
--
-- Principios:
--  * La IA nunca decide nada clínico. Las preguntas clínicas se convierten en una solicitud para el profesional y
--    recepción no ve su contenido.
--  * Las herramientas de los canales (`canal_*`, solo service_role, para n8n) trabajan siempre sobre una
--    conversación: el paciente sale de la identidad comprobada en esa conversación, nunca de lo que diga el modelo.
--    Aunque alguien engañe a la IA, la base de datos no le deja ver ni tocar citas de otra persona.
--  * Para ver o tocar citas que ya existen hace falta comprobar la identidad: teléfono de la conversación + fecha de
--    nacimiento (el teléfono no basta: en una familia varias personas comparten móvil).
--  * Nada se envía dos veces: cada envío lleva una clave única; los reintentos del proveedor y los mensajes
--    duplicados de Meta no repiten nada.
--  * Mientras `clinicas.modo_envio` = 'simulador', nada sale de la base de datos: los envíos quedan como
--    'simulado' y se ven en la aplicación. Solo se puede pasar a 'real' con el canal conectado de verdad.
-- =====================================================================

set search_path = nutricion, extensions, public;

-- ---------------------------------------------------------------- ajustes

-- Ajustes de la instalación (no de cada consulta).
create table sistema (
  clave text primary key,
  valor text
);
-- Dirección pública de la aplicación, para los enlaces de los formularios. Pendiente de confirmar el dominio.
insert into sistema values ('url_app', 'https://nutricion.corvexstudio.es');

alter table clinicas
  add column nombre_asistente          text not null default 'Asistente',
  add column enviar_confirmacion       boolean not null default true,
  add column recordatorio_horas        int not null default 24 check (recordatorio_horas between 0 and 168),  -- 0 = sin recordatorio
  add column formulario_recordatorio_horas int not null default 48 check (formulario_recordatorio_horas between 0 and 336),
  add column oferta_espera_minutos     int not null default 120 check (oferta_espera_minutos between 15 and 1440),
  add column verificacion_minutos      int not null default 30 check (verificacion_minutos between 5 and 240),
  add column retencion_mensajes_dias   int not null default 365 check (retencion_mensajes_dias between 30 and 3650);

-- ---------------------------------------------------------------- canales y conversaciones

-- Un canal por tipo y consulta. `identificador` es el que manda el proveedor para saber a qué consulta va el mensaje
-- (phone_number_id de Meta, agent_id de Retell). Las credenciales NO se guardan aquí: viven en n8n.
create table canales (
  id             bigint generated always as identity primary key,
  clinica_id     uuid not null references clinicas (id) on delete cascade,
  tipo           text not null check (tipo in ('whatsapp', 'telefono')),
  estado         text not null default 'simulador' check (estado in ('simulador', 'conectado', 'desactivado')),
  identificador  text not null unique,
  numero_publico text,
  conectado_en   timestamptz,
  unique (clinica_id, tipo)
);

create table conversaciones (
  id                  bigint generated always as identity primary key,
  clinica_id          uuid not null references clinicas (id) on delete cascade,
  canal               text not null check (canal in ('whatsapp', 'telefono')),
  contacto            text not null,                -- teléfono E.164 de quien escribe o llama
  nombre_perfil       text,                         -- nombre del perfil de WhatsApp (no comprobado)
  paciente_id         bigint,                       -- identidad comprobada en esta conversación
  verificada_hasta    timestamptz,
  verif_fallos        int not null default 0,
  verif_bloqueo_hasta timestamptz,
  ia_pausada          boolean not null default false,  -- el equipo ha tomado la conversación
  pausada_por         uuid,
  ultimo_entrante_en  timestamptz,
  ultimo_mensaje_en   timestamptz not null default now(),
  creada_en           timestamptz not null default now(),
  unique (clinica_id, id),
  unique (clinica_id, canal, contacto),
  foreign key (clinica_id, paciente_id) references pacientes (clinica_id, id) on delete set null (paciente_id)
);
create index conversaciones_recientes on conversaciones (clinica_id, ultimo_mensaje_en desc);

create table mensajes (
  id              bigint generated always as identity primary key,
  clinica_id      uuid not null,
  conversacion_id bigint not null,
  direccion       text not null check (direccion in ('entrante', 'saliente')),
  autor           text not null check (autor in ('paciente', 'ia', 'equipo', 'sistema')),
  texto           text not null,
  id_externo      text,                             -- id del proveedor: un mensaje repetido por Meta no se procesa dos veces
  envio_id        bigint,
  creado_en       timestamptz not null default now(),
  unique (clinica_id, id_externo),
  foreign key (clinica_id, conversacion_id) references conversaciones (clinica_id, id) on delete cascade
);
create index mensajes_conversacion on mensajes (conversacion_id, id);
create index mensajes_antiguos on mensajes (clinica_id, creado_en);

-- Lo que necesita a una persona del equipo. `pregunta_clinica` va al profesional y recepción no ve el resumen.
create table solicitudes (
  id              bigint generated always as identity primary key,
  clinica_id      uuid not null references clinicas (id) on delete cascade,
  tipo            text not null check (tipo in ('cambio_fuera_plazo', 'cancelacion_fuera_plazo', 'pregunta_clinica',
                    'pregunta_sin_respuesta', 'hablar_con_persona', 'queja', 'envio_fallido', 'otro')),
  paciente_id     bigint,
  profesional_id  bigint,
  conversacion_id bigint,
  cita_id         bigint,
  envio_id        bigint,
  contacto        text,
  resumen         text not null,
  urgente         boolean not null default false,
  estado          text not null default 'pendiente' check (estado in ('pendiente', 'en_curso', 'resuelta')),
  nota            text,
  creada_en       timestamptz not null default now(),
  resuelta_en     timestamptz,
  resuelta_por    uuid,
  unique (clinica_id, id),
  foreign key (clinica_id, paciente_id) references pacientes (clinica_id, id) on delete cascade,
  foreign key (clinica_id, profesional_id) references profesionales (clinica_id, id) on delete set null (profesional_id),
  foreign key (clinica_id, conversacion_id) references conversaciones (clinica_id, id) on delete set null (conversacion_id),
  foreign key (clinica_id, cita_id) references citas (clinica_id, id) on delete set null (cita_id)
);
create index solicitudes_pendientes on solicitudes (clinica_id, estado, creada_en desc);

-- ---------------------------------------------------------------- plantillas y envíos

-- Textos de los mensajes automáticos. Variables entre llaves: {paciente} {fecha} {servicio} {profesional} {clinica}
-- {lugar} {enlace} {comprobacion} {caduca} {tipo} {texto}. Fuera de la ventana de 24 h, WhatsApp exige una plantilla
-- aprobada por Meta: su nombre va en `plantilla_meta`; sin ella, ese envío falla y se avisa al equipo.
create table plantillas_mensaje (
  clinica_id     uuid not null references clinicas (id) on delete cascade,
  clave          text not null check (clave in ('confirmacion_cita', 'recordatorio_cita', 'cambio_cita', 'cancelacion_cita',
                   'formulario_pendiente', 'formulario_recordatorio', 'oferta_lista_espera', 'aviso_equipo', 'mensaje_equipo')),
  texto          text not null check (length(texto) between 5 and 1000),
  activa         boolean not null default true,
  plantilla_meta text,
  primary key (clinica_id, clave)
);

-- Cola de salida. Una fila por mensaje que hay que mandar; la clave impide duplicados.
create table envios (
  id                 bigint generated always as identity primary key,
  clinica_id         uuid not null references clinicas (id) on delete cascade,
  paciente_id        bigint,
  cita_id            bigint,
  cita_inicio        timestamptz,                    -- para descartar el envío si la cita cambia o se cancela
  tipo               text not null,
  canal              text not null check (canal in ('whatsapp', 'email')),
  destino            text not null,
  texto              text not null,                  -- con {enlace} sin rellenar: el enlace no queda guardado
  secreto            text,                           -- token del enlace, solo hasta que se envía
  variables          jsonb not null default '{}'::jsonb,
  clave_idempotencia text not null,
  estado             text not null default 'pendiente'
                     check (estado in ('pendiente', 'enviando', 'enviado', 'fallido', 'cancelado', 'simulado')),
  intentos           int not null default 0,
  programado_para    timestamptz not null default now(),
  proximo_intento    timestamptz not null default now(),
  ultimo_error       text,
  id_externo         text,
  creado_en          timestamptz not null default now(),
  enviado_en         timestamptz,
  unique (clinica_id, clave_idempotencia),
  foreign key (clinica_id, paciente_id) references pacientes (clinica_id, id) on delete cascade,
  foreign key (clinica_id, cita_id) references citas (clinica_id, id) on delete set null (cita_id)
);
create index envios_cola on envios (proximo_intento) where estado = 'pendiente';
create index envios_clinica on envios (clinica_id, creado_en desc);
create index envios_cita on envios (cita_id) where cita_id is not null;

-- ---------------------------------------------------------------- formularios

-- campos: [{clave, etiqueta, tipo: texto|texto_largo|numero|si_no|opcion|varias|fecha, opciones?, obligatorio?,
--           min?, max?, unidad?, ayuda?, destino?}]
-- destino: dónde puede volcarse la respuesta en la ficha de salud cuando el profesional la revise
-- ('motivo_consulta', 'alergias'... o 'extra'). Nunca se vuelca sola.
create table formularios (
  id             bigint generated always as identity primary key,
  clinica_id     uuid not null references clinicas (id) on delete cascade,
  nombre         text not null check (length(trim(nombre)) between 2 and 120),
  descripcion    text,
  campos         jsonb not null default '[]'::jsonb check (jsonb_typeof(campos) = 'array'),
  version        int not null default 1,
  activo         boolean not null default true,
  actualizado_en timestamptz not null default now(),
  unique (clinica_id, id),
  unique (clinica_id, nombre)
);

-- Qué formulario se manda solo al reservar cada servicio (p. ej. el cuestionario inicial con la primera visita).
create table servicio_formularios (
  clinica_id    uuid not null,
  servicio_id   bigint not null,
  formulario_id bigint not null,
  primary key (servicio_id, formulario_id),
  foreign key (clinica_id, servicio_id) references servicios (clinica_id, id) on delete cascade,
  foreign key (clinica_id, formulario_id) references formularios (clinica_id, id) on delete cascade
);

-- Cada formulario mandado a un paciente. El enlace lleva un token; aquí solo se guarda su huella (sha256).
-- Para abrirlo hace falta además la fecha de nacimiento (o, si no la tenemos, los 4 últimos dígitos del móvil).
create table formulario_envios (
  id               bigint generated always as identity primary key,
  clinica_id       uuid not null,
  formulario_id    bigint not null,
  version          int not null,
  campos           jsonb not null,                  -- copia del formulario tal y como se mandó
  paciente_id      bigint not null,
  cita_id          bigint,
  token_hash       bytea not null unique,
  caduca_en        timestamptz not null,
  estado           text not null default 'pendiente'
                   check (estado in ('pendiente', 'completado', 'revisado', 'caducado', 'anulado')),
  intentos_fallidos int not null default 0,
  bloqueado_hasta  timestamptz,
  respuestas       jsonb,                           -- datos de salud: solo propietario y nutricionistas
  abierto_en       timestamptz,
  completado_en    timestamptz,
  revisado_en      timestamptz,
  revisado_por     uuid,
  recordado_en     timestamptz,
  creado_en        timestamptz not null default now(),
  creado_por       uuid,
  unique (clinica_id, id),
  foreign key (clinica_id, formulario_id) references formularios (clinica_id, id),
  foreign key (clinica_id, paciente_id) references pacientes (clinica_id, id) on delete cascade,
  foreign key (clinica_id, cita_id) references citas (clinica_id, id) on delete set null (cita_id)
);
create index formulario_envios_paciente on formulario_envios (paciente_id, creado_en desc);
create index formulario_envios_pendientes on formulario_envios (clinica_id, estado);

-- ---------------------------------------------------------------- lista de espera

-- Pacientes que quieren un hueco antes (o adelantar una cita que ya tienen: `cita_id`). Cuando se libera un hueco
-- que les encaja, se ofrece al primero; si no responde a tiempo, pasa al siguiente.
create table lista_espera (
  id                 bigint generated always as identity primary key,
  clinica_id         uuid not null references clinicas (id) on delete cascade,
  paciente_id        bigint not null,
  servicio_id        bigint not null,
  profesional_id     bigint,                         -- null = con cualquiera
  modalidad          text check (modalidad in ('presencial', 'online')),
  desde              date not null,
  hasta              date not null,
  franja             text not null default 'cualquiera' check (franja in ('manana', 'tarde', 'cualquiera')),
  cita_id            bigint,                         -- cita que quiere adelantar
  estado             text not null default 'activa'
                     check (estado in ('activa', 'ofrecida', 'aceptada', 'cancelada', 'caducada')),
  oferta_inicio      timestamptz,
  oferta_profesional bigint,
  oferta_caduca_en   timestamptz,
  ofertas_hechas     int not null default 0,
  notas              text,
  origen             text not null default 'app' check (origen in ('app', 'whatsapp', 'telefono')),
  creada_en          timestamptz not null default now(),
  check (hasta >= desde),
  unique (clinica_id, id),
  foreign key (clinica_id, paciente_id) references pacientes (clinica_id, id) on delete cascade,
  foreign key (clinica_id, servicio_id) references servicios (clinica_id, id),
  foreign key (clinica_id, profesional_id) references profesionales (clinica_id, id) on delete set null (profesional_id),
  foreign key (clinica_id, cita_id) references citas (clinica_id, id) on delete set null (cita_id)
);
create index lista_espera_activa on lista_espera (clinica_id, estado, creada_en);
-- Un mismo hueco no se ofrece a dos personas a la vez.
create unique index lista_espera_una_oferta on lista_espera (oferta_profesional, oferta_inicio) where estado = 'ofrecida';

alter table sistema              enable row level security;
alter table canales              enable row level security;
alter table conversaciones       enable row level security;
alter table mensajes             enable row level security;
alter table solicitudes          enable row level security;
alter table plantillas_mensaje   enable row level security;
alter table envios               enable row level security;
alter table formularios          enable row level security;
alter table servicio_formularios enable row level security;
alter table formulario_envios    enable row level security;
alter table lista_espera         enable row level security;

-- =====================================================================
-- Valores por defecto de cada consulta
-- =====================================================================

create function _plantillas_por_defecto(p_clinica uuid) returns void
language sql security definer set search_path = nutricion, extensions, pg_temp as $$
  insert into plantillas_mensaje (clinica_id, clave, texto) values
    (p_clinica, 'confirmacion_cita', 'Hola {paciente}, tu cita en {clinica} queda reservada: {servicio} el {fecha} con {profesional}{lugar}. Si necesitas cambiarla, responde a este mensaje.'),
    (p_clinica, 'recordatorio_cita', 'Hola {paciente}, te recordamos tu cita de {servicio} el {fecha} con {profesional}{lugar}. ¿Nos confirmas que vienes? Responde SÍ, o escríbenos si necesitas cambiarla.'),
    (p_clinica, 'cambio_cita', 'Hola {paciente}, tu cita ha cambiado: {servicio} el {fecha} con {profesional}{lugar}.'),
    (p_clinica, 'cancelacion_cita', 'Hola {paciente}, tu cita de {servicio} del {fecha} está cancelada. Si quieres otra, escríbenos por aquí.'),
    (p_clinica, 'formulario_pendiente', 'Hola {paciente}, para preparar tu cita del {fecha} rellena este cuestionario: {enlace} . Te pedirá {comprobacion} para comprobar que eres tú.'),
    (p_clinica, 'formulario_recordatorio', 'Hola {paciente}, aún no has rellenado el cuestionario para tu cita del {fecha}. Aquí lo tienes: {enlace} . Te pedirá {comprobacion}.'),
    (p_clinica, 'oferta_lista_espera', 'Hola {paciente}, se ha quedado libre un hueco de {servicio} el {fecha} con {profesional}. ¿Lo quieres? Responde SÍ antes de las {caduca} y te lo reservo.'),
    (p_clinica, 'aviso_equipo', 'Tienes una solicitud nueva en {clinica}: {tipo}. Mírala en la aplicación.'),
    (p_clinica, 'mensaje_equipo', '{texto}')
  on conflict do nothing
$$;

-- Cuestionario inicial de ejemplo. El propietario lo revisa y decide con qué servicios se manda.
create function _formulario_por_defecto(p_clinica uuid) returns void
language sql security definer set search_path = nutricion, extensions, pg_temp as $$
  insert into formularios (clinica_id, nombre, descripcion, campos) values (p_clinica, 'Cuestionario de primera visita',
    'Nos ayuda a preparar tu primera consulta. Responde lo que sepas; lo revisaremos juntos en la cita.',
    '[{"clave":"motivo","etiqueta":"¿Por qué quieres venir a consulta?","tipo":"texto_largo","obligatorio":true,"destino":"motivo_consulta"},
      {"clave":"objetivos","etiqueta":"¿Qué te gustaría conseguir?","tipo":"texto_largo","destino":"objetivos"},
      {"clave":"antecedentes","etiqueta":"Enfermedades o problemas de salud que tengas o hayas tenido","tipo":"texto_largo","destino":"antecedentes"},
      {"clave":"alergias","etiqueta":"Alergias alimentarias","tipo":"texto","destino":"alergias"},
      {"clave":"intolerancias","etiqueta":"Intolerancias","tipo":"texto","destino":"intolerancias"},
      {"clave":"medicacion","etiqueta":"Medicación que tomas","tipo":"texto","destino":"medicacion"},
      {"clave":"suplementos","etiqueta":"Suplementos que tomas","tipo":"texto","destino":"suplementos"},
      {"clave":"actividad","etiqueta":"Actividad física","tipo":"opcion","opciones":["Casi ninguna","Ligera (1-2 días)","Moderada (3-4 días)","Alta (5 o más días)"],"destino":"actividad_fisica"},
      {"clave":"comidas","etiqueta":"¿Cuántas comidas haces al día?","tipo":"numero","min":1,"max":10,"destino":"extra"},
      {"clave":"habitos","etiqueta":"Cuéntanos un día normal de comidas","tipo":"texto_largo","destino":"habitos_alimentarios"},
      {"clave":"peso","etiqueta":"Peso aproximado","tipo":"numero","min":20,"max":350,"unidad":"kg","ayuda":"Si no lo sabes, déjalo en blanco: te pesaremos en consulta.","destino":"extra"},
      {"clave":"altura","etiqueta":"Altura","tipo":"numero","min":100,"max":250,"unidad":"cm","destino":"extra"}]'::jsonb)
  on conflict do nothing
$$;

create function _canales_por_defecto(p_clinica uuid) returns void
language sql security definer set search_path = nutricion, extensions, pg_temp as $$
  insert into canales (clinica_id, tipo, identificador) values
    (p_clinica, 'whatsapp', 'simulador-whatsapp-' || p_clinica),
    (p_clinica, 'telefono', 'simulador-telefono-' || p_clinica)
  on conflict do nothing
$$;

create function _clinica_nueva() returns trigger
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
begin
  perform _plantillas_por_defecto(new.id);
  perform _formulario_por_defecto(new.id);
  perform _canales_por_defecto(new.id);
  return null;
end;
$$;
create trigger clinica_nueva after insert on clinicas for each row execute function _clinica_nueva();

select _plantillas_por_defecto(id), _formulario_por_defecto(id), _canales_por_defecto(id) from clinicas;

-- =====================================================================
-- Funciones internas
-- =====================================================================

create function _render(p_texto text, p_vars jsonb) returns text language plpgsql immutable as $$
declare k text; v text; r text := p_texto;
begin
  for k, v in select * from jsonb_each_text(coalesce(p_vars, '{}'::jsonb)) loop
    r := replace(r, '{' || k || '}', coalesce(v, ''));
  end loop;
  return r;
end;
$$;

-- Variables de una cita para las plantillas.
create function _vars_cita(p_cita bigint) returns jsonb
language sql stable security definer set search_path = nutricion, extensions, pg_temp as $$
  select jsonb_build_object(
    'paciente', split_part(trim(pa.nombre), ' ', 1),
    'fecha', fecha_es(ci.inicio, cl.zona_horaria),
    'servicio', se.nombre, 'profesional', pr.nombre, 'clinica', cl.nombre,
    'lugar', case when ci.modalidad = 'online'
                  then ', online' || coalesce(' (enlace: ' || pr.enlace_online || ')', '')
                  else coalesce(', en ' || cl.direccion, '') end)
  from citas ci join clinicas cl on cl.id = ci.clinica_id join pacientes pa on pa.id = ci.paciente_id
  join profesionales pr on pr.id = ci.profesional_id join servicios se on se.id = ci.servicio_id
  where ci.id = p_cita
$$;

-- Busca o crea la conversación de WhatsApp de un teléfono (para guardar lo que se le manda).
create function _conversacion_de(p_clinica uuid, p_canal text, p_contacto text) returns bigint
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare v_id bigint;
begin
  insert into conversaciones (clinica_id, canal, contacto) values (p_clinica, p_canal, p_contacto)
  on conflict (clinica_id, canal, contacto) do update set ultimo_mensaje_en = now()
  returning id into v_id;
  return v_id;
end;
$$;

-- Marca un envío como hecho (de verdad o en el simulador) y lo apunta en la conversación del paciente.
create function _envio_hecho(p_envio bigint, p_estado text, p_id_externo text default null) returns void
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare e envios; v_conv bigint; v_texto text;
begin
  select * into e from envios where id = p_envio for update;
  v_texto := _render(e.texto, jsonb_build_object('enlace',
               case when e.secreto is null then '' when p_estado = 'simulado'
                    then rtrim((select valor from sistema where clave = 'url_app'), '/') || '/#/f/' || e.secreto
                    else '[enlace seguro]' end));
  update envios set estado = p_estado, enviado_en = now(), id_externo = coalesce(p_id_externo, id_externo),
                    secreto = null, ultimo_error = null
  where id = p_envio;
  if e.canal = 'whatsapp' and e.paciente_id is not null then
    v_conv := _conversacion_de(e.clinica_id, 'whatsapp', e.destino);
    insert into mensajes (clinica_id, conversacion_id, direccion, autor, texto, envio_id)
    values (e.clinica_id, v_conv, 'saliente', case when e.tipo = 'mensaje_equipo' then 'equipo' else 'sistema' end,
            v_texto, e.id);
    update conversaciones set ultimo_mensaje_en = now() where id = v_conv;
  end if;
end;
$$;

-- Mete un mensaje en la cola. Devuelve el id del envío, o null si no hay a quién mandarlo o la plantilla está
-- apagada. La clave hace que llamarla dos veces no duplique nada. En modo simulador se da por enviado al momento.
create function _encolar(p_clinica uuid, p_tipo text, p_clave text, p_paciente bigint default null,
                         p_cita bigint default null, p_vars jsonb default '{}'::jsonb,
                         p_programado timestamptz default null, p_secreto text default null,
                         p_destino text default null) returns bigint
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare
  c clinicas; pl plantillas_mensaje; pa pacientes;
  v_canal text; v_destino text; v_id bigint; v_inicio timestamptz;
begin
  select * into c from clinicas where id = p_clinica;
  select * into pl from plantillas_mensaje where clinica_id = p_clinica and clave = p_tipo;
  if pl.clave is null or not pl.activa then return null; end if;
  if p_destino is not null then
    v_canal := 'whatsapp'; v_destino := p_destino;
  else
    select * into pa from pacientes where id = p_paciente and clinica_id = p_clinica;
    if pa.id is null then return null; end if;
    if pa.canal_preferido = 'email' and pa.email is not null then v_canal := 'email'; v_destino := pa.email;
    elsif pa.telefono is not null then v_canal := 'whatsapp'; v_destino := pa.telefono;
    elsif pa.email is not null then v_canal := 'email'; v_destino := pa.email;
    else return null; end if;
  end if;
  select inicio into v_inicio from citas where id = p_cita;
  insert into envios (clinica_id, paciente_id, cita_id, cita_inicio, tipo, canal, destino, texto, secreto, variables,
                      clave_idempotencia, programado_para, proximo_intento)
  values (p_clinica, p_paciente, p_cita, v_inicio, p_tipo, v_canal, v_destino, _render(pl.texto, p_vars - 'enlace'),
          p_secreto, p_vars, p_clave, coalesce(p_programado, now()), coalesce(p_programado, now()))
  on conflict (clinica_id, clave_idempotencia) do nothing
  returning id into v_id;
  if v_id is not null and c.modo_envio = 'simulador' and coalesce(p_programado, now()) <= now() then
    perform _envio_hecho(v_id, 'simulado');
  end if;
  return v_id;
end;
$$;

-- Solicitud para el equipo (y aviso al profesional si tiene móvil de avisos). Sin contenido clínico en el aviso.
create function _solicitud(p_clinica uuid, p_tipo text, p_resumen text, p_paciente bigint default null,
                           p_conversacion bigint default null, p_cita bigint default null, p_urgente boolean default false,
                           p_envio bigint default null, p_contacto text default null) returns bigint
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare v_id bigint; v_prof bigint; v_tel text;
begin
  select profesional_id into v_prof from pacientes where id = p_paciente;
  if p_cita is not null then select profesional_id into v_prof from citas where id = p_cita; end if;
  insert into solicitudes (clinica_id, tipo, paciente_id, profesional_id, conversacion_id, cita_id, envio_id, contacto,
                           resumen, urgente)
  values (p_clinica, p_tipo, p_paciente, v_prof, p_conversacion, p_cita, p_envio, p_contacto,
          left(coalesce(nullif(trim(p_resumen), ''), 'Sin detalle'), 2000), coalesce(p_urgente, false))
  returning id into v_id;
  select telefono_avisos into v_tel from profesionales where id = v_prof;
  if v_tel is not null and p_tipo <> 'envio_fallido' then
    perform _encolar(p_clinica, 'aviso_equipo', 'aviso:solicitud:' || v_id, null, null,
                     jsonb_build_object('clinica', (select nombre from clinicas where id = p_clinica),
                                        'tipo', replace(p_tipo, '_', ' ')), null, null, v_tel);
  end if;
  perform _auditar(p_clinica, 'crear_solicitud', 'solicitud', v_id::text, p_paciente, jsonb_build_object('tipo', p_tipo));
  return v_id;
end;
$$;

create function _token() returns text language sql volatile as $$
  select translate(encode(gen_random_bytes(24), 'base64'), '+/=', '-_')
$$;

create function _huella(p_token text) returns bytea language sql immutable as $$
  select sha256(convert_to(coalesce(p_token, ''), 'UTF8'))
$$;

-- Manda un formulario a un paciente (o reutiliza el que tenga pendiente). Devuelve el id de formulario_envios.
create function _mandar_formulario(p_clinica uuid, p_paciente bigint, p_formulario bigint, p_cita bigint default null,
                                   p_reenviar boolean default false) returns bigint
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare
  f formularios; pa pacientes; v_id bigint; v_token text := _token(); v_caduca timestamptz; v_vars jsonb;
  v_tipo text := 'formulario_pendiente';
begin
  select * into f from formularios where id = p_formulario and clinica_id = p_clinica and activo;
  select * into pa from pacientes where id = p_paciente and clinica_id = p_clinica;
  if f.id is null or pa.id is null then return null; end if;
  select coalesce(max(inicio), now() + interval '14 days') into v_caduca from citas where id = p_cita;
  v_caduca := greatest(v_caduca, now() + interval '2 days');
  select id into v_id from formulario_envios
  where paciente_id = p_paciente and formulario_id = p_formulario and estado = 'pendiente' and caduca_en > now()
  order by id desc limit 1;
  if v_id is not null then
    if not p_reenviar then
      update formulario_envios set cita_id = coalesce(p_cita, cita_id), caduca_en = greatest(caduca_en, v_caduca)
      where id = v_id;
      return v_id;
    end if;
    -- Reenvío: enlace nuevo; el anterior deja de valer.
    update formulario_envios set token_hash = _huella(v_token), caduca_en = greatest(caduca_en, v_caduca),
                                 recordado_en = now(), cita_id = coalesce(p_cita, cita_id)
    where id = v_id;
    v_tipo := 'formulario_recordatorio';
  else
    insert into formulario_envios (clinica_id, formulario_id, version, campos, paciente_id, cita_id, token_hash, caduca_en,
                                   creado_por)
    values (p_clinica, f.id, f.version, f.campos, p_paciente, p_cita, _huella(v_token), v_caduca, auth.uid())
    returning id into v_id;
  end if;
  v_vars := coalesce(_vars_cita(p_cita), jsonb_build_object('paciente', split_part(trim(pa.nombre), ' ', 1),
                     'clinica', (select nombre from clinicas where id = p_clinica), 'fecha', 'próxima'))
            || jsonb_build_object('comprobacion', case when pa.fecha_nacimiento is not null then 'tu fecha de nacimiento'
                                                       else 'los 4 últimos dígitos de tu móvil' end);
  perform _encolar(p_clinica, v_tipo, 'formulario:' || v_id || ':' || encode(_huella(v_token), 'hex'), p_paciente,
                   p_cita, v_vars, null, v_token);
  return v_id;
end;
$$;

-- Ofrece un hueco que se acaba de liberar a la primera persona de la lista de espera a la que le encaje.
create function _ofrecer_hueco(p_clinica uuid, p_profesional bigint, p_inicio timestamptz,
                               p_excluir bigint default null) returns bigint
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare c clinicas; le lista_espera; v_fin timestamptz; v_vars jsonb; s servicios; pr profesionales;
begin
  select * into c from clinicas where id = p_clinica;
  if p_inicio < now() + make_interval(mins => c.antelacion_minima_min) then return null; end if;
  select * into pr from profesionales where id = p_profesional;
  for le in
    select l.* from lista_espera l
    join servicios sv on sv.id = l.servicio_id
    join profesional_servicios ps on ps.servicio_id = l.servicio_id and ps.profesional_id = p_profesional
    where l.clinica_id = p_clinica and l.estado = 'activa' and l.id is distinct from p_excluir
      and (l.profesional_id is null or l.profesional_id = p_profesional)
      and (p_inicio at time zone c.zona_horaria)::date between l.desde and l.hasta
      and (l.franja = 'cualquiera'
           or (l.franja = 'manana' and (p_inicio at time zone c.zona_horaria)::time < '14:00')
           or (l.franja = 'tarde' and (p_inicio at time zone c.zona_horaria)::time >= '14:00'))
      -- quien quiere adelantar una cita, solo si el hueco es antes que la que ya tiene
      and (l.cita_id is null or exists (select 1 from citas x where x.id = l.cita_id and x.estado = 'reservada'
                                         and x.inicio > p_inicio))
    order by l.creada_en, l.id
    for update of l skip locked
  loop
    select * into s from servicios where id = le.servicio_id;
    v_fin := p_inicio + make_interval(mins => s.duracion_min);
    continue when not _libre(p_profesional, p_inicio, v_fin, coalesce(le.modalidad, case when s.presencial then 'presencial' else 'online' end),
                             le.cita_id);
    continue when exists (select 1 from citas x where x.paciente_id = le.paciente_id and x.estado = 'reservada'
                            and x.id is distinct from le.cita_id and tstzrange(x.inicio, x.fin) && tstzrange(p_inicio, v_fin));
    begin
      update lista_espera set estado = 'ofrecida', oferta_inicio = p_inicio, oferta_profesional = p_profesional,
             oferta_caduca_en = least(now() + make_interval(mins => c.oferta_espera_minutos),
                                      p_inicio - make_interval(mins => c.antelacion_minima_min)),
             ofertas_hechas = ofertas_hechas + 1
      where id = le.id;
    exception when unique_violation then
      return null;   -- ese hueco ya está ofrecido a otra persona
    end;
    v_vars := jsonb_build_object('paciente', (select split_part(trim(nombre), ' ', 1) from pacientes where id = le.paciente_id),
                                 'servicio', s.nombre, 'profesional', pr.nombre, 'clinica', c.nombre,
                                 'fecha', fecha_es(p_inicio, c.zona_horaria),
                                 'caduca', (select to_char(oferta_caduca_en at time zone c.zona_horaria, 'HH24:MI')
                                            from lista_espera where id = le.id));
    perform _encolar(p_clinica, 'oferta_lista_espera', 'espera:' || le.id || ':' || extract(epoch from p_inicio)::bigint,
                     le.paciente_id, null, v_vars);
    perform _auditar(p_clinica, 'ofrecer_hueco', 'lista_espera', le.id::text, le.paciente_id);
    return le.id;
  end loop;
  return null;
end;
$$;

-- Lo que pasa solo cuando se reserva, cambia o cancela una cita, venga de donde venga (agenda, WhatsApp, teléfono):
-- confirmación, aviso de cambio o de cancelación, formularios del servicio, descartar recordatorios viejos y
-- ofrecer el hueco libre a la lista de espera. Si la acción viene del propio WhatsApp, la IA ya lo ha dicho en el
-- chat y no se manda un mensaje aparte.
create function _citas_despues() returns trigger
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare
  c clinicas; v_desde_chat boolean := coalesce(current_setting('nutricion.actor', true), '') = 'whatsapp';
  f record;
begin
  select * into c from clinicas where id = new.clinica_id;
  if tg_op = 'INSERT' then
    if new.estado = 'reservada' and new.inicio > now() then
      if c.enviar_confirmacion and not v_desde_chat then
        perform _encolar(new.clinica_id, 'confirmacion_cita', 'confirmacion:' || new.id, new.paciente_id, new.id,
                         _vars_cita(new.id));
      end if;
      for f in select sf.formulario_id from servicio_formularios sf join formularios fo on fo.id = sf.formulario_id
               where sf.servicio_id = new.servicio_id and fo.activo
                 and not exists (select 1 from formulario_envios fe where fe.paciente_id = new.paciente_id
                                   and fe.formulario_id = sf.formulario_id and fe.estado in ('completado', 'revisado'))
      loop
        perform _mandar_formulario(new.clinica_id, new.paciente_id, f.formulario_id, new.id);
      end loop;
    end if;
    return null;
  end if;

  if old.estado = 'reservada' and new.estado = 'cancelada' then
    update envios set estado = 'cancelado', secreto = null
    where cita_id = new.id and estado = 'pendiente' and tipo in ('confirmacion_cita', 'recordatorio_cita', 'cambio_cita');
    if new.inicio > now() then
      if not v_desde_chat then
        perform _encolar(new.clinica_id, 'cancelacion_cita', 'cancelacion:' || new.id, new.paciente_id, new.id,
                         _vars_cita(new.id));
      end if;
      perform _ofrecer_hueco(new.clinica_id, new.profesional_id, new.inicio);
    end if;
    update lista_espera set estado = 'cancelada' where cita_id = new.id and estado in ('activa', 'ofrecida');
  elsif new.estado = 'reservada' and (old.inicio <> new.inicio or old.profesional_id <> new.profesional_id) then
    update envios set estado = 'cancelado', secreto = null
    where cita_id = new.id and estado = 'pendiente' and tipo in ('confirmacion_cita', 'recordatorio_cita', 'cambio_cita');
    if new.inicio > now() and not v_desde_chat then
      perform _encolar(new.clinica_id, 'cambio_cita', 'cambio:' || new.id || ':' || extract(epoch from new.inicio)::bigint
                       || ':' || new.profesional_id, new.paciente_id, new.id, _vars_cita(new.id));
    end if;
    if old.inicio > now() then
      perform _ofrecer_hueco(new.clinica_id, old.profesional_id, old.inicio);
    end if;
  end if;
  return null;
end;
$$;
create trigger citas_despues after insert or update of estado, inicio, profesional_id on citas
for each row execute function _citas_despues();

-- =====================================================================
-- Canales (solo service_role: n8n). Siempre sobre una conversación.
-- =====================================================================

create function _conv(p_conversacion bigint) returns conversaciones
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare v conversaciones;
begin
  select * into v from conversaciones where id = p_conversacion;
  if v.id is null then raise exception 'conversacion_no_existe' using errcode = '22023'; end if;
  perform set_config('nutricion.actor', v.canal, true);
  return v;
end;
$$;

-- Paciente comprobado en esta conversación, o null.
create function _verificado(v conversaciones) returns bigint language sql stable as $$
  select case when v.paciente_id is not null and v.verificada_hasta > now() then v.paciente_id end
$$;

create function _cita_canal_json(p_cita bigint) returns jsonb
language sql stable security definer set search_path = nutricion, extensions, pg_temp as $$
  select jsonb_build_object('cita_id', ci.id, 'inicio', _local(ci.inicio, cl.zona_horaria),
    'fecha_texto', fecha_es(ci.inicio, cl.zona_horaria), 'servicio', se.nombre, 'profesional', pr.nombre,
    'modalidad', ci.modalidad, 'enlace_online', case when ci.modalidad = 'online' then pr.enlace_online end,
    'confirmada', ci.confirmada_en is not null,
    'modificable', ci.inicio - now() >= make_interval(hours => cl.horas_minimas_cambio))
  from citas ci join clinicas cl on cl.id = ci.clinica_id join servicios se on se.id = ci.servicio_id
  join profesionales pr on pr.id = ci.profesional_id where ci.id = p_cita
$$;

-- Lo que el agente necesita en cada turno: datos de la consulta, calendario, y (si la identidad está comprobada)
-- el paciente y sus citas. No dice nunca si un teléfono tiene pacientes ni cuántos.
create function canal_contexto(p_conversacion bigint) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare v conversaciones := _conv(p_conversacion); c clinicas; v_pac bigint; v_hoy date;
begin
  select * into c from clinicas where id = v.clinica_id;
  v_hoy := _hoy(c.zona_horaria);
  v_pac := _verificado(v);
  return jsonb_build_object(
    'conversacion_id', v.id, 'canal', v.canal, 'ahora', _local(now(), c.zona_horaria),
    'clinica', jsonb_build_object('nombre', c.nombre, 'asistente', c.nombre_asistente, 'telefono', c.telefono,
        'direccion', c.direccion, 'web', c.web, 'horas_minimas_cambio', c.horas_minimas_cambio,
        'antelacion_minima_min', c.antelacion_minima_min, 'precios_confirmados', c.precios_confirmados,
        'horario', (select coalesce(jsonb_agg(jsonb_build_object('dia', d.n, 'dia_texto',
                        (array['lunes','martes','miércoles','jueves','viernes','sábado','domingo'])[d.n],
                        'tramos', (select jsonb_agg(distinct to_char(h.hora_inicio, 'HH24:MI') || '-' || to_char(h.hora_fin, 'HH24:MI'))
                                   from horarios h join profesionales p on p.id = h.profesional_id and p.activo
                                   where h.clinica_id = c.id and h.dia_semana = d.n)) order by d.n), '[]'::jsonb)
                    from generate_series(1, 7) d(n))),
    'servicios', (select coalesce(jsonb_agg(jsonb_build_object('servicio_id', s.id, 'nombre', s.nombre,
                     'descripcion', s.descripcion, 'tipo', s.tipo, 'duracion_min', s.duracion_min,
                     'precio_euros', case when c.precios_confirmados then round(s.precio_centimos / 100.0, 2) end,
                     'presencial', s.presencial, 'online', s.online,
                     'profesionales', (select jsonb_agg(ps.profesional_id) from profesional_servicios ps where ps.servicio_id = s.id))
                   order by s.orden, s.id), '[]'::jsonb)
                  from servicios s where s.clinica_id = c.id and s.activo and s.reservable_canales),
    'profesionales', (select coalesce(jsonb_agg(jsonb_build_object('profesional_id', p.id, 'nombre', p.nombre,
                         'especialidades', p.especialidades) order by p.orden, p.id), '[]'::jsonb)
                      from profesionales p where p.clinica_id = c.id and p.activo),
    'calendario', (select jsonb_agg(jsonb_build_object('fecha', d::date, 'texto',
                      (array['lunes','martes','miércoles','jueves','viernes','sábado','domingo'])[extract(isodow from d)::int]
                      || ' ' || extract(day from d)::int || ' de ' ||
                      (array['enero','febrero','marzo','abril','mayo','junio','julio','agosto','septiembre','octubre',
                             'noviembre','diciembre'])[extract(month from d)::int]) order by d)
                   from generate_series(v_hoy, v_hoy + 20, interval '1 day') d),
    'identidad', jsonb_build_object('comprobada', v_pac is not null,
        'bloqueada', coalesce(v.verif_bloqueo_hasta > now(), false)),
    'paciente', case when v_pac is not null then (
        select jsonb_build_object('nombre', p.nombre, 'apellidos', p.apellidos,
          'profesional_habitual_id', p.profesional_id, 'modalidad_preferida', p.modalidad_preferida,
          'proximas_citas', (select coalesce(jsonb_agg(_cita_canal_json(x.id) order by x.inicio), '[]'::jsonb)
                             from citas x where x.paciente_id = p.id and x.estado = 'reservada' and x.inicio > now()),
          'formularios_pendientes', (select count(*) from formulario_envios fe where fe.paciente_id = p.id
                                       and fe.estado = 'pendiente' and fe.caduca_en > now()),
          'oferta_lista_espera', (select jsonb_build_object('fecha_texto', fecha_es(l.oferta_inicio, c.zona_horaria),
                                     'servicio', s.nombre, 'profesional', pr.nombre,
                                     'caduca', _local(l.oferta_caduca_en, c.zona_horaria))
                                  from lista_espera l join servicios s on s.id = l.servicio_id
                                  join profesionales pr on pr.id = l.oferta_profesional
                                  where l.paciente_id = p.id and l.estado = 'ofrecida' and l.oferta_caduca_en > now()
                                  order by l.id limit 1))
        from pacientes p where p.id = v_pac) end,
    'mensajes_recientes', (select coalesce(jsonb_agg(jsonb_build_object('autor', m.autor, 'texto', m.texto,
                              'cuando', _local(m.creado_en, c.zona_horaria)) order by m.id), '[]'::jsonb)
                           from (select * from mensajes where conversacion_id = v.id order by id desc limit 20) m));
end;
$$;

-- Entrada de un mensaje (o del inicio de una llamada). `p_destino` es el identificador del canal que manda el
-- proveedor; con él se sabe la consulta. Si el mensaje ya llegó (mismo id_externo), no se procesa otra vez.
create function canal_entrada(p_canal text, p_destino text, p_contacto text, p_texto text, p_id_externo text default null,
                              p_nombre_perfil text default null) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare ca canales; v_tel text := normalizar_telefono(p_contacto); v_conv bigint; v_dup boolean := false; v conversaciones;
begin
  select * into ca from canales where identificador = p_destino and tipo = p_canal;
  if ca.id is null then return jsonb_build_object('ok', false, 'motivo', 'canal_desconocido'); end if;
  if v_tel is null then return jsonb_build_object('ok', false, 'motivo', 'telefono_no_valido'); end if;
  perform set_config('nutricion.actor', p_canal, true);
  insert into conversaciones (clinica_id, canal, contacto, nombre_perfil, ultimo_entrante_en)
  values (ca.clinica_id, p_canal, v_tel, left(p_nombre_perfil, 80), now())
  on conflict (clinica_id, canal, contacto) do update
    set ultimo_entrante_en = now(), ultimo_mensaje_en = now(),
        nombre_perfil = coalesce(excluded.nombre_perfil, conversaciones.nombre_perfil)
  returning id into v_conv;
  begin
    insert into mensajes (clinica_id, conversacion_id, direccion, autor, texto, id_externo)
    values (ca.clinica_id, v_conv, 'entrante', 'paciente', left(coalesce(p_texto, ''), 4000), p_id_externo);
  exception when unique_violation then
    v_dup := true;
  end;
  select * into v from conversaciones where id = v_conv;
  return jsonb_build_object('ok', true, 'duplicado', v_dup, 'conversacion_id', v_conv,
    'ia_activa', not v_dup and not v.ia_pausada and ca.estado <> 'desactivado',
    'contexto', case when not v_dup and not v.ia_pausada then canal_contexto(v_conv) end);
end;
$$;

-- Lo que contesta la IA (o el resumen de una llamada). Idempotente con id_externo.
create function canal_registrar(p_conversacion bigint, p_texto text, p_autor text default 'ia', p_id_externo text default null)
returns jsonb language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare v conversaciones := _conv(p_conversacion);
begin
  if p_autor not in ('ia', 'sistema') then return jsonb_build_object('ok', false, 'motivo', 'valor_no_valido'); end if;
  insert into mensajes (clinica_id, conversacion_id, direccion, autor, texto, id_externo)
  values (v.clinica_id, v.id, 'saliente', p_autor, left(coalesce(p_texto, ''), 4000), p_id_externo)
  on conflict (clinica_id, id_externo) do nothing;
  update conversaciones set ultimo_mensaje_en = now() where id = v.id;
  return jsonb_build_object('ok', true);
end;
$$;

-- Comprobar identidad: fecha de nacimiento de alguien con el teléfono de la conversación. Si varias personas
-- comparten teléfono y fecha (gemelos), hace falta el nombre. 3 fallos: bloqueo de 15 minutos.
create function canal_verificar(p_conversacion bigint, p_fecha_nacimiento text, p_nombre text default null) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare v conversaciones := _conv(p_conversacion); v_fecha date; v_ids bigint[]; c clinicas;
begin
  select * into c from clinicas where id = v.clinica_id;
  if v.verif_bloqueo_hasta > now() then
    return jsonb_build_object('ok', false, 'motivo', 'bloqueada', 'hasta', _local(v.verif_bloqueo_hasta, c.zona_horaria));
  end if;
  begin v_fecha := p_fecha_nacimiento::date;
  exception when others then return jsonb_build_object('ok', false, 'motivo', 'fecha_no_valida'); end;
  select array_agg(id order by id) into v_ids from pacientes
  where clinica_id = v.clinica_id and telefono = v.contacto and fecha_nacimiento = v_fecha
    and (p_nombre is null or lower(split_part(trim(nombre), ' ', 1)) = lower(split_part(trim(p_nombre), ' ', 1)));
  if coalesce(array_length(v_ids, 1), 0) = 1 then
    update conversaciones set paciente_id = v_ids[1], verif_fallos = 0, verif_bloqueo_hasta = null,
           verificada_hasta = now() + make_interval(mins => c.verificacion_minutos)
    where id = v.id;
    perform _auditar(v.clinica_id, 'verificar_identidad', 'conversacion', v.id::text, v_ids[1]);
    return jsonb_build_object('ok', true, 'contexto', canal_contexto(v.id));
  end if;
  if coalesce(array_length(v_ids, 1), 0) > 1 then
    return jsonb_build_object('ok', false, 'motivo', 'falta_nombre');
  end if;
  update conversaciones set verif_fallos = case when verif_fallos + 1 >= 3 then 0 else verif_fallos + 1 end,
         verif_bloqueo_hasta = case when verif_fallos + 1 >= 3 then now() + interval '15 minutes' end
  where id = v.id;
  perform _auditar(v.clinica_id, 'verificar_identidad_fallo', 'conversacion', v.id::text);
  return jsonb_build_object('ok', false, 'motivo', 'no_coincide');
end;
$$;

-- Huecos para un servicio reservable por los canales. franja: manana | tarde | cualquiera.
create function canal_huecos(p_conversacion bigint, p_servicio bigint, p_desde text default null, p_dias int default 7,
                             p_profesional bigint default null, p_modalidad text default null,
                             p_franja text default 'cualquiera') returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare v conversaciones := _conv(p_conversacion); c clinicas; s servicios; v_desde date; v_mod text; v_pref bigint;
begin
  select * into c from clinicas where id = v.clinica_id;
  select * into s from servicios where id = p_servicio and clinica_id = c.id and activo and reservable_canales;
  if s.id is null then return jsonb_build_object('ok', false, 'motivo', 'servicio_no_existe'); end if;
  v_mod := coalesce(nullif(p_modalidad, ''), case when s.presencial then 'presencial' else 'online' end);
  if (v_mod = 'presencial' and not s.presencial) or (v_mod = 'online' and not s.online) then
    return jsonb_build_object('ok', false, 'motivo', 'modalidad_no_disponible');
  end if;
  v_desde := coalesce(nullif(p_desde, '')::date, _hoy(c.zona_horaria));
  select profesional_id into v_pref from pacientes where id = _verificado(v);
  return jsonb_build_object('ok', true, 'servicio', s.nombre, 'duracion_min', s.duracion_min, 'modalidad', v_mod,
    'huecos', (select coalesce(jsonb_agg(jsonb_build_object('inicio', _local(h.inicio, c.zona_horaria),
                  'fecha_texto', fecha_es(h.inicio, c.zona_horaria), 'profesional_id', h.profesional_id,
                  'profesional', h.profesional) order by h.inicio), '[]'::jsonb)
               from (select * from _huecos(c.id, s.id, nullif(p_profesional, 0), v_desde::timestamp at time zone c.zona_horaria,
                                           (v_desde + least(greatest(coalesce(p_dias, 7), 1), 30))::timestamp at time zone c.zona_horaria,
                                           v_mod, v_pref, 60, 6, true) h0
                     where coalesce(p_franja, 'cualquiera') = 'cualquiera'
                        or (p_franja = 'manana' and (h0.inicio at time zone c.zona_horaria)::time < '14:00')
                        or (p_franja = 'tarde' and (h0.inicio at time zone c.zona_horaria)::time >= '14:00')
                     order by h0.inicio limit 8) h));
end;
$$;

-- Reserva desde un canal. Si la identidad está comprobada, la cita es para esa persona (salvo p_para_otra).
-- Si no, se busca por teléfono + fecha de nacimiento + nombre; si no existe, se da de alta como paciente nuevo.
create function canal_reservar(p_conversacion bigint, p_servicio bigint, p_inicio text, p_profesional bigint default null,
                               p_modalidad text default null, p_nombre text default null, p_apellidos text default null,
                               p_fecha_nacimiento text default null, p_para_otra boolean default false,
                               p_motivo text default null, p_clave text default null) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare
  v conversaciones := _conv(p_conversacion); c clinicas; v_pac bigint; v_fecha date; v_ids bigint[]; r jsonb;
  v_ini timestamptz; v_nuevo boolean := false;
begin
  select * into c from clinicas where id = v.clinica_id;
  if not exists (select 1 from servicios where id = p_servicio and clinica_id = c.id and activo and reservable_canales) then
    return jsonb_build_object('ok', false, 'motivo', 'servicio_no_existe');
  end if;
  v_ini := _desde_local(p_inicio, c.zona_horaria);
  -- Reintento del mismo mensaje: devuelve lo que ya se hizo antes de crear a nadie.
  if exists (select 1 from citas where clinica_id = c.id
             and clave_idempotencia = coalesce(p_clave, 'conv:' || v.id || ':' || p_servicio || ':' || p_inicio)) then
    select id into v_pac from citas where clinica_id = c.id
      and clave_idempotencia = coalesce(p_clave, 'conv:' || v.id || ':' || p_servicio || ':' || p_inicio);
    return jsonb_build_object('ok', true, 'repetida', true, 'cita', _cita_canal_json(v_pac));
  end if;

  if not coalesce(p_para_otra, false) then v_pac := _verificado(v); end if;
  if v_pac is null then
    if nullif(trim(p_nombre), '') is null or nullif(trim(p_apellidos), '') is null then
      return jsonb_build_object('ok', false, 'motivo', 'falta_nombre');
    end if;
    begin v_fecha := nullif(p_fecha_nacimiento, '')::date;
    exception when others then return jsonb_build_object('ok', false, 'motivo', 'fecha_no_valida'); end;
    if v_fecha is null then return jsonb_build_object('ok', false, 'motivo', 'falta_fecha_nacimiento'); end if;
    if v_fecha > current_date or v_fecha < current_date - interval '120 years' then
      return jsonb_build_object('ok', false, 'motivo', 'fecha_no_valida');
    end if;
    select array_agg(id) into v_ids from pacientes
    where clinica_id = c.id and telefono = v.contacto and fecha_nacimiento = v_fecha
      and lower(split_part(trim(nombre), ' ', 1)) = lower(split_part(trim(p_nombre), ' ', 1));
    if coalesce(array_length(v_ids, 1), 0) = 1 then
      v_pac := v_ids[1];
    else
      insert into pacientes (clinica_id, nombre, apellidos, telefono, fecha_nacimiento, origen,
                             modalidad_preferida)
      values (c.id, left(trim(p_nombre), 80), left(trim(p_apellidos), 120), v.contacto, v_fecha, v.canal,
              nullif(p_modalidad, ''))
      returning id into v_pac;
      v_nuevo := true;
    end if;
  end if;

  r := _reservar(c.id, v_pac, p_servicio, nullif(p_profesional, 0), v_ini, nullif(p_modalidad, ''), v.canal,
                 coalesce(p_clave, 'conv:' || v.id || ':' || p_servicio || ':' || p_inicio), false, null, null,
                 left(p_motivo, 300));
  if not (r->>'ok')::boolean then
    if v_nuevo then delete from pacientes where id = v_pac; end if;   -- no dejamos fichas vacías por un intento fallido
    return r;
  end if;
  if v_nuevo then
    perform _auditar(c.id, 'crear_paciente', 'paciente', v_pac::text, v_pac, jsonb_build_object('origen', v.canal));
  end if;
  -- Quien acaba de dar sus datos y reservar queda identificado en la conversación (si la cita es suya).
  if not coalesce(p_para_otra, false) then
    update conversaciones set paciente_id = v_pac,
           verificada_hasta = now() + make_interval(mins => c.verificacion_minutos)
    where id = v.id;
  end if;
  return jsonb_build_object('ok', true, 'paciente_nuevo', v_nuevo, 'cita', _cita_canal_json((r->'cita'->>'id')::bigint),
    'formulario_enviado', exists (select 1 from formulario_envios where cita_id = (r->'cita'->>'id')::bigint));
end;
$$;

create function canal_mis_citas(p_conversacion bigint) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare v conversaciones := _conv(p_conversacion); v_pac bigint := _verificado(v);
begin
  if v_pac is null then return jsonb_build_object('ok', false, 'motivo', 'identidad_no_comprobada'); end if;
  return jsonb_build_object('ok', true, 'citas', (select coalesce(jsonb_agg(_cita_canal_json(id) order by inicio), '[]'::jsonb)
                                                  from citas where paciente_id = v_pac and estado = 'reservada' and inicio > now()));
end;
$$;

-- Cita del paciente comprobado, o motivo por el que no se puede tocar.
create function _cita_del_canal(v conversaciones, p_cita bigint, out ci citas, out motivo text)
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare v_pac bigint := _verificado(v); c clinicas;
begin
  if v_pac is null then motivo := 'identidad_no_comprobada'; return; end if;
  select * into ci from citas where id = p_cita and clinica_id = v.clinica_id and paciente_id = v_pac;
  if ci.id is null then motivo := 'cita_no_existe'; return; end if;
  if ci.estado <> 'reservada' or ci.inicio <= now() then motivo := 'cita_no_modificable'; return; end if;
  select * into c from clinicas where id = v.clinica_id;
  if ci.inicio - now() < make_interval(hours => c.horas_minimas_cambio) then motivo := 'fuera_de_plazo'; end if;
end;
$$;

-- Cambio por el canal. Fuera de plazo no se cambia: se crea una solicitud para que el equipo lo valore.
create function canal_cambiar(p_conversacion bigint, p_cita bigint, p_inicio text, p_profesional bigint default null)
returns jsonb language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare v conversaciones := _conv(p_conversacion); x record; r jsonb;
begin
  select * into x from _cita_del_canal(v, p_cita);
  if x.motivo = 'fuera_de_plazo' then
    perform _solicitud(v.clinica_id, 'cambio_fuera_plazo',
      'Quiere cambiar la cita del ' || fecha_es((x.ci).inicio, _tz(v.clinica_id)) || coalesce(' a ' || p_inicio, ''),
      (x.ci).paciente_id, v.id, (x.ci).id, false, null, v.contacto);
    return jsonb_build_object('ok', false, 'motivo', 'fuera_de_plazo', 'solicitud_creada', true);
  end if;
  if x.motivo is not null then return jsonb_build_object('ok', false, 'motivo', x.motivo); end if;
  r := _cambiar(v.clinica_id, p_cita, _desde_local(p_inicio, _tz(v.clinica_id)), nullif(p_profesional, 0), null, false, null, true);
  if (r->>'ok')::boolean then return jsonb_build_object('ok', true, 'cita', _cita_canal_json(p_cita)); end if;
  return r;
end;
$$;

create function canal_cancelar(p_conversacion bigint, p_cita bigint, p_motivo text default null) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare v conversaciones := _conv(p_conversacion); x record; r jsonb;
begin
  select * into x from _cita_del_canal(v, p_cita);
  if x.motivo = 'fuera_de_plazo' then
    perform _solicitud(v.clinica_id, 'cancelacion_fuera_plazo',
      'Quiere cancelar la cita del ' || fecha_es((x.ci).inicio, _tz(v.clinica_id)) || coalesce('. Motivo: ' || p_motivo, ''),
      (x.ci).paciente_id, v.id, (x.ci).id, false, null, v.contacto);
    return jsonb_build_object('ok', false, 'motivo', 'fuera_de_plazo', 'solicitud_creada', true);
  end if;
  if x.motivo is not null then return jsonb_build_object('ok', false, 'motivo', x.motivo); end if;
  r := _cancelar(v.clinica_id, p_cita, 'paciente', p_motivo);
  if (r->>'ok')::boolean then return jsonb_build_object('ok', true, 'cita', _cita_canal_json(p_cita)); end if;
  return r;
end;
$$;

-- El paciente confirma que viene (respuesta al recordatorio).
create function canal_confirmar_asistencia(p_conversacion bigint, p_cita bigint) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare v conversaciones := _conv(p_conversacion); v_pac bigint := _verificado(v); v_id bigint;
begin
  -- Basta con que el teléfono sea el de la cita: confirmar asistencia no revela ni cambia nada.
  update citas set confirmada_en = coalesce(confirmada_en, now()), actualizada_en = now()
  where id = p_cita and clinica_id = v.clinica_id and estado = 'reservada' and inicio > now()
    and (paciente_id = v_pac or paciente_id in (select id from pacientes where clinica_id = v.clinica_id and telefono = v.contacto))
  returning id into v_id;
  if v_id is null then return jsonb_build_object('ok', false, 'motivo', 'cita_no_existe'); end if;
  perform _auditar(v.clinica_id, 'confirmar_asistencia', 'cita', v_id::text, (select paciente_id from citas where id = v_id));
  return jsonb_build_object('ok', true);
end;
$$;

-- Confirmación de asistencia sin comprobar identidad: la cita más próxima con recordatorio enviado a este teléfono.
create function canal_confirmar_proxima(p_conversacion bigint) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare v conversaciones := _conv(p_conversacion); v_cita bigint;
begin
  select e.cita_id into v_cita from envios e join citas ci on ci.id = e.cita_id
  where e.clinica_id = v.clinica_id and e.destino = v.contacto and e.tipo = 'recordatorio_cita'
    and e.estado in ('enviado', 'simulado') and ci.estado = 'reservada' and ci.inicio > now()
  order by ci.inicio limit 1;
  if v_cita is null then return jsonb_build_object('ok', false, 'motivo', 'sin_recordatorio'); end if;
  perform canal_confirmar_asistencia(p_conversacion, v_cita);
  return jsonb_build_object('ok', true, 'fecha_texto', fecha_es((select inicio from citas where id = v_cita), _tz(v.clinica_id)));
end;
$$;

create function canal_lista_espera(p_conversacion bigint, p_servicio bigint, p_desde text default null,
                                   p_hasta text default null, p_franja text default 'cualquiera',
                                   p_profesional bigint default null, p_cita bigint default null) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare v conversaciones := _conv(p_conversacion); v_pac bigint := _verificado(v); v_id bigint; c clinicas;
begin
  if v_pac is null then return jsonb_build_object('ok', false, 'motivo', 'identidad_no_comprobada'); end if;
  select * into c from clinicas where id = v.clinica_id;
  if not exists (select 1 from servicios where id = p_servicio and clinica_id = c.id and activo and reservable_canales) then
    return jsonb_build_object('ok', false, 'motivo', 'servicio_no_existe');
  end if;
  if p_cita is not null and not exists (select 1 from citas where id = p_cita and paciente_id = v_pac and estado = 'reservada') then
    return jsonb_build_object('ok', false, 'motivo', 'cita_no_existe');
  end if;
  if exists (select 1 from lista_espera where paciente_id = v_pac and servicio_id = p_servicio and estado in ('activa', 'ofrecida')) then
    return jsonb_build_object('ok', true, 'ya_estaba', true);
  end if;
  insert into lista_espera (clinica_id, paciente_id, servicio_id, profesional_id, desde, hasta, franja, cita_id, origen)
  values (c.id, v_pac, p_servicio, nullif(p_profesional, 0),
          coalesce(nullif(p_desde, '')::date, _hoy(c.zona_horaria)),
          coalesce(nullif(p_hasta, '')::date, coalesce((select (inicio at time zone c.zona_horaria)::date - 1 from citas where id = p_cita),
                                                       _hoy(c.zona_horaria) + 30)),
          coalesce(nullif(p_franja, ''), 'cualquiera'), p_cita, v.canal)
  returning id into v_id;
  perform _auditar(c.id, 'apuntar_lista_espera', 'lista_espera', v_id::text, v_pac);
  return jsonb_build_object('ok', true, 'id', v_id);
end;
$$;

-- Acepta el hueco ofrecido: reserva (o mueve la cita que quería adelantar).
create function canal_aceptar_oferta(p_conversacion bigint) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare v conversaciones := _conv(p_conversacion); v_pac bigint := _verificado(v); le lista_espera; r jsonb;
begin
  if v_pac is null then return jsonb_build_object('ok', false, 'motivo', 'identidad_no_comprobada'); end if;
  select * into le from lista_espera where paciente_id = v_pac and estado = 'ofrecida' order by id limit 1 for update;
  if le.id is null then return jsonb_build_object('ok', false, 'motivo', 'sin_oferta'); end if;
  if le.oferta_caduca_en < now() then return jsonb_build_object('ok', false, 'motivo', 'oferta_caducada'); end if;
  if le.cita_id is not null and exists (select 1 from citas where id = le.cita_id and estado = 'reservada') then
    -- Mover la cita: el plazo de cambio no aplica, es la consulta quien lo ofrece.
    r := _cambiar(v.clinica_id, le.cita_id, le.oferta_inicio, le.oferta_profesional, le.modalidad, false, null, true);
  else
    r := _reservar(v.clinica_id, v_pac, le.servicio_id, le.oferta_profesional, le.oferta_inicio, le.modalidad, v.canal,
                   'espera:' || le.id || ':' || extract(epoch from le.oferta_inicio)::bigint);
  end if;
  if not (r->>'ok')::boolean then
    update lista_espera set estado = 'activa', oferta_inicio = null, oferta_profesional = null, oferta_caduca_en = null
    where id = le.id;
    return jsonb_build_object('ok', false, 'motivo', 'hueco_no_disponible');
  end if;
  update lista_espera set estado = 'aceptada' where id = le.id;
  return jsonb_build_object('ok', true, 'cita', _cita_canal_json((r->'cita'->>'id')::bigint));
end;
$$;

create function canal_rechazar_oferta(p_conversacion bigint, p_salir_de_lista boolean default false) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare v conversaciones := _conv(p_conversacion); v_pac bigint := _verificado(v); le lista_espera;
begin
  if v_pac is null then return jsonb_build_object('ok', false, 'motivo', 'identidad_no_comprobada'); end if;
  select * into le from lista_espera where paciente_id = v_pac and estado = 'ofrecida' order by id limit 1 for update;
  if le.id is null then return jsonb_build_object('ok', false, 'motivo', 'sin_oferta'); end if;
  update lista_espera set estado = case when p_salir_de_lista then 'cancelada' else 'activa' end,
         oferta_inicio = null, oferta_profesional = null, oferta_caduca_en = null
  where id = le.id;
  perform _ofrecer_hueco(v.clinica_id, le.oferta_profesional, le.oferta_inicio, le.id);
  return jsonb_build_object('ok', true);
end;
$$;

-- Pasar algo al equipo. Devuelve ok solo si queda creada: la IA no puede decir "te llamarán" si no.
-- tipo pregunta_clinica: va al profesional del paciente y recepción no ve el resumen.
create function canal_derivar(p_conversacion bigint, p_tipo text, p_resumen text, p_urgente boolean default false)
returns jsonb language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare v conversaciones := _conv(p_conversacion); v_id bigint;
begin
  if p_tipo not in ('pregunta_clinica', 'pregunta_sin_respuesta', 'hablar_con_persona', 'queja', 'otro') then
    return jsonb_build_object('ok', false, 'motivo', 'valor_no_valido');
  end if;
  if nullif(trim(p_resumen), '') is null then return jsonb_build_object('ok', false, 'motivo', 'falta_resumen'); end if;
  v_id := _solicitud(v.clinica_id, p_tipo, p_resumen, _verificado(v), v.id, null, p_urgente, null, v.contacto);
  return jsonb_build_object('ok', true, 'solicitud_id', v_id);
end;
$$;

-- =====================================================================
-- Motor de envíos (solo service_role). n8n o pg_cron llaman a motor_tick cada minuto; n8n recoge los envíos reales
-- con motor_pendientes y devuelve el resultado con motor_resultado.
-- =====================================================================

create function motor_tick() returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare r record; n_rec int := 0; n_form int := 0; n_ofertas int := 0; n_sim int := 0; n_borrados int := 0; v_ofrecida bigint;
begin
  perform set_config('nutricion.actor', 'sistema', true);
  -- Recordatorios de cita (no a las reservadas ya dentro de la ventana: acaban de recibir la confirmación).
  for r in
    select ci.id, ci.clinica_id, ci.paciente_id, ci.inicio from citas ci join clinicas c on c.id = ci.clinica_id
    where ci.estado = 'reservada' and c.recordatorio_horas > 0 and ci.confirmada_en is null
      and ci.inicio > now() and ci.inicio <= now() + make_interval(hours => c.recordatorio_horas)
      and ci.creada_en < ci.inicio - make_interval(hours => c.recordatorio_horas)
  loop
    if _encolar(r.clinica_id, 'recordatorio_cita', 'recordatorio:' || r.id || ':' || extract(epoch from r.inicio)::bigint,
                r.paciente_id, r.id, _vars_cita(r.id)) is not null then n_rec := n_rec + 1; end if;
  end loop;
  -- Formularios sin rellenar cerca de la cita: un recordatorio, con enlace nuevo.
  for r in
    select fe.id, fe.clinica_id, fe.paciente_id, fe.formulario_id, fe.cita_id from formulario_envios fe
    join citas ci on ci.id = fe.cita_id join clinicas c on c.id = fe.clinica_id
    where fe.estado = 'pendiente' and fe.recordado_en is null and c.formulario_recordatorio_horas > 0
      and ci.estado = 'reservada' and ci.inicio > now()
      and ci.inicio <= now() + make_interval(hours => c.formulario_recordatorio_horas)
      and fe.creado_en < now() - interval '12 hours'
  loop
    perform _mandar_formulario(r.clinica_id, r.paciente_id, r.formulario_id, r.cita_id, true);
    n_form := n_form + 1;
  end loop;
  update formulario_envios set estado = 'caducado' where estado = 'pendiente' and caduca_en < now();
  -- Ofertas de la lista de espera sin respuesta: vuelven a la lista y el hueco pasa al siguiente.
  for r in select * from lista_espera where estado = 'ofrecida' and oferta_caduca_en < now() for update skip locked loop
    update lista_espera set estado = 'activa', oferta_inicio = null, oferta_profesional = null, oferta_caduca_en = null
    where id = r.id;
    v_ofrecida := _ofrecer_hueco(r.clinica_id, r.oferta_profesional, r.oferta_inicio, r.id);
    n_ofertas := n_ofertas + 1;
  end loop;
  update lista_espera set estado = 'caducada' where estado = 'activa' and hasta < current_date;
  -- Simulador: lo programado que ya toca se da por enviado.
  for r in select e.id from envios e join clinicas c on c.id = e.clinica_id
           where e.estado = 'pendiente' and e.proximo_intento <= now() and c.modo_envio = 'simulador'
           for update of e skip locked loop
    perform _envio_hecho(r.id, 'simulado');
    n_sim := n_sim + 1;
  end loop;
  -- Envíos que se quedaron a medias (n8n se cayó): vuelven a la cola.
  update envios set estado = 'pendiente', proximo_intento = now()
  where estado = 'enviando' and proximo_intento < now() - interval '10 minutes';
  -- Retención de mensajes.
  with b as (delete from mensajes m using clinicas c
             where c.id = m.clinica_id and m.creado_en < now() - make_interval(days => c.retencion_mensajes_dias)
             returning 1)
  select count(*) into n_borrados from b;
  return jsonb_build_object('ok', true, 'recordatorios', n_rec, 'formularios', n_form, 'ofertas_caducadas', n_ofertas,
                            'simulados', n_sim, 'mensajes_borrados', n_borrados);
end;
$$;

-- Envíos reales que toca mandar. Cada uno sale una sola vez (skip locked + estado 'enviando'). Si la cita ha
-- cambiado o se ha cancelado desde que se encoló, el envío se descarta aquí.
create function motor_pendientes(p_limite int default 20) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare e record; v_lista jsonb := '[]'::jsonb; ci citas;
begin
  for e in
    select en.* from envios en join clinicas c on c.id = en.clinica_id
    where en.estado = 'pendiente' and en.proximo_intento <= now() and c.modo_envio = 'real'
    order by en.proximo_intento limit least(greatest(p_limite, 1), 100)
    for update of en skip locked
  loop
    if e.cita_id is not null and e.tipo in ('confirmacion_cita', 'recordatorio_cita', 'cambio_cita') then
      select * into ci from citas where id = e.cita_id;
      if ci.estado <> 'reservada' or ci.inicio is distinct from e.cita_inicio then
        update envios set estado = 'cancelado', secreto = null, ultimo_error = 'la cita ha cambiado' where id = e.id;
        continue;
      end if;
    end if;
    update envios set estado = 'enviando', intentos = intentos + 1, proximo_intento = now() where id = e.id;
    v_lista := v_lista || jsonb_build_object('envio_id', e.id, 'canal', e.canal, 'destino', e.destino, 'tipo', e.tipo,
      'texto', _render(e.texto, jsonb_build_object('enlace',
                 case when e.secreto is not null
                      then rtrim((select valor from sistema where clave = 'url_app'), '/') || '/#/f/' || e.secreto end)),
      'plantilla_meta', (select plantilla_meta from plantillas_mensaje where clinica_id = e.clinica_id and clave = e.tipo),
      'variables', e.variables,
      -- WhatsApp solo deja texto libre si el paciente escribió en las últimas 24 h; si no, hace falta la plantilla.
      'ventana_abierta', exists (select 1 from conversaciones v where v.clinica_id = e.clinica_id and v.canal = 'whatsapp'
                                   and v.contacto = e.destino and v.ultimo_entrante_en > now() - interval '24 hours'));
  end loop;
  return v_lista;
end;
$$;

-- Resultado de un envío. Reintentos con espera creciente (5, 20 min); al tercer fallo queda 'fallido' y el equipo
-- recibe una solicitud. Repetir la llamada con el mismo resultado no cambia nada.
create function motor_resultado(p_envio bigint, p_ok boolean, p_id_externo text default null, p_error text default null)
returns jsonb language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare e envios;
begin
  perform set_config('nutricion.actor', 'sistema', true);
  select * into e from envios where id = p_envio for update;
  if e.id is null then return jsonb_build_object('ok', false, 'motivo', 'envio_no_existe'); end if;
  if e.estado <> 'enviando' then return jsonb_build_object('ok', true, 'estado', e.estado, 'sin_cambios', true); end if;
  if p_ok then
    perform _envio_hecho(e.id, 'enviado', p_id_externo);
    return jsonb_build_object('ok', true, 'estado', 'enviado');
  end if;
  if e.intentos >= 3 then
    update envios set estado = 'fallido', secreto = null, ultimo_error = left(p_error, 500) where id = e.id;
    perform _solicitud(e.clinica_id, 'envio_fallido',
      'No se ha podido enviar "' || replace(e.tipo, '_', ' ') || '" a ' || e.destino || ': ' || coalesce(left(p_error, 200), 'sin detalle'),
      e.paciente_id, null, e.cita_id, false, e.id, e.destino);
    return jsonb_build_object('ok', true, 'estado', 'fallido');
  end if;
  update envios set estado = 'pendiente', ultimo_error = left(p_error, 500),
         proximo_intento = now() + case e.intentos when 1 then interval '5 minutes' else interval '20 minutes' end
  where id = e.id;
  return jsonb_build_object('ok', true, 'estado', 'pendiente', 'reintento', true);
end;
$$;

-- =====================================================================
-- Portal del paciente (anon): formularios con enlace seguro
-- =====================================================================

-- Comprueba token + segundo dato. Devuelve el envío o el motivo. Cuenta los fallos y bloquea.
create function _portal_entrar(p_token text, p_comprobacion text, out fe formulario_envios, out motivo text)
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare pa pacientes; v_ok boolean;
begin
  perform set_config('nutricion.actor', 'portal', true);
  select * into fe from formulario_envios where token_hash = _huella(p_token) for update;
  if fe.id is null then motivo := 'enlace_no_valido'; return; end if;
  if fe.estado in ('completado', 'revisado') then motivo := 'ya_completado'; return; end if;
  if fe.estado <> 'pendiente' or fe.caduca_en < now() then motivo := 'enlace_caducado'; return; end if;
  if fe.bloqueado_hasta > now() then motivo := 'bloqueado'; return; end if;
  select * into pa from pacientes where id = fe.paciente_id;
  if pa.fecha_nacimiento is not null then
    begin v_ok := p_comprobacion::date = pa.fecha_nacimiento;
    exception when others then v_ok := false; end;
  else
    v_ok := length(regexp_replace(coalesce(p_comprobacion, ''), '[^0-9]', '', 'g')) = 4
            and right(pa.telefono, 4) = regexp_replace(p_comprobacion, '[^0-9]', '', 'g');
  end if;
  if not coalesce(v_ok, false) then
    update formulario_envios set intentos_fallidos = intentos_fallidos + 1,
           bloqueado_hasta = case when (intentos_fallidos + 1) % 5 = 0 then now() + interval '30 minutes' end,
           estado = case when intentos_fallidos + 1 >= 15 then 'anulado' else estado end
    where id = fe.id;
    perform _auditar(fe.clinica_id, 'portal_fallo', 'formulario_envio', fe.id::text, fe.paciente_id);
    motivo := 'no_coincide';
    fe := null;
    return;
  end if;
end;
$$;

-- Primer paso sin datos: qué se pide para entrar (sin decir nada del paciente).
create function portal_formulario_info(p_token text) returns jsonb
language plpgsql stable security definer set search_path = nutricion, extensions, pg_temp as $$
declare fe formulario_envios; c clinicas; pa pacientes;
begin
  select * into fe from formulario_envios where token_hash = _huella(p_token);
  if fe.id is null then return jsonb_build_object('ok', false, 'motivo', 'enlace_no_valido'); end if;
  select * into c from clinicas where id = fe.clinica_id;
  select * into pa from pacientes where id = fe.paciente_id;
  return jsonb_build_object('ok', true, 'clinica', c.nombre, 'color', c.color,
    'formulario', (select nombre from formularios where id = fe.formulario_id),
    'estado', case when fe.estado in ('completado', 'revisado') then 'completado'
                   when fe.estado <> 'pendiente' or fe.caduca_en < now() then 'caducado'
                   when fe.bloqueado_hasta > now() then 'bloqueado' else 'pendiente' end,
    'comprobacion', case when pa.fecha_nacimiento is not null then 'fecha_nacimiento' else 'ultimos_digitos' end);
end;
$$;

create function portal_formulario_abrir(p_token text, p_comprobacion text) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare x record;
begin
  select * into x from _portal_entrar(p_token, p_comprobacion);
  if x.motivo is not null then return jsonb_build_object('ok', false, 'motivo', x.motivo); end if;
  update formulario_envios set abierto_en = coalesce(abierto_en, now()), intentos_fallidos = 0 where id = (x.fe).id;
  return jsonb_build_object('ok', true,
    'paciente', (select split_part(trim(nombre), ' ', 1) from pacientes where id = (x.fe).paciente_id),
    'formulario', (select jsonb_build_object('nombre', nombre, 'descripcion', descripcion) from formularios where id = (x.fe).formulario_id),
    'campos', (select coalesce(jsonb_agg(cp - 'destino'), '[]'::jsonb) from jsonb_array_elements((x.fe).campos) cp));
end;
$$;

-- Valida las respuestas contra los campos del formulario que se mandó. Devuelve {ok, respuestas} o {ok:false, errores}.
create function _validar_respuestas(p_campos jsonb, p_resp jsonb) returns jsonb language plpgsql immutable as $$
declare cp jsonb; k text; t text; v jsonb; s text; n numeric; errores jsonb := '{}'::jsonb; limpias jsonb := '{}'::jsonb;
begin
  for cp in select * from jsonb_array_elements(p_campos) loop
    k := cp->>'clave'; t := cp->>'tipo'; v := p_resp->k;
    s := case when v is null or jsonb_typeof(v) = 'null' then null
              when jsonb_typeof(v) = 'string' then nullif(trim(v #>> '{}'), '') else v::text end;
    if s is null or (jsonb_typeof(v) = 'array' and jsonb_array_length(v) = 0) then
      if coalesce((cp->>'obligatorio')::boolean, false) then errores := errores || jsonb_build_object(k, 'obligatorio'); end if;
      continue;
    end if;
    case t
      when 'texto' then
        if length(s) > 1000 then errores := errores || jsonb_build_object(k, 'demasiado_largo');
        else limpias := limpias || jsonb_build_object(k, s); end if;
      when 'texto_largo' then
        if length(s) > 5000 then errores := errores || jsonb_build_object(k, 'demasiado_largo');
        else limpias := limpias || jsonb_build_object(k, s); end if;
      when 'numero' then
        begin n := replace(s, ',', '.')::numeric;
        exception when others then errores := errores || jsonb_build_object(k, 'no_es_numero'); continue; end;
        if (cp ? 'min' and n < (cp->>'min')::numeric) or (cp ? 'max' and n > (cp->>'max')::numeric) then
          errores := errores || jsonb_build_object(k, 'fuera_de_rango');
        else limpias := limpias || jsonb_build_object(k, n); end if;
      when 'si_no' then
        if s not in ('true', 'false') then errores := errores || jsonb_build_object(k, 'valor_no_valido');
        else limpias := limpias || jsonb_build_object(k, s::boolean); end if;
      when 'opcion' then
        if not (cp->'opciones') ? s then errores := errores || jsonb_build_object(k, 'valor_no_valido');
        else limpias := limpias || jsonb_build_object(k, s); end if;
      when 'varias' then
        if jsonb_typeof(v) <> 'array' or exists (select 1 from jsonb_array_elements_text(v) x where not (cp->'opciones') ? x) then
          errores := errores || jsonb_build_object(k, 'valor_no_valido');
        else limpias := limpias || jsonb_build_object(k, v); end if;
      when 'fecha' then
        begin limpias := limpias || jsonb_build_object(k, s::date);
        exception when others then errores := errores || jsonb_build_object(k, 'fecha_no_valida'); end;
      else null;
    end case;
  end loop;
  if errores <> '{}'::jsonb then return jsonb_build_object('ok', false, 'motivo', 'respuestas_no_validas', 'errores', errores); end if;
  return jsonb_build_object('ok', true, 'respuestas', limpias);
end;
$$;

create function portal_formulario_enviar(p_token text, p_comprobacion text, p_respuestas jsonb) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare x record; r jsonb;
begin
  select * into x from _portal_entrar(p_token, p_comprobacion);
  if x.motivo is not null then return jsonb_build_object('ok', false, 'motivo', x.motivo); end if;
  r := _validar_respuestas((x.fe).campos, coalesce(p_respuestas, '{}'::jsonb));
  if not (r->>'ok')::boolean then return r; end if;
  update formulario_envios set respuestas = r->'respuestas', estado = 'completado', completado_en = now(), intentos_fallidos = 0
  where id = (x.fe).id;
  perform _auditar((x.fe).clinica_id, 'completar_formulario', 'formulario_envio', (x.fe).id::text, (x.fe).paciente_id);
  return jsonb_build_object('ok', true);
end;
$$;

-- =====================================================================
-- API de la aplicación (usuarios con sesión)
-- =====================================================================

-- Ajustes de mensajes y canales.
create function ajustes_mensajes(p_clinica uuid) returns jsonb
language plpgsql stable security definer set search_path = nutricion, extensions, pg_temp as $$
declare c clinicas;
begin
  perform _miembro(p_clinica);
  select * into c from clinicas where id = p_clinica;
  return jsonb_build_object('ok', true,
    'ajustes', jsonb_build_object('modo_envio', c.modo_envio, 'nombre_asistente', c.nombre_asistente,
      'enviar_confirmacion', c.enviar_confirmacion, 'recordatorio_horas', c.recordatorio_horas,
      'formulario_recordatorio_horas', c.formulario_recordatorio_horas, 'oferta_espera_minutos', c.oferta_espera_minutos,
      'verificacion_minutos', c.verificacion_minutos, 'retencion_mensajes_dias', c.retencion_mensajes_dias),
    'canales', (select coalesce(jsonb_agg(jsonb_build_object('tipo', tipo, 'estado', estado, 'numero_publico', numero_publico,
                   'conectado_en', _local(conectado_en, c.zona_horaria)) order by tipo), '[]'::jsonb)
                from canales where clinica_id = p_clinica),
    'plantillas', (select coalesce(jsonb_agg(jsonb_build_object('clave', clave, 'texto', texto, 'activa', activa,
                      'plantilla_meta', plantilla_meta) order by clave), '[]'::jsonb)
                   from plantillas_mensaje where clinica_id = p_clinica));
end;
$$;

create function guardar_ajustes_mensajes(p_clinica uuid, d jsonb) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare c clinicas;
begin
  perform _miembro(p_clinica, array['propietario']);
  select * into c from clinicas where id = p_clinica;
  if d->>'modo_envio' = 'real' and not exists (select 1 from canales where clinica_id = p_clinica and tipo = 'whatsapp'
                                                 and estado = 'conectado') then
    return jsonb_build_object('ok', false, 'motivo', 'canal_no_conectado');
  end if;
  update clinicas set
    modo_envio = coalesce(d->>'modo_envio', modo_envio),
    nombre_asistente = coalesce(nullif(trim(d->>'nombre_asistente'), ''), nombre_asistente),
    enviar_confirmacion = coalesce((d->>'enviar_confirmacion')::boolean, enviar_confirmacion),
    recordatorio_horas = coalesce((d->>'recordatorio_horas')::int, recordatorio_horas),
    formulario_recordatorio_horas = coalesce((d->>'formulario_recordatorio_horas')::int, formulario_recordatorio_horas),
    oferta_espera_minutos = coalesce((d->>'oferta_espera_minutos')::int, oferta_espera_minutos),
    verificacion_minutos = coalesce((d->>'verificacion_minutos')::int, verificacion_minutos),
    retencion_mensajes_dias = coalesce((d->>'retencion_mensajes_dias')::int, retencion_mensajes_dias)
  where id = p_clinica;
  perform _auditar(p_clinica, 'guardar_ajustes_mensajes', 'clinica', p_clinica::text, null,
                   jsonb_build_object('campos', (select jsonb_agg(k) from jsonb_object_keys(d) k)));
  return jsonb_build_object('ok', true);
end;
$$;

create function guardar_plantilla(p_clinica uuid, p_clave text, d jsonb) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare v_desconocidas text[];
begin
  perform _miembro(p_clinica, array['propietario']);
  select array_agg(distinct m[1]) into v_desconocidas
  from regexp_matches(coalesce(d->>'texto', ''), '\{([a-z_]+)\}', 'g') m
  where m[1] not in ('paciente', 'fecha', 'servicio', 'profesional', 'clinica', 'lugar', 'enlace', 'comprobacion', 'caduca',
                     'tipo', 'texto');
  if v_desconocidas is not null then
    return jsonb_build_object('ok', false, 'motivo', 'variable_desconocida', 'variables', to_jsonb(v_desconocidas));
  end if;
  if p_clave in ('formulario_pendiente', 'formulario_recordatorio') and d ? 'texto' and d->>'texto' not like '%{enlace}%' then
    return jsonb_build_object('ok', false, 'motivo', 'falta_enlace');
  end if;
  update plantillas_mensaje set
    texto = coalesce(nullif(trim(d->>'texto'), ''), texto),
    activa = coalesce((d->>'activa')::boolean, activa),
    plantilla_meta = case when d ? 'plantilla_meta' then nullif(trim(d->>'plantilla_meta'), '') else plantilla_meta end
  where clinica_id = p_clinica and clave = p_clave;
  if not found then return jsonb_build_object('ok', false, 'motivo', 'plantilla_no_existe'); end if;
  perform _auditar(p_clinica, 'guardar_plantilla', 'plantilla', p_clave);
  return jsonb_build_object('ok', true);
end;
$$;

-- Cola de envíos (lo enviado, lo pendiente, lo simulado). El enlace de los formularios nunca se muestra.
create function lista_envios(p_clinica uuid, p_estado text default null, p_limite int default 100) returns jsonb
language plpgsql stable security definer set search_path = nutricion, extensions, pg_temp as $$
declare v_tz text := _tz(p_clinica);
begin
  perform _miembro(p_clinica);
  return (select coalesce(jsonb_agg(jsonb_build_object('id', e.id, 'tipo', e.tipo, 'canal', e.canal, 'destino', e.destino,
            'paciente_id', e.paciente_id, 'paciente', trim(pa.nombre || ' ' || coalesce(pa.apellidos, '')),
            'cita_id', e.cita_id, 'texto', _render(e.texto, '{"enlace": "[enlace seguro]"}'), 'estado', e.estado,
            'intentos', e.intentos, 'error', e.ultimo_error, 'creado', _local(e.creado_en, v_tz),
            'programado', _local(e.programado_para, v_tz), 'enviado', _local(e.enviado_en, v_tz)) order by e.id desc), '[]'::jsonb)
    from (select * from envios where clinica_id = p_clinica and (p_estado is null or estado = p_estado)
          order by id desc limit least(greatest(p_limite, 1), 500)) e
    left join pacientes pa on pa.id = e.paciente_id);
end;
$$;

-- ---------------------------------------------------------------- conversaciones

create function lista_conversaciones(p_clinica uuid, p_limite int default 100) returns jsonb
language plpgsql stable security definer set search_path = nutricion, extensions, pg_temp as $$
declare v_tz text := _tz(p_clinica);
begin
  perform _miembro(p_clinica);
  return (select coalesce(jsonb_agg(jsonb_build_object('id', v.id, 'canal', v.canal, 'contacto', v.contacto,
            'nombre_perfil', v.nombre_perfil, 'paciente_id', v.paciente_id,
            -- sin identidad comprobada, el nombre solo si el teléfono es de una única ficha
            'paciente', coalesce(trim(pa.nombre || ' ' || coalesce(pa.apellidos, '')),
                                 (select min(trim(x.nombre || ' ' || coalesce(x.apellidos, ''))) from pacientes x
                                  where x.clinica_id = v.clinica_id and x.telefono = v.contacto having count(*) = 1)),
            'ia_pausada', v.ia_pausada,
            'ultimo', _local(v.ultimo_mensaje_en, v_tz),
            'ultimo_texto', (select left(texto, 140) from mensajes m where m.conversacion_id = v.id order by id desc limit 1),
            'solicitudes_abiertas', (select count(*) from solicitudes s where s.conversacion_id = v.id and s.estado <> 'resuelta'))
          order by v.ultimo_mensaje_en desc), '[]'::jsonb)
    from (select * from conversaciones where clinica_id = p_clinica order by ultimo_mensaje_en desc
          limit least(greatest(p_limite, 1), 500)) v
    left join pacientes pa on pa.id = v.paciente_id);
end;
$$;

create function ver_conversacion(p_clinica uuid, p_id bigint) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare v conversaciones; v_tz text := _tz(p_clinica);
begin
  perform _miembro(p_clinica);
  select * into v from conversaciones where id = p_id and clinica_id = p_clinica;
  if v.id is null then return jsonb_build_object('ok', false, 'motivo', 'conversacion_no_existe'); end if;
  perform _auditar(p_clinica, 'ver_conversacion', 'conversacion', v.id::text, v.paciente_id);
  return jsonb_build_object('ok', true, 'conversacion', jsonb_build_object('id', v.id, 'canal', v.canal,
      'contacto', v.contacto, 'nombre_perfil', v.nombre_perfil, 'paciente_id', v.paciente_id, 'ia_pausada', v.ia_pausada,
      'ventana_abierta', v.ultimo_entrante_en > now() - interval '24 hours',
      'pacientes_con_este_telefono', (select coalesce(jsonb_agg(jsonb_build_object('id', p.id,
          'nombre', trim(p.nombre || ' ' || coalesce(p.apellidos, '')))), '[]'::jsonb)
          from pacientes p where p.clinica_id = p_clinica and p.telefono = v.contacto)),
    'mensajes', (select coalesce(jsonb_agg(jsonb_build_object('id', m.id, 'direccion', m.direccion, 'autor', m.autor,
                   'texto', m.texto, 'cuando', _local(m.creado_en, v_tz),
                   'estado_envio', (select estado from envios e where e.id = m.envio_id)) order by m.id), '[]'::jsonb)
                 from mensajes m where m.conversacion_id = v.id));
end;
$$;

-- El equipo toma la conversación (la IA deja de contestar) o se la devuelve.
create function pausar_ia(p_clinica uuid, p_id bigint, p_pausar boolean) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
begin
  perform _miembro(p_clinica);
  update conversaciones set ia_pausada = p_pausar, pausada_por = case when p_pausar then auth.uid() end
  where id = p_id and clinica_id = p_clinica;
  if not found then return jsonb_build_object('ok', false, 'motivo', 'conversacion_no_existe'); end if;
  perform _auditar(p_clinica, case when p_pausar then 'pausar_ia' else 'reanudar_ia' end, 'conversacion', p_id::text);
  return jsonb_build_object('ok', true);
end;
$$;

-- Mensaje del equipo a una conversación. Va por la cola (con clave para no duplicar si se pulsa dos veces).
create function responder_conversacion(p_clinica uuid, p_id bigint, p_texto text, p_clave text default null) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare v conversaciones; v_envio bigint;
begin
  perform _miembro(p_clinica);
  select * into v from conversaciones where id = p_id and clinica_id = p_clinica;
  if v.id is null then return jsonb_build_object('ok', false, 'motivo', 'conversacion_no_existe'); end if;
  if v.canal <> 'whatsapp' then return jsonb_build_object('ok', false, 'motivo', 'canal_sin_mensajes'); end if;
  if nullif(trim(p_texto), '') is null then return jsonb_build_object('ok', false, 'motivo', 'falta_texto'); end if;
  -- Para que el texto escrito no se tome por variables de plantilla, se pasa como variable.
  v_envio := _encolar(p_clinica, 'mensaje_equipo', coalesce('equipo:' || p_clave, 'equipo:' || gen_random_uuid()),
                      coalesce(v.paciente_id, (select id from pacientes where clinica_id = p_clinica and telefono = v.contacto
                                                order by id limit 1)),
                      null, jsonb_build_object('texto', left(trim(p_texto), 1000)), null, null, v.contacto);
  perform _auditar(p_clinica, 'responder_conversacion', 'conversacion', v.id::text, v.paciente_id);
  return jsonb_build_object('ok', true, 'envio_id', v_envio);
end;
$$;

-- ---------------------------------------------------------------- solicitudes

create function _solicitud_json(s solicitudes, p_ve_salud boolean, p_tz text) returns jsonb
language sql stable security definer set search_path = nutricion, extensions, pg_temp as $$
  select jsonb_build_object('id', s.id, 'tipo', s.tipo, 'estado', s.estado, 'urgente', s.urgente,
    'resumen', case when s.tipo = 'pregunta_clinica' and not p_ve_salud
                    then 'Pregunta clínica para ' || coalesce(pr.nombre, 'el profesional') || '. Solo la ven los nutricionistas.'
                    else s.resumen end,
    'paciente_id', s.paciente_id, 'paciente', trim(pa.nombre || ' ' || coalesce(pa.apellidos, '')),
    'profesional_id', s.profesional_id, 'profesional', pr.nombre, 'contacto', s.contacto,
    'conversacion_id', s.conversacion_id, 'cita_id', s.cita_id, 'nota', s.nota,
    'creada', _local(s.creada_en, p_tz), 'resuelta', _local(s.resuelta_en, p_tz))
  from (select 1) x left join pacientes pa on pa.id = s.paciente_id left join profesionales pr on pr.id = s.profesional_id
$$;

create function lista_solicitudes(p_clinica uuid, p_estado text default 'abiertas') returns jsonb
language plpgsql stable security definer set search_path = nutricion, extensions, pg_temp as $$
declare m miembros := _miembro(p_clinica); v_tz text := _tz(p_clinica);
begin
  return (select coalesce(jsonb_agg(_solicitud_json(s, _puede_salud(m.rol), v_tz)
                                    order by s.urgente desc, s.creada_en desc), '[]'::jsonb)
    from solicitudes s where s.clinica_id = p_clinica
      and case p_estado when 'abiertas' then s.estado <> 'resuelta' when 'resueltas' then s.estado = 'resuelta' else true end
      -- un nutricionista ve las suyas y las que no son de nadie; el propietario y recepción, todas
      and (m.rol <> 'nutricionista' or s.profesional_id is null or s.profesional_id = m.profesional_id));
end;
$$;

create function resolver_solicitud(p_clinica uuid, p_id bigint, p_estado text, p_nota text default null) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare m miembros := _miembro(p_clinica); s solicitudes;
begin
  if p_estado not in ('pendiente', 'en_curso', 'resuelta') then return jsonb_build_object('ok', false, 'motivo', 'valor_no_valido'); end if;
  select * into s from solicitudes where id = p_id and clinica_id = p_clinica for update;
  if s.id is null then return jsonb_build_object('ok', false, 'motivo', 'solicitud_no_existe'); end if;
  if s.tipo = 'pregunta_clinica' and not _puede_salud(m.rol) then raise exception 'sin_permiso' using errcode = '42501'; end if;
  update solicitudes set estado = p_estado, nota = coalesce(nullif(trim(p_nota), ''), nota),
         resuelta_en = case when p_estado = 'resuelta' then now() end,
         resuelta_por = case when p_estado = 'resuelta' then auth.uid() end
  where id = s.id;
  perform _auditar(p_clinica, 'resolver_solicitud', 'solicitud', s.id::text, s.paciente_id, jsonb_build_object('estado', p_estado));
  return jsonb_build_object('ok', true);
end;
$$;

-- ---------------------------------------------------------------- formularios

create function lista_formularios(p_clinica uuid) returns jsonb
language plpgsql stable security definer set search_path = nutricion, extensions, pg_temp as $$
begin
  perform _miembro(p_clinica);
  return (select coalesce(jsonb_agg(jsonb_build_object('id', f.id, 'nombre', f.nombre, 'descripcion', f.descripcion,
            'campos', f.campos, 'version', f.version, 'activo', f.activo,
            'servicios', (select coalesce(jsonb_agg(sf.servicio_id), '[]'::jsonb) from servicio_formularios sf where sf.formulario_id = f.id))
          order by f.nombre), '[]'::jsonb)
    from formularios f where f.clinica_id = p_clinica);
end;
$$;

create function guardar_formulario(p_clinica uuid, d jsonb) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare v_id bigint := (d->>'id')::bigint; cp jsonb; v_claves text[] := '{}';
begin
  perform _miembro(p_clinica, array['propietario', 'nutricionista']);
  if d ? 'campos' then
    if jsonb_typeof(d->'campos') <> 'array' or jsonb_array_length(d->'campos') = 0 then
      return jsonb_build_object('ok', false, 'motivo', 'faltan_campos');
    end if;
    for cp in select * from jsonb_array_elements(d->'campos') loop
      if coalesce(cp->>'clave', '') !~ '^[a-z][a-z0-9_]{0,39}$' or nullif(trim(cp->>'etiqueta'), '') is null
         or coalesce(cp->>'tipo', '') not in ('texto', 'texto_largo', 'numero', 'si_no', 'opcion', 'varias', 'fecha')
         or (cp->>'tipo' in ('opcion', 'varias') and coalesce(jsonb_array_length(cp->'opciones'), 0) < 2)
         or (cp ? 'destino' and cp->>'destino' not in ('motivo_consulta', 'objetivos', 'antecedentes', 'alergias',
               'intolerancias', 'medicacion', 'suplementos', 'habitos_alimentarios', 'actividad_fisica', 'extra')) then
        return jsonb_build_object('ok', false, 'motivo', 'campo_no_valido', 'campo', cp);
      end if;
      if cp->>'clave' = any (v_claves) then return jsonb_build_object('ok', false, 'motivo', 'clave_repetida', 'campo', cp); end if;
      v_claves := v_claves || (cp->>'clave');
    end loop;
  end if;
  if v_id is null then
    insert into formularios (clinica_id, nombre, descripcion, campos)
    values (p_clinica, trim(d->>'nombre'), nullif(trim(d->>'descripcion'), ''), coalesce(d->'campos', '[]'::jsonb))
    returning id into v_id;
  else
    -- Los envíos ya hechos guardan su propia copia: cambiar el formulario no altera lo que el paciente ya recibió.
    update formularios set nombre = coalesce(nullif(trim(d->>'nombre'), ''), nombre),
      descripcion = case when d ? 'descripcion' then nullif(trim(d->>'descripcion'), '') else descripcion end,
      campos = coalesce(d->'campos', campos),
      version = version + case when d ? 'campos' and d->'campos' <> campos then 1 else 0 end,
      activo = coalesce((d->>'activo')::boolean, activo), actualizado_en = now()
    where id = v_id and clinica_id = p_clinica;
    if not found then return jsonb_build_object('ok', false, 'motivo', 'formulario_no_existe'); end if;
  end if;
  if d ? 'servicios' then
    delete from servicio_formularios where formulario_id = v_id;
    insert into servicio_formularios (clinica_id, servicio_id, formulario_id)
    select p_clinica, s.id, v_id from servicios s
    where s.clinica_id = p_clinica and s.id in (select x::bigint from jsonb_array_elements_text(d->'servicios') x);
  end if;
  perform _auditar(p_clinica, 'guardar_formulario', 'formulario', v_id::text);
  return jsonb_build_object('ok', true, 'id', v_id);
end;
$$;

create function enviar_formulario(p_clinica uuid, p_paciente bigint, p_formulario bigint, p_cita bigint default null,
                                  p_reenviar boolean default false) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare v_id bigint;
begin
  perform _miembro(p_clinica);
  if not exists (select 1 from pacientes where id = p_paciente and clinica_id = p_clinica) then
    return jsonb_build_object('ok', false, 'motivo', 'paciente_no_existe');
  end if;
  if not exists (select 1 from pacientes where id = p_paciente and (telefono is not null or email is not null)) then
    return jsonb_build_object('ok', false, 'motivo', 'falta_contacto');
  end if;
  v_id := _mandar_formulario(p_clinica, p_paciente, p_formulario, p_cita, p_reenviar);
  if v_id is null then return jsonb_build_object('ok', false, 'motivo', 'formulario_no_existe'); end if;
  perform _auditar(p_clinica, 'enviar_formulario', 'formulario_envio', v_id::text, p_paciente);
  return jsonb_build_object('ok', true, 'id', v_id);
end;
$$;

-- Formularios de un paciente. Las respuestas solo para quien ve datos de salud (y queda registrado).
create function formularios_paciente(p_clinica uuid, p_paciente bigint) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare m miembros := _miembro(p_clinica); v_tz text := _tz(p_clinica);
begin
  if _puede_salud(m.rol) and exists (select 1 from formulario_envios where paciente_id = p_paciente and clinica_id = p_clinica
                                        and respuestas is not null) then
    perform _auditar(p_clinica, 'ver_respuestas_formulario', 'paciente', p_paciente::text, p_paciente);
  end if;
  return (select coalesce(jsonb_agg(jsonb_build_object('id', fe.id, 'formulario_id', fe.formulario_id, 'formulario', f.nombre,
            'estado', case when fe.estado = 'pendiente' and fe.caduca_en < now() then 'caducado' else fe.estado end,
            'enviado', _local(fe.creado_en, v_tz), 'abierto', _local(fe.abierto_en, v_tz),
            'completado', _local(fe.completado_en, v_tz), 'revisado', _local(fe.revisado_en, v_tz),
            'caduca', _local(fe.caduca_en, v_tz), 'cita_id', fe.cita_id,
            'campos', case when _puede_salud(m.rol) then fe.campos end,
            'respuestas', case when _puede_salud(m.rol) then fe.respuestas end) order by fe.id desc), '[]'::jsonb)
    from formulario_envios fe join formularios f on f.id = fe.formulario_id
    where fe.paciente_id = p_paciente and fe.clinica_id = p_clinica);
end;
$$;

-- El profesional revisa las respuestas y decide cuáles pasan a la ficha de salud (p_claves; null = todas las que
-- tienen destino). Se añaden a lo que ya hubiera, con la fecha y de dónde salen; nunca se borra nada.
create function aplicar_respuestas(p_clinica uuid, p_envio bigint, p_claves jsonb default null) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare fe formulario_envios; cp jsonb; v_valor text; v_dest text; v_aplicados text[] := '{}'; v_pre text; v_actual text;
        v_extra jsonb := '{}'::jsonb;
begin
  perform _miembro(p_clinica, array['propietario', 'nutricionista']);
  select * into fe from formulario_envios where id = p_envio and clinica_id = p_clinica for update;
  if fe.id is null then return jsonb_build_object('ok', false, 'motivo', 'formulario_no_existe'); end if;
  if fe.estado not in ('completado', 'revisado') then return jsonb_build_object('ok', false, 'motivo', 'sin_respuestas'); end if;
  v_pre := '[Cuestionario ' || to_char(fe.completado_en at time zone _tz(p_clinica), 'DD/MM/YYYY') || ', lo dice el paciente] ';
  insert into pacientes_salud (paciente_id, clinica_id) values (fe.paciente_id, p_clinica) on conflict do nothing;
  for cp in select * from jsonb_array_elements(fe.campos) loop
    v_dest := cp->>'destino';
    continue when v_dest is null or not fe.respuestas ? (cp->>'clave');
    continue when p_claves is not null and jsonb_typeof(p_claves) = 'array' and not p_claves ? (cp->>'clave');
    v_valor := case jsonb_typeof(fe.respuestas->(cp->>'clave'))
                 when 'boolean' then case when (fe.respuestas->>(cp->>'clave'))::boolean then 'Sí' else 'No' end
                 when 'array' then (select string_agg(x, ', ') from jsonb_array_elements_text(fe.respuestas->(cp->>'clave')) x)
                 else fe.respuestas->>(cp->>'clave') end || coalesce(' ' || (cp->>'unidad'), '');
    if v_dest = 'extra' then
      v_extra := v_extra || jsonb_build_object(cp->>'clave', jsonb_build_object('etiqueta', cp->>'etiqueta', 'valor', v_valor,
                   'origen', 'paciente', 'fecha', fe.completado_en::date));
    else
      execute format('select %I from pacientes_salud where paciente_id = $1', v_dest) into v_actual using fe.paciente_id;
      execute format('update pacientes_salud set %I = $1 where paciente_id = $2', v_dest)
        using concat_ws(E'\n', nullif(v_actual, ''), v_pre || v_valor), fe.paciente_id;
    end if;
    v_aplicados := v_aplicados || (cp->>'clave');
  end loop;
  update pacientes_salud set campos_extra = campos_extra || v_extra, actualizado_en = now(), actualizado_por = auth.uid()
  where paciente_id = fe.paciente_id;
  update formulario_envios set estado = 'revisado', revisado_en = now(), revisado_por = auth.uid() where id = fe.id;
  perform _auditar(p_clinica, 'aplicar_respuestas', 'formulario_envio', fe.id::text, fe.paciente_id,
                   jsonb_build_object('campos', to_jsonb(v_aplicados)));
  return jsonb_build_object('ok', true, 'aplicados', to_jsonb(v_aplicados));
end;
$$;

create function anular_formulario(p_clinica uuid, p_envio bigint) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
begin
  perform _miembro(p_clinica);
  update formulario_envios set estado = 'anulado' where id = p_envio and clinica_id = p_clinica and estado = 'pendiente';
  if not found then return jsonb_build_object('ok', false, 'motivo', 'formulario_no_existe'); end if;
  update envios set estado = 'cancelado', secreto = null
  where clinica_id = p_clinica and estado = 'pendiente' and clave_idempotencia like 'formulario:' || p_envio || ':%';
  perform _auditar(p_clinica, 'anular_formulario', 'formulario_envio', p_envio::text);
  return jsonb_build_object('ok', true);
end;
$$;

-- ---------------------------------------------------------------- lista de espera

create function lista_espera_ver(p_clinica uuid, p_estado text default 'abiertas') returns jsonb
language plpgsql stable security definer set search_path = nutricion, extensions, pg_temp as $$
declare v_tz text := _tz(p_clinica);
begin
  perform _miembro(p_clinica);
  return (select coalesce(jsonb_agg(jsonb_build_object('id', l.id, 'paciente_id', l.paciente_id,
            'paciente', trim(pa.nombre || ' ' || coalesce(pa.apellidos, '')), 'telefono', pa.telefono,
            'servicio_id', l.servicio_id, 'servicio', s.nombre, 'profesional_id', l.profesional_id, 'profesional', pr.nombre,
            'modalidad', l.modalidad, 'desde', l.desde, 'hasta', l.hasta, 'franja', l.franja, 'cita_id', l.cita_id,
            'cita_actual', (select _local(inicio, v_tz) from citas where id = l.cita_id),
            'estado', l.estado, 'oferta', case when l.estado = 'ofrecida' then jsonb_build_object(
               'inicio', _local(l.oferta_inicio, v_tz), 'fecha_texto', fecha_es(l.oferta_inicio, v_tz),
               'profesional', (select nombre from profesionales where id = l.oferta_profesional),
               'caduca', _local(l.oferta_caduca_en, v_tz)) end,
            'ofertas_hechas', l.ofertas_hechas, 'notas', l.notas, 'origen', l.origen, 'creada', _local(l.creada_en, v_tz))
          order by l.creada_en), '[]'::jsonb)
    from lista_espera l join pacientes pa on pa.id = l.paciente_id join servicios s on s.id = l.servicio_id
    left join profesionales pr on pr.id = l.profesional_id
    where l.clinica_id = p_clinica
      and case p_estado when 'abiertas' then l.estado in ('activa', 'ofrecida') else true end);
end;
$$;

create function guardar_espera(p_clinica uuid, d jsonb) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare v_id bigint := (d->>'id')::bigint; v_tz text := _tz(p_clinica);
begin
  perform _miembro(p_clinica);
  if v_id is null then
    if not exists (select 1 from pacientes where id = (d->>'paciente_id')::bigint and clinica_id = p_clinica) then
      return jsonb_build_object('ok', false, 'motivo', 'paciente_no_existe');
    end if;
    if not exists (select 1 from servicios where id = (d->>'servicio_id')::bigint and clinica_id = p_clinica) then
      return jsonb_build_object('ok', false, 'motivo', 'servicio_no_existe');
    end if;
    insert into lista_espera (clinica_id, paciente_id, servicio_id, profesional_id, modalidad, desde, hasta, franja, cita_id,
                              notas)
    values (p_clinica, (d->>'paciente_id')::bigint, (d->>'servicio_id')::bigint, (d->>'profesional_id')::bigint,
            nullif(d->>'modalidad', ''), coalesce(nullif(d->>'desde', '')::date, _hoy(v_tz)),
            coalesce(nullif(d->>'hasta', '')::date, _hoy(v_tz) + 30), coalesce(nullif(d->>'franja', ''), 'cualquiera'),
            (d->>'cita_id')::bigint, nullif(trim(d->>'notas'), ''))
    returning id into v_id;
  else
    update lista_espera set
      estado = case when d->>'estado' in ('activa', 'cancelada') then d->>'estado' else estado end,
      hasta = coalesce(nullif(d->>'hasta', '')::date, hasta),
      franja = coalesce(nullif(d->>'franja', ''), franja),
      notas = case when d ? 'notas' then nullif(trim(d->>'notas'), '') else notas end,
      oferta_inicio = case when d->>'estado' = 'cancelada' then null else oferta_inicio end,
      oferta_profesional = case when d->>'estado' = 'cancelada' then null else oferta_profesional end
    where id = v_id and clinica_id = p_clinica;
    if not found then return jsonb_build_object('ok', false, 'motivo', 'no_existe'); end if;
  end if;
  perform _auditar(p_clinica, 'guardar_lista_espera', 'lista_espera', v_id::text, (select paciente_id from lista_espera where id = v_id));
  return jsonb_build_object('ok', true, 'id', v_id);
end;
$$;

-- ---------------------------------------------------------------- listas de pacientes: + formularios sin completar

create or replace function lista_pacientes(p_clinica uuid, p_filtro text default 'todos', p_desde date default null,
                                           p_hasta date default null) returns jsonb
language plpgsql stable security definer set search_path = nutricion, extensions, pg_temp as $$
declare v_tz text := _tz(p_clinica);
begin
  perform _miembro(p_clinica);
  return (select coalesce(jsonb_agg(_paciente_json(p.id) order by p.nombre, p.id), '[]'::jsonb)
    from pacientes p
    where p.clinica_id = p_clinica
      and case p_filtro
        when 'activos' then p.estado = 'activo'
        when 'nuevos' then (p.creado_en at time zone v_tz)::date between coalesce(p_desde, _hoy(v_tz) - 30) and coalesce(p_hasta, _hoy(v_tz))
        when 'sin_proxima' then p.estado = 'activo'
             and exists (select 1 from citas c where c.paciente_id = p.id and c.estado = 'realizada')
             and not exists (select 1 from citas c where c.paciente_id = p.id and c.estado = 'reservada' and c.inicio > now())
        when 'formulario_pendiente' then exists (select 1 from formulario_envios fe where fe.paciente_id = p.id
             and fe.estado = 'pendiente' and fe.caduca_en > now())
        else true end);
end;
$$;

-- ---------------------------------------------------------------- panel con los módulos de la fase 2

alter function panel(uuid, date, date, bigint) rename to _panel_fase1;

create function panel(p_clinica uuid, p_desde date default null, p_hasta date default null,
                      p_profesional bigint default null) returns jsonb
language plpgsql stable security definer set search_path = nutricion, extensions, pg_temp as $$
declare r jsonb := _panel_fase1(p_clinica, p_desde, p_hasta, p_profesional); m miembros := _miembro(p_clinica);
begin
  return jsonb_set(jsonb_set(jsonb_set(r,
    '{tareas,formularios_sin_completar}', to_jsonb((select count(*) from formulario_envios
        where clinica_id = p_clinica and estado = 'pendiente' and caduca_en > now()))),
    '{tareas,intervencion_humana}', to_jsonb((select count(*) from solicitudes s where s.clinica_id = p_clinica
        and s.estado <> 'resuelta'
        and (m.rol <> 'nutricionista' or s.profesional_id is null or s.profesional_id = m.profesional_id)))),
    '{tareas,lista_espera}', to_jsonb((select count(*) from lista_espera where clinica_id = p_clinica
        and estado in ('activa', 'ofrecida'))));
end;
$$;

select _aplicar_permisos();


-- =====================================================================
-- Corvex Nutrición · Fase 3: seguimiento nutricional
-- Valoraciones (plantillas por tipo de consulta, cerradas = inmutables), notas cronológicas, mediciones (medido en
-- consulta / aportado por el paciente / calculado), seguimientos tras una consulta, programas de varias sesiones
-- (formas A-D), bonos y paquetes, y recordatorios de seguimiento automáticos.
--
-- Principios:
--  * La frecuencia de las revisiones la decide el profesional. Nada automático la cambia: el sistema solo crea las
--    sesiones que él indica, ofrece huecos dentro del plazo que autorizó y le avisa cuando no los hay.
--  * Una sesión pendiente o propuesta no ocupa la agenda. Solo una cita reservada bloquea el hueco, y se vuelve a
--    comprobar la disponibilidad al confirmar.
--  * Un bono no se descuenta al reservar, solo cuando la cita se marca como realizada (o, si sus condiciones lo
--    dicen, por no asistir o cancelar tarde). Deshacer el "realizada" devuelve la sesión.
--  * Recepción gestiona sesiones, reservas y bonos, pero no ve valoraciones, notas, mediciones ni la indicación
--    clínica de un seguimiento.
-- =====================================================================

set search_path = nutricion, extensions, public;

-- ---------------------------------------------------------------- ajustes

alter table clinicas
  add column seguimiento_max_mensajes    int not null default 2 check (seguimiento_max_mensajes between 0 and 10),
  add column seguimiento_intervalo_dias  int not null default 4 check (seguimiento_intervalo_dias between 1 and 30),
  add column seguimiento_antelacion_dias int not null default 7 check (seguimiento_antelacion_dias between 0 and 60),
  add column seguimiento_margen_dias     int not null default 3 check (seguimiento_margen_dias between 0 and 60);

alter table plantillas_mensaje drop constraint plantillas_mensaje_clave_check;
alter table plantillas_mensaje add constraint plantillas_mensaje_clave_check check (clave in (
  'confirmacion_cita', 'recordatorio_cita', 'cambio_cita', 'cancelacion_cita', 'formulario_pendiente',
  'formulario_recordatorio', 'oferta_lista_espera', 'aviso_equipo', 'mensaje_equipo',
  'recordatorio_seguimiento', 'propuesta_sesiones', 'confirmacion_sesiones'));

alter table solicitudes drop constraint solicitudes_tipo_check;
alter table solicitudes add constraint solicitudes_tipo_check check (tipo in (
  'cambio_fuera_plazo', 'cancelacion_fuera_plazo', 'pregunta_clinica', 'pregunta_sin_respuesta', 'hablar_con_persona',
  'queja', 'envio_fallido', 'otro', 'sin_disponibilidad', 'seguimiento_vencido'));

-- ---------------------------------------------------------------- valoraciones

-- Estructura de la valoración según el tipo de consulta. secciones: [{clave, titulo, ayuda?}]
create table plantillas_valoracion (
  id         bigint generated always as identity primary key,
  clinica_id uuid not null references clinicas (id) on delete cascade,
  nombre     text not null check (length(trim(nombre)) between 2 and 120),
  tipo       text not null default 'revision' check (tipo in ('primera_visita', 'revision', 'otro')),
  secciones  jsonb not null check (jsonb_typeof(secciones) = 'array'),
  mediciones text[] not null default '{}',          -- tipos de medición que propone la pantalla
  activa     boolean not null default true,
  orden      int not null default 0,
  unique (clinica_id, id),
  unique (clinica_id, nombre)
);

-- Una valoración por consulta. Mientras es borrador se edita; al cerrarla ya no cambia (las correcciones van como
-- nota posterior, con su fecha y autor).
create table valoraciones (
  id             bigint generated always as identity primary key,
  clinica_id     uuid not null references clinicas (id) on delete cascade,
  paciente_id    bigint not null,
  profesional_id bigint,
  cita_id        bigint,
  plantilla_id   bigint,
  tipo           text not null check (tipo in ('primera_visita', 'revision', 'otro')),
  titulo         text not null,
  fecha          date not null,
  secciones      jsonb not null,                    -- copia de la plantilla al abrirla
  contenido      jsonb not null default '{}'::jsonb, -- {clave_seccion: texto}
  estado         text not null default 'borrador' check (estado in ('borrador', 'cerrada')),
  creada_por     uuid,
  creada_en      timestamptz not null default now(),
  actualizada_en timestamptz not null default now(),
  cerrada_en     timestamptz,
  cerrada_por    uuid,
  unique (clinica_id, id),
  foreign key (clinica_id, paciente_id) references pacientes (clinica_id, id) on delete cascade,
  foreign key (clinica_id, profesional_id) references profesionales (clinica_id, id) on delete set null (profesional_id),
  foreign key (clinica_id, cita_id) references citas (clinica_id, id) on delete set null (cita_id),
  foreign key (clinica_id, plantilla_id) references plantillas_valoracion (clinica_id, id) on delete set null (plantilla_id)
);
create unique index valoraciones_una_por_cita on valoraciones (cita_id) where cita_id is not null;
create index valoraciones_paciente on valoraciones (paciente_id, fecha desc, id desc);

create table notas_clinicas (
  id            bigint generated always as identity primary key,
  clinica_id    uuid not null references clinicas (id) on delete cascade,
  paciente_id   bigint not null,
  valoracion_id bigint,
  texto         text not null check (length(trim(texto)) between 1 and 5000),
  autor         uuid,
  autor_nombre  text,
  creada_en     timestamptz not null default now(),
  foreign key (clinica_id, paciente_id) references pacientes (clinica_id, id) on delete cascade,
  foreign key (clinica_id, valoracion_id) references valoraciones (clinica_id, id) on delete cascade
);
create index notas_paciente on notas_clinicas (paciente_id, creada_en desc);

-- Cada dato lleva su origen: medido en consulta, aportado por el paciente o calculado. Nunca se interpreta solo.
create table mediciones (
  id               bigint generated always as identity primary key,
  clinica_id       uuid not null references clinicas (id) on delete cascade,
  paciente_id      bigint not null,
  tipo             text not null,
  nombre           text not null,
  valor            numeric(8, 2) not null,
  unidad           text,
  origen           text not null check (origen in ('consulta', 'paciente', 'calculado')),
  metodo           text,                            -- bioimpedancia, plicometría, cinta... (composición corporal)
  fecha            date not null,
  valoracion_id    bigint,
  nota             text,
  anulada_en       timestamptz,
  motivo_anulacion text,
  registrada_por   uuid,
  creada_en        timestamptz not null default now(),
  foreign key (clinica_id, paciente_id) references pacientes (clinica_id, id) on delete cascade,
  foreign key (clinica_id, valoracion_id) references valoraciones (clinica_id, id) on delete cascade
);
create index mediciones_paciente on mediciones (paciente_id, tipo, fecha);

-- ---------------------------------------------------------------- bonos

create table bono_tipos (
  id                          bigint generated always as identity primary key,
  clinica_id                  uuid not null references clinicas (id) on delete cascade,
  nombre                      text not null check (length(trim(nombre)) between 2 and 120),
  descripcion                 text,
  sesiones                    int not null check (sesiones between 1 and 100),
  precio_centimos             int check (precio_centimos >= 0),
  servicios                   bigint[] not null default '{}',   -- servicios que cubre (se validan al guardar)
  validez_dias                int check (validez_dias between 1 and 1095),  -- null = no caduca
  condiciones                 text,
  penaliza_no_asistida        boolean not null default false,
  penaliza_cancelacion_tardia boolean not null default false,
  activo                      boolean not null default true,
  orden                       int not null default 0,
  unique (clinica_id, id),
  unique (clinica_id, nombre)
);

-- Bono comprado por un paciente. Copia las condiciones del tipo en el momento de la compra: cambiar el catálogo no
-- cambia lo que ya se vendió.
create table bonos (
  id                          bigint generated always as identity primary key,
  clinica_id                  uuid not null references clinicas (id) on delete cascade,
  paciente_id                 bigint not null,
  bono_tipo_id                bigint,
  nombre                      text not null,
  sesiones_total              int not null check (sesiones_total between 1 and 100),
  precio_centimos             int check (precio_centimos >= 0),
  servicios                   bigint[] not null,
  fecha_compra                date not null,
  caduca                      date,
  condiciones                 text,
  penaliza_no_asistida        boolean not null default false,
  penaliza_cancelacion_tardia boolean not null default false,
  estado                      text not null default 'activo' check (estado in ('activo', 'agotado', 'caducado', 'anulado')),
  pago_estado                 text not null default 'pendiente' check (pago_estado in ('pendiente', 'parcial', 'pagado')),
  notas                       text,
  clave_idempotencia          text,
  creado_por                  uuid,
  creado_en                   timestamptz not null default now(),
  unique (clinica_id, id),
  unique (clinica_id, clave_idempotencia),
  foreign key (clinica_id, paciente_id) references pacientes (clinica_id, id) on delete cascade,
  foreign key (clinica_id, bono_tipo_id) references bono_tipos (clinica_id, id) on delete set null (bono_tipo_id)
);
create index bonos_paciente on bonos (paciente_id, estado);

-- Una sesión descontada por cita. Deshacer la cita marca el consumo como revertido (no se borra).
create table bono_consumos (
  id           bigint generated always as identity primary key,
  clinica_id   uuid not null,
  bono_id      bigint not null,
  cita_id      bigint not null,
  tipo         text not null check (tipo in ('sesion', 'penalizacion')),
  creado_en    timestamptz not null default now(),
  revertido_en timestamptz,
  foreign key (clinica_id, bono_id) references bonos (clinica_id, id) on delete cascade,
  foreign key (clinica_id, cita_id) references citas (clinica_id, id) on delete cascade
);
create unique index bono_consumo_unico on bono_consumos (cita_id) where revertido_en is null;
create index bono_consumos_bono on bono_consumos (bono_id) where revertido_en is null;

alter table citas add column bono_id bigint;
alter table citas add foreign key (clinica_id, bono_id) references bonos (clinica_id, id) on delete set null (bono_id);
create index citas_bono on citas (bono_id) where bono_id is not null;

-- ---------------------------------------------------------------- programas y sesiones

-- Formas de programar:
--   todas      (A) se buscan huecos para todas las sesiones y el paciente confirma el conjunto
--   una_a_una  (B) se ofrece la siguiente cuando toca; su plazo se recalcula desde la fecha real de la anterior
--   recurrente (C) mismo día de la semana y hora, si hay disponibilidad
--   flexible   (D) cada sesión tiene un plazo y el paciente elige dentro
create table programas (
  id              bigint generated always as identity primary key,
  clinica_id      uuid not null references clinicas (id) on delete cascade,
  paciente_id     bigint not null,
  profesional_id  bigint not null,
  servicio_id     bigint not null,
  nombre          text not null check (length(trim(nombre)) between 2 and 120),
  forma           text not null check (forma in ('todas', 'una_a_una', 'recurrente', 'flexible')),
  num_sesiones    int not null check (num_sesiones between 1 and 52),
  frecuencia_dias int not null check (frecuencia_dias between 1 and 365),
  margen_dias     int not null default 3 check (margen_dias between 0 and 90),
  fecha_inicio    date not null,
  modalidad       text not null default 'presencial' check (modalidad in ('presencial', 'online')),
  dia_semana      int check (dia_semana between 1 and 7),
  hora            time,
  condiciones     text,                            -- condiciones de cancelación y del programa
  bono_id         bigint,
  avisar          boolean not null default true,   -- recordatorios de reserva autorizados
  estado          text not null default 'activo' check (estado in ('activo', 'pausado', 'finalizado', 'cancelado')),
  motivo_fin      text,
  origen_cita_id  bigint,                          -- consulta en la que se indicó (seguimientos)
  creado_por      uuid,
  creado_en       timestamptz not null default now(),
  finalizado_en   timestamptz,
  unique (clinica_id, id),
  check (forma <> 'recurrente' or (dia_semana is not null and hora is not null)),
  foreign key (clinica_id, paciente_id) references pacientes (clinica_id, id) on delete cascade,
  foreign key (clinica_id, profesional_id) references profesionales (clinica_id, id),
  foreign key (clinica_id, servicio_id) references servicios (clinica_id, id),
  foreign key (clinica_id, bono_id) references bonos (clinica_id, id) on delete set null (bono_id),
  foreign key (clinica_id, origen_cita_id) references citas (clinica_id, id) on delete set null (origen_cita_id)
);
create index programas_paciente on programas (paciente_id, estado);

-- Una sesión prevista. Pendiente o propuesta no ocupa la agenda; reservada tiene su cita.
create table sesiones (
  id                  bigint generated always as identity primary key,
  clinica_id          uuid not null references clinicas (id) on delete cascade,
  paciente_id         bigint not null,
  programa_id         bigint,                      -- null = seguimiento suelto ("revisión dentro de dos semanas")
  numero              int not null default 1,
  profesional_id      bigint not null,
  servicio_id         bigint not null,
  modalidad           text not null default 'presencial' check (modalidad in ('presencial', 'online')),
  objetivo            date not null,               -- fecha ideal que indicó el profesional
  ventana_desde       date not null,               -- plazo autorizado
  ventana_hasta       date not null,
  estado              text not null default 'pendiente' check (estado in
                        ('pendiente', 'propuesta', 'reservada', 'realizada', 'cancelada', 'no_asistida', 'suspendida')),
  cita_id             bigint,
  propuesta_inicio    timestamptz,
  avisar              boolean not null default true,
  mensajes_enviados   int not null default 0,
  ultima_gestion_en   timestamptz,                 -- último recordatorio (o última comprobación sin huecos)
  alerta_sin_hueco_en timestamptz,
  alerta_vencida_en   timestamptz,
  indicacion          text,                        -- lo que dijo el profesional; solo lo ve el equipo sanitario
  origen_cita_id      bigint,
  creada_por          uuid,
  creada_en           timestamptz not null default now(),
  actualizada_en      timestamptz not null default now(),
  unique (clinica_id, id),
  check (ventana_hasta >= ventana_desde),
  check (estado <> 'reservada' or cita_id is not null),
  check (estado <> 'propuesta' or propuesta_inicio is not null),
  foreign key (clinica_id, paciente_id) references pacientes (clinica_id, id) on delete cascade,
  foreign key (clinica_id, programa_id) references programas (clinica_id, id) on delete cascade,
  foreign key (clinica_id, profesional_id) references profesionales (clinica_id, id),
  foreign key (clinica_id, servicio_id) references servicios (clinica_id, id),
  foreign key (clinica_id, cita_id) references citas (clinica_id, id) on delete set null (cita_id),
  foreign key (clinica_id, origen_cita_id) references citas (clinica_id, id) on delete set null (origen_cita_id)
);
create unique index sesiones_cita on sesiones (cita_id) where cita_id is not null;
create unique index sesiones_numero on sesiones (programa_id, numero) where programa_id is not null;
create index sesiones_estado on sesiones (clinica_id, estado, ventana_desde);
create index sesiones_paciente on sesiones (paciente_id, estado);

alter table envios add column sesion_id bigint;
create index envios_sesion on envios (sesion_id) where sesion_id is not null;

alter table plantillas_valoracion enable row level security;
alter table valoraciones          enable row level security;
alter table notas_clinicas        enable row level security;
alter table mediciones            enable row level security;
alter table bono_tipos            enable row level security;
alter table bonos                 enable row level security;
alter table bono_consumos         enable row level security;
alter table programas             enable row level security;
alter table sesiones              enable row level security;

-- =====================================================================
-- Valores por defecto
-- =====================================================================

create function _plantillas_fase3(p_clinica uuid) returns void
language sql security definer set search_path = nutricion, extensions, pg_temp as $$
  insert into plantillas_mensaje (clinica_id, clave, texto) values
    (p_clinica, 'recordatorio_seguimiento', 'Hola {paciente}, {profesional} quiere verte para tu {servicio} entre el {desde} y el {hasta}. ¿Te busco hora? Contesta a este mensaje y te paso los huecos libres.'),
    (p_clinica, 'propuesta_sesiones', 'Hola {paciente}, para "{programa}" te proponemos estas citas:
{fechas}
¿Te vienen bien? Responde SÍ y las reservamos todas, o dinos cuál quieres cambiar.'),
    (p_clinica, 'confirmacion_sesiones', 'Hola {paciente}, quedan reservadas tus citas de "{programa}":
{fechas}
Si necesitas cambiar alguna, responde a este mensaje.')
  on conflict do nothing;
  insert into plantillas_valoracion (clinica_id, nombre, tipo, orden, mediciones, secciones) values
    (p_clinica, 'Primera valoración', 'primera_visita', 1, array['peso', 'altura', 'cintura', 'cadera'],
     '[{"clave":"anamnesis","titulo":"Anamnesis","ayuda":"Historia, antecedentes relevantes, medicación, hábitos y horarios."},
       {"clave":"objetivos","titulo":"Objetivos","ayuda":"Los que acordáis en consulta."},
       {"clave":"observaciones","titulo":"Observaciones"},
       {"clave":"pautas","titulo":"Pautas acordadas"},
       {"clave":"proximas","titulo":"Próximas actuaciones","ayuda":"Qué toca en la siguiente consulta."}]'::jsonb),
    (p_clinica, 'Revisión', 'revision', 2, array['peso', 'cintura'],
     '[{"clave":"evolucion","titulo":"Evolución","ayuda":"Cómo ha ido desde la última consulta, según el paciente y según lo observado."},
       {"clave":"dificultades","titulo":"Dificultades para seguir las pautas"},
       {"clave":"observaciones","titulo":"Observaciones"},
       {"clave":"pautas","titulo":"Pautas acordadas"},
       {"clave":"proximas","titulo":"Próximas actuaciones"}]'::jsonb)
  on conflict do nothing;
$$;

create function _clinica_nueva_fase3() returns trigger
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
begin
  perform _plantillas_fase3(new.id);
  return null;
end;
$$;
create trigger clinica_nueva_fase3 after insert on clinicas for each row execute function _clinica_nueva_fase3();
select _plantillas_fase3(id) from clinicas;

-- =====================================================================
-- Utilidades
-- =====================================================================

-- "lunes 3 de noviembre"
create function fecha_dia_es(p date) returns text language sql immutable as $$
  select (array['lunes','martes','miércoles','jueves','viernes','sábado','domingo'])[extract(isodow from p)::int]
      || ' ' || extract(day from p)::int || ' de '
      || (array['enero','febrero','marzo','abril','mayo','junio','julio','agosto','septiembre','octubre','noviembre',
                'diciembre'])[extract(month from p)::int]
$$;

-- Tipos de medición conocidos: unidad, rango válido y si necesitan método (composición corporal).
create function _tipos_medicion() returns jsonb language sql immutable as $$
  select '{
    "peso":     {"nombre":"Peso","unidad":"kg","min":2,"max":400},
    "altura":   {"nombre":"Altura","unidad":"cm","min":40,"max":250},
    "imc":      {"nombre":"IMC","unidad":"kg/m²","solo_calculado":true},
    "cintura":  {"nombre":"Perímetro de cintura","unidad":"cm","min":30,"max":250},
    "cadera":   {"nombre":"Perímetro de cadera","unidad":"cm","min":30,"max":250},
    "brazo":    {"nombre":"Perímetro de brazo","unidad":"cm","min":10,"max":80},
    "muslo":    {"nombre":"Perímetro de muslo","unidad":"cm","min":20,"max":120},
    "grasa":    {"nombre":"Masa grasa","unidad":"%","min":2,"max":75,"requiere_metodo":true},
    "musculo":  {"nombre":"Masa muscular","unidad":"kg","min":5,"max":150,"requiere_metodo":true},
    "agua":     {"nombre":"Agua corporal","unidad":"%","min":20,"max":80,"requiere_metodo":true},
    "visceral": {"nombre":"Grasa visceral","unidad":"nivel","min":1,"max":60,"requiere_metodo":true},
    "otro":     {"nombre":"Otro indicador","libre":true}
  }'::jsonb
$$;

-- Valida una medición. Devuelve null si está bien o el motivo.
create function _medicion_no_valida(d jsonb) returns text language plpgsql immutable as $$
declare t jsonb := _tipos_medicion() -> (d->>'tipo'); v numeric;
begin
  if t is null then return 'tipo_medicion_desconocido'; end if;
  if (t->>'solo_calculado')::boolean then return 'medicion_calculada'; end if;
  begin v := replace(d->>'valor', ',', '.')::numeric; exception when others then return 'no_es_numero'; end;
  if v is null then return 'no_es_numero'; end if;
  if t ? 'min' and (v < (t->>'min')::numeric or v > (t->>'max')::numeric) then return 'fuera_de_rango'; end if;
  if (t->>'libre')::boolean and nullif(trim(coalesce(d->>'nombre', '')), '') is null then return 'falta_nombre'; end if;
  if (t->>'requiere_metodo')::boolean and nullif(trim(coalesce(d->>'metodo', '')), '') is null then return 'falta_metodo'; end if;
  return null;
end;
$$;

create function _insertar_medicion(p_clinica uuid, p_paciente bigint, d jsonb, p_origen text, p_fecha date,
                                   p_valoracion bigint default null) returns bigint
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare t jsonb := _tipos_medicion() -> (d->>'tipo'); v_id bigint;
begin
  insert into mediciones (clinica_id, paciente_id, tipo, nombre, valor, unidad, origen, metodo, fecha, valoracion_id, nota,
                          registrada_por)
  values (p_clinica, p_paciente, d->>'tipo',
          case when (t->>'libre')::boolean then left(trim(d->>'nombre'), 80) else t->>'nombre' end,
          round(replace(d->>'valor', ',', '.')::numeric, 2),
          case when (t->>'libre')::boolean then left(nullif(trim(d->>'unidad'), ''), 20) else t->>'unidad' end,
          p_origen, left(nullif(trim(coalesce(d->>'metodo', '')), ''), 80), p_fecha, p_valoracion,
          left(nullif(trim(coalesce(d->>'nota', '')), ''), 500), auth.uid())
  returning id into v_id;
  return v_id;
end;
$$;

-- IMC calculado con el peso medido ese día en consulta y la última altura medida en consulta. Se apunta de dónde sale.
create function _calcular_imc(p_clinica uuid, p_paciente bigint, p_fecha date, p_valoracion bigint default null)
returns bigint language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare v_peso mediciones; v_alt mediciones; v_id bigint;
begin
  select * into v_peso from mediciones where paciente_id = p_paciente and tipo = 'peso' and origen = 'consulta'
    and anulada_en is null and fecha = p_fecha and (p_valoracion is null or valoracion_id = p_valoracion)
  order by id desc limit 1;
  select * into v_alt from mediciones where paciente_id = p_paciente and tipo = 'altura' and origen = 'consulta'
    and anulada_en is null and fecha <= p_fecha order by fecha desc, id desc limit 1;
  if v_peso.id is null or v_alt.id is null then return null; end if;
  update mediciones set anulada_en = now(), motivo_anulacion = 'recalculado'
  where paciente_id = p_paciente and tipo = 'imc' and origen = 'calculado' and fecha = p_fecha and anulada_en is null
    and valoracion_id is not distinct from p_valoracion;
  insert into mediciones (clinica_id, paciente_id, tipo, nombre, valor, unidad, origen, fecha, valoracion_id, nota)
  values (p_clinica, p_paciente, 'imc', 'IMC', round(v_peso.valor / power(v_alt.valor / 100.0, 2), 1), 'kg/m²', 'calculado',
          p_fecha, p_valoracion,
          'Peso / altura². Peso del ' || to_char(v_peso.fecha, 'DD/MM/YYYY') || ', altura del ' || to_char(v_alt.fecha, 'DD/MM/YYYY') || '.')
  returning id into v_id;
  return v_id;
end;
$$;

create function _medicion_json(m mediciones) returns jsonb language sql stable as $$
  select jsonb_build_object('id', m.id, 'tipo', m.tipo, 'nombre', m.nombre, 'valor', m.valor, 'unidad', m.unidad,
    'origen', m.origen, 'metodo', m.metodo, 'fecha', m.fecha, 'valoracion_id', m.valoracion_id, 'nota', m.nota,
    'anulada', m.anulada_en is not null, 'motivo_anulacion', m.motivo_anulacion)
$$;

-- Las valoraciones cerradas no se tocan, y los valores de una medición tampoco (se anulan con motivo).
create function _valoracion_inmutable() returns trigger language plpgsql as $$
begin
  if old.estado = 'cerrada' then
    raise exception 'valoracion_cerrada' using errcode = '55000';
  end if;
  return case when tg_op = 'DELETE' then old else new end;
end;
$$;
create trigger valoraciones_inmutables before update or delete on valoraciones
for each row when (old.estado = 'cerrada') execute function _valoracion_inmutable();

create function _medicion_inmutable() returns trigger language plpgsql
security definer set search_path = nutricion, extensions, pg_temp as $$
begin
  -- las de una valoración en borrador sí se pueden tocar
  if exists (select 1 from valoraciones where id = old.valoracion_id and estado = 'borrador') then return new; end if;
  if (new.tipo, new.valor, new.origen, new.fecha, new.paciente_id, new.metodo)
     is distinct from (old.tipo, old.valor, old.origen, old.fecha, old.paciente_id, old.metodo) then
    raise exception 'medicion_no_editable' using errcode = '55000';
  end if;
  return new;
end;
$$;
create trigger mediciones_inmutables before update on mediciones for each row execute function _medicion_inmutable();

-- ---------------------------------------------------------------- bonos (internas)

create function _bono_usadas(p_bono bigint) returns int language sql stable security definer
set search_path = nutricion, extensions, pg_temp as $$
  select count(*)::int from bono_consumos where bono_id = p_bono and revertido_en is null
$$;

-- Citas futuras (o pasadas sin marcar) que van a usar el bono.
create function _bono_reservadas(p_bono bigint) returns int language sql stable security definer
set search_path = nutricion, extensions, pg_temp as $$
  select count(*)::int from citas c where c.bono_id = p_bono and c.estado = 'reservada'
$$;

create function _bono_json(p_bono bigint) returns jsonb
language sql stable security definer set search_path = nutricion, extensions, pg_temp as $$
  select jsonb_build_object('id', b.id, 'paciente_id', b.paciente_id, 'bono_tipo_id', b.bono_tipo_id, 'nombre', b.nombre,
    'sesiones_total', b.sesiones_total, 'usadas', _bono_usadas(b.id), 'reservadas', _bono_reservadas(b.id),
    'restantes', b.sesiones_total - _bono_usadas(b.id),
    'precio', round(b.precio_centimos / 100.0, 2), 'fecha_compra', b.fecha_compra, 'caduca', b.caduca,
    'condiciones', b.condiciones, 'penaliza_no_asistida', b.penaliza_no_asistida,
    'penaliza_cancelacion_tardia', b.penaliza_cancelacion_tardia, 'estado', b.estado, 'pago_estado', b.pago_estado,
    'notas', b.notas,
    'servicios', (select coalesce(jsonb_agg(jsonb_build_object('id', s.id, 'nombre', s.nombre) order by s.orden, s.id), '[]'::jsonb)
                  from servicios s where s.id = any (b.servicios)))
  from bonos b where b.id = p_bono
$$;

-- Bono activo del paciente que cubre ese servicio y le quedan sesiones sin comprometer. Bloquea la fila del bono
-- para que dos reservas a la vez no se lleven la misma última sesión.
create function _bono_para(p_paciente bigint, p_servicio bigint, p_fecha date) returns bigint
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare b record;
begin
  for b in select id, sesiones_total from bonos
           where paciente_id = p_paciente and estado = 'activo' and p_servicio = any (servicios)
             and (caduca is null or caduca >= p_fecha)
           order by caduca nulls last, fecha_compra, id
           for update
  loop
    if b.sesiones_total - _bono_usadas(b.id) - _bono_reservadas(b.id) > 0 then return b.id; end if;
  end loop;
  return null;
end;
$$;

create function _bono_actualizar_estado(p_bono bigint) returns void
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
begin
  update bonos set estado = case
      when _bono_usadas(id) >= sesiones_total then 'agotado'
      when caduca is not null and caduca < _hoy(_tz(clinica_id)) then 'caducado'
      else 'activo' end
  where id = p_bono and estado in ('activo', 'agotado', 'caducado');
end;
$$;

create function _bono_consumir(p_bono bigint, p_cita bigint, p_tipo text) returns boolean
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare b bonos;
begin
  select * into b from bonos where id = p_bono for update;
  if b.id is null or b.estado = 'anulado' then return false; end if;
  if exists (select 1 from bono_consumos where cita_id = p_cita and revertido_en is null) then return true; end if;
  if _bono_usadas(b.id) >= b.sesiones_total then return false; end if;   -- agotado: no se descuenta de más
  insert into bono_consumos (clinica_id, bono_id, cita_id, tipo) values (b.clinica_id, b.id, p_cita, p_tipo);
  perform _bono_actualizar_estado(b.id);
  perform _auditar(b.clinica_id, 'consumir_bono', 'bono', b.id::text, b.paciente_id,
                   jsonb_build_object('cita', p_cita, 'tipo', p_tipo));
  return true;
end;
$$;

create function _bono_revertir(p_cita bigint) returns void
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare r record;
begin
  for r in update bono_consumos set revertido_en = now() where cita_id = p_cita and revertido_en is null
           returning bono_id, clinica_id loop
    perform _bono_actualizar_estado(r.bono_id);
    perform _auditar(r.clinica_id, 'revertir_consumo_bono', 'bono', r.bono_id::text,
                     (select paciente_id from bonos where id = r.bono_id), jsonb_build_object('cita', p_cita));
  end loop;
end;
$$;

-- Al crear una cita se le asigna el bono que la cubra (no se descuenta nada todavía).
create function _cita_bono() returns trigger
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
begin
  if new.bono_id is null and new.estado = 'reservada' then
    new.bono_id := _bono_para(new.paciente_id, new.servicio_id, (new.inicio at time zone _tz(new.clinica_id))::date);
  end if;
  return new;
end;
$$;
create trigger citas_bono before insert on citas for each row execute function _cita_bono();

-- ---------------------------------------------------------------- sesiones (internas)

create function _hora_local(p timestamptz, p_tz text) returns time language sql stable as $$
  select (p at time zone p_tz)::time
$$;

-- ¿Se le puede ofrecer ya esta sesión al paciente? En "una a una", solo la siguiente cuando la anterior ya pasó.
create function _sesion_ofrecible(p_sesion bigint) returns boolean
language sql stable security definer set search_path = nutricion, extensions, pg_temp as $$
  select s.estado in ('pendiente', 'propuesta')
     and (s.programa_id is null or p.estado = 'activo')
     and (p.forma is distinct from 'una_a_una' or not exists (
           select 1 from sesiones a where a.programa_id = s.programa_id and a.numero < s.numero
             and a.estado in ('pendiente', 'propuesta', 'reservada')))
  from sesiones s left join programas p on p.id = s.programa_id
  where s.id = p_sesion
$$;

create function _sesion_json(p_sesion bigint, p_ve_salud boolean) returns jsonb
language sql stable security definer set search_path = nutricion, extensions, pg_temp as $$
  select jsonb_build_object('id', s.id, 'programa_id', s.programa_id, 'programa', p.nombre, 'numero', s.numero,
    'total', p.num_sesiones, 'estado', s.estado,
    'paciente_id', s.paciente_id, 'paciente', trim(pa.nombre || ' ' || coalesce(pa.apellidos, '')),
    'servicio_id', s.servicio_id, 'servicio', se.nombre, 'profesional_id', s.profesional_id, 'profesional', pr.nombre,
    'modalidad', s.modalidad, 'objetivo', s.objetivo, 'ventana_desde', s.ventana_desde, 'ventana_hasta', s.ventana_hasta,
    'ventana_texto', 'entre el ' || fecha_dia_es(s.ventana_desde) || ' y el ' || fecha_dia_es(s.ventana_hasta),
    'cita_id', s.cita_id, 'cita_inicio', _local(ci.inicio, cl.zona_horaria),
    'cita_texto', fecha_es(ci.inicio, cl.zona_horaria), 'cita_estado', ci.estado,
    'propuesta_inicio', _local(s.propuesta_inicio, cl.zona_horaria),
    'propuesta_texto', fecha_es(s.propuesta_inicio, cl.zona_horaria),
    'avisar', s.avisar, 'mensajes_enviados', s.mensajes_enviados,
    'ultima_gestion', _local(s.ultima_gestion_en, cl.zona_horaria),
    'sin_hueco', s.alerta_sin_hueco_en is not null and s.estado in ('pendiente', 'propuesta'),
    'vencida', s.estado in ('pendiente', 'propuesta') and s.ventana_hasta < _hoy(cl.zona_horaria),
    'ofrecible', _sesion_ofrecible(s.id),
    'indicacion', case when p_ve_salud then s.indicacion end)
  from sesiones s join clinicas cl on cl.id = s.clinica_id join pacientes pa on pa.id = s.paciente_id
  join servicios se on se.id = s.servicio_id join profesionales pr on pr.id = s.profesional_id
  left join programas p on p.id = s.programa_id left join citas ci on ci.id = s.cita_id
  where s.id = p_sesion
$$;

create function _programa_json(p_programa bigint, p_ve_salud boolean) returns jsonb
language sql stable security definer set search_path = nutricion, extensions, pg_temp as $$
  select jsonb_build_object('id', p.id, 'paciente_id', p.paciente_id, 'nombre', p.nombre, 'forma', p.forma,
    'num_sesiones', p.num_sesiones, 'frecuencia_dias', p.frecuencia_dias, 'margen_dias', p.margen_dias,
    'fecha_inicio', p.fecha_inicio, 'profesional_id', p.profesional_id, 'profesional', pr.nombre,
    'servicio_id', p.servicio_id, 'servicio', se.nombre, 'modalidad', p.modalidad, 'dia_semana', p.dia_semana,
    'hora', to_char(p.hora, 'HH24:MI'), 'condiciones', p.condiciones, 'bono_id', p.bono_id,
    'bono', (select nombre from bonos where id = p.bono_id), 'avisar', p.avisar, 'estado', p.estado,
    'motivo_fin', p.motivo_fin, 'creado', p.creado_en::date, 'finalizado', p.finalizado_en::date,
    'cuenta', (select jsonb_object_agg(e, n) from (select estado e, count(*) n from sesiones where programa_id = p.id group by estado) x),
    'sesiones', (select coalesce(jsonb_agg(_sesion_json(s.id, p_ve_salud) order by s.numero), '[]'::jsonb)
                 from sesiones s where s.programa_id = p.id))
  from programas p join profesionales pr on pr.id = p.profesional_id join servicios se on se.id = p.servicio_id
  where p.id = p_programa
$$;

-- Huecos para una sesión: solo dentro de su plazo, con su profesional y sin chocar con otras citas del paciente.
create function _huecos_sesion(p_sesion bigint, p_respetar boolean, p_max int default 20, p_desde date default null,
                               p_profesional bigint default null, p_por_dia int default 6)
returns table (inicio timestamptz, fin timestamptz, profesional_id bigint, profesional text)
language plpgsql stable security definer set search_path = nutricion, extensions, pg_temp as $$
#variable_conflict use_column
declare s sesiones; v_tz text;
begin
  select * into s from sesiones x where x.id = p_sesion;
  if s.id is null then return; end if;
  v_tz := _tz(s.clinica_id);
  return query
  select h.inicio, h.fin, h.profesional_id, h.profesional
  from _huecos(s.clinica_id, s.servicio_id, coalesce(p_profesional, s.profesional_id),
               greatest(s.ventana_desde, coalesce(p_desde, s.ventana_desde))::timestamp at time zone v_tz,
               (s.ventana_hasta + 1)::timestamp at time zone v_tz, s.modalidad, s.profesional_id, 200, p_por_dia,
               p_respetar) h
  where not exists (select 1 from citas x where x.paciente_id = s.paciente_id and x.estado in ('reservada', 'realizada')
                      and tstzrange(x.inicio, x.fin) && tstzrange(h.inicio, h.fin))
  order by h.inicio limit greatest(p_max, 1);
end;
$$;

-- Deja de avisar de una sesión (ya reservada, cancelada o fuera del programa).
create function _detener_avisos(p_sesion bigint) returns void
language sql security definer set search_path = nutricion, extensions, pg_temp as $$
  update envios set estado = 'cancelado', secreto = null
  where sesion_id = p_sesion and estado = 'pendiente' and tipo = 'recordatorio_seguimiento'
$$;

-- Aviso al profesional (una vez por sesión) de que no hay huecos en el plazo que autorizó.
create function _alerta_sin_hueco(p_sesion bigint) returns bigint
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare s sesiones; v_id bigint; v_txt text;
begin
  select * into s from sesiones where id = p_sesion for update;
  update sesiones set ultima_gestion_en = now() where id = s.id;
  if s.alerta_sin_hueco_en is not null then return null; end if;
  select se.nombre || ' con ' || pr.nombre || ': no hay huecos ' || 'entre el ' || fecha_dia_es(s.ventana_desde)
         || ' y el ' || fecha_dia_es(s.ventana_hasta) || coalesce(' (sesión ' || s.numero || ' de "' || p.nombre || '")', '')
         || '. Busca otra fecha, otro profesional o reserva con una excepción.'
    into v_txt
  from servicios se, profesionales pr left join programas p on p.id = s.programa_id
  where se.id = s.servicio_id and pr.id = s.profesional_id;
  v_id := _solicitud(s.clinica_id, 'sin_disponibilidad', v_txt, s.paciente_id);
  update solicitudes set profesional_id = s.profesional_id where id = v_id;
  update sesiones set alerta_sin_hueco_en = now() where id = s.id;
  return v_id;
end;
$$;

-- Reserva una sesión. Dentro del plazo autorizado siempre; fuera, solo como excepción del equipo sanitario con motivo.
-- Nunca fuera del horario sin excepción, nunca con solape (eso lo garantiza _reservar).
create function _reservar_sesion(p_sesion bigint, p_inicio timestamptz, p_profesional bigint, p_origen text,
                                 p_clave text default null, p_forzar boolean default false,
                                 p_motivo_excepcion text default null) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare s sesiones; p programas; ci citas; v_tz text; v_fecha date; r jsonb; v_cita bigint; v_fuera boolean;
begin
  select * into s from sesiones where id = p_sesion for update;
  if s.id is null then return jsonb_build_object('ok', false, 'motivo', 'sesion_no_existe'); end if;
  v_tz := _tz(s.clinica_id);
  if s.estado = 'reservada' then
    select * into ci from citas where id = s.cita_id;
    if ci.inicio = p_inicio then
      return jsonb_build_object('ok', true, 'repetida', true, 'cita', _cita_json(ci.id), 'sesion', _sesion_json(s.id, false));
    end if;
    return jsonb_build_object('ok', false, 'motivo', 'sesion_ya_reservada', 'cita', _cita_json(ci.id));
  end if;
  if s.estado not in ('pendiente', 'propuesta') then
    return jsonb_build_object('ok', false, 'motivo', 'sesion_no_reservable', 'estado', s.estado);
  end if;
  select * into p from programas where id = s.programa_id;
  if p.id is not null and p.estado <> 'activo' then
    return jsonb_build_object('ok', false, 'motivo', 'programa_no_activo', 'estado', p.estado);
  end if;
  if p_inicio is null then return jsonb_build_object('ok', false, 'motivo', 'falta_hora'); end if;
  v_fecha := (p_inicio at time zone v_tz)::date;
  v_fuera := v_fecha not between s.ventana_desde and s.ventana_hasta;
  if v_fuera then
    if not p_forzar then
      return jsonb_build_object('ok', false, 'motivo', 'fuera_de_plazo', 'ventana_desde', s.ventana_desde,
                                'ventana_hasta', s.ventana_hasta,
                                'ventana_texto', 'entre el ' || fecha_dia_es(s.ventana_desde) || ' y el ' || fecha_dia_es(s.ventana_hasta));
    end if;
    if nullif(trim(coalesce(p_motivo_excepcion, '')), '') is null then
      return jsonb_build_object('ok', false, 'motivo', 'falta_motivo_excepcion', 'avisos', jsonb_build_array('fuera del plazo autorizado'));
    end if;
  end if;
  -- Para que la cita nueva no se enlace sola con otra sesión.
  perform set_config('nutricion.reservando_sesion', s.id::text, true);
  r := _reservar(s.clinica_id, s.paciente_id, s.servicio_id, coalesce(p_profesional, s.profesional_id), p_inicio,
                 s.modalidad, p_origen, coalesce(p_clave, 'sesion:' || s.id || ':' || extract(epoch from p_inicio)::bigint),
                 p_forzar, p_motivo_excepcion, null,
                 case when p.id is not null then 'Sesión ' || s.numero || ' de ' || p.num_sesiones || ' · ' || p.nombre
                      else 'Seguimiento' end);
  perform set_config('nutricion.reservando_sesion', '', true);
  if not (r->>'ok')::boolean then return r; end if;
  v_cita := (r->'cita'->>'id')::bigint;
  if v_fuera then
    update citas set excepcion = concat_ws('; ', excepcion, 'fuera del plazo autorizado (' || to_char(s.ventana_desde, 'DD/MM')
                                           || '-' || to_char(s.ventana_hasta, 'DD/MM') || ') — ' || left(trim(p_motivo_excepcion), 300))
    where id = v_cita;
  end if;
  if p.bono_id is not null then
    update citas set bono_id = p.bono_id where id = v_cita and bono_id is distinct from p.bono_id
      and exists (select 1 from bonos where id = p.bono_id and estado = 'activo');
  end if;
  update sesiones set estado = 'reservada', cita_id = v_cita, propuesta_inicio = null, actualizada_en = now()
  where id = s.id;
  perform _detener_avisos(s.id);
  perform _auditar(s.clinica_id, 'reservar_sesion', 'sesion', s.id::text, s.paciente_id,
                   jsonb_build_object('cita', v_cita, 'origen', p_origen, 'excepcion', v_fuera));
  return jsonb_build_object('ok', true, 'repetida', coalesce((r->>'repetida')::boolean, false),
                            'cita', _cita_json(v_cita), 'sesion', _sesion_json(s.id, false), 'avisos', r->'avisos');
end;
$$;

-- Fechas y huecos para las sesiones pendientes de un programa (formas A y C, o para rellenar las que falten).
-- No reserva nada ni bloquea la agenda: deja las sesiones en "propuesta".
create function _proponer(p_programa bigint) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare
  p programas; c clinicas; s sesiones; v_dur int; v_ini timestamptz; v_cand timestamptz; v_usadas date[] := '{}';
  v_hora time; d date; v_prop jsonb := '[]'::jsonb; v_sin jsonb := '[]'::jsonb; v_hoy date;
begin
  select * into p from programas where id = p_programa for update;
  select * into c from clinicas where id = p.clinica_id;
  select duracion_min into v_dur from servicios where id = p.servicio_id;
  v_hoy := _hoy(c.zona_horaria);
  v_hora := p.hora;
  -- Días que ya tiene ocupados el programa (reservadas): no se proponen dos sesiones el mismo día.
  select coalesce(array_agg((ci.inicio at time zone c.zona_horaria)::date), '{}') into v_usadas
  from sesiones x join citas ci on ci.id = x.cita_id where x.programa_id = p.id and x.estado = 'reservada';
  for s in select * from sesiones where programa_id = p.id and estado in ('pendiente', 'propuesta') order by numero for update loop
    v_ini := null;
    if p.forma = 'recurrente' then
      for d in select g::date from generate_series(greatest(s.ventana_desde, v_hoy), s.ventana_hasta, interval '1 day') g
               where extract(isodow from g) = p.dia_semana order by abs(g::date - s.objetivo), g loop
        v_cand := (d + p.hora) at time zone c.zona_horaria;
        continue when v_cand < now() + make_interval(mins => c.antelacion_minima_min) or d = any (v_usadas);
        continue when not _libre(s.profesional_id, v_cand, v_cand + make_interval(mins => v_dur), s.modalidad);
        continue when exists (select 1 from citas x where x.paciente_id = s.paciente_id and x.estado in ('reservada', 'realizada')
                                and tstzrange(x.inicio, x.fin) && tstzrange(v_cand, v_cand + make_interval(mins => v_dur)));
        v_ini := v_cand;
        exit;
      end loop;
    else
      select h.inicio into v_ini from _huecos_sesion(s.id, true, 400, null, null, 50) h
      where (h.inicio at time zone c.zona_horaria)::date <> all (v_usadas)
      order by abs((h.inicio at time zone c.zona_horaria)::date - s.objetivo),
               abs(extract(epoch from (_hora_local(h.inicio, c.zona_horaria) - coalesce(v_hora, '10:00'::time)))),
               h.inicio
      limit 1;
    end if;
    if v_ini is null then
      update sesiones set estado = 'pendiente', propuesta_inicio = null, actualizada_en = now() where id = s.id;
      perform _alerta_sin_hueco(s.id);
      v_sin := v_sin || _sesion_json(s.id, false);
    else
      v_hora := coalesce(v_hora, _hora_local(v_ini, c.zona_horaria));   -- las siguientes, a la misma hora si se puede
      v_usadas := v_usadas || (v_ini at time zone c.zona_horaria)::date;
      update sesiones set estado = 'propuesta', propuesta_inicio = v_ini, actualizada_en = now() where id = s.id;
      v_prop := v_prop || _sesion_json(s.id, false);
    end if;
  end loop;
  perform _auditar(p.clinica_id, 'proponer_sesiones', 'programa', p.id::text, p.paciente_id,
                   jsonb_build_object('propuestas', jsonb_array_length(v_prop), 'sin_hueco', jsonb_array_length(v_sin)));
  return jsonb_build_object('ok', true, 'propuestas', v_prop, 'sin_hueco', v_sin);
end;
$$;

-- Lista "• lunes 3 de noviembre a las 10:00" de las sesiones de un programa en un estado.
create function _lista_fechas(p_programa bigint, p_estado text) returns text
language sql stable security definer set search_path = nutricion, extensions, pg_temp as $$
  select string_agg('• ' || fecha_es(coalesce(ci.inicio, s.propuesta_inicio), cl.zona_horaria), E'\n'
                    order by coalesce(ci.inicio, s.propuesta_inicio))
  from sesiones s join clinicas cl on cl.id = s.clinica_id left join citas ci on ci.id = s.cita_id
  where s.programa_id = p_programa and s.estado = p_estado
$$;

-- Confirma de golpe todas las sesiones propuestas: o se reservan todas o ninguna (si un hueco se ha ocupado
-- mientras tanto, se dice cuál y no se reserva nada). Manda un solo mensaje con todas las fechas.
create function _confirmar_propuesta(p_programa bigint, p_origen text) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare p programas; s sesiones; r jsonb; v_n int := 0; v_fallo jsonb; v_fallo_id bigint; v_fechas text;
begin
  select * into p from programas where id = p_programa for update;
  if p.id is null then return jsonb_build_object('ok', false, 'motivo', 'programa_no_existe'); end if;
  if p.estado <> 'activo' then return jsonb_build_object('ok', false, 'motivo', 'programa_no_activo'); end if;
  if not exists (select 1 from sesiones where programa_id = p.id and estado = 'propuesta') then
    return jsonb_build_object('ok', false, 'motivo', 'sin_propuestas');
  end if;
  perform set_config('nutricion.confirmacion_agrupada', 'si', true);
  begin
    for s in select * from sesiones where programa_id = p.id and estado = 'propuesta' order by numero loop
      r := _reservar_sesion(s.id, s.propuesta_inicio, null, p_origen,
                            'propuesta:' || s.id || ':' || extract(epoch from s.propuesta_inicio)::bigint);
      if not (r->>'ok')::boolean then
        v_fallo_id := s.id;
        v_fallo := jsonb_build_object('numero', s.numero, 'motivo', r->>'motivo',
                                      'fecha_texto', fecha_es(s.propuesta_inicio, _tz(p.clinica_id)));
        raise exception 'propuesta_no_disponible' using errcode = 'CN001';
      end if;
      v_n := v_n + 1;
    end loop;
  exception when sqlstate 'CN001' then
    perform set_config('nutricion.confirmacion_agrupada', '', true);
    -- Esa fecha ya no vale: vuelve a pendiente para proponer otra. Las demás siguen propuestas.
    update sesiones set estado = 'pendiente', propuesta_inicio = null, actualizada_en = now() where id = v_fallo_id;
    return jsonb_build_object('ok', false, 'motivo', 'propuesta_no_disponible', 'sesion', v_fallo);
  end;
  perform set_config('nutricion.confirmacion_agrupada', '', true);
  v_fechas := _lista_fechas(p.id, 'reservada');
  if coalesce(current_setting('nutricion.actor', true), '') <> 'whatsapp'
     and (select enviar_confirmacion from clinicas where id = p.clinica_id) then
    perform _encolar(p.clinica_id, 'confirmacion_sesiones', 'confirmacion_sesiones:' || p.id || ':' || md5(v_fechas),
                     p.paciente_id, null,
                     jsonb_build_object('paciente', (select split_part(trim(nombre), ' ', 1) from pacientes where id = p.paciente_id),
                                        'programa', p.nombre, 'fechas', v_fechas,
                                        'clinica', (select nombre from clinicas where id = p.clinica_id)));
  end if;
  perform _auditar(p.clinica_id, 'confirmar_propuesta', 'programa', p.id::text, p.paciente_id,
                   jsonb_build_object('reservadas', v_n, 'origen', p_origen));
  return jsonb_build_object('ok', true, 'reservadas', v_n, 'programa', _programa_json(p.id, false));
end;
$$;

-- Ventana de una sesión a partir de su fecha objetivo.
create function _ventana(p_objetivo date, p_margen int, out desde date, out hasta date) language sql immutable as $$
  select p_objetivo - p_margen, p_objetivo + p_margen
$$;

create function _crear_sesiones(p_programa bigint, p_indicacion text default null) returns void
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare p programas; k int; v_obj date;
begin
  select * into p from programas where id = p_programa;
  for k in 1 .. p.num_sesiones loop
    v_obj := p.fecha_inicio + (k - 1) * p.frecuencia_dias;
    insert into sesiones (clinica_id, paciente_id, programa_id, numero, profesional_id, servicio_id, modalidad, objetivo,
                          ventana_desde, ventana_hasta, avisar, indicacion, origen_cita_id, creada_por)
    select p.clinica_id, p.paciente_id, p.id, k, p.profesional_id, p.servicio_id, p.modalidad, v_obj, w.desde, w.hasta,
           p.avisar, p_indicacion, p.origen_cita_id, auth.uid()
    from _ventana(v_obj, p.margen_dias) w;
  end loop;
end;
$$;

-- Cierra un programa si ya no le queda ninguna sesión por hacer.
create function _programa_completo(p_programa bigint) returns boolean
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare p programas;
begin
  select * into p from programas where id = p_programa for update;
  if p.id is null or p.estado <> 'activo' then return false; end if;
  if exists (select 1 from sesiones where programa_id = p.id and estado in ('pendiente', 'propuesta', 'reservada', 'suspendida')) then
    return false;
  end if;
  if not exists (select 1 from sesiones where programa_id = p.id and estado = 'realizada') then return false; end if;
  update programas set estado = 'finalizado', motivo_fin = 'completado', finalizado_en = now() where id = p.id;
  perform _auditar(p.clinica_id, 'finalizar_programa', 'programa', p.id::text, p.paciente_id,
                   jsonb_build_object('motivo', 'completado'));
  return true;
end;
$$;

-- Lo que pasa en los seguimientos y bonos cuando una cita cambia de estado.
create function _citas_seguimiento() returns trigger
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare s sesiones; p programas; b bonos; c clinicas; v_dia date; k record;
begin
  if new.estado = old.estado then return null; end if;
  select * into c from clinicas where id = new.clinica_id;

  -- Bono: solo se descuenta al realizarse (o por penalización si sus condiciones lo dicen).
  if new.bono_id is not null then
    select * into b from bonos where id = new.bono_id;
    if new.estado = 'realizada' then
      perform _bono_consumir(b.id, new.id, 'sesion');
    elsif new.estado = 'no_asistida' and b.penaliza_no_asistida then
      perform _bono_consumir(b.id, new.id, 'penalizacion');
    elsif new.estado = 'cancelada' and new.cancelada_por = 'paciente' and b.penaliza_cancelacion_tardia
          and old.inicio - now() < make_interval(hours => c.horas_minimas_cambio) and old.inicio > now() - interval '1 day' then
      perform _bono_consumir(b.id, new.id, 'penalizacion');
    elsif new.estado = 'reservada' then
      perform _bono_revertir(new.id);
    end if;
  end if;

  select * into s from sesiones where cita_id = new.id for update;
  if s.id is null then return null; end if;
  select * into p from programas where id = s.programa_id;
  if new.estado = 'cancelada' then
    -- La sesión vuelve a estar por programar (y los recordatorios pueden volver a empezar).
    update sesiones set estado = case when p.id is null or p.estado = 'activo' then 'pendiente'
                                      when p.estado = 'pausado' then 'suspendida' else 'cancelada' end,
           cita_id = null, mensajes_enviados = 0, ultima_gestion_en = null, alerta_sin_hueco_en = null,
           alerta_vencida_en = null, actualizada_en = now()
    where id = s.id;
  elsif new.estado in ('realizada', 'no_asistida') then
    update sesiones set estado = new.estado, actualizada_en = now() where id = s.id;
    if new.estado = 'realizada' and p.forma = 'una_a_una' then
      -- La siguiente se cuenta desde la fecha real de esta, con la frecuencia que indicó el profesional.
      v_dia := (new.inicio at time zone c.zona_horaria)::date;
      for k in select x.id, x.numero from sesiones x where x.programa_id = p.id and x.numero > s.numero
                 and x.estado in ('pendiente', 'suspendida') loop
        update sesiones x set objetivo = v_dia + (k.numero - s.numero) * p.frecuencia_dias,
               ventana_desde = v_dia + (k.numero - s.numero) * p.frecuencia_dias - p.margen_dias,
               ventana_hasta = v_dia + (k.numero - s.numero) * p.frecuencia_dias + p.margen_dias,
               mensajes_enviados = 0, ultima_gestion_en = null, alerta_sin_hueco_en = null, alerta_vencida_en = null,
               actualizada_en = now()
        where x.id = k.id;
      end loop;
    end if;
    if p.id is not null then perform _programa_completo(p.id); end if;
  elsif new.estado = 'reservada' and old.estado in ('realizada', 'no_asistida') then
    -- Deshacer: la sesión vuelve a reservada; si el programa se cerró solo por esto, se reabre.
    update sesiones set estado = 'reservada', actualizada_en = now() where id = s.id;
    update programas set estado = 'activo', motivo_fin = null, finalizado_en = null
    where id = p.id and estado = 'finalizado' and motivo_fin = 'completado';
  end if;
  return null;
end;
$$;
create trigger citas_seguimiento after update of estado on citas for each row execute function _citas_seguimiento();

-- Si alguien reserva por la agenda (o por el canal normal) una cita que encaja con una sesión pendiente del
-- paciente (mismo servicio, dentro del plazo), la sesión queda reservada con ella y dejan de salir recordatorios.
create function _cita_enlazar_sesion() returns trigger
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare v_sesion bigint; v_dia date;
begin
  if new.estado <> 'reservada' or coalesce(current_setting('nutricion.reservando_sesion', true), '') <> '' then
    return null;
  end if;
  v_dia := (new.inicio at time zone _tz(new.clinica_id))::date;
  select s.id into v_sesion from sesiones s
  where s.paciente_id = new.paciente_id and s.servicio_id = new.servicio_id and s.estado in ('pendiente', 'propuesta')
    and v_dia between s.ventana_desde and s.ventana_hasta and _sesion_ofrecible(s.id)
  order by s.objetivo, s.numero limit 1
  for update skip locked;
  if v_sesion is null then return null; end if;
  update sesiones set estado = 'reservada', cita_id = new.id, propuesta_inicio = null, actualizada_en = now()
  where id = v_sesion;
  perform _detener_avisos(v_sesion);
  return null;
end;
$$;
create trigger citas_enlazar_sesion after insert on citas for each row execute function _cita_enlazar_sesion();

-- La confirmación de cada cita no sale si se están confirmando varias sesiones a la vez (sale un solo mensaje).
create or replace function _citas_despues() returns trigger
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare
  c clinicas; v_desde_chat boolean := coalesce(current_setting('nutricion.actor', true), '') = 'whatsapp';
  v_agrupada boolean := coalesce(current_setting('nutricion.confirmacion_agrupada', true), '') = 'si';
  f record;
begin
  select * into c from clinicas where id = new.clinica_id;
  if tg_op = 'INSERT' then
    if new.estado = 'reservada' and new.inicio > now() then
      if c.enviar_confirmacion and not v_desde_chat and not v_agrupada then
        perform _encolar(new.clinica_id, 'confirmacion_cita', 'confirmacion:' || new.id, new.paciente_id, new.id,
                         _vars_cita(new.id));
      end if;
      for f in select sf.formulario_id from servicio_formularios sf join formularios fo on fo.id = sf.formulario_id
               where sf.servicio_id = new.servicio_id and fo.activo
                 and not exists (select 1 from formulario_envios fe where fe.paciente_id = new.paciente_id
                                   and fe.formulario_id = sf.formulario_id and fe.estado in ('completado', 'revisado'))
      loop
        perform _mandar_formulario(new.clinica_id, new.paciente_id, f.formulario_id, new.id);
      end loop;
    end if;
    return null;
  end if;

  if old.estado = 'reservada' and new.estado = 'cancelada' then
    update envios set estado = 'cancelado', secreto = null
    where cita_id = new.id and estado = 'pendiente' and tipo in ('confirmacion_cita', 'recordatorio_cita', 'cambio_cita');
    if new.inicio > now() then
      if not v_desde_chat then
        perform _encolar(new.clinica_id, 'cancelacion_cita', 'cancelacion:' || new.id, new.paciente_id, new.id,
                         _vars_cita(new.id));
      end if;
      perform _ofrecer_hueco(new.clinica_id, new.profesional_id, new.inicio);
    end if;
    update lista_espera set estado = 'cancelada' where cita_id = new.id and estado in ('activa', 'ofrecida');
  elsif new.estado = 'reservada' and (old.inicio <> new.inicio or old.profesional_id <> new.profesional_id) then
    update envios set estado = 'cancelado', secreto = null
    where cita_id = new.id and estado = 'pendiente' and tipo in ('confirmacion_cita', 'recordatorio_cita', 'cambio_cita');
    if new.inicio > now() and not v_desde_chat then
      perform _encolar(new.clinica_id, 'cambio_cita', 'cambio:' || new.id || ':' || extract(epoch from new.inicio)::bigint
                       || ':' || new.profesional_id, new.paciente_id, new.id, _vars_cita(new.id));
    end if;
    if old.inicio > now() then
      perform _ofrecer_hueco(new.clinica_id, old.profesional_id, old.inicio);
    end if;
  end if;
  return null;
end;
$$;

-- Reserva común (fase 1), con una diferencia: el límite de citas futuras por paciente no cuenta las sesiones de
-- un programa (un programa de 5 sesiones reservadas juntas es normal).
create or replace function _reservar(p_clinica uuid, p_paciente bigint, p_servicio bigint, p_profesional bigint, p_inicio timestamptz,
                          p_modalidad text, p_origen text, p_clave text default null, p_forzar boolean default false,
                          p_motivo_excepcion text default null, p_notas text default null, p_motivo text default null)
returns jsonb language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare
  c        clinicas;
  s        servicios;
  pa       pacientes;
  v_mod    text;
  v_fin    timestamptz;
  v_prof   bigint;
  v_id     bigint;
  v_avisos text[] := '{}';
  v_restr  text;
begin
  select * into c from clinicas where id = p_clinica;
  if p_clave is not null then
    select id into v_id from citas where clinica_id = p_clinica and clave_idempotencia = p_clave;
    if v_id is not null then
      return jsonb_build_object('ok', true, 'repetida', true, 'cita', _cita_json(v_id));
    end if;
  end if;

  select * into s from servicios where id = p_servicio and clinica_id = p_clinica;
  if s.id is null or not s.activo then return jsonb_build_object('ok', false, 'motivo', 'servicio_no_existe'); end if;
  select * into pa from pacientes where id = p_paciente and clinica_id = p_clinica;
  if pa.id is null then return jsonb_build_object('ok', false, 'motivo', 'paciente_no_existe'); end if;

  v_mod := coalesce(p_modalidad, pa.modalidad_preferida, case when s.presencial then 'presencial' else 'online' end);
  if v_mod not in ('presencial', 'online') or (v_mod = 'presencial' and not s.presencial) or (v_mod = 'online' and not s.online) then
    return jsonb_build_object('ok', false, 'motivo', 'modalidad_no_disponible');
  end if;
  if p_inicio is null then return jsonb_build_object('ok', false, 'motivo', 'falta_hora'); end if;
  v_fin := p_inicio + make_interval(mins => s.duracion_min);

  -- La antelación mínima es para los canales (WhatsApp, teléfono, portal); el equipo puede dar cita para dentro de
  -- un rato. En el pasado solo como excepción (registrar a posteriori, como mucho 30 días atrás).
  if p_inicio < now() + make_interval(mins => case when p_origen = 'app' then 0 else c.antelacion_minima_min end) then
    if not p_forzar or p_inicio < now() - interval '30 days' then
      return jsonb_build_object('ok', false, 'motivo', 'hora_demasiado_pronto',
                                'antelacion_minima_min', c.antelacion_minima_min);
    end if;
    v_avisos := array_append(v_avisos, case when p_origen = 'app' then 'la hora ya ha pasado' else 'menos antelación de la habitual' end);
  end if;
  if p_inicio > now() + make_interval(days => c.dias_reserva_max) and not p_forzar then
    return jsonb_build_object('ok', false, 'motivo', 'demasiado_lejos', 'dias_reserva_max', c.dias_reserva_max);
  end if;
  -- Las sesiones de un programa no cuentan para el límite: las ha autorizado el profesional.
  if not p_forzar and coalesce(current_setting('nutricion.reservando_sesion', true), '') = ''
     and (select count(*) from citas x where x.paciente_id = p_paciente and x.estado = 'reservada' and x.inicio > now()
            and not exists (select 1 from sesiones ss where ss.cita_id = x.id)) >= c.max_citas_futuras then
    return jsonb_build_object('ok', false, 'motivo', 'demasiadas_citas', 'maximo', c.max_citas_futuras);
  end if;
  if exists (select 1 from citas where paciente_id = p_paciente and estado in ('reservada', 'realizada')
             and tstzrange(inicio, fin) && tstzrange(p_inicio, v_fin)) then
    return jsonb_build_object('ok', false, 'motivo', 'paciente_ya_tiene_cita_a_esa_hora');
  end if;

  if p_profesional is not null then
    if not exists (select 1 from profesionales where id = p_profesional and clinica_id = p_clinica and activo) then
      return jsonb_build_object('ok', false, 'motivo', 'profesional_no_existe');
    end if;
    if not exists (select 1 from profesional_servicios where profesional_id = p_profesional and servicio_id = p_servicio) then
      if not p_forzar then return jsonb_build_object('ok', false, 'motivo', 'profesional_no_hace_servicio'); end if;
      v_avisos := array_append(v_avisos, 'el profesional no tiene asignado este servicio');
    end if;
    if not _libre(p_profesional, p_inicio, v_fin, v_mod) then
      if not p_forzar then return jsonb_build_object('ok', false, 'motivo', 'hueco_no_disponible'); end if;
      if exists (select 1 from citas where profesional_id = p_profesional and estado in ('reservada', 'realizada')
                 and tstzrange(inicio, fin) && tstzrange(p_inicio, v_fin)) then
        return jsonb_build_object('ok', false, 'motivo', 'hueco_no_disponible');
      end if;
      v_avisos := array_append(v_avisos, 'fuera del horario o en una ausencia');
    end if;
    v_prof := p_profesional;
  else
    select pr.id into v_prof from profesionales pr
    join profesional_servicios ps on ps.profesional_id = pr.id and ps.servicio_id = p_servicio
    where pr.clinica_id = p_clinica and pr.activo and _libre(pr.id, p_inicio, v_fin, v_mod)
    order by (pr.id = pa.profesional_id) desc nulls last,
             (select count(*) from citas x where x.profesional_id = pr.id and x.estado = 'reservada'
                and (x.inicio at time zone c.zona_horaria)::date = (p_inicio at time zone c.zona_horaria)::date),
             pr.orden, pr.id
    limit 1;
    if v_prof is null then return jsonb_build_object('ok', false, 'motivo', 'hueco_no_disponible'); end if;
  end if;

  if array_length(v_avisos, 1) > 0 and nullif(trim(coalesce(p_motivo_excepcion, '')), '') is null then
    return jsonb_build_object('ok', false, 'motivo', 'falta_motivo_excepcion', 'avisos', to_jsonb(v_avisos));
  end if;

  begin
    insert into citas (clinica_id, paciente_id, profesional_id, servicio_id, inicio, fin, modalidad, origen,
                       precio_centimos, motivo, notas, excepcion, clave_idempotencia, creada_por)
    values (p_clinica, p_paciente, v_prof, p_servicio, p_inicio, v_fin, v_mod, p_origen, s.precio_centimos,
            left(nullif(trim(coalesce(p_motivo, '')), ''), 300), left(nullif(trim(coalesce(p_notas, '')), ''), 2000),
            case when array_length(v_avisos, 1) > 0
                 then array_to_string(v_avisos, '; ') || ' — ' || left(trim(p_motivo_excepcion), 300) end,
            p_clave, auth.uid())
    returning id into v_id;
  exception
    when exclusion_violation then
      get stacked diagnostics v_restr = constraint_name;
      return jsonb_build_object('ok', false, 'motivo',
        case when v_restr = 'citas_sin_solape_paciente' then 'paciente_ya_tiene_cita_a_esa_hora' else 'hueco_no_disponible' end);
    when unique_violation then
      -- El mismo reintento llegó dos veces a la vez: devolvemos la cita que se quedó.
      select id into v_id from citas where clinica_id = p_clinica and clave_idempotencia = p_clave;
      if v_id is null then raise; end if;
      return jsonb_build_object('ok', true, 'repetida', true, 'cita', _cita_json(v_id));
  end;

  update pacientes set profesional_id = v_prof where id = p_paciente and profesional_id is null;
  perform _auditar(p_clinica, 'reservar_cita', 'cita', v_id::text, p_paciente,
                   jsonb_build_object('origen', p_origen, 'excepcion', array_length(v_avisos, 1) > 0));
  return jsonb_build_object('ok', true, 'cita', _cita_json(v_id), 'avisos', to_jsonb(v_avisos));
end;
$$;

-- ¿La nueva hora de una cita de sesión se sale de su plazo? Devuelve la sesión si se sale.
create function _cita_fuera_de_plazo(p_cita bigint, p_inicio timestamptz) returns sesiones
language sql stable security definer set search_path = nutricion, extensions, pg_temp as $$
  select s.* from sesiones s
  where s.cita_id = p_cita and s.estado = 'reservada'
    and (p_inicio at time zone _tz(s.clinica_id))::date not between s.ventana_desde and s.ventana_hasta
$$;

-- =====================================================================
-- API de la aplicación: valoraciones, notas y mediciones (solo equipo sanitario)
-- =====================================================================

create function lista_plantillas_valoracion(p_clinica uuid) returns jsonb
language plpgsql stable security definer set search_path = nutricion, extensions, pg_temp as $$
begin
  perform _miembro(p_clinica, array['propietario', 'nutricionista']);
  return jsonb_build_object('ok', true, 'tipos_medicion', _tipos_medicion(), 'plantillas',
    (select coalesce(jsonb_agg(jsonb_build_object('id', id, 'nombre', nombre, 'tipo', tipo, 'secciones', secciones,
             'mediciones', to_jsonb(mediciones), 'activa', activa) order by orden, id), '[]'::jsonb)
     from plantillas_valoracion where clinica_id = p_clinica));
end;
$$;

-- d: {id?, nombre, tipo, secciones: [{clave?, titulo, ayuda?}], mediciones: [tipo], activa?}
create function guardar_plantilla_valoracion(p_clinica uuid, d jsonb) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare v_id bigint := (d->>'id')::bigint; v_secc jsonb := '[]'::jsonb; e jsonb; v_clave text; n int := 0; v_med text[];
begin
  perform _miembro(p_clinica, array['propietario', 'nutricionista']);
  if jsonb_typeof(d->'secciones') is distinct from 'array' or jsonb_array_length(d->'secciones') = 0 then
    return jsonb_build_object('ok', false, 'motivo', 'faltan_secciones');
  end if;
  for e in select * from jsonb_array_elements(d->'secciones') loop
    n := n + 1;
    continue when nullif(trim(coalesce(e->>'titulo', '')), '') is null;
    v_clave := coalesce(nullif(regexp_replace(lower(coalesce(e->>'clave', '')), '[^a-z0-9_]', '', 'g'), ''), 's' || n);
    if v_secc @> jsonb_build_array(jsonb_build_object('clave', v_clave)) then v_clave := v_clave || '_' || n; end if;
    v_secc := v_secc || jsonb_strip_nulls(jsonb_build_object('clave', v_clave, 'titulo', left(trim(e->>'titulo'), 120),
                                                              'ayuda', left(nullif(trim(e->>'ayuda'), ''), 300)));
  end loop;
  if jsonb_array_length(v_secc) = 0 then return jsonb_build_object('ok', false, 'motivo', 'faltan_secciones'); end if;
  select coalesce(array_agg(x), '{}') into v_med from jsonb_array_elements_text(coalesce(d->'mediciones', '[]')) x
  where _tipos_medicion() ? x and x not in ('imc', 'otro');
  begin
    if v_id is null then
      insert into plantillas_valoracion (clinica_id, nombre, tipo, secciones, mediciones, activa, orden)
      values (p_clinica, trim(d->>'nombre'), coalesce(d->>'tipo', 'revision'), v_secc, v_med,
              coalesce((d->>'activa')::boolean, true),
              (select coalesce(max(orden), 0) + 1 from plantillas_valoracion where clinica_id = p_clinica))
      returning id into v_id;
    else
      update plantillas_valoracion set nombre = coalesce(nullif(trim(d->>'nombre'), ''), nombre),
             tipo = coalesce(d->>'tipo', tipo), secciones = v_secc, mediciones = v_med,
             activa = coalesce((d->>'activa')::boolean, activa)
      where id = v_id and clinica_id = p_clinica;
      if not found then return jsonb_build_object('ok', false, 'motivo', 'no_existe'); end if;
    end if;
  exception
    when unique_violation then return jsonb_build_object('ok', false, 'motivo', 'nombre_repetido');
    when check_violation or not_null_violation then return jsonb_build_object('ok', false, 'motivo', 'valor_no_valido');
  end;
  perform _auditar(p_clinica, 'guardar_plantilla_valoracion', 'plantilla_valoracion', v_id::text);
  return jsonb_build_object('ok', true, 'id', v_id);
end;
$$;

create function _valoracion_json(p_id bigint) returns jsonb
language sql stable security definer set search_path = nutricion, extensions, pg_temp as $$
  select jsonb_build_object('id', v.id, 'paciente_id', v.paciente_id,
    'paciente', trim(pa.nombre || ' ' || coalesce(pa.apellidos, '')), 'profesional_id', v.profesional_id,
    'profesional', pr.nombre, 'cita_id', v.cita_id, 'cita_texto', fecha_es(ci.inicio, cl.zona_horaria),
    'plantilla_id', v.plantilla_id, 'tipo', v.tipo, 'titulo', v.titulo, 'fecha', v.fecha, 'secciones', v.secciones,
    'contenido', v.contenido, 'estado', v.estado, 'creada', _local(v.creada_en, cl.zona_horaria),
    'actualizada', _local(v.actualizada_en, cl.zona_horaria), 'cerrada', _local(v.cerrada_en, cl.zona_horaria),
    'cerrada_por', (select nombre from miembros where clinica_id = v.clinica_id and user_id = v.cerrada_por),
    'mediciones', (select coalesce(jsonb_agg(_medicion_json(m) order by m.id), '[]'::jsonb)
                   from mediciones m where m.valoracion_id = v.id and m.anulada_en is null),
    'notas', (select coalesce(jsonb_agg(jsonb_build_object('id', n.id, 'texto', n.texto, 'autor', n.autor_nombre,
                 'creada', _local(n.creada_en, cl.zona_horaria)) order by n.id), '[]'::jsonb)
              from notas_clinicas n where n.valoracion_id = v.id))
  from valoraciones v join clinicas cl on cl.id = v.clinica_id join pacientes pa on pa.id = v.paciente_id
  left join profesionales pr on pr.id = v.profesional_id left join citas ci on ci.id = v.cita_id
  where v.id = p_id
$$;

-- Abre la valoración de una consulta (la crea si no existe) o una nueva sin cita.
-- d: {paciente_id, cita_id?, plantilla_id?}
create function abrir_valoracion(p_clinica uuid, d jsonb) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare
  m miembros := _miembro(p_clinica, array['propietario', 'nutricionista']);
  v_pac bigint := (d->>'paciente_id')::bigint; v_cita bigint := (d->>'cita_id')::bigint; ci citas; pl plantillas_valoracion;
  v_id bigint; v_tipo text;
begin
  if v_cita is not null then
    select * into ci from citas where id = v_cita and clinica_id = p_clinica;
    if ci.id is null then return jsonb_build_object('ok', false, 'motivo', 'cita_no_existe'); end if;
    v_pac := ci.paciente_id;
    select id into v_id from valoraciones where cita_id = v_cita;
    if v_id is not null then return jsonb_build_object('ok', true, 'id', v_id, 'existente', true); end if;
    select case s.tipo when 'primera_visita' then 'primera_visita' when 'otro' then 'otro' else 'revision' end
      into v_tipo from servicios s where s.id = ci.servicio_id;
  end if;
  if not exists (select 1 from pacientes where id = v_pac and clinica_id = p_clinica) then
    return jsonb_build_object('ok', false, 'motivo', 'paciente_no_existe');
  end if;
  if d->>'plantilla_id' is not null then
    select * into pl from plantillas_valoracion where id = (d->>'plantilla_id')::bigint and clinica_id = p_clinica;
  else
    select * into pl from plantillas_valoracion where clinica_id = p_clinica and activa
    order by (tipo = coalesce(v_tipo, case when exists (select 1 from valoraciones where paciente_id = v_pac)
                                           then 'revision' else 'primera_visita' end)) desc, orden, id limit 1;
  end if;
  if pl.id is null then return jsonb_build_object('ok', false, 'motivo', 'plantilla_no_existe'); end if;
  begin
    insert into valoraciones (clinica_id, paciente_id, profesional_id, cita_id, plantilla_id, tipo, titulo, fecha, secciones,
                              creada_por)
    values (p_clinica, v_pac, coalesce(ci.profesional_id, m.profesional_id), v_cita, pl.id, pl.tipo, pl.nombre,
            coalesce((ci.inicio at time zone _tz(p_clinica))::date, _hoy(_tz(p_clinica))), pl.secciones, auth.uid())
    returning id into v_id;
  exception when unique_violation then
    select id into v_id from valoraciones where cita_id = v_cita;   -- dos clics a la vez: la misma valoración
    return jsonb_build_object('ok', true, 'id', v_id, 'existente', true);
  end;
  perform _auditar(p_clinica, 'crear_valoracion', 'valoracion', v_id::text, v_pac);
  return jsonb_build_object('ok', true, 'id', v_id, 'existente', false);
end;
$$;

create function ver_valoracion(p_clinica uuid, p_id bigint) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare v valoraciones;
begin
  perform _miembro(p_clinica, array['propietario', 'nutricionista']);
  select * into v from valoraciones where id = p_id and clinica_id = p_clinica;
  if v.id is null then return jsonb_build_object('ok', false, 'motivo', 'valoracion_no_existe'); end if;
  perform _auditar(p_clinica, 'ver_valoracion', 'valoracion', v.id::text, v.paciente_id);
  return jsonb_build_object('ok', true, 'valoracion', _valoracion_json(v.id), 'tipos_medicion', _tipos_medicion(),
    'mediciones_sugeridas', (select to_jsonb(mediciones) from plantillas_valoracion where id = v.plantilla_id),
    -- último valor anterior de cada tipo, con su origen, para tenerlo a la vista (sin juzgarlo)
    'anteriores_mediciones', (select coalesce(jsonb_object_agg(x.tipo, _medicion_json(x)), '{}'::jsonb) from (
        select distinct on (m.tipo) m.* from mediciones m
        where m.paciente_id = v.paciente_id and m.anulada_en is null and m.valoracion_id is distinct from v.id
          and m.fecha <= v.fecha
        order by m.tipo, m.fecha desc, m.id desc) x),
    'anteriores', (select coalesce(jsonb_agg(jsonb_build_object('id', a.id, 'fecha', a.fecha, 'titulo', a.titulo,
                     'estado', a.estado, 'contenido', a.contenido, 'secciones', a.secciones) order by a.fecha desc, a.id desc), '[]'::jsonb)
                   from (select * from valoraciones where paciente_id = v.paciente_id and id <> v.id and estado = 'cerrada'
                           and fecha <= v.fecha order by fecha desc, id desc limit 5) a));
end;
$$;

-- Guarda el borrador. d: {contenido: {clave: texto}, fecha?, mediciones?: [{tipo, valor, nombre?, unidad?, metodo?}]}
-- Las mediciones de la valoración se sustituyen enteras (es un borrador).
create function guardar_valoracion(p_clinica uuid, p_id bigint, d jsonb) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare v valoraciones; v_cont jsonb := '{}'::jsonb; sec jsonb; e jsonb; v_mal text; v_errores jsonb := '{}'::jsonb; i int := 0;
        v_fecha date;
begin
  perform _miembro(p_clinica, array['propietario', 'nutricionista']);
  select * into v from valoraciones where id = p_id and clinica_id = p_clinica for update;
  if v.id is null then return jsonb_build_object('ok', false, 'motivo', 'valoracion_no_existe'); end if;
  if v.estado = 'cerrada' then return jsonb_build_object('ok', false, 'motivo', 'valoracion_cerrada'); end if;
  v_fecha := coalesce(nullif(d->>'fecha', '')::date, v.fecha);
  if v_fecha > _hoy(_tz(p_clinica)) then return jsonb_build_object('ok', false, 'motivo', 'fecha_futura'); end if;
  for sec in select * from jsonb_array_elements(v.secciones) loop
    if d->'contenido' ? (sec->>'clave') and nullif(trim(d->'contenido'->>(sec->>'clave')), '') is not null then
      v_cont := v_cont || jsonb_build_object(sec->>'clave', left(d->'contenido'->>(sec->>'clave'), 10000));
    end if;
  end loop;
  if d ? 'mediciones' then
    for e in select * from jsonb_array_elements(coalesce(d->'mediciones', '[]')) loop
      continue when nullif(trim(coalesce(e->>'valor', '')), '') is null;
      v_mal := _medicion_no_valida(e);
      if v_mal is not null then v_errores := v_errores || jsonb_build_object(i::text, v_mal); end if;
      i := i + 1;
    end loop;
    if v_errores <> '{}'::jsonb then
      return jsonb_build_object('ok', false, 'motivo', 'medicion_no_valida', 'errores', v_errores);
    end if;
    delete from mediciones where valoracion_id = v.id;
    for e in select * from jsonb_array_elements(coalesce(d->'mediciones', '[]')) loop
      continue when nullif(trim(coalesce(e->>'valor', '')), '') is null;
      perform _insertar_medicion(p_clinica, v.paciente_id, e, 'consulta', v_fecha, v.id);
    end loop;
  end if;
  update valoraciones set contenido = v_cont, fecha = v_fecha, actualizada_en = now() where id = v.id;
  update mediciones set fecha = v_fecha where valoracion_id = v.id and fecha <> v_fecha;
  perform _auditar(p_clinica, 'guardar_valoracion', 'valoracion', v.id::text, v.paciente_id,
                   jsonb_build_object('secciones', (select coalesce(jsonb_agg(k), '[]'::jsonb) from jsonb_object_keys(v_cont) k)));
  return jsonb_build_object('ok', true, 'valoracion', _valoracion_json(v.id));
end;
$$;

create function cerrar_valoracion(p_clinica uuid, p_id bigint) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare v valoraciones;
begin
  perform _miembro(p_clinica, array['propietario', 'nutricionista']);
  select * into v from valoraciones where id = p_id and clinica_id = p_clinica for update;
  if v.id is null then return jsonb_build_object('ok', false, 'motivo', 'valoracion_no_existe'); end if;
  if v.estado = 'cerrada' then return jsonb_build_object('ok', true, 'repetida', true, 'valoracion', _valoracion_json(v.id)); end if;
  if v.contenido = '{}'::jsonb and not exists (select 1 from mediciones where valoracion_id = v.id) then
    return jsonb_build_object('ok', false, 'motivo', 'valoracion_vacia');
  end if;
  perform _calcular_imc(p_clinica, v.paciente_id, v.fecha, v.id);
  update valoraciones set estado = 'cerrada', cerrada_en = now(), cerrada_por = auth.uid(), actualizada_en = now()
  where id = v.id;
  perform _auditar(p_clinica, 'cerrar_valoracion', 'valoracion', v.id::text, v.paciente_id);
  return jsonb_build_object('ok', true, 'valoracion', _valoracion_json(v.id));
end;
$$;

create function borrar_valoracion(p_clinica uuid, p_id bigint) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare v valoraciones;
begin
  perform _miembro(p_clinica, array['propietario', 'nutricionista']);
  select * into v from valoraciones where id = p_id and clinica_id = p_clinica for update;
  if v.id is null then return jsonb_build_object('ok', false, 'motivo', 'valoracion_no_existe'); end if;
  if v.estado = 'cerrada' then return jsonb_build_object('ok', false, 'motivo', 'valoracion_cerrada'); end if;
  delete from valoraciones where id = v.id;
  perform _auditar(p_clinica, 'borrar_valoracion', 'valoracion', v.id::text, v.paciente_id);
  return jsonb_build_object('ok', true);
end;
$$;

-- Nota cronológica (también para corregir o completar una valoración ya cerrada). No se editan ni se borran.
-- d: {paciente_id, texto, valoracion_id?}
create function anadir_nota(p_clinica uuid, d jsonb) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare m miembros := _miembro(p_clinica, array['propietario', 'nutricionista']); v_pac bigint := (d->>'paciente_id')::bigint;
        v_val bigint := (d->>'valoracion_id')::bigint; v_id bigint;
begin
  if v_val is not null then
    select paciente_id into v_pac from valoraciones where id = v_val and clinica_id = p_clinica;
    if v_pac is null then return jsonb_build_object('ok', false, 'motivo', 'valoracion_no_existe'); end if;
  elsif not exists (select 1 from pacientes where id = v_pac and clinica_id = p_clinica) then
    return jsonb_build_object('ok', false, 'motivo', 'paciente_no_existe');
  end if;
  if nullif(trim(coalesce(d->>'texto', '')), '') is null then return jsonb_build_object('ok', false, 'motivo', 'falta_texto'); end if;
  insert into notas_clinicas (clinica_id, paciente_id, valoracion_id, texto, autor, autor_nombre)
  values (p_clinica, v_pac, v_val, left(trim(d->>'texto'), 5000), auth.uid(), m.nombre)
  returning id into v_id;
  perform _auditar(p_clinica, 'anadir_nota', 'nota', v_id::text, v_pac);
  return jsonb_build_object('ok', true, 'id', v_id);
end;
$$;

-- Medición suelta (fuera de una valoración): en consulta o aportada por el paciente.
-- d: {paciente_id, tipo, valor, fecha?, origen: consulta|paciente, nombre?, unidad?, metodo?, nota?}
create function registrar_medicion(p_clinica uuid, d jsonb) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare v_pac bigint := (d->>'paciente_id')::bigint; v_mal text; v_id bigint; v_fecha date; v_origen text := coalesce(d->>'origen', 'consulta');
begin
  perform _miembro(p_clinica, array['propietario', 'nutricionista']);
  if not exists (select 1 from pacientes where id = v_pac and clinica_id = p_clinica) then
    return jsonb_build_object('ok', false, 'motivo', 'paciente_no_existe');
  end if;
  if v_origen not in ('consulta', 'paciente') then return jsonb_build_object('ok', false, 'motivo', 'valor_no_valido'); end if;
  v_mal := _medicion_no_valida(d);
  if v_mal is not null then return jsonb_build_object('ok', false, 'motivo', v_mal); end if;
  v_fecha := coalesce(nullif(d->>'fecha', '')::date, _hoy(_tz(p_clinica)));
  if v_fecha > _hoy(_tz(p_clinica)) then return jsonb_build_object('ok', false, 'motivo', 'fecha_futura'); end if;
  v_id := _insertar_medicion(p_clinica, v_pac, d, v_origen, v_fecha);
  if v_origen = 'consulta' and d->>'tipo' in ('peso', 'altura') then perform _calcular_imc(p_clinica, v_pac, v_fecha); end if;
  perform _auditar(p_clinica, 'registrar_medicion', 'medicion', v_id::text, v_pac,
                   jsonb_build_object('tipo', d->>'tipo', 'origen', v_origen));
  return jsonb_build_object('ok', true, 'id', v_id);
end;
$$;

create function anular_medicion(p_clinica uuid, p_id bigint, p_motivo text) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare me mediciones;
begin
  perform _miembro(p_clinica, array['propietario', 'nutricionista']);
  select * into me from mediciones where id = p_id and clinica_id = p_clinica for update;
  if me.id is null then return jsonb_build_object('ok', false, 'motivo', 'medicion_no_existe'); end if;
  if nullif(trim(coalesce(p_motivo, '')), '') is null then return jsonb_build_object('ok', false, 'motivo', 'falta_motivo'); end if;
  if me.anulada_en is not null then return jsonb_build_object('ok', true, 'repetida', true); end if;
  update mediciones set anulada_en = now(), motivo_anulacion = left(trim(p_motivo), 300) where id = me.id;
  -- El IMC que salía de esa medición deja de valer.
  if me.tipo in ('peso', 'altura') then
    update mediciones set anulada_en = now(), motivo_anulacion = 'se anuló la medición de la que salía'
    where paciente_id = me.paciente_id and tipo = 'imc' and origen = 'calculado' and anulada_en is null
      and (fecha = me.fecha or me.tipo = 'altura');
  end if;
  perform _auditar(p_clinica, 'anular_medicion', 'medicion', me.id::text, me.paciente_id);
  return jsonb_build_object('ok', true);
end;
$$;

-- Historial clínico del paciente: valoraciones, notas y mediciones por tipo.
create function historial_paciente(p_clinica uuid, p_paciente bigint) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare v_tz text := _tz(p_clinica);
begin
  perform _miembro(p_clinica, array['propietario', 'nutricionista']);
  if not exists (select 1 from pacientes where id = p_paciente and clinica_id = p_clinica) then
    return jsonb_build_object('ok', false, 'motivo', 'paciente_no_existe');
  end if;
  perform _auditar(p_clinica, 'ver_historial', 'paciente', p_paciente::text, p_paciente);
  return jsonb_build_object('ok', true,
    'valoraciones', (select coalesce(jsonb_agg(jsonb_build_object('id', v.id, 'fecha', v.fecha, 'titulo', v.titulo,
        'tipo', v.tipo, 'estado', v.estado, 'profesional', pr.nombre, 'cita_id', v.cita_id,
        'resumen', left((select string_agg(v.contenido->>(s->>'clave'), ' · ') from jsonb_array_elements(v.secciones) s
                         where v.contenido ? (s->>'clave')), 240)) order by v.fecha desc, v.id desc), '[]'::jsonb)
      from valoraciones v left join profesionales pr on pr.id = v.profesional_id where v.paciente_id = p_paciente),
    'notas', (select coalesce(jsonb_agg(jsonb_build_object('id', n.id, 'texto', n.texto, 'autor', n.autor_nombre,
        'valoracion_id', n.valoracion_id, 'creada', _local(n.creada_en, v_tz)) order by n.creada_en desc), '[]'::jsonb)
      from notas_clinicas n where n.paciente_id = p_paciente),
    'mediciones', (select coalesce(jsonb_agg(jsonb_build_object('tipo', x.tipo, 'nombre', x.nombre, 'unidad', x.unidad,
        'puntos', x.puntos) order by x.orden), '[]'::jsonb)
      from (select m.tipo, m.nombre, max(m.unidad) unidad, min(m.id) orden,
                   jsonb_agg(_medicion_json(m) order by m.fecha, m.id) puntos
            from mediciones m where m.paciente_id = p_paciente and m.anulada_en is null
            group by m.tipo, m.nombre) x));
end;
$$;

-- =====================================================================
-- API de la aplicación: seguimientos y programas
-- =====================================================================

-- Tras una consulta, el profesional dice cuándo debe volver el paciente.
-- d: {paciente_id, cita_id?, en_dias? | fecha?, margen_dias?, sesiones? (1), frecuencia_dias?, servicio_id?,
--     profesional_id?, modalidad?, avisar?, indicacion?}
-- "Revisión dentro de dos semanas" = {en_dias: 14}; "un mes con siete días de margen" = {en_dias: 30, margen_dias: 7};
-- "tres revisiones quincenales" = {en_dias: 15, sesiones: 3, frecuencia_dias: 15}.
create function indicar_seguimiento(p_clinica uuid, d jsonb) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare
  m miembros := _miembro(p_clinica, array['propietario', 'nutricionista']);
  c clinicas; ci citas; pa pacientes; v_base date; v_obj date; v_margen int; v_n int; v_freq int; v_serv bigint;
  v_prof bigint; v_mod text; v_prog bigint; v_ses bigint; s servicios; v_hay boolean; v_indic text;
begin
  select * into c from clinicas where id = p_clinica;
  if d->>'cita_id' is not null then
    select * into ci from citas where id = (d->>'cita_id')::bigint and clinica_id = p_clinica;
    if ci.id is null then return jsonb_build_object('ok', false, 'motivo', 'cita_no_existe'); end if;
    -- Ya se indicó en esta consulta y sigue pendiente: no se duplica.
    select id into v_ses from sesiones where origen_cita_id = ci.id and estado in ('pendiente', 'propuesta', 'reservada')
    order by numero limit 1;
    if v_ses is not null then
      return jsonb_build_object('ok', false, 'motivo', 'ya_indicado', 'sesion', _sesion_json(v_ses, true));
    end if;
  end if;
  select * into pa from pacientes where id = coalesce(ci.paciente_id, (d->>'paciente_id')::bigint) and clinica_id = p_clinica;
  if pa.id is null then return jsonb_build_object('ok', false, 'motivo', 'paciente_no_existe'); end if;
  v_base := coalesce((ci.inicio at time zone c.zona_horaria)::date, _hoy(c.zona_horaria));
  v_obj := coalesce(nullif(d->>'fecha', '')::date, v_base + nullif(d->>'en_dias', '')::int);
  if v_obj is null then return jsonb_build_object('ok', false, 'motivo', 'falta_plazo'); end if;
  if v_obj < _hoy(c.zona_horaria) then return jsonb_build_object('ok', false, 'motivo', 'fecha_pasada'); end if;
  v_margen := coalesce(nullif(d->>'margen_dias', '')::int, c.seguimiento_margen_dias);
  v_n := coalesce(nullif(d->>'sesiones', '')::int, 1);
  v_freq := coalesce(nullif(d->>'frecuencia_dias', '')::int, nullif(d->>'en_dias', '')::int, 14);
  if v_n not between 1 and 52 or v_margen not between 0 and 90 or v_freq not between 1 and 365 then
    return jsonb_build_object('ok', false, 'motivo', 'valor_no_valido');
  end if;
  v_prof := coalesce(nullif(d->>'profesional_id', '')::bigint, ci.profesional_id, pa.profesional_id, m.profesional_id);
  -- Servicio: el indicado; si no, una revisión que haga ese profesional.
  v_serv := nullif(d->>'servicio_id', '')::bigint;
  if v_serv is null then
    select se.id into v_serv from servicios se join profesional_servicios ps on ps.servicio_id = se.id and ps.profesional_id = v_prof
    where se.clinica_id = p_clinica and se.activo order by (se.tipo = 'revision') desc, (se.tipo = 'sesion_programa') desc, se.orden, se.id
    limit 1;
  end if;
  select * into s from servicios where id = v_serv and clinica_id = p_clinica and activo;
  if s.id is null then return jsonb_build_object('ok', false, 'motivo', 'servicio_no_existe'); end if;
  if v_prof is null or not exists (select 1 from profesional_servicios where profesional_id = v_prof and servicio_id = s.id) then
    return jsonb_build_object('ok', false, 'motivo', 'profesional_no_hace_servicio');
  end if;
  v_mod := coalesce(nullif(d->>'modalidad', ''), ci.modalidad, pa.modalidad_preferida,
                    case when s.presencial then 'presencial' else 'online' end);
  if (v_mod = 'presencial' and not s.presencial) or (v_mod = 'online' and not s.online) then
    return jsonb_build_object('ok', false, 'motivo', 'modalidad_no_disponible');
  end if;
  v_indic := left(nullif(trim(coalesce(d->>'indicacion', '')), ''), 500);
  if v_n = 1 then
    insert into sesiones (clinica_id, paciente_id, profesional_id, servicio_id, modalidad, objetivo, ventana_desde,
                          ventana_hasta, avisar, indicacion, origen_cita_id, creada_por)
    select p_clinica, pa.id, v_prof, s.id, v_mod, v_obj, greatest(w.desde, _hoy(c.zona_horaria)), w.hasta,
           coalesce((d->>'avisar')::boolean, true), v_indic, ci.id, auth.uid()
    from _ventana(v_obj, v_margen) w
    returning id into v_ses;
  else
    insert into programas (clinica_id, paciente_id, profesional_id, servicio_id, nombre, forma, num_sesiones, frecuencia_dias,
                           margen_dias, fecha_inicio, modalidad, avisar, origen_cita_id, creado_por)
    values (p_clinica, pa.id, v_prof, s.id, 'Seguimiento: ' || v_n || ' ' || lower(s.nombre) || ' cada ' || v_freq || ' días',
            'una_a_una', v_n, v_freq, v_margen, v_obj, v_mod, coalesce((d->>'avisar')::boolean, true), ci.id, auth.uid())
    returning id into v_prog;
    perform _crear_sesiones(v_prog, v_indic);
    update sesiones set ventana_desde = greatest(ventana_desde, _hoy(c.zona_horaria)) where programa_id = v_prog;
    select id into v_ses from sesiones where programa_id = v_prog and numero = 1;
  end if;
  update pacientes set estado = 'activo' where id = pa.id and estado = 'inactivo';
  v_hay := exists (select 1 from _huecos_sesion(v_ses, false, 1));
  if not v_hay then perform _alerta_sin_hueco(v_ses); end if;
  perform _auditar(p_clinica, 'indicar_seguimiento', case when v_prog is null then 'sesion' else 'programa' end,
                   coalesce(v_prog, v_ses)::text, pa.id, jsonb_build_object('sesiones', v_n, 'frecuencia_dias', v_freq,
                   'margen_dias', v_margen));
  return jsonb_build_object('ok', true, 'programa_id', v_prog, 'sesion', _sesion_json(v_ses, true), 'hay_huecos', v_hay);
end;
$$;

-- Programa de varias sesiones. d: {paciente_id, nombre?, forma, num_sesiones, frecuencia_dias, margen_dias?,
--   fecha_inicio, profesional_id, servicio_id, modalidad?, dia_semana?, hora?, condiciones?, bono_id?, avisar?}
create function crear_programa(p_clinica uuid, d jsonb) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare c clinicas; pa pacientes; s servicios; v_id bigint; v_mod text; v_forma text := d->>'forma'; v_margen int;
begin
  perform _miembro(p_clinica, array['propietario', 'nutricionista']);
  select * into c from clinicas where id = p_clinica;
  select * into pa from pacientes where id = (d->>'paciente_id')::bigint and clinica_id = p_clinica;
  if pa.id is null then return jsonb_build_object('ok', false, 'motivo', 'paciente_no_existe'); end if;
  select * into s from servicios where id = (d->>'servicio_id')::bigint and clinica_id = p_clinica and activo;
  if s.id is null then return jsonb_build_object('ok', false, 'motivo', 'servicio_no_existe'); end if;
  if not exists (select 1 from profesional_servicios ps join profesionales pr on pr.id = ps.profesional_id and pr.activo
                 where ps.profesional_id = (d->>'profesional_id')::bigint and ps.servicio_id = s.id and pr.clinica_id = p_clinica) then
    return jsonb_build_object('ok', false, 'motivo', 'profesional_no_hace_servicio');
  end if;
  if v_forma not in ('todas', 'una_a_una', 'recurrente', 'flexible') then
    return jsonb_build_object('ok', false, 'motivo', 'valor_no_valido');
  end if;
  v_margen := coalesce(nullif(d->>'margen_dias', '')::int, c.seguimiento_margen_dias);
  if v_forma = 'recurrente' then
    if d->>'dia_semana' is null or nullif(d->>'hora', '') is null then return jsonb_build_object('ok', false, 'motivo', 'falta_dia_hora'); end if;
    if v_margen < 3 then return jsonb_build_object('ok', false, 'motivo', 'margen_insuficiente'); end if;
  end if;
  if nullif(d->>'fecha_inicio', '') is null then return jsonb_build_object('ok', false, 'motivo', 'falta_fecha'); end if;
  if (d->>'fecha_inicio')::date < _hoy(c.zona_horaria) then return jsonb_build_object('ok', false, 'motivo', 'fecha_pasada'); end if;
  v_mod := coalesce(nullif(d->>'modalidad', ''), pa.modalidad_preferida, case when s.presencial then 'presencial' else 'online' end);
  if (v_mod = 'presencial' and not s.presencial) or (v_mod = 'online' and not s.online) then
    return jsonb_build_object('ok', false, 'motivo', 'modalidad_no_disponible');
  end if;
  if d->>'bono_id' is not null and not exists (select 1 from bonos where id = (d->>'bono_id')::bigint and paciente_id = pa.id
                                                 and estado = 'activo' and s.id = any (servicios)) then
    return jsonb_build_object('ok', false, 'motivo', 'bono_no_valido');
  end if;
  begin
    insert into programas (clinica_id, paciente_id, profesional_id, servicio_id, nombre, forma, num_sesiones, frecuencia_dias,
                           margen_dias, fecha_inicio, modalidad, dia_semana, hora, condiciones, bono_id, avisar, creado_por)
    values (p_clinica, pa.id, (d->>'profesional_id')::bigint, s.id,
            coalesce(nullif(trim(d->>'nombre'), ''), 'Programa de ' || (d->>'num_sesiones') || ' sesiones'),
            v_forma, (d->>'num_sesiones')::int, (d->>'frecuencia_dias')::int, v_margen, (d->>'fecha_inicio')::date, v_mod,
            nullif(d->>'dia_semana', '')::int, nullif(d->>'hora', '')::time, left(nullif(trim(d->>'condiciones'), ''), 2000),
            nullif(d->>'bono_id', '')::bigint, coalesce((d->>'avisar')::boolean, true), auth.uid())
    returning id into v_id;
  exception when check_violation or not_null_violation or invalid_text_representation or invalid_datetime_format
                 or datetime_field_overflow then
    return jsonb_build_object('ok', false, 'motivo', 'valor_no_valido');
  end;
  perform _crear_sesiones(v_id);
  update pacientes set estado = 'activo' where id = pa.id and estado = 'inactivo';
  perform _auditar(p_clinica, 'crear_programa', 'programa', v_id::text, pa.id,
                   jsonb_build_object('forma', v_forma, 'sesiones', (d->>'num_sesiones')::int));
  return jsonb_build_object('ok', true, 'programa', _programa_json(v_id, true));
end;
$$;

create function ver_programa(p_clinica uuid, p_id bigint) returns jsonb
language plpgsql stable security definer set search_path = nutricion, extensions, pg_temp as $$
declare m miembros := _miembro(p_clinica);
begin
  if not exists (select 1 from programas where id = p_id and clinica_id = p_clinica) then
    return jsonb_build_object('ok', false, 'motivo', 'programa_no_existe');
  end if;
  return jsonb_build_object('ok', true, 'programa', _programa_json(p_id, _puede_salud(m.rol)));
end;
$$;

-- Programas, seguimientos sueltos y bonos del paciente (todo el equipo; la indicación clínica solo la ve sanidad).
create function seguimiento_paciente(p_clinica uuid, p_paciente bigint) returns jsonb
language plpgsql stable security definer set search_path = nutricion, extensions, pg_temp as $$
declare m miembros := _miembro(p_clinica);
begin
  if not exists (select 1 from pacientes where id = p_paciente and clinica_id = p_clinica) then
    return jsonb_build_object('ok', false, 'motivo', 'paciente_no_existe');
  end if;
  return jsonb_build_object('ok', true,
    'programas', (select coalesce(jsonb_agg(_programa_json(p.id, _puede_salud(m.rol))
                    order by (p.estado in ('activo', 'pausado')) desc, p.creado_en desc), '[]'::jsonb)
                  from programas p where p.paciente_id = p_paciente),
    'sesiones', (select coalesce(jsonb_agg(_sesion_json(s.id, _puede_salud(m.rol)) order by s.objetivo desc), '[]'::jsonb)
                 from sesiones s where s.paciente_id = p_paciente and s.programa_id is null),
    'bonos', (select coalesce(jsonb_agg(_bono_json(b.id) order by (b.estado = 'activo') desc, b.fecha_compra desc), '[]'::jsonb)
              from bonos b where b.paciente_id = p_paciente));
end;
$$;

create function proponer_sesiones(p_clinica uuid, p_programa bigint, p_enviar boolean default false) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare p programas; r jsonb; v_fechas text;
begin
  perform _miembro(p_clinica);
  select * into p from programas where id = p_programa and clinica_id = p_clinica;
  if p.id is null then return jsonb_build_object('ok', false, 'motivo', 'programa_no_existe'); end if;
  if p.estado <> 'activo' then return jsonb_build_object('ok', false, 'motivo', 'programa_no_activo'); end if;
  r := _proponer(p.id);
  if p_enviar and jsonb_array_length(r->'propuestas') > 0 then
    v_fechas := _lista_fechas(p.id, 'propuesta');
    perform _encolar(p_clinica, 'propuesta_sesiones', 'propuesta_sesiones:' || p.id || ':' || md5(v_fechas), p.paciente_id, null,
                     jsonb_build_object('paciente', (select split_part(trim(nombre), ' ', 1) from pacientes where id = p.paciente_id),
                                        'programa', p.nombre, 'fechas', v_fechas,
                                        'clinica', (select nombre from clinicas where id = p_clinica)));
  end if;
  return r || jsonb_build_object('enviada', p_enviar and jsonb_array_length(r->'propuestas') > 0,
                                 'programa', _programa_json(p.id, false));
end;
$$;

create function confirmar_propuesta(p_clinica uuid, p_programa bigint) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
begin
  perform _miembro(p_clinica);
  if not exists (select 1 from programas where id = p_programa and clinica_id = p_clinica) then
    return jsonb_build_object('ok', false, 'motivo', 'programa_no_existe');
  end if;
  return _confirmar_propuesta(p_programa, 'app');
end;
$$;

create function huecos_sesion(p_clinica uuid, p_sesion bigint, p_desde date default null, p_profesional bigint default null,
                              p_max int default 30) returns jsonb
language plpgsql stable security definer set search_path = nutricion, extensions, pg_temp as $$
declare v_tz text := _tz(p_clinica);
begin
  perform _miembro(p_clinica);
  if not exists (select 1 from sesiones where id = p_sesion and clinica_id = p_clinica) then
    return jsonb_build_object('ok', false, 'motivo', 'sesion_no_existe');
  end if;
  return jsonb_build_object('ok', true, 'sesion', _sesion_json(p_sesion, false), 'huecos',
    (select coalesce(jsonb_agg(jsonb_build_object('inicio', _local(h.inicio, v_tz), 'fecha_texto', fecha_es(h.inicio, v_tz),
              'profesional_id', h.profesional_id, 'profesional', h.profesional) order by h.inicio), '[]'::jsonb)
     from _huecos_sesion(p_sesion, false, least(greatest(p_max, 1), 100), p_desde, p_profesional) h));
end;
$$;

-- d: {inicio, profesional_id?, forzar?, motivo_excepcion?}. Fuera del plazo autorizado solo el equipo sanitario.
create function reservar_sesion(p_clinica uuid, p_sesion bigint, d jsonb) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare m miembros := _miembro(p_clinica); v_forzar boolean := coalesce((d->>'forzar')::boolean, false);
begin
  if not exists (select 1 from sesiones where id = p_sesion and clinica_id = p_clinica) then
    return jsonb_build_object('ok', false, 'motivo', 'sesion_no_existe');
  end if;
  if v_forzar and not _puede_salud(m.rol) then
    return jsonb_build_object('ok', false, 'motivo', 'excepcion_solo_profesional');
  end if;
  return _reservar_sesion(p_sesion, _desde_local(d->>'inicio', _tz(p_clinica)), nullif(d->>'profesional_id', '')::bigint,
                          'app', nullif(d->>'clave', ''), v_forzar, d->>'motivo_excepcion');
end;
$$;

-- Cambia la frecuencia (y el margen) de las sesiones que faltan por programar. Las ya reservadas no se mueven: se
-- devuelven las que quedarían fuera del nuevo plazo para que el equipo hable con el paciente.
-- d: {frecuencia_dias, margen_dias?}
create function cambiar_frecuencia(p_clinica uuid, p_programa bigint, d jsonb) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare
  p programas; v_tz text := _tz(p_clinica); v_freq int := (d->>'frecuencia_dias')::int; v_margen int;
  v_ancla_dia date; v_ancla_num int; s record; v_obj date; v_recalc int := 0; v_descart int := 0;
  v_fuera jsonb := '[]'::jsonb; v_dia date;
begin
  perform _miembro(p_clinica, array['propietario', 'nutricionista']);
  select * into p from programas where id = p_programa and clinica_id = p_clinica for update;
  if p.id is null then return jsonb_build_object('ok', false, 'motivo', 'programa_no_existe'); end if;
  if p.estado not in ('activo', 'pausado') then return jsonb_build_object('ok', false, 'motivo', 'programa_no_activo'); end if;
  v_margen := coalesce(nullif(d->>'margen_dias', '')::int, p.margen_dias);
  if v_freq is null or v_freq not between 1 and 365 or v_margen not between 0 and 90 then
    return jsonb_build_object('ok', false, 'motivo', 'valor_no_valido');
  end if;
  -- Se cuenta desde la última sesión realizada (su fecha real), o desde el inicio del programa.
  select (ci.inicio at time zone v_tz)::date, x.numero into v_ancla_dia, v_ancla_num
  from sesiones x join citas ci on ci.id = x.cita_id
  where x.programa_id = p.id and x.estado = 'realizada' order by x.numero desc limit 1;
  for s in select x.*, ci.inicio as cita_inicio from sesiones x left join citas ci on ci.id = x.cita_id
           where x.programa_id = p.id and x.estado in ('pendiente', 'propuesta', 'suspendida', 'reservada')
             and (v_ancla_num is null or x.numero > v_ancla_num)
           order by x.numero for update of x loop
    v_obj := case when v_ancla_dia is null then p.fecha_inicio + (s.numero - 1) * v_freq
                  else v_ancla_dia + (s.numero - v_ancla_num) * v_freq end;
    if s.estado = 'reservada' then
      v_dia := (s.cita_inicio at time zone v_tz)::date;
      if v_dia not between v_obj - v_margen and v_obj + v_margen then
        v_fuera := v_fuera || (_sesion_json(s.id, false) || jsonb_build_object('nueva_ventana_texto',
                     'entre el ' || fecha_dia_es(v_obj - v_margen) || ' y el ' || fecha_dia_es(v_obj + v_margen)));
      end if;
      continue;
    end if;
    if s.estado = 'propuesta' then v_descart := v_descart + 1; end if;
    update sesiones set objetivo = v_obj, ventana_desde = greatest(v_obj - v_margen, _hoy(v_tz)),
           ventana_hasta = greatest(v_obj + v_margen, _hoy(v_tz)),
           estado = case when estado = 'propuesta' then 'pendiente' else estado end, propuesta_inicio = null,
           mensajes_enviados = 0, ultima_gestion_en = null, alerta_sin_hueco_en = null, alerta_vencida_en = null,
           actualizada_en = now()
    where id = s.id;
    v_recalc := v_recalc + 1;
  end loop;
  perform _auditar(p_clinica, 'cambiar_frecuencia', 'programa', p.id::text, p.paciente_id,
                   jsonb_build_object('antes', jsonb_build_object('frecuencia_dias', p.frecuencia_dias, 'margen_dias', p.margen_dias),
                                      'despues', jsonb_build_object('frecuencia_dias', v_freq, 'margen_dias', v_margen),
                                      'recalculadas', v_recalc));
  update programas set frecuencia_dias = v_freq, margen_dias = v_margen where id = p.id;
  return jsonb_build_object('ok', true, 'recalculadas', v_recalc, 'propuestas_descartadas', v_descart,
                            'reservadas_fuera', v_fuera, 'programa', _programa_json(p.id, true));
end;
$$;

-- Finalizar, cancelar, pausar o reanudar un programa. Las sesiones por programar se cancelan (o se suspenden) y
-- dejan de salir recordatorios. Las citas ya reservadas solo se cancelan si se pide expresamente.
create function cambiar_estado_programa(p_clinica uuid, p_programa bigint, p_estado text, p_motivo text default null,
                                        p_cancelar_citas boolean default false) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare p programas; s record; v_citas jsonb := '[]'::jsonb;
begin
  perform _miembro(p_clinica, array['propietario', 'nutricionista']);
  if p_estado not in ('activo', 'pausado', 'finalizado', 'cancelado') then
    return jsonb_build_object('ok', false, 'motivo', 'valor_no_valido');
  end if;
  select * into p from programas where id = p_programa and clinica_id = p_clinica for update;
  if p.id is null then return jsonb_build_object('ok', false, 'motivo', 'programa_no_existe'); end if;
  if p.estado = p_estado then return jsonb_build_object('ok', true, 'repetida', true, 'programa', _programa_json(p.id, true)); end if;
  if p.estado in ('finalizado', 'cancelado') and p_estado <> 'activo' then
    return jsonb_build_object('ok', false, 'motivo', 'programa_no_activo');
  end if;
  update programas set estado = p_estado, motivo_fin = case when p_estado in ('finalizado', 'cancelado')
                                                           then left(nullif(trim(p_motivo), ''), 300) end,
         finalizado_en = case when p_estado in ('finalizado', 'cancelado') then now() end
  where id = p.id;
  if p_estado in ('finalizado', 'cancelado', 'pausado') then
    for s in select id from sesiones where programa_id = p.id and estado in ('pendiente', 'propuesta', 'suspendida') loop
      perform _detener_avisos(s.id);
    end loop;
    update sesiones set estado = case when p_estado = 'pausado' then 'suspendida' else 'cancelada' end,
           propuesta_inicio = null, actualizada_en = now()
    where programa_id = p.id and estado in ('pendiente', 'propuesta', 'suspendida');
    -- Citas futuras ya reservadas: se avisan (y solo se cancelan si se ha pedido).
    -- (al cancelar la cita, su sesión queda cancelada porque el programa ya no está activo)
    for s in select x.cita_id from sesiones x join citas ci on ci.id = x.cita_id
             where x.programa_id = p.id and x.estado = 'reservada' and ci.inicio > now() order by ci.inicio loop
      if p_cancelar_citas and p_estado <> 'pausado' then
        perform _cancelar(p_clinica, s.cita_id, 'clinica', 'Programa ' || p_estado);
      end if;
      v_citas := v_citas || _cita_json(s.cita_id);
    end loop;
  else
    -- Reanudar: lo suspendido vuelve a estar por programar, con los avisos desde cero.
    update sesiones set estado = 'pendiente', mensajes_enviados = 0, ultima_gestion_en = null, alerta_sin_hueco_en = null,
           alerta_vencida_en = null, actualizada_en = now()
    where programa_id = p.id and estado = 'suspendida';
  end if;
  perform _auditar(p_clinica, 'estado_programa', 'programa', p.id::text, p.paciente_id,
                   jsonb_build_object('antes', p.estado, 'despues', p_estado, 'cancelar_citas', p_cancelar_citas));
  return jsonb_build_object('ok', true, 'citas_reservadas', v_citas, 'citas_canceladas', p_cancelar_citas and p_estado <> 'pausado',
                            'programa', _programa_json(p.id, true));
end;
$$;

create function anadir_sesion(p_clinica uuid, p_programa bigint) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare p programas; v_ult sesiones; v_base date; v_obj date; v_id bigint; v_tz text := _tz(p_clinica);
begin
  perform _miembro(p_clinica, array['propietario', 'nutricionista']);
  select * into p from programas where id = p_programa and clinica_id = p_clinica for update;
  if p.id is null then return jsonb_build_object('ok', false, 'motivo', 'programa_no_existe'); end if;
  if p.estado <> 'activo' then return jsonb_build_object('ok', false, 'motivo', 'programa_no_activo'); end if;
  if p.num_sesiones >= 52 then return jsonb_build_object('ok', false, 'motivo', 'valor_no_valido'); end if;
  select * into v_ult from sesiones where programa_id = p.id order by numero desc limit 1;
  v_base := coalesce((select (inicio at time zone v_tz)::date from citas where id = v_ult.cita_id), v_ult.objetivo, p.fecha_inicio);
  v_obj := greatest(v_base + p.frecuencia_dias, _hoy(v_tz));
  insert into sesiones (clinica_id, paciente_id, programa_id, numero, profesional_id, servicio_id, modalidad, objetivo,
                        ventana_desde, ventana_hasta, avisar, creada_por)
  select p.clinica_id, p.paciente_id, p.id, coalesce(v_ult.numero, 0) + 1, p.profesional_id, p.servicio_id, p.modalidad,
         v_obj, greatest(w.desde, _hoy(v_tz)), w.hasta, p.avisar, auth.uid()
  from _ventana(v_obj, p.margen_dias) w returning id into v_id;
  update programas set num_sesiones = num_sesiones + 1 where id = p.id;
  perform _auditar(p_clinica, 'anadir_sesion', 'programa', p.id::text, p.paciente_id);
  return jsonb_build_object('ok', true, 'sesion', _sesion_json(v_id, true));
end;
$$;

-- d: {avisar?, ventana_desde?, ventana_hasta?, estado? (pendiente|suspendida|cancelada), indicacion?}
-- Avisar sí/no lo puede tocar todo el equipo (p. ej. el paciente pide que no le escriban); el plazo y el estado son
-- decisiones del profesional.
create function editar_sesion(p_clinica uuid, p_sesion bigint, d jsonb) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare m miembros := _miembro(p_clinica); s sesiones; v_desde date; v_hasta date; v_cambia boolean; v_estado text;
begin
  select * into s from sesiones where id = p_sesion and clinica_id = p_clinica for update;
  if s.id is null then return jsonb_build_object('ok', false, 'motivo', 'sesion_no_existe'); end if;
  if (d ? 'ventana_desde' or d ? 'ventana_hasta' or d ? 'estado' or d ? 'indicacion') and not _puede_salud(m.rol) then
    raise exception 'sin_permiso' using errcode = '42501';
  end if;
  if d ? 'estado' then
    if d->>'estado' not in ('pendiente', 'suspendida', 'cancelada') or s.estado not in ('pendiente', 'propuesta', 'suspendida') then
      return jsonb_build_object('ok', false, 'motivo', 'sesion_no_modificable', 'estado', s.estado);
    end if;
  end if;
  v_desde := coalesce(nullif(d->>'ventana_desde', '')::date, s.ventana_desde);
  v_hasta := coalesce(nullif(d->>'ventana_hasta', '')::date, s.ventana_hasta);
  if v_hasta < v_desde then return jsonb_build_object('ok', false, 'motivo', 'valor_no_valido'); end if;
  if (d ? 'ventana_desde' or d ? 'ventana_hasta') and s.estado not in ('pendiente', 'propuesta', 'suspendida') then
    return jsonb_build_object('ok', false, 'motivo', 'sesion_no_modificable', 'estado', s.estado);
  end if;
  v_cambia := (v_desde, v_hasta) is distinct from (s.ventana_desde, s.ventana_hasta);
  v_estado := coalesce(d->>'estado', case when v_cambia and s.estado = 'propuesta' then 'pendiente' else s.estado end);
  update sesiones set avisar = coalesce((d->>'avisar')::boolean, avisar),
         ventana_desde = v_desde, ventana_hasta = v_hasta,
         objetivo = case when v_cambia then least(greatest(objetivo, v_desde), v_hasta) else objetivo end,
         estado = v_estado,
         propuesta_inicio = case when v_estado = 'propuesta' then propuesta_inicio end,
         indicacion = case when d ? 'indicacion' then left(nullif(trim(d->>'indicacion'), ''), 500) else indicacion end,
         alerta_sin_hueco_en = case when v_cambia then null else alerta_sin_hueco_en end,
         alerta_vencida_en = case when v_hasta <> s.ventana_hasta then null else alerta_vencida_en end,
         mensajes_enviados = case when v_cambia or (v_estado = 'pendiente' and s.estado = 'suspendida') then 0 else mensajes_enviados end,
         actualizada_en = now()
  where id = s.id;
  if coalesce((d->>'avisar')::boolean, true) = false or d->>'estado' in ('suspendida', 'cancelada') then
    perform _detener_avisos(s.id);
  end if;
  if s.programa_id is not null then perform _programa_completo(s.programa_id); end if;
  perform _auditar(p_clinica, 'editar_sesion', 'sesion', s.id::text, s.paciente_id,
                   jsonb_build_object('campos', (select jsonb_agg(k) from jsonb_object_keys(d) k)));
  return jsonb_build_object('ok', true, 'sesion', _sesion_json(s.id, _puede_salud(m.rol)));
end;
$$;

-- Sesiones por programar de toda la consulta. filtro: por_programar | sin_hueco | vencidas | propuestas | todas
create function lista_seguimiento(p_clinica uuid, p_filtro text default 'por_programar', p_profesional bigint default null)
returns jsonb language plpgsql stable security definer set search_path = nutricion, extensions, pg_temp as $$
declare m miembros := _miembro(p_clinica); v_hoy date := _hoy(_tz(p_clinica));
begin
  return (select coalesce(jsonb_agg(_sesion_json(s.id, _puede_salud(m.rol)) order by s.ventana_desde, s.id), '[]'::jsonb)
    from sesiones s left join programas p on p.id = s.programa_id
    where s.clinica_id = p_clinica and (p_profesional is null or s.profesional_id = p_profesional)
      and (p.id is null or p.estado = 'activo')
      and case p_filtro
        when 'por_programar' then s.estado in ('pendiente', 'propuesta') and _sesion_ofrecible(s.id)
        when 'sin_hueco' then s.estado in ('pendiente', 'propuesta') and s.alerta_sin_hueco_en is not null
        when 'vencidas' then s.estado in ('pendiente', 'propuesta') and s.ventana_hasta < v_hoy
        when 'propuestas' then s.estado = 'propuesta'
        when 'todas' then s.estado in ('pendiente', 'propuesta', 'reservada', 'suspendida')
        else false end);
end;
$$;

-- =====================================================================
-- API de la aplicación: bonos
-- =====================================================================

create function lista_bono_tipos(p_clinica uuid) returns jsonb
language plpgsql stable security definer set search_path = nutricion, extensions, pg_temp as $$
begin
  perform _miembro(p_clinica);
  return (select coalesce(jsonb_agg(jsonb_build_object('id', t.id, 'nombre', t.nombre, 'descripcion', t.descripcion,
            'sesiones', t.sesiones, 'precio', round(t.precio_centimos / 100.0, 2), 'servicios', to_jsonb(t.servicios),
            'validez_dias', t.validez_dias, 'condiciones', t.condiciones, 'penaliza_no_asistida', t.penaliza_no_asistida,
            'penaliza_cancelacion_tardia', t.penaliza_cancelacion_tardia, 'activo', t.activo,
            'vendidos', (select count(*) from bonos b where b.bono_tipo_id = t.id)) order by t.orden, t.id), '[]'::jsonb)
    from bono_tipos t where t.clinica_id = p_clinica);
end;
$$;

-- d: {id?, nombre, descripcion?, sesiones, precio?, servicios: [id], validez_dias?, condiciones?,
--     penaliza_no_asistida?, penaliza_cancelacion_tardia?, activo?}
create function guardar_bono_tipo(p_clinica uuid, d jsonb) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare v_id bigint := (d->>'id')::bigint; v_serv bigint[];
begin
  perform _miembro(p_clinica, array['propietario']);
  select coalesce(array_agg(s.id order by s.id), '{}') into v_serv from servicios s
  where s.clinica_id = p_clinica and s.id in (select x::bigint from jsonb_array_elements_text(coalesce(d->'servicios', '[]')) x);
  if cardinality(v_serv) = 0 or cardinality(v_serv) <> jsonb_array_length(coalesce(d->'servicios', '[]')) then
    return jsonb_build_object('ok', false, 'motivo', 'servicios_no_validos');
  end if;
  begin
    if v_id is null then
      insert into bono_tipos (clinica_id, nombre, descripcion, sesiones, precio_centimos, servicios, validez_dias, condiciones,
                              penaliza_no_asistida, penaliza_cancelacion_tardia, activo, orden)
      values (p_clinica, trim(d->>'nombre'), nullif(trim(d->>'descripcion'), ''), (d->>'sesiones')::int,
              round(nullif(replace(d->>'precio', ',', '.'), '')::numeric * 100)::int, v_serv,
              nullif(d->>'validez_dias', '')::int, left(nullif(trim(d->>'condiciones'), ''), 2000),
              coalesce((d->>'penaliza_no_asistida')::boolean, false), coalesce((d->>'penaliza_cancelacion_tardia')::boolean, false),
              coalesce((d->>'activo')::boolean, true),
              (select coalesce(max(orden), 0) + 1 from bono_tipos where clinica_id = p_clinica))
      returning id into v_id;
    else
      update bono_tipos set nombre = coalesce(nullif(trim(d->>'nombre'), ''), nombre),
             descripcion = case when d ? 'descripcion' then nullif(trim(d->>'descripcion'), '') else descripcion end,
             sesiones = coalesce((d->>'sesiones')::int, sesiones),
             precio_centimos = case when d ? 'precio' then round(nullif(replace(d->>'precio', ',', '.'), '')::numeric * 100)::int
                                    else precio_centimos end,
             servicios = v_serv,
             validez_dias = case when d ? 'validez_dias' then nullif(d->>'validez_dias', '')::int else validez_dias end,
             condiciones = case when d ? 'condiciones' then left(nullif(trim(d->>'condiciones'), ''), 2000) else condiciones end,
             penaliza_no_asistida = coalesce((d->>'penaliza_no_asistida')::boolean, penaliza_no_asistida),
             penaliza_cancelacion_tardia = coalesce((d->>'penaliza_cancelacion_tardia')::boolean, penaliza_cancelacion_tardia),
             activo = coalesce((d->>'activo')::boolean, activo)
      where id = v_id and clinica_id = p_clinica;
      if not found then return jsonb_build_object('ok', false, 'motivo', 'no_existe'); end if;
    end if;
  exception
    when unique_violation then return jsonb_build_object('ok', false, 'motivo', 'nombre_repetido');
    when check_violation or not_null_violation or invalid_text_representation then
      return jsonb_build_object('ok', false, 'motivo', 'valor_no_valido');
  end;
  perform _auditar(p_clinica, 'guardar_bono_tipo', 'bono_tipo', v_id::text);
  return jsonb_build_object('ok', true, 'id', v_id);
end;
$$;

-- Venta de un bono a un paciente. d: {paciente_id, bono_tipo_id, fecha_compra?, pago_estado?, notas?, clave?}
-- Las citas ya reservadas de esos servicios sin bono pasan a usarlo (hasta cubrir sus sesiones).
create function vender_bono(p_clinica uuid, d jsonb) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare t bono_tipos; v_pac bigint := (d->>'paciente_id')::bigint; v_id bigint; v_fecha date; v_n int := 0; ci record;
begin
  perform _miembro(p_clinica);
  if d->>'clave' is not null then
    select id into v_id from bonos where clinica_id = p_clinica and clave_idempotencia = d->>'clave';
    if v_id is not null then return jsonb_build_object('ok', true, 'repetida', true, 'bono', _bono_json(v_id)); end if;
  end if;
  if not exists (select 1 from pacientes where id = v_pac and clinica_id = p_clinica) then
    return jsonb_build_object('ok', false, 'motivo', 'paciente_no_existe');
  end if;
  select * into t from bono_tipos where id = (d->>'bono_tipo_id')::bigint and clinica_id = p_clinica and activo;
  if t.id is null then return jsonb_build_object('ok', false, 'motivo', 'bono_tipo_no_existe'); end if;
  v_fecha := coalesce(nullif(d->>'fecha_compra', '')::date, _hoy(_tz(p_clinica)));
  if coalesce(d->>'pago_estado', 'pendiente') not in ('pendiente', 'parcial', 'pagado') then
    return jsonb_build_object('ok', false, 'motivo', 'valor_no_valido');
  end if;
  begin
    insert into bonos (clinica_id, paciente_id, bono_tipo_id, nombre, sesiones_total, precio_centimos, servicios, fecha_compra,
                       caduca, condiciones, penaliza_no_asistida, penaliza_cancelacion_tardia, pago_estado, notas,
                       clave_idempotencia, creado_por)
    values (p_clinica, v_pac, t.id, t.nombre, t.sesiones, t.precio_centimos, t.servicios, v_fecha,
            v_fecha + t.validez_dias, t.condiciones, t.penaliza_no_asistida, t.penaliza_cancelacion_tardia,
            coalesce(d->>'pago_estado', 'pendiente'), left(nullif(trim(d->>'notas'), ''), 500), d->>'clave', auth.uid())
    returning id into v_id;
  exception when unique_violation then
    select id into v_id from bonos where clinica_id = p_clinica and clave_idempotencia = d->>'clave';
    return jsonb_build_object('ok', true, 'repetida', true, 'bono', _bono_json(v_id));
  end;
  for ci in select c.id from citas c where c.paciente_id = v_pac and c.estado = 'reservada' and c.bono_id is null
              and c.servicio_id = any (t.servicios) and (t.validez_dias is null or (c.inicio at time zone _tz(p_clinica))::date <= v_fecha + t.validez_dias)
              and c.inicio > now()
            order by c.inicio limit t.sesiones loop
    update citas set bono_id = v_id where id = ci.id;
    v_n := v_n + 1;
  end loop;
  perform _auditar(p_clinica, 'vender_bono', 'bono', v_id::text, v_pac, jsonb_build_object('tipo', t.id, 'citas_asignadas', v_n));
  return jsonb_build_object('ok', true, 'bono', _bono_json(v_id), 'citas_asignadas', v_n);
end;
$$;

-- d: {pago_estado?, notas?, estado? ('anulado' | 'activo'), caduca?}. Anular o cambiar la caducidad: propietario.
create function editar_bono(p_clinica uuid, p_id bigint, d jsonb) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare m miembros := _miembro(p_clinica); b bonos;
begin
  select * into b from bonos where id = p_id and clinica_id = p_clinica for update;
  if b.id is null then return jsonb_build_object('ok', false, 'motivo', 'bono_no_existe'); end if;
  if (d ? 'estado' or d ? 'caduca') and m.rol <> 'propietario' then raise exception 'sin_permiso' using errcode = '42501'; end if;
  if d ? 'estado' and d->>'estado' not in ('anulado', 'activo') then return jsonb_build_object('ok', false, 'motivo', 'valor_no_valido'); end if;
  if coalesce(d->>'pago_estado', 'pendiente') not in ('pendiente', 'parcial', 'pagado') then
    return jsonb_build_object('ok', false, 'motivo', 'valor_no_valido');
  end if;
  update bonos set pago_estado = coalesce(d->>'pago_estado', pago_estado),
         notas = case when d ? 'notas' then left(nullif(trim(d->>'notas'), ''), 500) else notas end,
         caduca = case when d ? 'caduca' then nullif(d->>'caduca', '')::date else caduca end,
         estado = coalesce(d->>'estado', estado)
  where id = b.id;
  if d->>'estado' = 'anulado' then
    update citas set bono_id = null where bono_id = b.id and estado = 'reservada';
  else
    perform _bono_actualizar_estado(b.id);
  end if;
  perform _auditar(p_clinica, 'editar_bono', 'bono', b.id::text, b.paciente_id,
                   jsonb_build_object('campos', (select jsonb_agg(k) from jsonb_object_keys(d) k)));
  return jsonb_build_object('ok', true, 'bono', _bono_json(b.id));
end;
$$;

-- Movimientos de un bono: qué citas lo usan y qué se ha descontado.
create function ver_bono(p_clinica uuid, p_id bigint) returns jsonb
language plpgsql stable security definer set search_path = nutricion, extensions, pg_temp as $$
declare v_tz text := _tz(p_clinica);
begin
  perform _miembro(p_clinica);
  if not exists (select 1 from bonos where id = p_id and clinica_id = p_clinica) then
    return jsonb_build_object('ok', false, 'motivo', 'bono_no_existe');
  end if;
  return jsonb_build_object('ok', true, 'bono', _bono_json(p_id),
    'citas', (select coalesce(jsonb_agg(jsonb_build_object('cita_id', c.id, 'inicio', _local(c.inicio, v_tz),
                'fecha_texto', fecha_es(c.inicio, v_tz), 'estado', c.estado, 'servicio', se.nombre,
                'consumo', (select bc.tipo from bono_consumos bc where bc.cita_id = c.id and bc.bono_id = p_id and bc.revertido_en is null))
                order by c.inicio), '[]'::jsonb)
              from citas c join servicios se on se.id = c.servicio_id
              where c.bono_id = p_id or exists (select 1 from bono_consumos bc where bc.cita_id = c.id and bc.bono_id = p_id)));
end;
$$;

-- Asigna (o quita) el bono de una cita reservada. Nada se descuenta hasta que se realiza.
create function asignar_bono_cita(p_clinica uuid, p_cita bigint, p_bono bigint) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare ci citas; b bonos;
begin
  perform _miembro(p_clinica);
  select * into ci from citas where id = p_cita and clinica_id = p_clinica for update;
  if ci.id is null then return jsonb_build_object('ok', false, 'motivo', 'cita_no_existe'); end if;
  if ci.estado <> 'reservada' then return jsonb_build_object('ok', false, 'motivo', 'cita_no_modificable', 'estado', ci.estado); end if;
  if p_bono is not null then
    select * into b from bonos where id = p_bono and clinica_id = p_clinica and paciente_id = ci.paciente_id for update;
    if b.id is null or b.estado <> 'activo' or not (ci.servicio_id = any (b.servicios)) then
      return jsonb_build_object('ok', false, 'motivo', 'bono_no_valido');
    end if;
    if b.sesiones_total - _bono_usadas(b.id) - _bono_reservadas(b.id) <= 0 and ci.bono_id is distinct from b.id then
      return jsonb_build_object('ok', false, 'motivo', 'bono_sin_sesiones');
    end if;
  end if;
  update citas set bono_id = p_bono where id = ci.id;
  perform _auditar(p_clinica, 'asignar_bono_cita', 'cita', ci.id::text, ci.paciente_id, jsonb_build_object('bono', p_bono));
  return jsonb_build_object('ok', true, 'cita', _cita_json(ci.id));
end;
$$;

-- =====================================================================
-- Canales (service_role): seguimientos y bonos del paciente comprobado
-- =====================================================================

create function _sesion_canal_json(p_sesion bigint) returns jsonb
language sql stable security definer set search_path = nutricion, extensions, pg_temp as $$
  select jsonb_build_object('sesion_id', s.id, 'programa_id', s.programa_id, 'programa', p.nombre, 'numero', s.numero,
    'total', p.num_sesiones, 'estado', s.estado, 'servicio', se.nombre, 'profesional', pr.nombre, 'modalidad', s.modalidad,
    'plazo', 'entre el ' || fecha_dia_es(s.ventana_desde) || ' y el ' || fecha_dia_es(s.ventana_hasta),
    'plazo_desde', s.ventana_desde, 'plazo_hasta', s.ventana_hasta,
    'propuesta', fecha_es(s.propuesta_inicio, cl.zona_horaria),
    'cita', case when s.cita_id is not null then _cita_canal_json(s.cita_id) end)
  from sesiones s join clinicas cl on cl.id = s.clinica_id join servicios se on se.id = s.servicio_id
  join profesionales pr on pr.id = s.profesional_id left join programas p on p.id = s.programa_id
  where s.id = p_sesion
$$;

-- Revisiones y sesiones del paciente: las que puede reservar ya (con su plazo), las propuestas y las reservadas.
create function canal_mis_sesiones(p_conversacion bigint) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare v conversaciones := _conv(p_conversacion); v_pac bigint := _verificado(v);
begin
  if v_pac is null then return jsonb_build_object('ok', false, 'motivo', 'identidad_no_comprobada'); end if;
  return jsonb_build_object('ok', true,
    'por_reservar', (select coalesce(jsonb_agg(_sesion_canal_json(s.id) order by s.ventana_desde, s.numero), '[]'::jsonb)
                     from sesiones s where s.paciente_id = v_pac and s.estado = 'pendiente' and _sesion_ofrecible(s.id)
                       and s.ventana_hasta >= _hoy(_tz(v.clinica_id))),
    'propuestas', (select coalesce(jsonb_agg(jsonb_build_object('programa_id', p.id, 'programa', p.nombre,
                     'fechas', (select jsonb_agg(fecha_es(s.propuesta_inicio, _tz(v.clinica_id)) order by s.numero)
                                from sesiones s where s.programa_id = p.id and s.estado = 'propuesta'))), '[]'::jsonb)
                   from programas p where p.paciente_id = v_pac and p.estado = 'activo'
                     and exists (select 1 from sesiones s where s.programa_id = p.id and s.estado = 'propuesta')),
    'reservadas', (select coalesce(jsonb_agg(_sesion_canal_json(s.id) order by ci.inicio), '[]'::jsonb)
                   from sesiones s join citas ci on ci.id = s.cita_id
                   where s.paciente_id = v_pac and s.estado = 'reservada' and ci.inicio > now()));
end;
$$;

-- Huecos para una sesión, solo dentro del plazo autorizado. Si no hay ninguno, se avisa al profesional.
create function canal_huecos_sesion(p_conversacion bigint, p_sesion bigint, p_desde text default null,
                                    p_franja text default 'cualquiera') returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare v conversaciones := _conv(p_conversacion); v_pac bigint := _verificado(v); s sesiones; v_tz text := _tz(v.clinica_id);
        v_h jsonb;
begin
  if v_pac is null then return jsonb_build_object('ok', false, 'motivo', 'identidad_no_comprobada'); end if;
  select * into s from sesiones where id = p_sesion and paciente_id = v_pac;
  if s.id is null then return jsonb_build_object('ok', false, 'motivo', 'sesion_no_existe'); end if;
  if s.estado not in ('pendiente', 'propuesta') or not _sesion_ofrecible(s.id) then
    return jsonb_build_object('ok', false, 'motivo', 'sesion_no_reservable', 'estado', s.estado);
  end if;
  select coalesce(jsonb_agg(jsonb_build_object('inicio', _local(h.inicio, v_tz), 'fecha_texto', fecha_es(h.inicio, v_tz),
                  'profesional', h.profesional) order by h.inicio), '[]'::jsonb) into v_h
  from (select * from _huecos_sesion(s.id, true, 60, nullif(p_desde, '')::date) h0
        where coalesce(p_franja, 'cualquiera') = 'cualquiera'
           or (p_franja = 'manana' and _hora_local(h0.inicio, v_tz) < '14:00')
           or (p_franja = 'tarde' and _hora_local(h0.inicio, v_tz) >= '14:00')
        order by h0.inicio limit 8) h;
  if jsonb_array_length(v_h) = 0 and not exists (select 1 from _huecos_sesion(s.id, true, 1)) then
    perform _alerta_sin_hueco(s.id);
    return jsonb_build_object('ok', true, 'sesion', _sesion_canal_json(s.id), 'huecos', '[]'::jsonb,
                              'sin_disponibilidad', true, 'equipo_avisado', true);
  end if;
  return jsonb_build_object('ok', true, 'sesion', _sesion_canal_json(s.id), 'huecos', v_h);
end;
$$;

create function canal_reservar_sesion(p_conversacion bigint, p_sesion bigint, p_inicio text, p_clave text default null)
returns jsonb language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare v conversaciones := _conv(p_conversacion); v_pac bigint := _verificado(v); r jsonb;
begin
  if v_pac is null then return jsonb_build_object('ok', false, 'motivo', 'identidad_no_comprobada'); end if;
  if not exists (select 1 from sesiones where id = p_sesion and paciente_id = v_pac) then
    return jsonb_build_object('ok', false, 'motivo', 'sesion_no_existe');
  end if;
  if not _sesion_ofrecible(p_sesion) and not exists (select 1 from sesiones where id = p_sesion and estado = 'reservada') then
    return jsonb_build_object('ok', false, 'motivo', 'sesion_no_reservable');
  end if;
  r := _reservar_sesion(p_sesion, _desde_local(p_inicio, _tz(v.clinica_id)), null, v.canal,
                        coalesce(p_clave, 'conv:' || v.id || ':sesion:' || p_sesion || ':' || p_inicio));
  if not (r->>'ok')::boolean then return r - 'cita'; end if;
  return jsonb_build_object('ok', true, 'repetida', r->'repetida', 'sesion', _sesion_canal_json(p_sesion),
                            'cita', _cita_canal_json((r->'cita'->>'id')::bigint));
end;
$$;

create function canal_confirmar_propuesta(p_conversacion bigint, p_programa bigint) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare v conversaciones := _conv(p_conversacion); v_pac bigint := _verificado(v); r jsonb;
begin
  if v_pac is null then return jsonb_build_object('ok', false, 'motivo', 'identidad_no_comprobada'); end if;
  if not exists (select 1 from programas where id = p_programa and paciente_id = v_pac) then
    return jsonb_build_object('ok', false, 'motivo', 'programa_no_existe');
  end if;
  r := _confirmar_propuesta(p_programa, v.canal);
  if not (r->>'ok')::boolean then return r; end if;
  return jsonb_build_object('ok', true, 'reservadas', r->'reservadas',
    'citas', (select jsonb_agg(_cita_canal_json(s.cita_id) order by s.numero) from sesiones s
              where s.programa_id = p_programa and s.estado = 'reservada'));
end;
$$;

create function canal_mis_bonos(p_conversacion bigint) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare v conversaciones := _conv(p_conversacion); v_pac bigint := _verificado(v);
begin
  if v_pac is null then return jsonb_build_object('ok', false, 'motivo', 'identidad_no_comprobada'); end if;
  return jsonb_build_object('ok', true, 'bonos', (select coalesce(jsonb_agg(jsonb_build_object(
      'nombre', x->>'nombre', 'sesiones_total', x->'sesiones_total', 'usadas', x->'usadas',
      'restantes', x->'restantes', 'ya_reservadas', x->'reservadas',
      'caduca', case when x->>'caduca' is not null then fecha_dia_es((x->>'caduca')::date) end,
      'servicios', (select jsonb_agg(s->>'nombre') from jsonb_array_elements(x->'servicios') s),
      'pago', x->>'pago_estado', 'condiciones', x->>'condiciones')), '[]'::jsonb)
    from (select _bono_json(b.id) x from bonos b where b.paciente_id = v_pac and b.estado = 'activo'
          order by b.fecha_compra) y));
end;
$$;

-- El contexto de cada turno dice también si tiene revisiones por reservar o propuestas sin contestar.
alter function canal_contexto(bigint) rename to _canal_contexto_fase2;
create function canal_contexto(p_conversacion bigint) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare r jsonb := _canal_contexto_fase2(p_conversacion); v conversaciones := _conv(p_conversacion); v_pac bigint := _verificado(v);
begin
  if v_pac is null then return r; end if;
  return jsonb_set(r, '{paciente}', (r->'paciente') || jsonb_build_object(
    'sesiones_por_reservar', (select count(*) from sesiones s where s.paciente_id = v_pac and s.estado = 'pendiente'
                                and _sesion_ofrecible(s.id) and s.ventana_hasta >= _hoy(_tz(v.clinica_id))),
    'propuestas_sin_confirmar', (select count(*) from sesiones s join programas p on p.id = s.programa_id
                                   where s.paciente_id = v_pac and s.estado = 'propuesta' and p.estado = 'activo'),
    'bonos_activos', (select count(*) from bonos where paciente_id = v_pac and estado = 'activo')));
end;
$$;

-- Cambio por el canal de una cita de sesión: además de las reglas de siempre, dentro de su plazo autorizado.
create or replace function canal_cambiar(p_conversacion bigint, p_cita bigint, p_inicio text, p_profesional bigint default null)
returns jsonb language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare v conversaciones := _conv(p_conversacion); x record; r jsonb; s sesiones;
begin
  select * into x from _cita_del_canal(v, p_cita);
  if x.motivo = 'fuera_de_plazo' then
    perform _solicitud(v.clinica_id, 'cambio_fuera_plazo',
      'Quiere cambiar la cita del ' || fecha_es((x.ci).inicio, _tz(v.clinica_id)) || coalesce(' a ' || p_inicio, ''),
      (x.ci).paciente_id, v.id, (x.ci).id, false, null, v.contacto);
    return jsonb_build_object('ok', false, 'motivo', 'fuera_de_plazo', 'solicitud_creada', true);
  end if;
  if x.motivo is not null then return jsonb_build_object('ok', false, 'motivo', x.motivo); end if;
  s := _cita_fuera_de_plazo(p_cita, _desde_local(p_inicio, _tz(v.clinica_id)));
  if s.id is not null then
    return jsonb_build_object('ok', false, 'motivo', 'fuera_de_plazo_sesion',
                              'plazo', 'entre el ' || fecha_dia_es(s.ventana_desde) || ' y el ' || fecha_dia_es(s.ventana_hasta));
  end if;
  r := _cambiar(v.clinica_id, p_cita, _desde_local(p_inicio, _tz(v.clinica_id)), nullif(p_profesional, 0), null, false, null, true);
  if (r->>'ok')::boolean then return jsonb_build_object('ok', true, 'cita', _cita_canal_json(p_cita)); end if;
  return r;
end;
$$;

-- Cambio desde la agenda: fuera del plazo de su sesión, solo el equipo sanitario y con motivo.
create or replace function cambiar_cita(p_clinica uuid, p_cita bigint, d jsonb) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare m miembros := _miembro(p_clinica); s sesiones; v_ini timestamptz := _desde_local(d->>'inicio', _tz(p_clinica)); r jsonb;
begin
  s := _cita_fuera_de_plazo(p_cita, v_ini);
  if s.id is not null then
    if not coalesce((d->>'forzar')::boolean, false) or not _puede_salud(m.rol) then
      return jsonb_build_object('ok', false, 'motivo', 'fuera_de_plazo_sesion',
                                'plazo', 'entre el ' || fecha_dia_es(s.ventana_desde) || ' y el ' || fecha_dia_es(s.ventana_hasta));
    end if;
    if nullif(trim(coalesce(d->>'motivo_excepcion', '')), '') is null then
      return jsonb_build_object('ok', false, 'motivo', 'falta_motivo_excepcion');
    end if;
  end if;
  r := _cambiar(p_clinica, p_cita, v_ini, (d->>'profesional_id')::bigint, nullif(d->>'modalidad', ''),
                coalesce((d->>'forzar')::boolean, false), d->>'motivo_excepcion');
  if (r->>'ok')::boolean and s.id is not null then
    update citas set excepcion = concat_ws('; ', excepcion, 'fuera del plazo autorizado — ' || left(trim(d->>'motivo_excepcion'), 300))
    where id = p_cita;
    r := jsonb_set(r, '{cita}', _cita_json(p_cita));
  end if;
  return r;
end;
$$;

-- Variables nuevas en las plantillas.
create or replace function guardar_plantilla(p_clinica uuid, p_clave text, d jsonb) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare v_desconocidas text[];
begin
  perform _miembro(p_clinica, array['propietario']);
  select array_agg(distinct m[1]) into v_desconocidas
  from regexp_matches(coalesce(d->>'texto', ''), '\{([a-z_]+)\}', 'g') m
  where m[1] not in ('paciente', 'fecha', 'servicio', 'profesional', 'clinica', 'lugar', 'enlace', 'comprobacion', 'caduca',
                     'tipo', 'texto', 'desde', 'hasta', 'programa', 'fechas');
  if v_desconocidas is not null then
    return jsonb_build_object('ok', false, 'motivo', 'variable_desconocida', 'variables', to_jsonb(v_desconocidas));
  end if;
  if p_clave in ('formulario_pendiente', 'formulario_recordatorio') and d ? 'texto' and d->>'texto' not like '%{enlace}%' then
    return jsonb_build_object('ok', false, 'motivo', 'falta_enlace');
  end if;
  if p_clave in ('propuesta_sesiones', 'confirmacion_sesiones') and d ? 'texto' and d->>'texto' not like '%{fechas}%' then
    return jsonb_build_object('ok', false, 'motivo', 'falta_fechas');
  end if;
  update plantillas_mensaje set
    texto = coalesce(nullif(trim(d->>'texto'), ''), texto),
    activa = coalesce((d->>'activa')::boolean, activa),
    plantilla_meta = case when d ? 'plantilla_meta' then nullif(trim(d->>'plantilla_meta'), '') else plantilla_meta end
  where clinica_id = p_clinica and clave = p_clave;
  if not found then return jsonb_build_object('ok', false, 'motivo', 'plantilla_no_existe'); end if;
  perform _auditar(p_clinica, 'guardar_plantilla', 'plantilla', p_clave);
  return jsonb_build_object('ok', true);
end;
$$;

-- Ajustes de seguimiento (propietario). d: {seguimiento_max_mensajes?, seguimiento_intervalo_dias?,
--   seguimiento_antelacion_dias?, seguimiento_margen_dias?}
create function ajustes_seguimiento(p_clinica uuid) returns jsonb
language plpgsql stable security definer set search_path = nutricion, extensions, pg_temp as $$
begin
  perform _miembro(p_clinica);
  return (select jsonb_build_object('seguimiento_max_mensajes', seguimiento_max_mensajes,
            'seguimiento_intervalo_dias', seguimiento_intervalo_dias, 'seguimiento_antelacion_dias', seguimiento_antelacion_dias,
            'seguimiento_margen_dias', seguimiento_margen_dias) from clinicas where id = p_clinica);
end;
$$;

create function guardar_ajustes_seguimiento(p_clinica uuid, d jsonb) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
begin
  perform _miembro(p_clinica, array['propietario']);
  begin
    update clinicas set
      seguimiento_max_mensajes = coalesce((d->>'seguimiento_max_mensajes')::int, seguimiento_max_mensajes),
      seguimiento_intervalo_dias = coalesce((d->>'seguimiento_intervalo_dias')::int, seguimiento_intervalo_dias),
      seguimiento_antelacion_dias = coalesce((d->>'seguimiento_antelacion_dias')::int, seguimiento_antelacion_dias),
      seguimiento_margen_dias = coalesce((d->>'seguimiento_margen_dias')::int, seguimiento_margen_dias)
    where id = p_clinica;
  exception when check_violation or invalid_text_representation then
    return jsonb_build_object('ok', false, 'motivo', 'valor_no_valido');
  end;
  perform _auditar(p_clinica, 'guardar_ajustes_seguimiento', 'clinica', p_clinica::text, null,
                   jsonb_build_object('campos', (select jsonb_agg(k) from jsonb_object_keys(d) k)));
  return jsonb_build_object('ok', true, 'ajustes', ajustes_seguimiento(p_clinica));
end;
$$;

-- =====================================================================
-- Motor: recordatorios de seguimiento, alertas y caducidad de bonos
-- =====================================================================

alter function motor_tick() rename to _motor_tick_fase2;

create function motor_tick() returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare r jsonb := _motor_tick_fase2(); s record; v_envio bigint; n_seg int := 0; n_sin int := 0; n_venc int := 0; n_bonos int := 0;
        v_vars jsonb;
begin
  perform set_config('nutricion.actor', 'sistema', true);
  -- Recordatorios para reservar una revisión pendiente: solo si el profesional los autorizó, dentro del número
  -- máximo de mensajes de la consulta y con días entre uno y otro. Si no hay huecos en el plazo, no se le pide al
  -- paciente que reserve: se avisa al profesional.
  for s in
    select x.id, x.clinica_id, x.paciente_id, x.mensajes_enviados, x.ventana_desde, x.ventana_hasta, x.alerta_sin_hueco_en,
           c.zona_horaria, c.nombre clinica, se.nombre servicio, pr.nombre profesional, pa.nombre paciente
    from sesiones x join clinicas c on c.id = x.clinica_id join pacientes pa on pa.id = x.paciente_id
    join servicios se on se.id = x.servicio_id join profesionales pr on pr.id = x.profesional_id
    left join programas p on p.id = x.programa_id
    where x.estado = 'pendiente' and x.avisar and pa.estado = 'activo'
      and (p.id is null or (p.estado = 'activo' and p.avisar))
      and x.ventana_hasta >= _hoy(c.zona_horaria)
      and _hoy(c.zona_horaria) >= x.ventana_desde - c.seguimiento_antelacion_dias
      and x.mensajes_enviados < c.seguimiento_max_mensajes
      and (x.ultima_gestion_en is null or x.ultima_gestion_en <= now() - make_interval(days => c.seguimiento_intervalo_dias))
      and _sesion_ofrecible(x.id)
      -- como mucho un recordatorio de seguimiento por paciente en ese intervalo, aunque tenga varias sesiones
      and not exists (select 1 from envios e where e.paciente_id = x.paciente_id and e.tipo = 'recordatorio_seguimiento'
                        and e.estado <> 'cancelado' and e.creado_en > now() - make_interval(days => c.seguimiento_intervalo_dias))
    for update of x skip locked
  loop
    if not exists (select 1 from _huecos_sesion(s.id, true, 1)) then
      if _alerta_sin_hueco(s.id) is not null then n_sin := n_sin + 1; end if;
      continue;
    end if;
    v_vars := jsonb_build_object('paciente', split_part(trim(s.paciente), ' ', 1), 'clinica', s.clinica,
      'servicio', lower(s.servicio), 'profesional', s.profesional,
      'desde', fecha_dia_es(greatest(s.ventana_desde, _hoy(s.zona_horaria))), 'hasta', fecha_dia_es(s.ventana_hasta));
    v_envio := _encolar(s.clinica_id, 'recordatorio_seguimiento', 'seguimiento:' || s.id || ':' || (s.mensajes_enviados + 1),
                        s.paciente_id, null, v_vars);
    update sesiones set ultima_gestion_en = now(),
           mensajes_enviados = mensajes_enviados + case when v_envio is not null then 1 else 0 end
    where id = s.id;
    if v_envio is not null then
      update envios set sesion_id = s.id where id = v_envio;
      n_seg := n_seg + 1;
    end if;
  end loop;
  -- Plazo vencido sin reservar: aviso al profesional (una vez). La sesión sigue pendiente: él decide.
  for s in
    select x.id, x.clinica_id, x.paciente_id, x.profesional_id, x.numero, x.ventana_desde, x.ventana_hasta, se.nombre servicio,
           p.nombre programa
    from sesiones x join clinicas c on c.id = x.clinica_id join servicios se on se.id = x.servicio_id
    left join programas p on p.id = x.programa_id
    where x.estado in ('pendiente', 'propuesta') and x.alerta_vencida_en is null and x.ventana_hasta < _hoy(c.zona_horaria)
      and (p.id is null or p.estado = 'activo')
    for update of x skip locked
  loop
    v_envio := _solicitud(s.clinica_id, 'seguimiento_vencido',
      s.servicio || coalesce(' (sesión ' || s.numero || ' de "' || s.programa || '")', '') || ': el plazo terminó el '
      || fecha_dia_es(s.ventana_hasta) || ' y no tiene cita. Decide si se amplía el plazo, se le llama o se cierra.',
      s.paciente_id);
    update solicitudes set profesional_id = s.profesional_id where id = v_envio;
    update sesiones set alerta_vencida_en = now() where id = s.id;
    n_venc := n_venc + 1;
  end loop;
  with b as (update bonos set estado = 'caducado' where estado = 'activo' and caduca < _hoy(_tz(clinica_id)) returning 1)
  select count(*) into n_bonos from b;
  return r || jsonb_build_object('seguimientos', n_seg, 'sin_disponibilidad', n_sin, 'seguimientos_vencidos', n_venc,
                                 'bonos_caducados', n_bonos);
end;
$$;

-- =====================================================================
-- Listas y panel
-- =====================================================================

create or replace function lista_pacientes(p_clinica uuid, p_filtro text default 'todos', p_desde date default null,
                                           p_hasta date default null) returns jsonb
language plpgsql stable security definer set search_path = nutricion, extensions, pg_temp as $$
declare v_tz text := _tz(p_clinica);
begin
  perform _miembro(p_clinica);
  return (select coalesce(jsonb_agg(_paciente_json(p.id) order by p.nombre, p.id), '[]'::jsonb)
    from pacientes p
    where p.clinica_id = p_clinica
      and case p_filtro
        when 'activos' then p.estado = 'activo'
        when 'nuevos' then (p.creado_en at time zone v_tz)::date between coalesce(p_desde, _hoy(v_tz) - 30) and coalesce(p_hasta, _hoy(v_tz))
        when 'sin_proxima' then p.estado = 'activo'
             and exists (select 1 from citas c where c.paciente_id = p.id and c.estado = 'realizada')
             and not exists (select 1 from citas c where c.paciente_id = p.id and c.estado = 'reservada' and c.inicio > now())
        when 'formulario_pendiente' then exists (select 1 from formulario_envios fe where fe.paciente_id = p.id
             and fe.estado = 'pendiente' and fe.caduca_en > now())
        when 'con_programa' then exists (select 1 from sesiones s left join programas pr on pr.id = s.programa_id
             where s.paciente_id = p.id and s.estado in ('pendiente', 'propuesta') and (pr.id is null or pr.estado = 'activo'))
        when 'con_bono' then exists (select 1 from bonos b where b.paciente_id = p.id and b.estado = 'activo')
        else true end);
end;
$$;

-- La cita dice qué bono usa, a qué sesión corresponde y si ya tiene valoración o seguimiento indicado.
create or replace function _cita_json(p_cita bigint) returns jsonb
language sql stable security definer set search_path = nutricion, extensions, pg_temp as $$
  select jsonb_build_object(
    'id', ci.id, 'inicio', _local(ci.inicio, cl.zona_horaria), 'fin', _local(ci.fin, cl.zona_horaria),
    'fecha_texto', fecha_es(ci.inicio, cl.zona_horaria),
    'estado', ci.estado, 'modalidad', ci.modalidad, 'origen', ci.origen,
    'confirmada', ci.confirmada_en is not null,
    'paciente_id', ci.paciente_id, 'paciente', trim(pa.nombre || ' ' || coalesce(pa.apellidos, '')),
    'telefono', pa.telefono,
    'profesional_id', ci.profesional_id, 'profesional', pr.nombre,
    'servicio_id', ci.servicio_id, 'servicio', se.nombre, 'tipo', se.tipo,
    'precio', round(ci.precio_centimos / 100.0, 2),
    'motivo', ci.motivo, 'notas', ci.notas, 'excepcion', ci.excepcion,
    'enlace_online', case when ci.modalidad = 'online' then pr.enlace_online end,
    -- fase 3: bono que usa y sesión de seguimiento o programa a la que corresponde
    'bono_id', ci.bono_id, 'bono', (select b.nombre from bonos b where b.id = ci.bono_id),
    'bono_consumo', (select bc.tipo from bono_consumos bc where bc.cita_id = ci.id and bc.revertido_en is null limit 1),
    'sesion_id', (select s.id from sesiones s where s.cita_id = ci.id),
    'sesion_texto', (select case when s.programa_id is null then 'Seguimiento indicado'
                                 else 'Sesión ' || s.numero || ' de ' || p.num_sesiones || ' · ' || p.nombre end
                     from sesiones s left join programas p on p.id = s.programa_id where s.cita_id = ci.id),
    'seguimiento_indicado', exists (select 1 from sesiones s where s.origen_cita_id = ci.id
                                     and s.estado in ('pendiente', 'propuesta', 'reservada')),
    'valoracion_id', (select v.id from valoraciones v where v.cita_id = ci.id))
  from citas ci
  join clinicas cl on cl.id = ci.clinica_id
  join pacientes pa on pa.id = ci.paciente_id
  join profesionales pr on pr.id = ci.profesional_id
  join servicios se on se.id = ci.servicio_id
  where ci.id = p_cita
$$;

alter function panel(uuid, date, date, bigint) rename to _panel_fase2;

create function panel(p_clinica uuid, p_desde date default null, p_hasta date default null,
                      p_profesional bigint default null) returns jsonb
language plpgsql stable security definer set search_path = nutricion, extensions, pg_temp as $$
declare r jsonb := _panel_fase2(p_clinica, p_desde, p_hasta, p_profesional); c clinicas;
begin
  select * into c from clinicas where id = p_clinica;
  r := jsonb_set(r, '{pacientes,con_programas_pendientes}', to_jsonb(jsonb_array_length(lista_pacientes(p_clinica, 'con_programa'))));
  r := jsonb_set(r, '{pacientes,con_bonos_activos}', to_jsonb(jsonb_array_length(lista_pacientes(p_clinica, 'con_bono'))));
  r := jsonb_set(r, '{indicadores,sesiones_pendientes}', to_jsonb((select count(*) from sesiones s
          left join programas pr on pr.id = s.programa_id
          where s.clinica_id = p_clinica and s.estado in ('pendiente', 'propuesta') and (pr.id is null or pr.estado = 'activo')
            and (p_profesional is null or s.profesional_id = p_profesional))));
  -- Revisiones que necesitan programarse: las que ya se pueden reservar y no tienen cita.
  r := jsonb_set(r, '{tareas,revisiones_por_programar}', to_jsonb(jsonb_array_length(
          lista_seguimiento(p_clinica, 'por_programar', p_profesional))));
  r := jsonb_set(r, '{tareas,seguimiento_sin_hueco}', to_jsonb(jsonb_array_length(lista_seguimiento(p_clinica, 'sin_hueco', p_profesional))));
  return r;
end;
$$;

select _aplicar_permisos();


-- =====================================================================
-- Corvex Nutrición · Fase 4: documentos y evolución
-- Archivos privados (Supabase Storage), planes nutricionales con versiones, plantillas de recomendaciones,
-- documentos con lectura / aceptación / firma, enlaces seguros para el paciente, objetivos por medición y
-- formularios de revisión antes de cada cita.
--
-- Principios:
--  * Los archivos viven en un bucket privado. La aplicación nunca guarda el contenido en la base de datos; para
--    abrir uno pide un enlace firmado de un minuto, y solo lo consigue quien puede verlo (políticas del bucket).
--  * Un plan solo llega al paciente cuando un profesional ha aprobado esa versión. Las versiones aprobadas no se
--    tocan: un cambio es una versión nueva. El paciente ve siempre la última que se le entregó; el profesional,
--    todas.
--  * Un documento guarda una copia del texto tal y como se envió y su huella. Lo que responde el paciente (lectura,
--    aceptación, firma dibujada, rechazo) queda con fecha, método de identificación y huella, y ya no cambia.
--  * Nada de esto interpreta datos clínicos: la evolución se muestra, no se juzga, y la IA no toca planes.
-- =====================================================================

set search_path = nutricion, extensions, public;

-- ---------------------------------------------------------------- ajustes

alter table plantillas_mensaje drop constraint plantillas_mensaje_clave_check;
alter table plantillas_mensaje add constraint plantillas_mensaje_clave_check check (clave in (
  'confirmacion_cita', 'recordatorio_cita', 'cambio_cita', 'cancelacion_cita', 'formulario_pendiente',
  'formulario_recordatorio', 'oferta_lista_espera', 'aviso_equipo', 'mensaje_equipo',
  'recordatorio_seguimiento', 'propuesta_sesiones', 'confirmacion_sesiones',
  'plan_entregado', 'documento_pendiente', 'documento_recordatorio'));

alter table solicitudes drop constraint solicitudes_tipo_check;
alter table solicitudes add constraint solicitudes_tipo_check check (tipo in (
  'cambio_fuera_plazo', 'cancelacion_fuera_plazo', 'pregunta_clinica', 'pregunta_sin_respuesta', 'hablar_con_persona',
  'queja', 'envio_fallido', 'otro', 'sin_disponibilidad', 'seguimiento_vencido',
  'documento_rechazado', 'formulario_incompleto'));

-- Formularios de revisión: se mandan antes de cada cita del servicio (no solo al reservar), y avisan al profesional
-- si el paciente no responde algo importante.
alter table formularios
  add column envio           text not null default 'al_reservar' check (envio in ('al_reservar', 'antes_de_cada_cita')),
  add column dias_antes      int not null default 3 check (dias_antes between 1 and 14),
  add column avisar_si_falta boolean not null default true;

alter table formulario_envios add column alerta_en timestamptz;

-- Una medición puede venir de un formulario (lo dice el paciente). Así no se apunta dos veces.
alter table mediciones add column formulario_envio_id bigint;
create unique index mediciones_de_formulario on mediciones (formulario_envio_id, tipo)
  where formulario_envio_id is not null and anulada_en is null;

-- ---------------------------------------------------------------- archivos

-- Un archivo subido al bucket privado `nutricion`. La ruta es <consulta>/<uuid>: el nombre original no forma parte
-- de la ruta. `sanitario` = solo lo ven propietario y nutricionistas.
create table archivos (
  id                 bigint generated always as identity primary key,
  clinica_id         uuid not null references clinicas (id) on delete cascade,
  paciente_id        bigint not null,
  ruta               text not null unique,
  nombre             text not null check (length(trim(nombre)) between 1 and 200),
  mime               text not null,
  tamano             bigint not null check (tamano between 1 and 10485760),
  categoria          text not null check (categoria in ('plan', 'documento', 'analitica', 'informe', 'otro')),
  sanitario          boolean not null,
  origen             text not null default 'consulta' check (origen in ('consulta', 'paciente')),
  descripcion        text,
  estado             text not null default 'pendiente' check (estado in ('pendiente', 'listo', 'eliminado')),
  subido_por         uuid,
  creado_en          timestamptz not null default now(),
  listo_en           timestamptz,
  eliminado_en       timestamptz,
  eliminado_por      uuid,
  motivo_eliminacion text,
  unique (clinica_id, id),
  foreign key (clinica_id, paciente_id) references pacientes (clinica_id, id) on delete cascade
);
create index archivos_paciente on archivos (paciente_id, creado_en desc);

-- Permiso de dos minutos para que el portal (sin sesión) pida el enlace firmado de un archivo concreto.
create table concesiones_portal (
  ruta      text not null,
  enlace_id bigint not null,
  expira_en timestamptz not null,
  primary key (ruta, enlace_id)
);

-- ---------------------------------------------------------------- planes

create table plantillas_recomendacion (
  id         bigint generated always as identity primary key,
  clinica_id uuid not null references clinicas (id) on delete cascade,
  titulo     text not null check (length(trim(titulo)) between 2 and 120),
  texto      text not null check (length(texto) between 5 and 5000),
  activa     boolean not null default true,
  orden      int not null default 0,
  unique (clinica_id, titulo)
);

-- `origen` y `referencia_externa` preparan la llegada de planes desde herramientas de nutrición: hoy no hay
-- ninguna conectada, y un plan externo se sube como archivo.
create table planes (
  id                 bigint generated always as identity primary key,
  clinica_id         uuid not null references clinicas (id) on delete cascade,
  paciente_id        bigint not null,
  profesional_id     bigint,
  titulo             text not null check (length(trim(titulo)) between 2 and 120),
  descripcion        text,
  estado             text not null default 'activo' check (estado in ('activo', 'archivado')),
  origen             text not null default 'corvex' check (origen in ('corvex', 'externo')),
  herramienta        text,
  referencia_externa text,
  creado_por         uuid,
  creado_en          timestamptz not null default now(),
  archivado_en       timestamptz,
  unique (clinica_id, id),
  foreign key (clinica_id, paciente_id) references pacientes (clinica_id, id) on delete cascade,
  foreign key (clinica_id, profesional_id) references profesionales (clinica_id, id) on delete set null (profesional_id)
);
create index planes_paciente on planes (paciente_id, creado_en desc);

create table plan_versiones (
  id                   bigint generated always as identity primary key,
  clinica_id           uuid not null,
  plan_id              bigint not null,
  numero               int not null,
  estado               text not null default 'borrador' check (estado in ('borrador', 'aprobada', 'sustituida')),
  texto                text check (length(texto) <= 20000),
  archivo_id           bigint,
  nota_cambios         text,
  creada_por           uuid,
  creada_en            timestamptz not null default now(),
  actualizada_en       timestamptz not null default now(),
  aprobada_por         uuid,
  aprobada_por_nombre  text,
  aprobada_en          timestamptz,
  entregada_en         timestamptz,
  entrega_via          text check (entrega_via in ('enlace', 'en_mano', 'otro')),
  entregada_por_nombre text,
  reenviada_en         timestamptz,
  visto_en             timestamptz,
  unique (clinica_id, id),
  unique (plan_id, numero),
  foreign key (clinica_id, plan_id) references planes (clinica_id, id) on delete cascade,
  foreign key (clinica_id, archivo_id) references archivos (clinica_id, id)
);
create unique index plan_un_borrador on plan_versiones (plan_id) where estado = 'borrador';
create unique index plan_una_aprobada on plan_versiones (plan_id) where estado = 'aprobada';

-- ---------------------------------------------------------------- documentos

-- Plantillas de documentos. `firma`: lectura (confirma que lo ha leído), aceptacion (acepta con su nombre),
-- firma (firma dibujada). `automatico`: se manda solo al vender un bono, al crear un programa o con la primera cita.
-- No se manda nada hasta que el propietario marca el texto como revisado; cambiarlo lo vuelve a dejar sin revisar.
create table documento_plantillas (
  id           bigint generated always as identity primary key,
  clinica_id   uuid not null references clinicas (id) on delete cascade,
  nombre       text not null check (length(trim(nombre)) between 2 and 120),
  tipo         text not null check (tipo in ('privacidad', 'contrato_programa', 'condiciones_bono', 'autorizacion', 'otro')),
  texto        text not null check (length(texto) between 20 and 30000),
  version      int not null default 1,
  firma        text not null check (firma in ('lectura', 'aceptacion', 'firma')),
  automatico   text check (automatico in ('venta_bono', 'crear_programa', 'primera_cita')),
  sanitario    boolean not null default false,
  activa       boolean not null default true,
  revisada     boolean not null default false,
  revisada_por text,
  revisada_en  timestamptz,
  validez_dias int not null default 30 check (validez_dias between 1 and 365),
  orden        int not null default 0,
  unique (clinica_id, id),
  unique (clinica_id, nombre)
);

create table documentos (
  id                bigint generated always as identity primary key,
  clinica_id        uuid not null references clinicas (id) on delete cascade,
  paciente_id       bigint not null,
  plantilla_id      bigint,
  version_plantilla int,
  nombre            text not null,
  tipo              text not null,
  texto             text,                             -- copia de lo que se envió (null en papel sin texto)
  texto_huella      bytea,
  firma             text not null check (firma in ('lectura', 'aceptacion', 'firma', 'papel')),
  sanitario         boolean not null default false,
  estado            text not null default 'pendiente' check (estado in ('pendiente', 'leido', 'aceptado', 'firmado',
                      'rechazado', 'anulado', 'caducado', 'revocado')),
  archivo_id        bigint,
  bono_id           bigint,
  programa_id       bigint,
  contexto          text,                             -- envíos automáticos: el mismo contexto no se manda dos veces
  enviado_en        timestamptz,
  enviado_por       uuid,
  caduca_en         timestamptz,
  visto_en          timestamptz,
  recordado_en      timestamptz,
  respondido_en     timestamptz,
  firmante_nombre   text,
  firma_trazos      jsonb,                            -- firma dibujada como trazos (vector), nunca como imagen
  evidencias        jsonb,
  motivo_rechazo    text,
  anulado_en        timestamptz,
  motivo_anulacion  text,
  revocado_en       timestamptz,
  motivo_revocacion text,
  creado_por        uuid,
  creado_en         timestamptz not null default now(),
  unique (clinica_id, id),
  unique (clinica_id, contexto),
  foreign key (clinica_id, paciente_id) references pacientes (clinica_id, id) on delete cascade,
  foreign key (clinica_id, plantilla_id) references documento_plantillas (clinica_id, id) on delete set null (plantilla_id),
  foreign key (clinica_id, archivo_id) references archivos (clinica_id, id),
  foreign key (clinica_id, bono_id) references bonos (clinica_id, id) on delete set null (bono_id),
  foreign key (clinica_id, programa_id) references programas (clinica_id, id) on delete set null (programa_id)
);
create index documentos_paciente on documentos (paciente_id, creado_en desc);
create index documentos_pendientes on documentos (clinica_id, estado);

-- Enlaces del paciente a un documento o a su plan. Solo se guarda la huella del token. Un enlace nuevo anula el
-- anterior del mismo documento o plan.
create table enlaces (
  id                bigint generated always as identity primary key,
  clinica_id        uuid not null references clinicas (id) on delete cascade,
  paciente_id       bigint not null,
  tipo              text not null check (tipo in ('documento', 'plan')),
  documento_id      bigint,
  plan_id           bigint,
  token_hash        bytea not null unique,
  caduca_en         timestamptz not null,
  intentos_fallidos int not null default 0,
  bloqueado_hasta   timestamptz,
  anulado_en        timestamptz,
  abierto_en        timestamptz,
  creado_en         timestamptz not null default now(),
  check ((tipo = 'documento') = (documento_id is not null) and (tipo = 'plan') = (plan_id is not null)),
  foreign key (clinica_id, paciente_id) references pacientes (clinica_id, id) on delete cascade,
  foreign key (clinica_id, documento_id) references documentos (clinica_id, id) on delete cascade,
  foreign key (clinica_id, plan_id) references planes (clinica_id, id) on delete cascade
);
create index enlaces_documento on enlaces (documento_id) where anulado_en is null;
create index enlaces_plan on enlaces (plan_id) where anulado_en is null;

-- ---------------------------------------------------------------- objetivos

create table objetivos_medicion (
  id                bigint generated always as identity primary key,
  clinica_id        uuid not null references clinicas (id) on delete cascade,
  paciente_id       bigint not null,
  tipo              text not null,
  nombre            text not null,
  valor             numeric(8, 2) not null,
  unidad            text,
  fecha_objetivo    date,
  nota              text,
  creado_por        uuid,
  creado_por_nombre text,
  creado_en         timestamptz not null default now(),
  retirado_en       timestamptz,
  foreign key (clinica_id, paciente_id) references pacientes (clinica_id, id) on delete cascade
);
create unique index objetivo_activo on objetivos_medicion (paciente_id, tipo, nombre) where retirado_en is null;

alter table archivos                 enable row level security;
alter table concesiones_portal       enable row level security;
alter table plantillas_recomendacion enable row level security;
alter table planes                   enable row level security;
alter table plan_versiones           enable row level security;
alter table documento_plantillas     enable row level security;
alter table documentos               enable row level security;
alter table enlaces                  enable row level security;
alter table objetivos_medicion       enable row level security;

-- ---------------------------------------------------------------- inmutabilidad

-- Una versión aprobada no cambia: ni texto, ni archivo, ni quién la aprobó, ni la fecha de entrega una vez puesta.
create function _plan_version_inmutable() returns trigger language plpgsql as $$
begin
  if tg_op = 'DELETE' then
    if old.estado <> 'borrador' then raise exception 'version_aprobada_inmutable' using errcode = '42501'; end if;
    return old;
  end if;
  if old.estado <> 'borrador' and (
       new.texto is distinct from old.texto or new.archivo_id is distinct from old.archivo_id
       or new.numero <> old.numero or new.plan_id <> old.plan_id
       or new.aprobada_por is distinct from old.aprobada_por or new.aprobada_en is distinct from old.aprobada_en
       or new.aprobada_por_nombre is distinct from old.aprobada_por_nombre or new.nota_cambios is distinct from old.nota_cambios
       or new.estado = 'borrador' or (old.estado = 'sustituida' and new.estado <> 'sustituida')) then
    raise exception 'version_aprobada_inmutable' using errcode = '42501';
  end if;
  if old.entregada_en is not null and (new.entregada_en is distinct from old.entregada_en
                                       or new.entrega_via is distinct from old.entrega_via) then
    raise exception 'version_aprobada_inmutable' using errcode = '42501';
  end if;
  return new;
end;
$$;
create trigger plan_version_inmutable before update or delete on plan_versiones
for each row execute function _plan_version_inmutable();

-- El texto de un documento no cambia nunca después de crearse, y lo que respondió el paciente tampoco.
create function _documento_inmutable() returns trigger language plpgsql as $$
begin
  if tg_op = 'DELETE' then
    if old.estado not in ('pendiente', 'anulado', 'caducado') then
      raise exception 'documento_inmutable' using errcode = '42501';
    end if;
    return old;
  end if;
  if new.texto is distinct from old.texto or new.texto_huella is distinct from old.texto_huella
     or new.firma <> old.firma or new.paciente_id <> old.paciente_id then
    raise exception 'documento_inmutable' using errcode = '42501';
  end if;
  if old.respondido_en is not null and (
       new.respondido_en is distinct from old.respondido_en or new.firmante_nombre is distinct from old.firmante_nombre
       or new.firma_trazos is distinct from old.firma_trazos or new.evidencias is distinct from old.evidencias
       or new.motivo_rechazo is distinct from old.motivo_rechazo or new.archivo_id is distinct from old.archivo_id) then
    raise exception 'documento_inmutable' using errcode = '42501';
  end if;
  if old.estado <> new.estado and not (
       (old.estado = 'pendiente' and new.estado in ('leido', 'aceptado', 'firmado', 'rechazado', 'anulado', 'caducado'))
       or (old.estado = 'caducado' and new.estado in ('pendiente', 'anulado'))
       or (old.estado in ('aceptado', 'firmado') and new.estado = 'revocado')) then
    raise exception 'documento_inmutable' using errcode = '42501';
  end if;
  return new;
end;
$$;
create trigger documento_inmutable before update or delete on documentos
for each row execute function _documento_inmutable();

-- =====================================================================
-- Almacenamiento: bucket privado y políticas
-- =====================================================================

insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('nutricion', 'nutricion', false, 10485760,
        array['application/pdf', 'image/jpeg', 'image/png', 'image/webp',
              'application/vnd.openxmlformats-officedocument.wordprocessingml.document'])
on conflict (id) do update set public = false, file_size_limit = excluded.file_size_limit,
                               allowed_mime_types = excluded.allowed_mime_types;

-- Las comprobaciones de las políticas viven fuera del esquema de la API (no se pueden llamar por PostgREST).
create schema if not exists nutricion_storage;

-- Subir: solo el archivo que el propio usuario preparó hace menos de 30 minutos, y si sigue en la consulta.
create function nutricion_storage.puede_subir(p_ruta text) returns boolean
language sql stable security definer set search_path = nutricion, extensions, pg_temp as $$
  select exists (select 1 from archivos a join miembros m on m.clinica_id = a.clinica_id and m.user_id = auth.uid() and m.activo
                 where a.ruta = p_ruta and a.estado = 'pendiente' and a.subido_por = auth.uid()
                   and a.creado_en > now() - interval '30 minutes')
$$;

-- Leer (pedir un enlace firmado): miembros de la consulta, y si es sanitario solo propietario y nutricionistas; el
-- que lo está subiendo; quien acaba de borrarlo (para poder quitarlo del bucket); o el portal con una concesión vigente.
create function nutricion_storage.puede_leer(p_ruta text) returns boolean
language sql stable security definer set search_path = nutricion, extensions, pg_temp as $$
  select exists (select 1 from archivos a join miembros m on m.clinica_id = a.clinica_id and m.user_id = auth.uid() and m.activo
                 where a.ruta = p_ruta and (
                   (a.estado = 'listo' and (not a.sanitario or _puede_salud(m.rol)))
                   or (a.estado = 'pendiente' and a.subido_por = auth.uid())
                   or (a.estado = 'eliminado' and a.eliminado_por = auth.uid() and a.eliminado_en > now() - interval '30 minutes')))
      or exists (select 1 from concesiones_portal c join archivos a on a.ruta = c.ruta
                 where c.ruta = p_ruta and c.expira_en > now() and a.estado = 'listo')
$$;

create function nutricion_storage.puede_borrar(p_ruta text) returns boolean
language sql stable security definer set search_path = nutricion, extensions, pg_temp as $$
  select exists (select 1 from archivos a join miembros m on m.clinica_id = a.clinica_id and m.user_id = auth.uid() and m.activo
                 where a.ruta = p_ruta and (
                   (a.estado = 'eliminado' and a.eliminado_por = auth.uid())
                   or (a.estado = 'pendiente' and a.subido_por = auth.uid())))
$$;

revoke all on schema nutricion_storage from public;
grant usage on schema nutricion_storage to anon, authenticated;
revoke all on all functions in schema nutricion_storage from public;
grant execute on all functions in schema nutricion_storage to anon, authenticated;

drop policy if exists nutricion_subir on storage.objects;
drop policy if exists nutricion_leer on storage.objects;
drop policy if exists nutricion_borrar on storage.objects;
create policy nutricion_subir on storage.objects for insert to authenticated
  with check (bucket_id = 'nutricion' and nutricion_storage.puede_subir(name));
create policy nutricion_leer on storage.objects for select to anon, authenticated
  using (bucket_id = 'nutricion' and nutricion_storage.puede_leer(name));
create policy nutricion_borrar on storage.objects for delete to authenticated
  using (bucket_id = 'nutricion' and nutricion_storage.puede_borrar(name));

