create function _plantillas_fase4(p_clinica uuid) returns void
language sql security definer set search_path = nutricion, extensions, pg_temp as $$
  insert into plantillas_mensaje (clinica_id, clave, texto) values
    (p_clinica, 'plan_entregado', 'Hola {paciente}, {profesional} te ha preparado tu plan "{texto}". Puedes verlo aquí: {enlace} . Te pedirá {comprobacion} para comprobar que eres tú.'),
    (p_clinica, 'documento_pendiente', 'Hola {paciente}, {clinica} te envía "{texto}" para que lo leas{tipo}: {enlace} . Te pedirá {comprobacion} para comprobar que eres tú.'),
    (p_clinica, 'documento_recordatorio', 'Hola {paciente}, tienes pendiente leer{tipo} "{texto}". Aquí lo tienes: {enlace} . Te pedirá {comprobacion}.')
  on conflict do nothing;
  insert into plantillas_recomendacion (clinica_id, titulo, texto, orden) values
    (p_clinica, 'Hidratación', 'Ten agua a mano durante el día y bebe sobre todo agua. [Texto de ejemplo: adáptalo a tu forma de trabajar.]', 1),
    (p_clinica, 'Organización de la compra', 'Planifica los menús de la semana antes de ir a comprar y haz la lista a partir de ellos. [Texto de ejemplo.]', 2),
    (p_clinica, 'Comer fuera de casa', 'Cuando comas fuera, elige platos con verdura y una ración de proteína, y deja el pan y el postre para ocasiones puntuales. [Texto de ejemplo.]', 3)
  on conflict do nothing;
  insert into documento_plantillas (clinica_id, nombre, tipo, firma, automatico, sanitario, orden, texto) values
    (p_clinica, 'Información sobre protección de datos', 'privacidad', 'lectura', null, false, 1,
'[TEXTO DE EJEMPLO. No lo uses sin que lo revise tu asesor de protección de datos.]

Responsable del tratamiento: {clinica}.
Finalidad: prestarte el servicio de consulta de nutrición que solicitas, gestionar tus citas y comunicarnos contigo sobre ellas.
Base jurídica: la prestación del servicio sanitario que nos pides y las obligaciones legales de conservación de la historia clínica.
Destinatarios: no cedemos tus datos salvo obligación legal. Nuestros proveedores tecnológicos tratan los datos por encargo nuestro.
Conservación: durante el tiempo que exige la normativa sanitaria.
Derechos: puedes pedir acceso, rectificación, supresión, oposición, limitación y portabilidad escribiendo a {clinica}, y reclamar ante la Agencia Española de Protección de Datos.

Las comunicaciones comerciales son aparte: solo las recibirás si las aceptas expresamente, y puedes retirarlas cuando quieras.'),
    (p_clinica, 'Condiciones del bono', 'condiciones_bono', 'aceptacion', 'venta_bono', false, 2,
'[TEXTO DE EJEMPLO. Revísalo antes de usarlo.]

{paciente}, has contratado el bono "{bono}" en {clinica} el {fecha}.
Sesiones incluidas: {sesiones}. Precio: {precio}. Válido hasta: {caduca}.

Condiciones:
{condiciones}'),
    (p_clinica, 'Condiciones del programa', 'contrato_programa', 'aceptacion', 'crear_programa', false, 3,
'[TEXTO DE EJEMPLO. Revísalo antes de usarlo.]

{paciente}, empiezas el programa "{programa}" en {clinica} con {profesional}, el {fecha}.

Condiciones del programa y de cancelación:
{condiciones}'),
    (p_clinica, 'Autorización para compartir información con otro profesional', 'autorizacion', 'firma', null, true, 4,
'[TEXTO DE EJEMPLO. Revísalo con tu asesor antes de usarlo.]

Yo, {paciente}, autorizo a {clinica} a compartir la información de mi seguimiento nutricional con el profesional sanitario que le indique, solo para coordinar mi atención. Puedo retirar esta autorización cuando quiera.')
  on conflict do nothing;
  insert into formularios (clinica_id, nombre, descripcion, envio, dias_antes, campos) values (p_clinica, 'Antes de tu revisión',
    'Unas preguntas para preparar la revisión. Lo que no sepas, déjalo en blanco y lo vemos en consulta.', 'antes_de_cada_cita', 3,
    '[{"clave":"evolucion","etiqueta":"¿Cómo te has encontrado desde la última consulta?","tipo":"texto_largo","importante":true},
      {"clave":"dificultades","etiqueta":"¿Qué te ha costado más seguir?","tipo":"texto_largo"},
      {"clave":"cambios","etiqueta":"¿Qué cambios de hábitos has conseguido mantener?","tipo":"texto_largo"},
      {"clave":"preguntas","etiqueta":"¿Qué quieres preguntar en la consulta?","tipo":"texto_largo"},
      {"clave":"peso","etiqueta":"Tu peso de esta semana","tipo":"numero","min":20,"max":350,"unidad":"kg","ayuda":"Solo si te pesas en casa.","importante":true,"destino":"medicion:peso"},
      {"clave":"cintura","etiqueta":"Perímetro de cintura","tipo":"numero","min":30,"max":250,"unidad":"cm","ayuda":"Si te lo has medido.","destino":"medicion:cintura"}]'::jsonb)
  on conflict do nothing;
$$;

create function _clinica_nueva_fase4() returns trigger
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
begin
  perform _plantillas_fase4(new.id);
  return null;
end;
$$;
create trigger clinica_nueva_fase4 after insert on clinicas for each row execute function _clinica_nueva_fase4();
select _plantillas_fase4(id) from clinicas;

-- =====================================================================
-- Utilidades
-- =====================================================================

create function _nombre_miembro(p_clinica uuid) returns text
language sql stable security definer set search_path = nutricion, extensions, pg_temp as $$
  select coalesce((select nombre from miembros where clinica_id = p_clinica and user_id = auth.uid()), 'Equipo')
$$;

create function _comprobacion(p_paciente bigint) returns text
language sql stable security definer set search_path = nutricion, extensions, pg_temp as $$
  select case when fecha_nacimiento is not null then 'tu fecha de nacimiento' else 'los 4 últimos dígitos de tu móvil' end
  from pacientes where id = p_paciente
$$;

-- Crea un enlace nuevo para un documento o plan y anula los anteriores. Devuelve el token (solo existe aquí y en el
-- envío hasta que sale).
create function _nuevo_enlace(p_clinica uuid, p_paciente bigint, p_tipo text, p_id bigint, p_caduca timestamptz)
returns text language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare v_token text := _token();
begin
  update enlaces set anulado_en = now()
  where anulado_en is null and ((p_tipo = 'documento' and documento_id = p_id) or (p_tipo = 'plan' and plan_id = p_id));
  insert into enlaces (clinica_id, paciente_id, tipo, documento_id, plan_id, token_hash, caduca_en)
  values (p_clinica, p_paciente, p_tipo, case when p_tipo = 'documento' then p_id end, case when p_tipo = 'plan' then p_id end,
          _huella(v_token), p_caduca);
  return v_token;
end;
$$;

-- Datos de un archivo para la aplicación.
create function _archivo_json(p_id bigint) returns jsonb
language sql stable security definer set search_path = nutricion, extensions, pg_temp as $$
  select jsonb_build_object('id', a.id, 'nombre', a.nombre, 'mime', a.mime, 'tamano', a.tamano, 'categoria', a.categoria,
    'sanitario', a.sanitario, 'origen', a.origen, 'descripcion', a.descripcion, 'estado', a.estado,
    'creado', _local(a.creado_en, _tz(a.clinica_id)))
  from archivos a where a.id = p_id
$$;

-- Plan con sus versiones. El texto solo para quien ve datos de salud.
create function _plan_json(p_plan bigint, p_salud boolean) returns jsonb
language sql stable security definer set search_path = nutricion, extensions, pg_temp as $$
  select jsonb_build_object('id', p.id, 'titulo', p.titulo, 'descripcion', case when p_salud then p.descripcion end,
    'estado', p.estado, 'origen', p.origen, 'herramienta', p.herramienta, 'referencia_externa', p.referencia_externa,
    'profesional_id', p.profesional_id, 'profesional', pr.nombre, 'creado', _local(p.creado_en, cl.zona_horaria),
    'vigente', (select v.numero from plan_versiones v where v.plan_id = p.id and v.entregada_en is not null
                order by v.numero desc limit 1),
    'por_entregar', exists (select 1 from plan_versiones v where v.plan_id = p.id and v.estado = 'aprobada'
                              and v.entregada_en is null) and p.estado = 'activo',
    'visto', (select _local(max(v.visto_en), cl.zona_horaria) from plan_versiones v where v.plan_id = p.id),
    'versiones', (select coalesce(jsonb_agg(jsonb_build_object('id', v.id, 'numero', v.numero, 'estado', v.estado,
        'texto', case when p_salud then v.texto end, 'tiene_texto', coalesce(length(trim(v.texto)), 0) > 0,
        'archivo', case when v.archivo_id is not null then _archivo_json(v.archivo_id) end,
        'nota_cambios', v.nota_cambios, 'aprobada_por', v.aprobada_por_nombre,
        'aprobada', _local(v.aprobada_en, cl.zona_horaria), 'entregada', _local(v.entregada_en, cl.zona_horaria),
        'entrega_via', v.entrega_via, 'entregada_por', v.entregada_por_nombre,
        'reenviada', _local(v.reenviada_en, cl.zona_horaria), 'visto', _local(v.visto_en, cl.zona_horaria),
        'actualizada', _local(v.actualizada_en, cl.zona_horaria)) order by v.numero desc), '[]'::jsonb)
      from plan_versiones v where v.plan_id = p.id))
  from planes p join clinicas cl on cl.id = p.clinica_id left join profesionales pr on pr.id = p.profesional_id
  where p.id = p_plan
$$;

create function _documento_json(p_doc bigint, p_completo boolean) returns jsonb
language sql stable security definer set search_path = nutricion, extensions, pg_temp as $$
  select jsonb_build_object('id', d.id, 'nombre', d.nombre, 'tipo', d.tipo, 'firma', d.firma, 'sanitario', d.sanitario,
    'estado', case when d.estado = 'pendiente' and d.caduca_en < now() then 'caducado' else d.estado end,
    'plantilla_id', d.plantilla_id, 'version_plantilla', d.version_plantilla, 'bono_id', d.bono_id, 'programa_id', d.programa_id,
    'automatico', d.contexto is not null,
    'enviado', _local(d.enviado_en, cl.zona_horaria), 'caduca', _local(d.caduca_en, cl.zona_horaria),
    'visto', _local(d.visto_en, cl.zona_horaria), 'recordado', _local(d.recordado_en, cl.zona_horaria),
    'respondido', _local(d.respondido_en, cl.zona_horaria), 'firmante', d.firmante_nombre,
    'motivo_rechazo', d.motivo_rechazo, 'anulado', _local(d.anulado_en, cl.zona_horaria), 'motivo_anulacion', d.motivo_anulacion,
    'revocado', _local(d.revocado_en, cl.zona_horaria), 'motivo_revocacion', d.motivo_revocacion,
    'archivo', case when d.archivo_id is not null then _archivo_json(d.archivo_id) end)
    || case when p_completo then jsonb_build_object('texto', d.texto, 'huella', encode(d.texto_huella, 'hex'),
                                   'trazos', d.firma_trazos, 'evidencias', d.evidencias) else '{}'::jsonb end
  from documentos d join clinicas cl on cl.id = d.clinica_id where d.id = p_doc
$$;

-- Variables de los textos de documentos: {paciente} (nombre completo) {clinica} {fecha} {profesional} {bono}
-- {sesiones} {precio} {caduca} {condiciones} {programa}
create function _vars_documento(p_paciente bigint, p_bono bigint default null, p_programa bigint default null) returns jsonb
language sql stable security definer set search_path = nutricion, extensions, pg_temp as $$
  select jsonb_build_object('paciente', trim(pa.nombre || ' ' || coalesce(pa.apellidos, '')), 'clinica', cl.nombre,
           'fecha', fecha_dia_es(_hoy(cl.zona_horaria)),
           'profesional', coalesce((select pr.nombre from programas p join profesionales pr on pr.id = p.profesional_id
                                    where p.id = p_programa),
                                   (select pr.nombre from profesionales pr where pr.id = pa.profesional_id), cl.nombre))
      || coalesce((select jsonb_build_object('bono', b.nombre, 'sesiones', b.sesiones_total,
           'precio', case when b.precio_centimos is null then 'según tarifa'
                          else replace(to_char(b.precio_centimos / 100.0, 'FM999G990D00'), '.', ',') || ' €' end,
           'caduca', coalesce(fecha_dia_es(b.caduca), 'sin caducidad'),
           'condiciones', coalesce(b.condiciones, 'Las generales de la consulta.')) from bonos b where b.id = p_bono), '{}'::jsonb)
      || coalesce((select jsonb_build_object('programa', p.nombre,
           'condiciones', coalesce(p.condiciones, 'Las generales de la consulta.')) from programas p where p.id = p_programa), '{}'::jsonb)
  from pacientes pa join clinicas cl on cl.id = pa.clinica_id where pa.id = p_paciente
$$;

-- Crea un documento a partir de una plantilla y manda el enlace. Devuelve el id, o null si el contexto ya se mandó.
create function _crear_documento(p_clinica uuid, p_paciente bigint, p_plantilla bigint, p_contexto text default null,
                                 p_bono bigint default null, p_programa bigint default null) returns bigint
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare t documento_plantillas; v_id bigint; v_texto text; v_token text; v_caduca timestamptz;
begin
  select * into t from documento_plantillas where id = p_plantilla and clinica_id = p_clinica;
  v_texto := _render(t.texto, _vars_documento(p_paciente, p_bono, p_programa));
  v_caduca := now() + make_interval(days => t.validez_dias);
  insert into documentos (clinica_id, paciente_id, plantilla_id, version_plantilla, nombre, tipo, texto, texto_huella, firma,
                          sanitario, bono_id, programa_id, contexto, enviado_en, enviado_por, caduca_en, creado_por)
  values (p_clinica, p_paciente, t.id, t.version, t.nombre, t.tipo, v_texto, _huella(v_texto), t.firma, t.sanitario,
          p_bono, p_programa, p_contexto, now(), auth.uid(), v_caduca, auth.uid())
  on conflict (clinica_id, contexto) do nothing
  returning id into v_id;
  if v_id is null then return null; end if;
  v_token := _nuevo_enlace(p_clinica, p_paciente, 'documento', v_id, v_caduca);
  perform _encolar(p_clinica, 'documento_pendiente', 'documento:' || v_id || ':' || encode(_huella(v_token), 'hex'),
                   p_paciente, null, _vars_mensaje_documento(v_id), null, v_token);
  perform _auditar(p_clinica, 'enviar_documento', 'documento', v_id::text, p_paciente,
                   jsonb_build_object('plantilla', t.id, 'automatico', p_contexto is not null));
  return v_id;
end;
$$;

create function _vars_mensaje_documento(p_doc bigint) returns jsonb
language sql stable security definer set search_path = nutricion, extensions, pg_temp as $$
  select jsonb_build_object('paciente', split_part(trim(pa.nombre), ' ', 1), 'clinica', cl.nombre, 'texto', d.nombre,
           'tipo', case d.firma when 'aceptacion' then ' y aceptarlo' when 'firma' then ' y firmarlo' else '' end,
           'comprobacion', _comprobacion(pa.id))
  from documentos d join pacientes pa on pa.id = d.paciente_id join clinicas cl on cl.id = d.clinica_id where d.id = p_doc
$$;

-- Manda de nuevo el enlace de un documento pendiente (o caducado, que vuelve a quedar pendiente). Anula el anterior.
create function _reenviar_documento(p_doc bigint, p_tipo text default 'documento_pendiente') returns boolean
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare d documentos; t documento_plantillas; v_token text; v_caduca timestamptz;
begin
  select * into d from documentos where id = p_doc for update;
  if d.estado not in ('pendiente', 'caducado') then return false; end if;
  select * into t from documento_plantillas where id = d.plantilla_id;
  v_caduca := greatest(d.caduca_en, now() + make_interval(days => coalesce(t.validez_dias, 30)));
  if p_tipo = 'documento_recordatorio' then v_caduca := d.caduca_en; end if;
  update documentos set estado = 'pendiente', caduca_en = v_caduca, recordado_en = now() where id = d.id;
  v_token := _nuevo_enlace(d.clinica_id, d.paciente_id, 'documento', d.id, v_caduca);
  update envios set estado = 'cancelado', secreto = null
  where clinica_id = d.clinica_id and estado = 'pendiente' and clave_idempotencia like 'documento:' || d.id || ':%';
  perform _encolar(d.clinica_id, p_tipo, 'documento:' || d.id || ':' || encode(_huella(v_token), 'hex'),
                   d.paciente_id, null, _vars_mensaje_documento(d.id), null, v_token);
  return true;
end;
$$;

-- Entrega por enlace de la versión aprobada de un plan (o reenvío del enlace). Anula los enlaces anteriores.
create function _mandar_plan(p_plan bigint, p_reenvio boolean) returns void
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare p planes; v_token text; v_vars jsonb;
begin
  select * into p from planes where id = p_plan;
  v_token := _nuevo_enlace(p.clinica_id, p.paciente_id, 'plan', p.id, now() + interval '180 days');
  v_vars := jsonb_build_object('paciente', (select split_part(trim(nombre), ' ', 1) from pacientes where id = p.paciente_id),
    'clinica', (select nombre from clinicas where id = p.clinica_id), 'texto', p.titulo,
    'profesional', coalesce((select pr.nombre from profesionales pr where pr.id = p.profesional_id),
                            (select aprobada_por_nombre from plan_versiones where plan_id = p.id and estado = 'aprobada'), 'Tu nutricionista'),
    'comprobacion', _comprobacion(p.paciente_id));
  perform _encolar(p.clinica_id, 'plan_entregado', 'plan:' || p.id || ':' || encode(_huella(v_token), 'hex'),
                   p.paciente_id, null, v_vars, null, v_token);
end;
$$;

-- =====================================================================
-- API: archivos
-- =====================================================================

-- Paso 1 de una subida. d: {paciente_id, nombre, mime, tamano, categoria, sanitario?, descripcion?}
-- Devuelve la ruta en el bucket; la aplicación sube el archivo ahí y luego llama a confirmar_subida.
create function preparar_subida(p_clinica uuid, d jsonb) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare m miembros := _miembro(p_clinica); v_cat text := coalesce(d->>'categoria', 'otro'); v_san boolean; v_id bigint;
        v_ruta text := p_clinica || '/' || gen_random_uuid(); v_tam bigint;
begin
  if not exists (select 1 from pacientes where id = (d->>'paciente_id')::bigint and clinica_id = p_clinica) then
    return jsonb_build_object('ok', false, 'motivo', 'paciente_no_existe');
  end if;
  if v_cat not in ('plan', 'documento', 'analitica', 'informe', 'otro') then
    return jsonb_build_object('ok', false, 'motivo', 'valor_no_valido');
  end if;
  if coalesce(d->>'mime', '') not in (select unnest(allowed_mime_types) from storage.buckets where id = 'nutricion') then
    return jsonb_build_object('ok', false, 'motivo', 'tipo_archivo_no_permitido');
  end if;
  begin v_tam := (d->>'tamano')::bigint; exception when others then v_tam := null; end;
  if v_tam is null or v_tam < 1 then return jsonb_build_object('ok', false, 'motivo', 'valor_no_valido'); end if;
  if v_tam > 10485760 then return jsonb_build_object('ok', false, 'motivo', 'archivo_demasiado_grande'); end if;
  if nullif(trim(coalesce(d->>'nombre', '')), '') is null then return jsonb_build_object('ok', false, 'motivo', 'falta_nombre'); end if;
  -- Planes, analíticas e informes son siempre sanitarios. Un documento administrativo no, salvo que se diga.
  v_san := case when v_cat in ('plan', 'analitica', 'informe') then true
                else coalesce((d->>'sanitario')::boolean, v_cat <> 'documento') end;
  if v_san and not _puede_salud(m.rol) then return jsonb_build_object('ok', false, 'motivo', 'solo_profesional'); end if;
  insert into archivos (clinica_id, paciente_id, ruta, nombre, mime, tamano, categoria, sanitario, descripcion, subido_por)
  values (p_clinica, (d->>'paciente_id')::bigint, v_ruta, left(trim(d->>'nombre'), 200), d->>'mime', v_tam, v_cat, v_san,
          left(nullif(trim(d->>'descripcion'), ''), 500), auth.uid())
  returning id into v_id;
  return jsonb_build_object('ok', true, 'id', v_id, 'bucket', 'nutricion', 'ruta', v_ruta);
end;
$$;

-- Paso 2: comprueba que el archivo está en el bucket, con el tipo y tamaño permitidos.
create function confirmar_subida(p_clinica uuid, p_id bigint) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare a archivos; o record;
begin
  perform _miembro(p_clinica);
  select * into a from archivos where id = p_id and clinica_id = p_clinica for update;
  if a.id is null then return jsonb_build_object('ok', false, 'motivo', 'archivo_no_existe'); end if;
  if a.estado = 'listo' then return jsonb_build_object('ok', true, 'repetida', true, 'archivo', _archivo_json(a.id)); end if;
  if a.estado <> 'pendiente' or a.subido_por is distinct from auth.uid() then
    return jsonb_build_object('ok', false, 'motivo', 'archivo_no_existe');
  end if;
  select (metadata->>'size')::bigint tam, metadata->>'mimetype' mime into o
  from storage.objects where bucket_id = 'nutricion' and name = a.ruta;
  if not found then return jsonb_build_object('ok', false, 'motivo', 'archivo_no_subido'); end if;
  if o.tam is null or o.tam > 10485760 or o.mime is distinct from a.mime then
    return jsonb_build_object('ok', false, 'motivo', 'archivo_no_valido');
  end if;
  update archivos set estado = 'listo', listo_en = now(), tamano = o.tam where id = a.id;
  perform _auditar(p_clinica, 'subir_archivo', 'archivo', a.id::text, a.paciente_id,
                   jsonb_build_object('categoria', a.categoria, 'sanitario', a.sanitario));
  return jsonb_build_object('ok', true, 'archivo', _archivo_json(a.id));
end;
$$;

-- Para abrir un archivo: comprueba el permiso, lo registra y devuelve la ruta. La aplicación pide entonces un enlace
-- firmado de un minuto (que el bucket solo da si las políticas lo permiten).
create function abrir_archivo(p_clinica uuid, p_id bigint) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare m miembros := _miembro(p_clinica); a archivos;
begin
  select * into a from archivos where id = p_id and clinica_id = p_clinica and estado = 'listo';
  if a.id is null then return jsonb_build_object('ok', false, 'motivo', 'archivo_no_existe'); end if;
  if a.sanitario and not _puede_salud(m.rol) then return jsonb_build_object('ok', false, 'motivo', 'solo_profesional'); end if;
  perform _auditar(p_clinica, 'ver_archivo', 'archivo', a.id::text, a.paciente_id);
  return jsonb_build_object('ok', true, 'bucket', 'nutricion', 'ruta', a.ruta, 'nombre', a.nombre, 'mime', a.mime);
end;
$$;

-- Quitar un archivo subido por error. No se puede si es el de un plan aprobado o el de un documento respondido.
-- Devuelve la ruta para que la aplicación lo borre del bucket.
create function eliminar_archivo(p_clinica uuid, p_id bigint, p_motivo text) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare m miembros := _miembro(p_clinica); a archivos;
begin
  select * into a from archivos where id = p_id and clinica_id = p_clinica for update;
  if a.id is null or a.estado = 'eliminado' then return jsonb_build_object('ok', false, 'motivo', 'archivo_no_existe'); end if;
  if not _puede_salud(m.rol) and (a.sanitario or a.subido_por is distinct from auth.uid()) then
    return jsonb_build_object('ok', false, 'motivo', 'solo_profesional');
  end if;
  if nullif(trim(coalesce(p_motivo, '')), '') is null then return jsonb_build_object('ok', false, 'motivo', 'falta_motivo'); end if;
  if exists (select 1 from plan_versiones where archivo_id = a.id and estado <> 'borrador')
     or exists (select 1 from documentos where archivo_id = a.id and estado not in ('pendiente', 'anulado', 'caducado')) then
    return jsonb_build_object('ok', false, 'motivo', 'archivo_en_uso');
  end if;
  update plan_versiones set archivo_id = null, actualizada_en = now() where archivo_id = a.id and estado = 'borrador';
  update archivos set estado = 'eliminado', eliminado_en = now(), eliminado_por = auth.uid(),
                      motivo_eliminacion = left(trim(p_motivo), 300)
  where id = a.id;
  perform _auditar(p_clinica, 'eliminar_archivo', 'archivo', a.id::text, a.paciente_id);
  return jsonb_build_object('ok', true, 'bucket', 'nutricion', 'ruta', a.ruta);
end;
$$;

create function archivos_paciente(p_clinica uuid, p_paciente bigint) returns jsonb
language plpgsql stable security definer set search_path = nutricion, extensions, pg_temp as $$
declare m miembros := _miembro(p_clinica);
begin
  return (select coalesce(jsonb_agg(_archivo_json(a.id) || jsonb_build_object('en_uso',
              exists (select 1 from plan_versiones v where v.archivo_id = a.id)
              or exists (select 1 from documentos d where d.archivo_id = a.id)) order by a.creado_en desc), '[]'::jsonb)
    from archivos a where a.paciente_id = p_paciente and a.clinica_id = p_clinica and a.estado = 'listo'
      and (not a.sanitario or _puede_salud(m.rol)));
end;
$$;

-- =====================================================================
-- API: planes
-- =====================================================================

create function lista_plantillas_recomendacion(p_clinica uuid) returns jsonb
language plpgsql stable security definer set search_path = nutricion, extensions, pg_temp as $$
begin
  perform _miembro(p_clinica, array['propietario', 'nutricionista']);
  return (select coalesce(jsonb_agg(jsonb_build_object('id', id, 'titulo', titulo, 'texto', texto, 'activa', activa,
            'orden', orden) order by orden, titulo), '[]'::jsonb)
    from plantillas_recomendacion where clinica_id = p_clinica);
end;
$$;

-- d: {id?, titulo, texto, activa?, orden?}
create function guardar_plantilla_recomendacion(p_clinica uuid, d jsonb) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare v_id bigint := (d->>'id')::bigint;
begin
  perform _miembro(p_clinica, array['propietario', 'nutricionista']);
  begin
    if v_id is null then
      insert into plantillas_recomendacion (clinica_id, titulo, texto, activa, orden)
      values (p_clinica, trim(d->>'titulo'), trim(d->>'texto'), coalesce((d->>'activa')::boolean, true),
              coalesce((d->>'orden')::int, 0))
      returning id into v_id;
    else
      update plantillas_recomendacion set titulo = coalesce(nullif(trim(d->>'titulo'), ''), titulo),
        texto = coalesce(nullif(trim(d->>'texto'), ''), texto), activa = coalesce((d->>'activa')::boolean, activa),
        orden = coalesce((d->>'orden')::int, orden)
      where id = v_id and clinica_id = p_clinica;
      if not found then return jsonb_build_object('ok', false, 'motivo', 'plantilla_no_existe'); end if;
    end if;
  exception
    when unique_violation then return jsonb_build_object('ok', false, 'motivo', 'nombre_repetido');
    when check_violation or not_null_violation then return jsonb_build_object('ok', false, 'motivo', 'valor_no_valido');
  end;
  perform _auditar(p_clinica, 'guardar_recomendacion', 'plantilla_recomendacion', v_id::text);
  return jsonb_build_object('ok', true, 'id', v_id);
end;
$$;

-- Texto de las recomendaciones elegidas, en el orden en que se eligieron.
create function _texto_recomendaciones(p_clinica uuid, p_ids jsonb) returns text
language sql stable security definer set search_path = nutricion, extensions, pg_temp as $$
  select string_agg(r.titulo || E'\n' || r.texto, E'\n\n' order by x.n)
  from jsonb_array_elements_text(coalesce(p_ids, '[]'::jsonb)) with ordinality x(id, n)
  join plantillas_recomendacion r on r.id = x.id::bigint and r.clinica_id = p_clinica and r.activa
$$;

-- d: {paciente_id, titulo, descripcion?, profesional_id?, origen? ('corvex'|'externo'), herramienta?,
--     referencia_externa?, texto?, recomendaciones?: [id], archivo_id?}. Crea el plan y su versión 1 en borrador.
create function crear_plan(p_clinica uuid, d jsonb) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare m miembros := _miembro(p_clinica, array['propietario', 'nutricionista']); v_pac bigint := (d->>'paciente_id')::bigint;
        v_id bigint; v_prof bigint; v_texto text;
begin
  if not exists (select 1 from pacientes where id = v_pac and clinica_id = p_clinica) then
    return jsonb_build_object('ok', false, 'motivo', 'paciente_no_existe');
  end if;
  if nullif(trim(coalesce(d->>'titulo', '')), '') is null then return jsonb_build_object('ok', false, 'motivo', 'falta_titulo'); end if;
  if d->>'archivo_id' is not null and not exists (select 1 from archivos where id = (d->>'archivo_id')::bigint
       and paciente_id = v_pac and estado = 'listo') then
    return jsonb_build_object('ok', false, 'motivo', 'archivo_no_existe');
  end if;
  v_prof := coalesce(nullif(d->>'profesional_id', '')::bigint, m.profesional_id,
                     (select profesional_id from pacientes where id = v_pac));
  if v_prof is not null and not exists (select 1 from profesionales where id = v_prof and clinica_id = p_clinica) then
    return jsonb_build_object('ok', false, 'motivo', 'profesional_no_existe');
  end if;
  v_texto := nullif(concat_ws(E'\n\n', nullif(trim(coalesce(d->>'texto', '')), ''),
                              _texto_recomendaciones(p_clinica, d->'recomendaciones')), '');
  begin
    insert into planes (clinica_id, paciente_id, profesional_id, titulo, descripcion, origen, herramienta, referencia_externa,
                        creado_por)
    values (p_clinica, v_pac, v_prof, trim(d->>'titulo'), left(nullif(trim(d->>'descripcion'), ''), 1000),
            coalesce(nullif(d->>'origen', ''), 'corvex'), left(nullif(trim(d->>'herramienta'), ''), 80),
            left(nullif(trim(d->>'referencia_externa'), ''), 200), auth.uid())
    returning id into v_id;
    insert into plan_versiones (clinica_id, plan_id, numero, texto, archivo_id, creada_por)
    values (p_clinica, v_id, 1, v_texto, nullif(d->>'archivo_id', '')::bigint, auth.uid());
  exception when check_violation then
    return jsonb_build_object('ok', false, 'motivo', 'valor_no_valido');
  end;
  perform _auditar(p_clinica, 'crear_plan', 'plan', v_id::text, v_pac);
  return jsonb_build_object('ok', true, 'plan', _plan_json(v_id, true));
end;
$$;

create function planes_paciente(p_clinica uuid, p_paciente bigint) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare m miembros := _miembro(p_clinica);
begin
  if _puede_salud(m.rol) and exists (select 1 from planes where paciente_id = p_paciente and clinica_id = p_clinica) then
    perform _auditar(p_clinica, 'ver_planes', 'paciente', p_paciente::text, p_paciente);
  end if;
  return (select coalesce(jsonb_agg(_plan_json(p.id, _puede_salud(m.rol)) order by p.estado, p.creado_en desc), '[]'::jsonb)
    from planes p where p.paciente_id = p_paciente and p.clinica_id = p_clinica);
end;
$$;

-- d: {texto?, archivo_id? (0 = quitar), nota_cambios?, anadir_recomendaciones?: [id]}. Solo en borrador.
create function guardar_version_plan(p_clinica uuid, p_version bigint, d jsonb) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare v plan_versiones; p planes; v_texto text; v_archivo bigint;
begin
  perform _miembro(p_clinica, array['propietario', 'nutricionista']);
  select * into v from plan_versiones where id = p_version and clinica_id = p_clinica for update;
  if v.id is null then return jsonb_build_object('ok', false, 'motivo', 'plan_no_existe'); end if;
  if v.estado <> 'borrador' then return jsonb_build_object('ok', false, 'motivo', 'version_aprobada_inmutable'); end if;
  select * into p from planes where id = v.plan_id;
  v_texto := case when d ? 'texto' then nullif(trim(d->>'texto'), '') else v.texto end;
  if d ? 'anadir_recomendaciones' then
    v_texto := nullif(concat_ws(E'\n\n', v_texto, _texto_recomendaciones(p_clinica, d->'anadir_recomendaciones')), '');
  end if;
  v_archivo := case when not d ? 'archivo_id' then v.archivo_id when (d->>'archivo_id')::bigint = 0 then null
                    else (d->>'archivo_id')::bigint end;
  if v_archivo is not null and v_archivo is distinct from v.archivo_id and not exists (
       select 1 from archivos where id = v_archivo and paciente_id = p.paciente_id and estado = 'listo') then
    return jsonb_build_object('ok', false, 'motivo', 'archivo_no_existe');
  end if;
  begin
    update plan_versiones set texto = v_texto, archivo_id = v_archivo,
      nota_cambios = case when d ? 'nota_cambios' then left(nullif(trim(d->>'nota_cambios'), ''), 500) else nota_cambios end,
      actualizada_en = now()
    where id = v.id;
  exception when check_violation then return jsonb_build_object('ok', false, 'motivo', 'demasiado_largo');
  end;
  perform _auditar(p_clinica, 'guardar_plan', 'plan_version', v.id::text, p.paciente_id);
  return jsonb_build_object('ok', true, 'plan', _plan_json(p.id, true));
end;
$$;

-- Nueva versión a partir de la última (o la que ya está en borrador, si la hay).
create function nueva_version_plan(p_clinica uuid, p_plan bigint) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare p planes; u plan_versiones;
begin
  perform _miembro(p_clinica, array['propietario', 'nutricionista']);
  select * into p from planes where id = p_plan and clinica_id = p_clinica for update;
  if p.id is null then return jsonb_build_object('ok', false, 'motivo', 'plan_no_existe'); end if;
  if p.estado <> 'activo' then return jsonb_build_object('ok', false, 'motivo', 'plan_archivado'); end if;
  if exists (select 1 from plan_versiones where plan_id = p.id and estado = 'borrador') then
    return jsonb_build_object('ok', true, 'repetida', true, 'plan', _plan_json(p.id, true));
  end if;
  select * into u from plan_versiones where plan_id = p.id order by numero desc limit 1;
  insert into plan_versiones (clinica_id, plan_id, numero, texto, archivo_id, creada_por)
  values (p_clinica, p.id, u.numero + 1, u.texto, u.archivo_id, auth.uid());
  perform _auditar(p_clinica, 'nueva_version_plan', 'plan', p.id::text, p.paciente_id, jsonb_build_object('numero', u.numero + 1));
  return jsonb_build_object('ok', true, 'plan', _plan_json(p.id, true));
end;
$$;

-- Borrar un borrador que no se va a usar (si es la única versión, se borra el plan).
create function borrar_borrador_plan(p_clinica uuid, p_version bigint) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare v plan_versiones; p planes;
begin
  perform _miembro(p_clinica, array['propietario', 'nutricionista']);
  select * into v from plan_versiones where id = p_version and clinica_id = p_clinica for update;
  if v.id is null then return jsonb_build_object('ok', false, 'motivo', 'plan_no_existe'); end if;
  if v.estado <> 'borrador' then return jsonb_build_object('ok', false, 'motivo', 'version_aprobada_inmutable'); end if;
  select * into p from planes where id = v.plan_id;
  delete from plan_versiones where id = v.id;
  if not exists (select 1 from plan_versiones where plan_id = p.id) then delete from planes where id = p.id; end if;
  perform _auditar(p_clinica, 'borrar_borrador_plan', 'plan', p.id::text, p.paciente_id);
  return jsonb_build_object('ok', true);
end;
$$;

-- Ver una versión (con su texto completo). Queda registrado.
create function ver_plan(p_clinica uuid, p_plan bigint) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare p planes;
begin
  perform _miembro(p_clinica, array['propietario', 'nutricionista']);
  select * into p from planes where id = p_plan and clinica_id = p_clinica;
  if p.id is null then return jsonb_build_object('ok', false, 'motivo', 'plan_no_existe'); end if;
  perform _auditar(p_clinica, 'ver_plan', 'plan', p.id::text, p.paciente_id);
  return jsonb_build_object('ok', true, 'plan', _plan_json(p.id, true));
end;
$$;

-- El profesional aprueba el borrador: queda firmado con su nombre y hora y ya no cambia. La aprobada anterior pasa a
-- sustituida (el paciente sigue viendo la última entregada hasta que se le entregue la nueva).
create function aprobar_version_plan(p_clinica uuid, p_version bigint) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare v plan_versiones; p planes;
begin
  perform _miembro(p_clinica, array['propietario', 'nutricionista']);
  select * into v from plan_versiones where id = p_version and clinica_id = p_clinica for update;
  if v.id is null then return jsonb_build_object('ok', false, 'motivo', 'plan_no_existe'); end if;
  select * into p from planes where id = v.plan_id for update;
  if v.estado <> 'borrador' then
    return jsonb_build_object('ok', true, 'repetida', true, 'plan', _plan_json(p.id, true));
  end if;
  if p.estado <> 'activo' then return jsonb_build_object('ok', false, 'motivo', 'plan_archivado'); end if;
  if coalesce(length(trim(v.texto)), 0) = 0 and v.archivo_id is null then
    return jsonb_build_object('ok', false, 'motivo', 'plan_vacio');
  end if;
  update plan_versiones set estado = 'sustituida' where plan_id = p.id and estado = 'aprobada';
  update plan_versiones set estado = 'aprobada', aprobada_por = auth.uid(), aprobada_por_nombre = _nombre_miembro(p_clinica),
                            aprobada_en = now()
  where id = v.id;
  perform _auditar(p_clinica, 'aprobar_plan', 'plan_version', v.id::text, p.paciente_id, jsonb_build_object('numero', v.numero));
  return jsonb_build_object('ok', true, 'plan', _plan_json(p.id, true));
end;
$$;

-- Entrega la versión aprobada. p_via: 'enlace' (manda el enlace seguro), 'en_mano' u 'otro' (solo se apunta).
-- Con p_reenviar se vuelve a mandar el enlace de lo ya entregado (el anterior deja de valer).
create function entregar_plan(p_clinica uuid, p_plan bigint, p_via text default 'enlace', p_reenviar boolean default false)
returns jsonb language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare m miembros := _miembro(p_clinica); p planes; v plan_versiones;
begin
  select * into p from planes where id = p_plan and clinica_id = p_clinica for update;
  if p.id is null then return jsonb_build_object('ok', false, 'motivo', 'plan_no_existe'); end if;
  if p.estado <> 'activo' then return jsonb_build_object('ok', false, 'motivo', 'plan_archivado'); end if;
  if p_via not in ('enlace', 'en_mano', 'otro') then return jsonb_build_object('ok', false, 'motivo', 'valor_no_valido'); end if;
  if p_via <> 'enlace' and not _puede_salud(m.rol) then return jsonb_build_object('ok', false, 'motivo', 'solo_profesional'); end if;
  select * into v from plan_versiones where plan_id = p.id and estado = 'aprobada' for update;
  if v.id is null then return jsonb_build_object('ok', false, 'motivo', 'plan_sin_aprobar'); end if;
  if p_via = 'enlace' and not exists (select 1 from pacientes where id = p.paciente_id and (telefono is not null or email is not null)) then
    return jsonb_build_object('ok', false, 'motivo', 'falta_contacto');
  end if;
  if v.entregada_en is not null then
    if not p_reenviar then return jsonb_build_object('ok', true, 'repetida', true, 'plan', _plan_json(p.id, _puede_salud(m.rol))); end if;
    perform _mandar_plan(p.id, true);
    update plan_versiones set reenviada_en = now() where id = v.id;
    perform _auditar(p_clinica, 'reenviar_plan', 'plan_version', v.id::text, p.paciente_id);
    return jsonb_build_object('ok', true, 'plan', _plan_json(p.id, _puede_salud(m.rol)));
  end if;
  update plan_versiones set entregada_en = now(), entrega_via = p_via, entregada_por_nombre = _nombre_miembro(p_clinica)
  where id = v.id;
  if p_via = 'enlace' then perform _mandar_plan(p.id, false); end if;
  perform _auditar(p_clinica, 'entregar_plan', 'plan_version', v.id::text, p.paciente_id,
                   jsonb_build_object('via', p_via, 'numero', v.numero));
  return jsonb_build_object('ok', true, 'plan', _plan_json(p.id, _puede_salud(m.rol)));
end;
$$;

-- Archivar un plan que ya no está vigente: su enlace deja de funcionar. Se puede reactivar.
create function archivar_plan(p_clinica uuid, p_plan bigint, p_archivar boolean default true) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare p planes;
begin
  perform _miembro(p_clinica, array['propietario', 'nutricionista']);
  update planes set estado = case when p_archivar then 'archivado' else 'activo' end,
                    archivado_en = case when p_archivar then now() end
  where id = p_plan and clinica_id = p_clinica returning * into p;
  if p.id is null then return jsonb_build_object('ok', false, 'motivo', 'plan_no_existe'); end if;
  if p_archivar then update enlaces set anulado_en = now() where plan_id = p.id and anulado_en is null; end if;
  perform _auditar(p_clinica, case when p_archivar then 'archivar_plan' else 'reactivar_plan' end, 'plan', p.id::text, p.paciente_id);
  return jsonb_build_object('ok', true, 'plan', _plan_json(p.id, true));
end;
$$;

-- =====================================================================
-- API: documentos
-- =====================================================================

create function lista_documento_plantillas(p_clinica uuid) returns jsonb
language plpgsql stable security definer set search_path = nutricion, extensions, pg_temp as $$
declare m miembros := _miembro(p_clinica);
begin
  return (select coalesce(jsonb_agg(jsonb_build_object('id', id, 'nombre', nombre, 'tipo', tipo, 'texto', texto,
            'version', version, 'firma', firma, 'automatico', automatico, 'sanitario', sanitario, 'activa', activa,
            'revisada', revisada, 'revisada_por', revisada_por, 'revisada_en', _local(revisada_en, _tz(p_clinica)),
            'validez_dias', validez_dias, 'orden', orden) order by orden, nombre), '[]'::jsonb)
    from documento_plantillas where clinica_id = p_clinica and (not sanitario or _puede_salud(m.rol)));
end;
$$;

-- d: {id?, nombre, tipo, texto, firma, automatico?, sanitario?, activa?, validez_dias?, orden?, revisada?}
-- Solo el propietario. Cambiar el texto sube la versión y lo deja sin revisar; lo ya enviado no cambia.
create function guardar_documento_plantilla(p_clinica uuid, d jsonb) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare v_id bigint := (d->>'id')::bigint; t documento_plantillas; v_desconocidas text[]; v_nuevo_texto boolean;
begin
  perform _miembro(p_clinica, array['propietario']);
  select array_agg(distinct x[1]) into v_desconocidas
  from regexp_matches(coalesce(d->>'texto', ''), '\{([a-z_]+)\}', 'g') x
  where x[1] not in ('paciente', 'clinica', 'fecha', 'profesional', 'bono', 'sesiones', 'precio', 'caduca', 'condiciones', 'programa');
  if v_desconocidas is not null then
    return jsonb_build_object('ok', false, 'motivo', 'variable_desconocida', 'variables', to_jsonb(v_desconocidas));
  end if;
  if d ? 'automatico' and nullif(d->>'automatico', '') is not null and d->>'automatico' not in ('venta_bono', 'crear_programa', 'primera_cita') then
    return jsonb_build_object('ok', false, 'motivo', 'valor_no_valido');
  end if;
  begin
    if v_id is null then
      insert into documento_plantillas (clinica_id, nombre, tipo, texto, firma, automatico, sanitario, activa, validez_dias, orden)
      values (p_clinica, trim(d->>'nombre'), d->>'tipo', trim(d->>'texto'), d->>'firma', nullif(d->>'automatico', ''),
              coalesce((d->>'sanitario')::boolean, false), coalesce((d->>'activa')::boolean, true),
              coalesce((d->>'validez_dias')::int, 30), coalesce((d->>'orden')::int, 0))
      returning id into v_id;
    else
      select * into t from documento_plantillas where id = v_id and clinica_id = p_clinica for update;
      if t.id is null then return jsonb_build_object('ok', false, 'motivo', 'plantilla_no_existe'); end if;
      v_nuevo_texto := d ? 'texto' and trim(d->>'texto') <> t.texto;
      update documento_plantillas set
        nombre = coalesce(nullif(trim(d->>'nombre'), ''), nombre), tipo = coalesce(d->>'tipo', tipo),
        texto = case when v_nuevo_texto then trim(d->>'texto') else texto end,
        version = version + case when v_nuevo_texto or (d ? 'firma' and d->>'firma' <> firma) then 1 else 0 end,
        firma = coalesce(d->>'firma', firma),
        automatico = case when d ? 'automatico' then nullif(d->>'automatico', '') else automatico end,
        sanitario = coalesce((d->>'sanitario')::boolean, sanitario), activa = coalesce((d->>'activa')::boolean, activa),
        validez_dias = coalesce((d->>'validez_dias')::int, validez_dias), orden = coalesce((d->>'orden')::int, orden),
        revisada = case when v_nuevo_texto then false else revisada end,
        revisada_por = case when v_nuevo_texto then null else revisada_por end,
        revisada_en = case when v_nuevo_texto then null else revisada_en end
      where id = v_id;
    end if;
    if coalesce((d->>'revisada')::boolean, false) then
      update documento_plantillas set revisada = true, revisada_por = _nombre_miembro(p_clinica), revisada_en = now()
      where id = v_id;
    elsif d ? 'revisada' then
      update documento_plantillas set revisada = false, revisada_por = null, revisada_en = null where id = v_id;
    end if;
  exception
    when unique_violation then return jsonb_build_object('ok', false, 'motivo', 'nombre_repetido');
    when check_violation or not_null_violation or invalid_text_representation then
      return jsonb_build_object('ok', false, 'motivo', 'valor_no_valido');
  end;
  perform _auditar(p_clinica, 'guardar_documento_plantilla', 'documento_plantilla', v_id::text, null,
                   jsonb_build_object('revisada', (select revisada from documento_plantillas where id = v_id)));
  return jsonb_build_object('ok', true, 'id', v_id);
end;
$$;

-- d: {paciente_id, plantilla_id, bono_id?, programa_id?}. Si ya tiene ese mismo documento pendiente, no se duplica.
create function enviar_documento(p_clinica uuid, d jsonb) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare m miembros := _miembro(p_clinica); t documento_plantillas; v_pac bigint := (d->>'paciente_id')::bigint; v_id bigint;
begin
  if not exists (select 1 from pacientes where id = v_pac and clinica_id = p_clinica) then
    return jsonb_build_object('ok', false, 'motivo', 'paciente_no_existe');
  end if;
  select * into t from documento_plantillas where id = (d->>'plantilla_id')::bigint and clinica_id = p_clinica;
  if t.id is null or not t.activa then return jsonb_build_object('ok', false, 'motivo', 'plantilla_no_existe'); end if;
  if t.sanitario and not _puede_salud(m.rol) then return jsonb_build_object('ok', false, 'motivo', 'solo_profesional'); end if;
  if not t.revisada then return jsonb_build_object('ok', false, 'motivo', 'plantilla_sin_revisar'); end if;
  if not exists (select 1 from pacientes where id = v_pac and (telefono is not null or email is not null)) then
    return jsonb_build_object('ok', false, 'motivo', 'falta_contacto');
  end if;
  if d->>'bono_id' is not null and not exists (select 1 from bonos where id = (d->>'bono_id')::bigint and paciente_id = v_pac) then
    return jsonb_build_object('ok', false, 'motivo', 'bono_no_valido');
  end if;
  if d->>'programa_id' is not null and not exists (select 1 from programas where id = (d->>'programa_id')::bigint and paciente_id = v_pac) then
    return jsonb_build_object('ok', false, 'motivo', 'programa_no_existe');
  end if;
  perform pg_advisory_xact_lock(hashtext('documento:' || v_pac || ':' || t.id));
  select id into v_id from documentos where paciente_id = v_pac and plantilla_id = t.id and estado = 'pendiente'
    and caduca_en > now() and bono_id is not distinct from nullif(d->>'bono_id', '')::bigint
    and programa_id is not distinct from nullif(d->>'programa_id', '')::bigint;
  if v_id is not null then return jsonb_build_object('ok', true, 'repetida', true, 'documento', _documento_json(v_id, false)); end if;
  v_id := _crear_documento(p_clinica, v_pac, t.id, null, nullif(d->>'bono_id', '')::bigint, nullif(d->>'programa_id', '')::bigint);
  return jsonb_build_object('ok', true, 'documento', _documento_json(v_id, false));
end;
$$;

-- Documento firmado en papel. d: {paciente_id, plantilla_id? | nombre + tipo, archivo_id? (el escaneado), fecha?,
-- firmante?}
create function registrar_documento_papel(p_clinica uuid, d jsonb) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare m miembros := _miembro(p_clinica); t documento_plantillas; v_pac bigint := (d->>'paciente_id')::bigint; v_id bigint;
        v_fecha timestamptz; v_texto text; a archivos;
begin
  if not exists (select 1 from pacientes where id = v_pac and clinica_id = p_clinica) then
    return jsonb_build_object('ok', false, 'motivo', 'paciente_no_existe');
  end if;
  if d->>'plantilla_id' is not null then
    select * into t from documento_plantillas where id = (d->>'plantilla_id')::bigint and clinica_id = p_clinica;
    if t.id is null then return jsonb_build_object('ok', false, 'motivo', 'plantilla_no_existe'); end if;
    v_texto := _render(t.texto, _vars_documento(v_pac));
  elsif nullif(trim(coalesce(d->>'nombre', '')), '') is null then
    return jsonb_build_object('ok', false, 'motivo', 'falta_nombre');
  end if;
  if d->>'archivo_id' is not null then
    select * into a from archivos where id = (d->>'archivo_id')::bigint and paciente_id = v_pac and estado = 'listo';
    if a.id is null then return jsonb_build_object('ok', false, 'motivo', 'archivo_no_existe'); end if;
  end if;
  if (coalesce(t.sanitario, false) or coalesce(a.sanitario, false)) and not _puede_salud(m.rol) then
    return jsonb_build_object('ok', false, 'motivo', 'solo_profesional');
  end if;
  v_fecha := coalesce(_desde_local(nullif(d->>'fecha', '') || 'T12:00', _tz(p_clinica)), now());
  if v_fecha > now() + interval '1 day' then return jsonb_build_object('ok', false, 'motivo', 'fecha_futura'); end if;
  insert into documentos (clinica_id, paciente_id, plantilla_id, version_plantilla, nombre, tipo, texto, texto_huella, firma,
                          sanitario, estado, archivo_id, enviado_en, enviado_por, respondido_en, firmante_nombre, evidencias,
                          creado_por)
  values (p_clinica, v_pac, t.id, t.version, coalesce(t.nombre, left(trim(d->>'nombre'), 120)),
          coalesce(t.tipo, coalesce(nullif(d->>'tipo', ''), 'otro')), v_texto, _huella(v_texto), 'papel',
          coalesce(t.sanitario, false) or coalesce(a.sanitario, false), 'firmado', a.id, v_fecha, auth.uid(), v_fecha,
          left(nullif(trim(coalesce(d->>'firmante', '')), ''), 120),
          jsonb_build_object('metodo', 'papel', 'registrado_por', _nombre_miembro(p_clinica), 'registrado_en', now(),
                             'escaneado', a.id is not null), auth.uid())
  returning id into v_id;
  perform _auditar(p_clinica, 'registrar_documento_papel', 'documento', v_id::text, v_pac);
  return jsonb_build_object('ok', true, 'documento', _documento_json(v_id, false));
end;
$$;

create function documentos_paciente(p_clinica uuid, p_paciente bigint) returns jsonb
language plpgsql stable security definer set search_path = nutricion, extensions, pg_temp as $$
declare m miembros := _miembro(p_clinica);
begin
  return (select coalesce(jsonb_agg(_documento_json(d.id, false) order by d.creado_en desc), '[]'::jsonb)
    from documentos d where d.paciente_id = p_paciente and d.clinica_id = p_clinica and (not d.sanitario or _puede_salud(m.rol)));
end;
$$;

-- El documento entero: texto enviado, huella, firma y evidencias. Queda registrado.
create function ver_documento(p_clinica uuid, p_doc bigint) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare m miembros := _miembro(p_clinica); d documentos;
begin
  select * into d from documentos where id = p_doc and clinica_id = p_clinica;
  if d.id is null or (d.sanitario and not _puede_salud(m.rol)) then
    return jsonb_build_object('ok', false, 'motivo', 'documento_no_existe');
  end if;
  perform _auditar(p_clinica, 'ver_documento', 'documento', d.id::text, d.paciente_id);
  return jsonb_build_object('ok', true, 'documento', _documento_json(d.id, true));
end;
$$;

create function reenviar_documento(p_clinica uuid, p_doc bigint) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare m miembros := _miembro(p_clinica); d documentos;
begin
  select * into d from documentos where id = p_doc and clinica_id = p_clinica;
  if d.id is null or (d.sanitario and not _puede_salud(m.rol)) then
    return jsonb_build_object('ok', false, 'motivo', 'documento_no_existe');
  end if;
  if d.estado not in ('pendiente', 'caducado') then return jsonb_build_object('ok', false, 'motivo', 'ya_respondido'); end if;
  perform _reenviar_documento(d.id);
  perform _auditar(p_clinica, 'reenviar_documento', 'documento', d.id::text, d.paciente_id);
  return jsonb_build_object('ok', true, 'documento', _documento_json(d.id, false));
end;
$$;

create function anular_documento(p_clinica uuid, p_doc bigint, p_motivo text) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare m miembros := _miembro(p_clinica); d documentos;
begin
  select * into d from documentos where id = p_doc and clinica_id = p_clinica for update;
  if d.id is null or (d.sanitario and not _puede_salud(m.rol)) then
    return jsonb_build_object('ok', false, 'motivo', 'documento_no_existe');
  end if;
  if d.estado = 'anulado' then return jsonb_build_object('ok', true, 'repetida', true); end if;
  if d.estado not in ('pendiente', 'caducado') then return jsonb_build_object('ok', false, 'motivo', 'ya_respondido'); end if;
  if nullif(trim(coalesce(p_motivo, '')), '') is null then return jsonb_build_object('ok', false, 'motivo', 'falta_motivo'); end if;
  update documentos set estado = 'anulado', anulado_en = now(), motivo_anulacion = left(trim(p_motivo), 300) where id = d.id;
  update enlaces set anulado_en = now() where documento_id = d.id and anulado_en is null;
  update envios set estado = 'cancelado', secreto = null
  where clinica_id = p_clinica and estado = 'pendiente' and clave_idempotencia like 'documento:' || d.id || ':%';
  perform _auditar(p_clinica, 'anular_documento', 'documento', d.id::text, d.paciente_id);
  return jsonb_build_object('ok', true, 'documento', _documento_json(d.id, false));
end;
$$;

-- El paciente retira una aceptación o una autorización (lo pide por cualquier vía y el equipo lo apunta). Lo que
-- firmó se conserva como prueba de lo que hubo; desde ahora consta como revocado.
create function revocar_documento(p_clinica uuid, p_doc bigint, p_motivo text) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare m miembros := _miembro(p_clinica); d documentos;
begin
  select * into d from documentos where id = p_doc and clinica_id = p_clinica for update;
  if d.id is null or (d.sanitario and not _puede_salud(m.rol)) then
    return jsonb_build_object('ok', false, 'motivo', 'documento_no_existe');
  end if;
  if d.estado = 'revocado' then return jsonb_build_object('ok', true, 'repetida', true); end if;
  if d.estado not in ('aceptado', 'firmado') then return jsonb_build_object('ok', false, 'motivo', 'no_revocable'); end if;
  if nullif(trim(coalesce(p_motivo, '')), '') is null then return jsonb_build_object('ok', false, 'motivo', 'falta_motivo'); end if;
  update documentos set estado = 'revocado', revocado_en = now(), motivo_revocacion = left(trim(p_motivo), 300) where id = d.id;
  perform _auditar(p_clinica, 'revocar_documento', 'documento', d.id::text, d.paciente_id);
  return jsonb_build_object('ok', true, 'documento', _documento_json(d.id, false));
end;
$$;

-- Envíos automáticos: al vender un bono, al crear un programa y con la primera cita. Solo plantillas activas y
-- revisadas. El contexto hace que no se repitan.
create function _documentos_automaticos() returns trigger
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare t record; v_evento text := tg_argv[0];
begin
  for t in select * from documento_plantillas where clinica_id = new.clinica_id and automatico = v_evento and activa and revisada
           order by orden, id loop
    if v_evento = 'venta_bono' then
      perform _crear_documento(new.clinica_id, new.paciente_id, t.id, 'bono:' || new.id || ':' || t.id, new.id, null);
    elsif v_evento = 'crear_programa' then
      -- Solo si el programa lleva condiciones (un acuerdo con el paciente). Una serie de revisiones indicada por el
      -- profesional no necesita contrato.
      continue when new.condiciones is null;
      perform _crear_documento(new.clinica_id, new.paciente_id, t.id, 'programa:' || new.id || ':' || t.id, null, new.id);
    elsif v_evento = 'primera_cita' and new.estado = 'reservada'
          and not exists (select 1 from citas c where c.paciente_id = new.paciente_id and c.id <> new.id) then
      perform _crear_documento(new.clinica_id, new.paciente_id, t.id, 'paciente:' || new.paciente_id || ':' || t.id);
    end if;
  end loop;
  return null;
end;
$$;
create trigger bonos_documentos after insert on bonos for each row execute function _documentos_automaticos('venta_bono');
create trigger programas_documentos after insert on programas for each row execute function _documentos_automaticos('crear_programa');
create trigger citas_documentos after insert on citas for each row execute function _documentos_automaticos('primera_cita');

-- =====================================================================
-- Portal del paciente (anon): documentos y plan
-- =====================================================================

-- Comprueba token + segundo dato (como en los formularios). Cuenta los fallos y bloquea.
create function _enlace_entrar(p_token text, p_comprobacion text, out en enlaces, out motivo text)
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare pa pacientes; v_ok boolean;
begin
  perform set_config('nutricion.actor', 'portal', true);
  select * into en from enlaces where token_hash = _huella(p_token) for update;
  if en.id is null then motivo := 'enlace_no_valido'; return; end if;
  if en.anulado_en is not null then motivo := 'enlace_sustituido'; en := null; return; end if;
  if en.caduca_en < now() then motivo := 'enlace_caducado'; en := null; return; end if;
  if en.bloqueado_hasta > now() then motivo := 'bloqueado'; en := null; return; end if;
  select * into pa from pacientes where id = en.paciente_id;
  if pa.fecha_nacimiento is not null then
    begin v_ok := p_comprobacion::date = pa.fecha_nacimiento;
    exception when others then v_ok := false; end;
  else
    v_ok := length(regexp_replace(coalesce(p_comprobacion, ''), '[^0-9]', '', 'g')) = 4
            and right(pa.telefono, 4) = regexp_replace(p_comprobacion, '[^0-9]', '', 'g');
  end if;
  if not coalesce(v_ok, false) then
    update enlaces set intentos_fallidos = intentos_fallidos + 1,
           bloqueado_hasta = case when (intentos_fallidos + 1) % 5 = 0 then now() + interval '30 minutes' end,
           anulado_en = case when intentos_fallidos + 1 >= 15 then now() end
    where id = en.id;
    perform _auditar(en.clinica_id, 'portal_fallo', 'enlace', en.id::text, en.paciente_id);
    motivo := 'no_coincide';
    en := null;
    return;
  end if;
  update enlaces set intentos_fallidos = 0, abierto_en = coalesce(abierto_en, now()) where id = en.id;
end;
$$;

-- Primer paso sin datos: de qué es el enlace y qué se pide para entrar. Los enlaces de formularios también valen.
create function portal_enlace_info(p_token text) returns jsonb
language plpgsql stable security definer set search_path = nutricion, extensions, pg_temp as $$
declare en enlaces; c clinicas; pa pacientes; d documentos; p planes;
begin
  if exists (select 1 from formulario_envios where token_hash = _huella(p_token)) then
    return portal_formulario_info(p_token) || jsonb_build_object('tipo', 'formulario');
  end if;
  select * into en from enlaces where token_hash = _huella(p_token);
  if en.id is null then return jsonb_build_object('ok', false, 'motivo', 'enlace_no_valido'); end if;
  select * into c from clinicas where id = en.clinica_id;
  select * into pa from pacientes where id = en.paciente_id;
  select * into d from documentos where id = en.documento_id;
  select * into p from planes where id = en.plan_id;
  return jsonb_build_object('ok', true, 'tipo', en.tipo, 'clinica', c.nombre, 'color', c.color,
    'titulo', coalesce(d.nombre, p.titulo),
    'estado', case when en.anulado_en is not null then 'sustituido'
                   when en.caduca_en < now() or d.estado in ('anulado', 'caducado') or p.estado = 'archivado'
                        or (d.estado = 'pendiente' and d.caduca_en < now()) then 'caducado'
                   when en.bloqueado_hasta > now() then 'bloqueado'
                   when d.estado in ('leido', 'aceptado', 'firmado', 'rechazado', 'revocado') then 'respondido'
                   else 'pendiente' end,
    'comprobacion', case when pa.fecha_nacimiento is not null then 'fecha_nacimiento' else 'ultimos_digitos' end);
end;
$$;

-- Lo que ve el paciente al entrar: el documento a leer o firmar, o la última versión entregada de su plan.
create function portal_enlace_abrir(p_token text, p_comprobacion text) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare x record; d documentos; p planes; v plan_versiones; c clinicas;
begin
  select * into x from _enlace_entrar(p_token, p_comprobacion);
  if x.motivo is not null then return jsonb_build_object('ok', false, 'motivo', x.motivo); end if;
  select * into c from clinicas where id = (x.en).clinica_id;
  if (x.en).tipo = 'documento' then
    select * into d from documentos where id = (x.en).documento_id for update;
    if d.estado in ('anulado', 'caducado') or (d.estado = 'pendiente' and d.caduca_en < now()) then
      return jsonb_build_object('ok', false, 'motivo', 'enlace_caducado');
    end if;
    update documentos set visto_en = coalesce(visto_en, now()) where id = d.id;
    perform _auditar(d.clinica_id, 'portal_ver_documento', 'documento', d.id::text, d.paciente_id);
    return jsonb_build_object('ok', true, 'tipo', 'documento',
      'paciente', (select split_part(trim(nombre), ' ', 1) from pacientes where id = d.paciente_id),
      'documento', jsonb_build_object('nombre', d.nombre, 'texto', d.texto, 'firma', d.firma, 'estado', d.estado,
        'respondido', _local(d.respondido_en, c.zona_horaria), 'firmante', d.firmante_nombre));
  end if;
  select * into p from planes where id = (x.en).plan_id;
  if p.estado <> 'activo' then return jsonb_build_object('ok', false, 'motivo', 'enlace_caducado'); end if;
  select * into v from plan_versiones where plan_id = p.id and entregada_en is not null order by numero desc limit 1;
  if v.id is null then return jsonb_build_object('ok', false, 'motivo', 'enlace_caducado'); end if;
  update plan_versiones set visto_en = coalesce(visto_en, now()) where id = v.id;
  perform _auditar(p.clinica_id, 'portal_ver_plan', 'plan_version', v.id::text, p.paciente_id);
  return jsonb_build_object('ok', true, 'tipo', 'plan',
    'paciente', (select split_part(trim(nombre), ' ', 1) from pacientes where id = p.paciente_id),
    'plan', jsonb_build_object('titulo', p.titulo, 'numero', v.numero, 'texto', v.texto,
      'aprobado_por', v.aprobada_por_nombre, 'aprobado', fecha_dia_es((v.aprobada_en at time zone c.zona_horaria)::date),
      'entregado', fecha_dia_es((v.entregada_en at time zone c.zona_horaria)::date),
      'archivo', (select jsonb_build_object('nombre', a.nombre, 'mime', a.mime, 'tamano', a.tamano)
                  from archivos a where a.id = v.archivo_id and a.estado = 'listo')));
end;
$$;

-- Para descargar el archivo del plan desde el portal: deja pedir un enlace firmado durante dos minutos.
create function portal_enlace_archivo(p_token text, p_comprobacion text) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare x record; v_a archivos;
begin
  select * into x from _enlace_entrar(p_token, p_comprobacion);
  if x.motivo is not null then return jsonb_build_object('ok', false, 'motivo', x.motivo); end if;
  if (x.en).tipo <> 'plan' then return jsonb_build_object('ok', false, 'motivo', 'archivo_no_existe'); end if;
  select a.* into v_a from plan_versiones v join archivos a on a.id = v.archivo_id and a.estado = 'listo'
  join planes p on p.id = v.plan_id and p.estado = 'activo'
  where v.plan_id = (x.en).plan_id and v.entregada_en is not null order by v.numero desc limit 1;
  if v_a.id is null then return jsonb_build_object('ok', false, 'motivo', 'archivo_no_existe'); end if;
  delete from concesiones_portal where expira_en < now();
  insert into concesiones_portal (ruta, enlace_id, expira_en) values (v_a.ruta, (x.en).id, now() + interval '2 minutes')
  on conflict (ruta, enlace_id) do update set expira_en = excluded.expira_en;
  perform _auditar(v_a.clinica_id, 'portal_descargar_archivo', 'archivo', v_a.id::text, v_a.paciente_id);
  return jsonb_build_object('ok', true, 'bucket', 'nutricion', 'ruta', v_a.ruta, 'nombre', v_a.nombre, 'mime', v_a.mime);
end;
$$;

-- Respuesta del paciente. d: {accion: 'leido' | 'aceptar' | 'rechazar', nombre?, trazos?, motivo?}
-- lectura → 'leido'; aceptacion → 'aceptar' con su nombre; firma → 'aceptar' con su nombre y la firma dibujada.
-- Se guardan la huella del texto, el método de identificación, la fecha, la IP y el navegador.
create function portal_documento_responder(p_token text, p_comprobacion text, d jsonb) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare x record; doc documentos; v_accion text := d->>'accion'; v_estado text; v_nombre text := nullif(trim(coalesce(d->>'nombre', '')), '');
        v_puntos int; v_cab jsonb; v_sol bigint; pa pacientes;
begin
  select * into x from _enlace_entrar(p_token, p_comprobacion);
  if x.motivo is not null then return jsonb_build_object('ok', false, 'motivo', x.motivo); end if;
  if (x.en).tipo <> 'documento' then return jsonb_build_object('ok', false, 'motivo', 'enlace_no_valido'); end if;
  select * into doc from documentos where id = (x.en).documento_id for update;
  v_estado := case v_accion when 'leido' then 'leido' when 'rechazar' then 'rechazado'
                when 'aceptar' then case doc.firma when 'firma' then 'firmado' when 'aceptacion' then 'aceptado' end end;
  if v_estado is null or (doc.firma = 'lectura' and v_accion <> 'leido') or (doc.firma <> 'lectura' and v_accion = 'leido') then
    return jsonb_build_object('ok', false, 'motivo', 'valor_no_valido');
  end if;
  if doc.estado <> 'pendiente' then
    if doc.estado = v_estado then return jsonb_build_object('ok', true, 'repetida', true, 'estado', doc.estado); end if;
    if doc.estado in ('anulado', 'caducado') then return jsonb_build_object('ok', false, 'motivo', 'enlace_caducado'); end if;
    return jsonb_build_object('ok', false, 'motivo', 'ya_respondido');
  end if;
  if doc.caduca_en < now() then return jsonb_build_object('ok', false, 'motivo', 'enlace_caducado'); end if;
  if v_accion = 'aceptar' and (v_nombre is null or length(v_nombre) < 3 or length(v_nombre) > 120) then
    return jsonb_build_object('ok', false, 'motivo', 'falta_nombre');
  end if;
  if v_estado = 'firmado' then
    if jsonb_typeof(d->'trazos') <> 'array' or length((d->'trazos')::text) > 60000 then
      return jsonb_build_object('ok', false, 'motivo', 'firma_no_valida');
    end if;
    begin
      select count(*) into v_puntos from jsonb_array_elements(d->'trazos') t, jsonb_array_elements(t) pt
      where jsonb_typeof(pt) = 'array' and jsonb_array_length(pt) = 2
        and (pt->>0)::numeric between 0 and 2000 and (pt->>1)::numeric between 0 and 2000;
    exception when others then v_puntos := 0;
    end;
    if v_puntos < 10 then return jsonb_build_object('ok', false, 'motivo', 'firma_no_valida'); end if;
  end if;
  select * into pa from pacientes where id = doc.paciente_id;
  v_cab := nullif(current_setting('request.headers', true), '')::jsonb;
  update documentos set estado = v_estado, respondido_en = now(), visto_en = coalesce(visto_en, now()),
    firmante_nombre = case when v_accion = 'aceptar' then left(v_nombre, 120) end,
    firma_trazos = case when v_estado = 'firmado' then d->'trazos' end,
    motivo_rechazo = case when v_estado = 'rechazado' then left(nullif(trim(coalesce(d->>'motivo', '')), ''), 500) end,
    evidencias = jsonb_build_object('huella_texto', encode(doc.texto_huella, 'hex'), 'fecha', now(),
      'metodo', 'enlace personal + ' || case when pa.fecha_nacimiento is not null then 'fecha de nacimiento'
                                             else 'últimos dígitos del móvil' end,
      'ip', nullif(trim(split_part(coalesce(v_cab->>'x-forwarded-for', ''), ',', 1)), ''),
      'navegador', left(v_cab->>'user-agent', 300))
  where id = doc.id;
  if v_estado = 'rechazado' then
    v_sol := _solicitud(doc.clinica_id, 'documento_rechazado',
      'Ha rechazado "' || doc.nombre || '"' || coalesce('. Motivo: ' || left(nullif(trim(coalesce(d->>'motivo', '')), ''), 300), ''),
      doc.paciente_id);
  end if;
  perform _auditar(doc.clinica_id, 'portal_responder_documento', 'documento', doc.id::text, doc.paciente_id,
                   jsonb_build_object('estado', v_estado));
  return jsonb_build_object('ok', true, 'estado', v_estado);
end;
$$;

-- =====================================================================
-- Formularios de revisión
-- =====================================================================

-- Los formularios de revisión no se mandan al reservar: los manda el motor unos días antes de cada cita.
create or replace function _citas_despues() returns trigger
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare
  c clinicas; v_desde_chat boolean := coalesce(current_setting('nutricion.actor', true), '') = 'whatsapp';
  v_agrupada boolean := coalesce(current_setting('nutricion.confirmacion_agrupada', true), '') = 'si';
  f record;
begin
  select * into c from clinicas where id = new.clinica_id;
  if tg_op = 'INSERT' then
    if new.estado = 'reservada' and new.inicio > now() then
      if c.enviar_confirmacion and not v_desde_chat and not v_agrupada then
        perform _encolar(new.clinica_id, 'confirmacion_cita', 'confirmacion:' || new.id, new.paciente_id, new.id,
                         _vars_cita(new.id));
      end if;
      for f in select sf.formulario_id from servicio_formularios sf join formularios fo on fo.id = sf.formulario_id
               where sf.servicio_id = new.servicio_id and fo.activo and fo.envio = 'al_reservar'
                 and not exists (select 1 from formulario_envios fe where fe.paciente_id = new.paciente_id
                                   and fe.formulario_id = sf.formulario_id and fe.estado in ('completado', 'revisado'))
      loop
        perform _mandar_formulario(new.clinica_id, new.paciente_id, f.formulario_id, new.id);
      end loop;
    end if;
    return null;
  end if;

  if old.estado = 'reservada' and new.estado = 'cancelada' then
    update envios set estado = 'cancelado', secreto = null
    where cita_id = new.id and estado = 'pendiente' and tipo in ('confirmacion_cita', 'recordatorio_cita', 'cambio_cita');
    -- El formulario de revisión de una cita cancelada ya no hace falta.
    update formulario_envios fe set estado = 'anulado' from formularios fo
    where fo.id = fe.formulario_id and fo.envio = 'antes_de_cada_cita' and fe.cita_id = new.id and fe.estado = 'pendiente';
    if new.inicio > now() then
      if not v_desde_chat then
        perform _encolar(new.clinica_id, 'cancelacion_cita', 'cancelacion:' || new.id, new.paciente_id, new.id,
                         _vars_cita(new.id));
      end if;
      perform _ofrecer_hueco(new.clinica_id, new.profesional_id, new.inicio);
    end if;
    update lista_espera set estado = 'cancelada' where cita_id = new.id and estado in ('activa', 'ofrecida');
  elsif new.estado = 'reservada' and (old.inicio <> new.inicio or old.profesional_id <> new.profesional_id) then
    update envios set estado = 'cancelado', secreto = null
    where cita_id = new.id and estado = 'pendiente' and tipo in ('confirmacion_cita', 'recordatorio_cita', 'cambio_cita');
    if new.inicio > now() and not v_desde_chat then
      perform _encolar(new.clinica_id, 'cambio_cita', 'cambio:' || new.id || ':' || extract(epoch from new.inicio)::bigint
                       || ':' || new.profesional_id, new.paciente_id, new.id, _vars_cita(new.id));
    end if;
    if old.inicio > now() then
      perform _ofrecer_hueco(new.clinica_id, old.profesional_id, old.inicio);
    end if;
  end if;
  return null;
end;
$$;

-- Campos nuevos: `importante` (si queda sin responder, se avisa al profesional) y destino 'medicion:<tipo>' para los
-- números (pasan a las mediciones como "lo dice el paciente" cuando el profesional lo revisa). Ajustes del envío:
-- envio ('al_reservar' | 'antes_de_cada_cita'), dias_antes, avisar_si_falta.
create or replace function guardar_formulario(p_clinica uuid, d jsonb) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare v_id bigint := (d->>'id')::bigint; cp jsonb; v_claves text[] := '{}'; v_dest text; t jsonb;
begin
  perform _miembro(p_clinica, array['propietario', 'nutricionista']);
  if d ? 'campos' then
    if jsonb_typeof(d->'campos') <> 'array' or jsonb_array_length(d->'campos') = 0 then
      return jsonb_build_object('ok', false, 'motivo', 'faltan_campos');
    end if;
    for cp in select * from jsonb_array_elements(d->'campos') loop
      v_dest := cp->>'destino';
      t := case when v_dest like 'medicion:%' then _tipos_medicion() -> substr(v_dest, 10) end;
      if coalesce(cp->>'clave', '') !~ '^[a-z][a-z0-9_]{0,39}$' or nullif(trim(cp->>'etiqueta'), '') is null
         or coalesce(cp->>'tipo', '') not in ('texto', 'texto_largo', 'numero', 'si_no', 'opcion', 'varias', 'fecha')
         or (cp->>'tipo' in ('opcion', 'varias') and coalesce(jsonb_array_length(cp->'opciones'), 0) < 2)
         or (v_dest is not null and v_dest not like 'medicion:%' and v_dest not in ('motivo_consulta', 'objetivos', 'antecedentes',
               'alergias', 'intolerancias', 'medicacion', 'suplementos', 'habitos_alimentarios', 'actividad_fisica', 'extra'))
         or (v_dest like 'medicion:%' and (cp->>'tipo' <> 'numero' or t is null or (t->>'solo_calculado')::boolean
               or (t->>'libre')::boolean or (t->>'requiere_metodo')::boolean)) then
        return jsonb_build_object('ok', false, 'motivo', 'campo_no_valido', 'campo', cp);
      end if;
      if cp->>'clave' = any (v_claves) then return jsonb_build_object('ok', false, 'motivo', 'clave_repetida', 'campo', cp); end if;
      v_claves := v_claves || (cp->>'clave');
    end loop;
  end if;
  if coalesce(d->>'envio', 'al_reservar') not in ('al_reservar', 'antes_de_cada_cita') then
    return jsonb_build_object('ok', false, 'motivo', 'valor_no_valido');
  end if;
  begin
    if v_id is null then
      insert into formularios (clinica_id, nombre, descripcion, campos, envio, dias_antes, avisar_si_falta)
      values (p_clinica, trim(d->>'nombre'), nullif(trim(d->>'descripcion'), ''), coalesce(d->'campos', '[]'::jsonb),
              coalesce(d->>'envio', 'al_reservar'), coalesce((d->>'dias_antes')::int, 3),
              coalesce((d->>'avisar_si_falta')::boolean, true))
      returning id into v_id;
    else
      -- Los envíos ya hechos guardan su propia copia: cambiar el formulario no altera lo que el paciente ya recibió.
      update formularios set nombre = coalesce(nullif(trim(d->>'nombre'), ''), nombre),
        descripcion = case when d ? 'descripcion' then nullif(trim(d->>'descripcion'), '') else descripcion end,
        campos = coalesce(d->'campos', campos),
        version = version + case when d ? 'campos' and d->'campos' <> campos then 1 else 0 end,
        activo = coalesce((d->>'activo')::boolean, activo), envio = coalesce(d->>'envio', envio),
        dias_antes = coalesce((d->>'dias_antes')::int, dias_antes),
        avisar_si_falta = coalesce((d->>'avisar_si_falta')::boolean, avisar_si_falta), actualizado_en = now()
      where id = v_id and clinica_id = p_clinica;
      if not found then return jsonb_build_object('ok', false, 'motivo', 'formulario_no_existe'); end if;
    end if;
  exception
    when unique_violation then return jsonb_build_object('ok', false, 'motivo', 'nombre_repetido');
    when check_violation or not_null_violation or invalid_text_representation then
      return jsonb_build_object('ok', false, 'motivo', 'valor_no_valido');
  end;
  if d ? 'servicios' then
    delete from servicio_formularios where formulario_id = v_id;
    insert into servicio_formularios (clinica_id, servicio_id, formulario_id)
    select p_clinica, s.id, v_id from servicios s
    where s.clinica_id = p_clinica and s.id in (select x::bigint from jsonb_array_elements_text(d->'servicios') x);
  end if;
  perform _auditar(p_clinica, 'guardar_formulario', 'formulario', v_id::text);
  return jsonb_build_object('ok', true, 'id', v_id);
end;
$$;

-- La lista de formularios lleva también cómo se envían.
create or replace function lista_formularios(p_clinica uuid) returns jsonb
language plpgsql stable security definer set search_path = nutricion, extensions, pg_temp as $$
begin
  perform _miembro(p_clinica);
  return (select coalesce(jsonb_agg(jsonb_build_object('id', f.id, 'nombre', f.nombre, 'descripcion', f.descripcion,
            'campos', f.campos, 'version', f.version, 'activo', f.activo, 'envio', f.envio, 'dias_antes', f.dias_antes,
            'avisar_si_falta', f.avisar_si_falta,
            'servicios', (select coalesce(jsonb_agg(sf.servicio_id), '[]'::jsonb) from servicio_formularios sf where sf.formulario_id = f.id))
          order by f.nombre), '[]'::jsonb)
    from formularios f where f.clinica_id = p_clinica);
end;
$$;

-- Al enviar, si quedan sin responder preguntas marcadas como importantes, se avisa al profesional (solo con los
-- nombres de las preguntas, no con las respuestas).
alter function portal_formulario_enviar(text, text, jsonb) rename to _portal_formulario_enviar_fase2;
create function portal_formulario_enviar(p_token text, p_comprobacion text, p_respuestas jsonb) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare r jsonb := _portal_formulario_enviar_fase2(p_token, p_comprobacion, p_respuestas); fe formulario_envios; f formularios;
        v_faltan text; v_sol bigint;
begin
  if not coalesce((r->>'ok')::boolean, false) then return r; end if;
  select * into fe from formulario_envios where token_hash = _huella(p_token);
  select * into f from formularios where id = fe.formulario_id;
  select string_agg(cp->>'etiqueta', '; ') into v_faltan from jsonb_array_elements(fe.campos) cp
  where coalesce((cp->>'importante')::boolean, false) and not coalesce(fe.respuestas, '{}'::jsonb) ? (cp->>'clave');
  if v_faltan is not null and f.avisar_si_falta and fe.alerta_en is null then
    v_sol := _solicitud(fe.clinica_id, 'formulario_incompleto',
      'Ha enviado "' || f.nombre || '" sin responder: ' || left(v_faltan, 600), fe.paciente_id, null, fe.cita_id);
    update formulario_envios set alerta_en = now() where id = fe.id;
  end if;
  return r;
end;
$$;

-- Al revisar las respuestas, los números con destino 'medicion:<tipo>' pasan a mediciones como "lo dice el
-- paciente", con la fecha del formulario. Nunca dos veces la misma.
alter function aplicar_respuestas(uuid, bigint, jsonb) rename to _aplicar_respuestas_fase2;
create function aplicar_respuestas(p_clinica uuid, p_envio bigint, p_claves jsonb default null) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare fe formulario_envios; cp jsonb; v_normales jsonb := '[]'::jsonb; v_med text[] := '{}'; r jsonb; v_tipo text;
        v_mal text; v_fecha date; v_id bigint; v_omitidas text[] := '{}';
begin
  perform _miembro(p_clinica, array['propietario', 'nutricionista']);
  select * into fe from formulario_envios where id = p_envio and clinica_id = p_clinica;
  if fe.id is null then return jsonb_build_object('ok', false, 'motivo', 'formulario_no_existe'); end if;
  for cp in select * from jsonb_array_elements(fe.campos) loop
    continue when p_claves is not null and jsonb_typeof(p_claves) = 'array' and not p_claves ? (cp->>'clave');
    if cp->>'destino' like 'medicion:%' then v_med := v_med || (cp->>'clave');
    elsif cp->>'destino' is not null then v_normales := v_normales || to_jsonb(cp->>'clave'); end if;
  end loop;
  r := _aplicar_respuestas_fase2(p_clinica, p_envio, v_normales);
  if not (r->>'ok')::boolean then return r; end if;
  v_fecha := (fe.completado_en at time zone _tz(p_clinica))::date;
  for cp in select * from jsonb_array_elements(fe.campos) x where x->>'clave' = any (v_med) loop
    continue when not fe.respuestas ? (cp->>'clave');
    v_tipo := substr(cp->>'destino', 10);
    v_mal := _medicion_no_valida(jsonb_build_object('tipo', v_tipo, 'valor', fe.respuestas->>(cp->>'clave')));
    if v_mal is not null then v_omitidas := v_omitidas || (cp->>'clave'); continue; end if;
    if exists (select 1 from mediciones where formulario_envio_id = fe.id and tipo = v_tipo and anulada_en is null) then continue; end if;
    v_id := _insertar_medicion(p_clinica, fe.paciente_id,
      jsonb_build_object('tipo', v_tipo, 'valor', fe.respuestas->>(cp->>'clave'),
                         'nota', 'Del formulario «' || (select nombre from formularios where id = fe.formulario_id) || '»'),
      'paciente', v_fecha);
    update mediciones set formulario_envio_id = fe.id where id = v_id;
    r := jsonb_set(r, '{aplicados}', (r->'aplicados') || to_jsonb(cp->>'clave'));
  end loop;
  if array_length(v_omitidas, 1) > 0 then r := r || jsonb_build_object('omitidas', to_jsonb(v_omitidas)); end if;
  return r;
end;
$$;

-- =====================================================================
-- Objetivos de medición
-- =====================================================================

-- d: {paciente_id, tipo, nombre? (solo 'otro'), unidad? (solo 'otro'), valor, fecha_objetivo?, nota?}
-- Un objetivo nuevo del mismo tipo sustituye al anterior (que queda retirado, no borrado).
create function guardar_objetivo(p_clinica uuid, d jsonb) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare v_pac bigint := (d->>'paciente_id')::bigint; t jsonb := _tipos_medicion() -> (d->>'tipo'); v_mal text; v_nombre text;
        v_id bigint;
begin
  perform _miembro(p_clinica, array['propietario', 'nutricionista']);
  if not exists (select 1 from pacientes where id = v_pac and clinica_id = p_clinica) then
    return jsonb_build_object('ok', false, 'motivo', 'paciente_no_existe');
  end if;
  v_mal := _medicion_no_valida(d || jsonb_build_object('metodo', 'objetivo'));
  if v_mal is not null then return jsonb_build_object('ok', false, 'motivo', v_mal); end if;
  if nullif(d->>'fecha_objetivo', '') is not null and (d->>'fecha_objetivo')::date < _hoy(_tz(p_clinica)) then
    return jsonb_build_object('ok', false, 'motivo', 'fecha_pasada');
  end if;
  v_nombre := case when (t->>'libre')::boolean then left(trim(d->>'nombre'), 80) else t->>'nombre' end;
  update objetivos_medicion set retirado_en = now()
  where paciente_id = v_pac and tipo = d->>'tipo' and nombre = v_nombre and retirado_en is null;
  insert into objetivos_medicion (clinica_id, paciente_id, tipo, nombre, valor, unidad, fecha_objetivo, nota, creado_por,
                                  creado_por_nombre)
  values (p_clinica, v_pac, d->>'tipo', v_nombre, round(replace(d->>'valor', ',', '.')::numeric, 2),
          case when (t->>'libre')::boolean then left(nullif(trim(d->>'unidad'), ''), 20) else t->>'unidad' end,
          nullif(d->>'fecha_objetivo', '')::date, left(nullif(trim(coalesce(d->>'nota', '')), ''), 300), auth.uid(),
          _nombre_miembro(p_clinica))
  returning id into v_id;
  perform _auditar(p_clinica, 'guardar_objetivo', 'objetivo', v_id::text, v_pac, jsonb_build_object('tipo', d->>'tipo'));
  return jsonb_build_object('ok', true, 'id', v_id);
end;
$$;

create function retirar_objetivo(p_clinica uuid, p_id bigint) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare o objetivos_medicion;
begin
  perform _miembro(p_clinica, array['propietario', 'nutricionista']);
  update objetivos_medicion set retirado_en = now() where id = p_id and clinica_id = p_clinica and retirado_en is null
  returning * into o;
  if o.id is null then return jsonb_build_object('ok', false, 'motivo', 'objetivo_no_existe'); end if;
  perform _auditar(p_clinica, 'retirar_objetivo', 'objetivo', o.id::text, o.paciente_id);
  return jsonb_build_object('ok', true);
end;
$$;

-- El historial clínico trae también los objetivos vigentes.
alter function historial_paciente(uuid, bigint) rename to _historial_paciente_fase3;
create function historial_paciente(p_clinica uuid, p_paciente bigint) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare r jsonb := _historial_paciente_fase3(p_clinica, p_paciente); v_tz text := _tz(p_clinica);
begin
  if not coalesce((r->>'ok')::boolean, false) then return r; end if;
  return r || jsonb_build_object('objetivos', (select coalesce(jsonb_agg(jsonb_build_object('id', o.id, 'tipo', o.tipo,
      'nombre', o.nombre, 'valor', o.valor, 'unidad', o.unidad, 'fecha_objetivo', o.fecha_objetivo, 'nota', o.nota,
      'autor', o.creado_por_nombre, 'desde', (o.creado_en at time zone v_tz)::date) order by o.tipo), '[]'::jsonb)
    from objetivos_medicion o where o.paciente_id = p_paciente and o.retirado_en is null));
end;
$$;

-- =====================================================================
-- Canales (agente): documentos pendientes y reenvío de enlaces. El agente nunca ve el contenido de un plan ni de un
-- documento; solo puede decir qué tiene pendiente y volver a mandar el enlace seguro.
-- =====================================================================

create function canal_mis_documentos(p_conversacion bigint) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare v conversaciones := _conv(p_conversacion); v_pac bigint := _verificado(v);
begin
  if v_pac is null then return jsonb_build_object('ok', false, 'motivo', 'identidad_no_comprobada'); end if;
  return jsonb_build_object('ok', true,
    'documentos_pendientes', (select coalesce(jsonb_agg(jsonb_build_object('documento_id', d.id, 'nombre', d.nombre,
        'que_hay_que_hacer', case d.firma when 'lectura' then 'leerlo' when 'aceptacion' then 'leerlo y aceptarlo' else 'leerlo y firmarlo' end,
        'caduca', fecha_dia_es((d.caduca_en at time zone _tz(v.clinica_id))::date)) order by d.enviado_en), '[]'::jsonb)
      from documentos d where d.paciente_id = v_pac and d.estado = 'pendiente' and d.caduca_en > now()),
    'planes', (select coalesce(jsonb_agg(jsonb_build_object('plan_id', p.id, 'titulo', p.titulo,
        'entregado', fecha_dia_es((x.entregada_en at time zone _tz(v.clinica_id))::date)) order by x.entregada_en desc), '[]'::jsonb)
      from planes p cross join lateral (select max(entregada_en) entregada_en from plan_versiones where plan_id = p.id) x
      where p.paciente_id = v_pac and p.estado = 'activo' and x.entregada_en is not null));
end;
$$;

-- p_tipo: 'documento' | 'plan'. Manda un enlace nuevo (el anterior deja de valer).
create function canal_reenviar_enlace(p_conversacion bigint, p_tipo text, p_id bigint) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare v conversaciones := _conv(p_conversacion); v_pac bigint := _verificado(v); v_doc documentos; p planes;
begin
  if v_pac is null then return jsonb_build_object('ok', false, 'motivo', 'identidad_no_comprobada'); end if;
  if p_tipo = 'documento' then
    select * into v_doc from documentos where id = p_id and paciente_id = v_pac and estado = 'pendiente' and caduca_en > now();
    if v_doc.id is null then return jsonb_build_object('ok', false, 'motivo', 'documento_no_existe'); end if;
    -- Como mucho un reenvío cada 10 minutos, por si el agente lo pide dos veces.
    if v_doc.recordado_en > now() - interval '10 minutes' then return jsonb_build_object('ok', true, 'repetida', true); end if;
    perform _reenviar_documento(v_doc.id);
    perform _auditar(v.clinica_id, 'reenviar_documento', 'documento', v_doc.id::text, v_pac);
    return jsonb_build_object('ok', true);
  elsif p_tipo = 'plan' then
    select * into p from planes where id = p_id and paciente_id = v_pac and estado = 'activo';
    if p.id is null or not exists (select 1 from plan_versiones where plan_id = p.id and entregada_en is not null) then
      return jsonb_build_object('ok', false, 'motivo', 'plan_no_existe');
    end if;
    if exists (select 1 from enlaces where plan_id = p.id and creado_en > now() - interval '10 minutes') then
      return jsonb_build_object('ok', true, 'repetida', true);
    end if;
    perform _mandar_plan(p.id, true);
    update plan_versiones set reenviada_en = now()
    where id = (select id from plan_versiones where plan_id = p.id and entregada_en is not null order by numero desc limit 1);
    perform _auditar(v.clinica_id, 'reenviar_plan', 'plan', p.id::text, v_pac);
    return jsonb_build_object('ok', true);
  end if;
  return jsonb_build_object('ok', false, 'motivo', 'valor_no_valido');
end;
$$;

alter function canal_contexto(bigint) rename to _canal_contexto_fase3;
create function canal_contexto(p_conversacion bigint) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare r jsonb := _canal_contexto_fase3(p_conversacion); v conversaciones := _conv(p_conversacion); v_pac bigint := _verificado(v);
begin
  if v_pac is null then return r; end if;
  return jsonb_set(r, '{paciente}', (r->'paciente') || jsonb_build_object(
    'documentos_pendientes', (select count(*) from documentos where paciente_id = v_pac and estado = 'pendiente' and caduca_en > now()),
    'planes_entregados', (select count(*) from planes p where p.paciente_id = v_pac and p.estado = 'activo'
                            and exists (select 1 from plan_versiones x where x.plan_id = p.id and x.entregada_en is not null))));
end;
$$;

-- Plantillas: los mensajes de planes y documentos necesitan el enlace.
create or replace function guardar_plantilla(p_clinica uuid, p_clave text, d jsonb) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare v_desconocidas text[];
begin
  perform _miembro(p_clinica, array['propietario']);
  select array_agg(distinct m[1]) into v_desconocidas
  from regexp_matches(coalesce(d->>'texto', ''), '\{([a-z_]+)\}', 'g') m
  where m[1] not in ('paciente', 'fecha', 'servicio', 'profesional', 'clinica', 'lugar', 'enlace', 'comprobacion', 'caduca',
                     'tipo', 'texto', 'desde', 'hasta', 'programa', 'fechas');
  if v_desconocidas is not null then
    return jsonb_build_object('ok', false, 'motivo', 'variable_desconocida', 'variables', to_jsonb(v_desconocidas));
  end if;
  if p_clave in ('formulario_pendiente', 'formulario_recordatorio', 'plan_entregado', 'documento_pendiente',
                 'documento_recordatorio') and d ? 'texto' and d->>'texto' not like '%{enlace}%' then
    return jsonb_build_object('ok', false, 'motivo', 'falta_enlace');
  end if;
  if p_clave in ('propuesta_sesiones', 'confirmacion_sesiones') and d ? 'texto' and d->>'texto' not like '%{fechas}%' then
    return jsonb_build_object('ok', false, 'motivo', 'falta_fechas');
  end if;
  update plantillas_mensaje set
    texto = coalesce(nullif(trim(d->>'texto'), ''), texto),
    activa = coalesce((d->>'activa')::boolean, activa),
    plantilla_meta = case when d ? 'plantilla_meta' then nullif(trim(d->>'plantilla_meta'), '') else plantilla_meta end
  where clinica_id = p_clinica and clave = p_clave;
  if not found then return jsonb_build_object('ok', false, 'motivo', 'plantilla_no_existe'); end if;
  perform _auditar(p_clinica, 'guardar_plantilla', 'plantilla', p_clave);
  return jsonb_build_object('ok', true);
end;
$$;

-- =====================================================================
-- Motor
-- =====================================================================

alter function motor_tick() rename to _motor_tick_fase3;
create function motor_tick() returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare r jsonb; x record; n_doc_rec int := 0; n_doc_cad int := 0; n_rev int := 0; n_alerta int := 0; v_sol bigint;
begin
  perform set_config('nutricion.actor', 'sistema', true);
  -- Formularios de revisión: unos días antes de cada cita del servicio, si esa cita aún no tiene el suyo. El que quedó
  -- pendiente de una cita anterior caduca (no se reutiliza para otra).
  for x in
    select ci.id cita_id, ci.clinica_id, ci.paciente_id, fo.id formulario_id from citas ci
    join servicio_formularios sf on sf.servicio_id = ci.servicio_id
    join formularios fo on fo.id = sf.formulario_id and fo.activo and fo.envio = 'antes_de_cada_cita'
    join pacientes pa on pa.id = ci.paciente_id
    where ci.estado = 'reservada' and ci.inicio > now() + interval '6 hours'
      and ci.inicio <= now() + make_interval(days => fo.dias_antes)
      and (pa.telefono is not null or pa.email is not null)
      and not exists (select 1 from formulario_envios fe where fe.cita_id = ci.id and fe.formulario_id = fo.id)
    for update of ci skip locked
  loop
    update formulario_envios set estado = 'caducado'
    where paciente_id = x.paciente_id and formulario_id = x.formulario_id and estado = 'pendiente'
      and cita_id is distinct from x.cita_id;
    if _mandar_formulario(x.clinica_id, x.paciente_id, x.formulario_id, x.cita_id) is not null then n_rev := n_rev + 1; end if;
  end loop;
  r := _motor_tick_fase3();
  -- El día antes de la revisión, si el formulario sigue sin rellenar, se avisa al profesional (una vez).
  for x in
    select fe.id, fe.clinica_id, fe.paciente_id, fe.cita_id, fo.nombre, ci.inicio from formulario_envios fe
    join formularios fo on fo.id = fe.formulario_id and fo.envio = 'antes_de_cada_cita' and fo.avisar_si_falta
    join citas ci on ci.id = fe.cita_id and ci.estado = 'reservada'
    where fe.estado = 'pendiente' and fe.alerta_en is null and ci.inicio > now() and ci.inicio <= now() + interval '24 hours'
    for update of fe skip locked
  loop
    v_sol := _solicitud(x.clinica_id, 'formulario_incompleto',
      'No ha rellenado "' || x.nombre || '" para la cita del ' || fecha_es(x.inicio, _tz(x.clinica_id)) || '.',
      x.paciente_id, null, x.cita_id);
    update formulario_envios set alerta_en = now() where id = x.id;
    n_alerta := n_alerta + 1;
  end loop;
  -- Documentos sin responder: un recordatorio a los 3 días, con enlace nuevo. Luego caducan.
  for x in
    select d.id from documentos d
    where d.estado = 'pendiente' and d.recordado_en is null and d.enviado_en < now() - interval '3 days'
      and d.caduca_en > now() + interval '1 day'
    for update skip locked
  loop
    if _reenviar_documento(x.id, 'documento_recordatorio') then n_doc_rec := n_doc_rec + 1; end if;
  end loop;
  with c as (update documentos set estado = 'caducado' where estado = 'pendiente' and caduca_en < now() returning id),
       e as (update enlaces set anulado_en = now() where anulado_en is null and documento_id in (select id from c) returning 1)
  select count(*) into n_doc_cad from c;
  delete from concesiones_portal where expira_en < now();
  return r || jsonb_build_object('formularios_revision', n_rev, 'formularios_sin_rellenar', n_alerta,
                                 'documentos_recordados', n_doc_rec, 'documentos_caducados', n_doc_cad);
end;
$$;

-- =====================================================================
-- Listas y panel
-- =====================================================================

create or replace function lista_pacientes(p_clinica uuid, p_filtro text default 'todos', p_desde date default null,
                                           p_hasta date default null) returns jsonb
language plpgsql stable security definer set search_path = nutricion, extensions, pg_temp as $$
declare v_tz text := _tz(p_clinica);
begin
  perform _miembro(p_clinica);
  return (select coalesce(jsonb_agg(_paciente_json(p.id) order by p.nombre, p.id), '[]'::jsonb)
    from pacientes p
    where p.clinica_id = p_clinica
      and case p_filtro
        when 'activos' then p.estado = 'activo'
        when 'nuevos' then (p.creado_en at time zone v_tz)::date between coalesce(p_desde, _hoy(v_tz) - 30) and coalesce(p_hasta, _hoy(v_tz))
        when 'sin_proxima' then p.estado = 'activo'
             and exists (select 1 from citas c where c.paciente_id = p.id and c.estado = 'realizada')
             and not exists (select 1 from citas c where c.paciente_id = p.id and c.estado = 'reservada' and c.inicio > now())
        when 'formulario_pendiente' then exists (select 1 from formulario_envios fe where fe.paciente_id = p.id
             and fe.estado = 'pendiente' and fe.caduca_en > now())
        when 'con_programa' then exists (select 1 from sesiones s left join programas pr on pr.id = s.programa_id
             where s.paciente_id = p.id and s.estado in ('pendiente', 'propuesta') and (pr.id is null or pr.estado = 'activo'))
        when 'con_bono' then exists (select 1 from bonos b where b.paciente_id = p.id and b.estado = 'activo')
        when 'plan_por_entregar' then exists (select 1 from planes pl join plan_versiones v on v.plan_id = pl.id
             where pl.paciente_id = p.id and pl.estado = 'activo' and v.estado = 'aprobada' and v.entregada_en is null)
        when 'documento_pendiente' then exists (select 1 from documentos d where d.paciente_id = p.id
             and d.estado = 'pendiente' and d.firma in ('aceptacion', 'firma') and d.caduca_en > now())
        else true end);
end;
$$;

alter function panel(uuid, date, date, bigint) rename to _panel_fase3;
create function panel(p_clinica uuid, p_desde date default null, p_hasta date default null,
                      p_profesional bigint default null) returns jsonb
language plpgsql stable security definer set search_path = nutricion, extensions, pg_temp as $$
declare r jsonb := _panel_fase3(p_clinica, p_desde, p_hasta, p_profesional);
begin
  r := jsonb_set(r, '{tareas,planes_por_entregar}', to_jsonb((select count(*) from planes pl
          join plan_versiones v on v.plan_id = pl.id
          where pl.clinica_id = p_clinica and pl.estado = 'activo' and v.estado = 'aprobada' and v.entregada_en is null
            and (p_profesional is null or pl.profesional_id = p_profesional))));
  r := jsonb_set(r, '{tareas,documentos_por_firmar}', to_jsonb((select count(*) from documentos d
          where d.clinica_id = p_clinica and d.estado = 'pendiente' and d.firma in ('aceptacion', 'firma')
            and d.caduca_en > now())));
  return r;
end;
$$;

select _aplicar_permisos();


-- =====================================================================
-- Corvex Nutrición · Fase 5: gestión avanzada
-- Cobros (cargos y pagos con recibo), enlaces de pago por un proveedor (Stripe), facturas pedidas y emitidas fuera,
-- estadísticas del negocio y asistente de voz del profesional (vista previa + confirmación).
--
-- Principios:
--  * La aplicación nunca ve ni guarda datos de tarjeta. Un pago con tarjeta se hace en la página del proveedor y
--    aquí solo llega su referencia, el importe y el resultado.
--  * Un cargo es lo que se debe (una consulta, un bono u otra cosa); un pago es lo que se ha cobrado. Los pagos no
--    se modifican ni se borran: un error se corrige con una devolución, que también queda registrada.
--  * No hay cobros automáticos: cada enlace de pago lo pide alguien del equipo y lo paga el paciente.
--  * Los recibos no son facturas. Las facturas se emiten con un programa de facturación (VeriFactu); aquí se
--    apunta que se han pedido y su número cuando están hechas.
--  * El asistente de voz no hace nada sin enseñar antes qué va a hacer y recibir la confirmación, salvo consultar.
--    Cada orden ejecutada usa las mismas funciones (y permisos) que la aplicación y queda en el registro.
-- =====================================================================

set search_path = nutricion, extensions, public;

-- ---------------------------------------------------------------- ajustes de la consulta

alter table clinicas
  add column razon_social   text check (length(razon_social) <= 160),
  add column nif            text check (length(nif) <= 20),
  add column serie_recibos  text not null default 'R' check (serie_recibos ~ '^[A-Z0-9-]{1,10}$'),
  add column pago_proveedor text not null default 'ninguno' check (pago_proveedor in ('ninguno', 'stripe')),
  add column pago_modo      text not null default 'prueba' check (pago_modo in ('prueba', 'real')),
  -- Dictar con el micrófono usa el reconocimiento de voz del navegador, que puede mandar el audio a su proveedor
  -- (Google en Chrome). Apagado hasta que el propietario lo active sabiéndolo.
  add column dictado_permitido boolean not null default false;

alter table plantillas_mensaje drop constraint plantillas_mensaje_clave_check;
alter table plantillas_mensaje add constraint plantillas_mensaje_clave_check check (clave in (
  'confirmacion_cita', 'recordatorio_cita', 'cambio_cita', 'cancelacion_cita', 'formulario_pendiente',
  'formulario_recordatorio', 'oferta_lista_espera', 'aviso_equipo', 'mensaje_equipo',
  'recordatorio_seguimiento', 'propuesta_sesiones', 'confirmacion_sesiones',
  'plan_entregado', 'documento_pendiente', 'documento_recordatorio', 'enlace_pago'));

alter table solicitudes drop constraint solicitudes_tipo_check;
alter table solicitudes add constraint solicitudes_tipo_check check (tipo in (
  'cambio_fuera_plazo', 'cancelacion_fuera_plazo', 'pregunta_clinica', 'pregunta_sin_respuesta', 'hablar_con_persona',
  'queja', 'envio_fallido', 'otro', 'sin_disponibilidad', 'seguimiento_vencido',
  'documento_rechazado', 'formulario_incompleto', 'pago_revisar'));

-- ---------------------------------------------------------------- cobros

create table cargos (
  id                 bigint generated always as identity primary key,
  clinica_id         uuid not null references clinicas (id) on delete cascade,
  paciente_id        bigint not null,
  tipo               text not null check (tipo in ('cita', 'bono', 'otro')),
  concepto           text not null check (length(trim(concepto)) between 2 and 200),
  cita_id            bigint,
  bono_id            bigint,
  importe_centimos   int not null check (importe_centimos between 1 and 10000000),
  estado             text not null default 'abierto' check (estado in ('abierto', 'anulado')),
  motivo_anulacion   text,
  anulado_en         timestamptz,
  factura_estado     text not null default 'no_pedida' check (factura_estado in ('no_pedida', 'pedida', 'emitida')),
  factura_datos      jsonb,          -- nombre, NIF y dirección del destinatario, solo si pide factura
  factura_numero     text check (length(factura_numero) <= 40),
  factura_pedida_en  timestamptz,
  factura_emitida_en timestamptz,
  clave_idempotencia text,
  creado_por         uuid,
  creado_en          timestamptz not null default now(),
  unique (clinica_id, id),
  unique (clinica_id, clave_idempotencia),
  foreign key (clinica_id, paciente_id) references pacientes (clinica_id, id) on delete cascade,
  foreign key (clinica_id, cita_id) references citas (clinica_id, id) on delete set null (cita_id),
  foreign key (clinica_id, bono_id) references bonos (clinica_id, id) on delete set null (bono_id)
);
-- Una cita o un bono tienen como mucho un cargo vivo.
create unique index cargos_por_cita on cargos (cita_id) where estado = 'abierto' and cita_id is not null;
create unique index cargos_por_bono on cargos (bono_id) where estado = 'abierto' and bono_id is not null;
create index cargos_paciente on cargos (paciente_id, creado_en desc);

create table contadores (
  clinica_id uuid not null references clinicas (id) on delete cascade,
  serie      text not null,
  ultimo     int not null default 0,
  primary key (clinica_id, serie)
);

create table pagos (
  id                    bigint generated always as identity primary key,
  clinica_id            uuid not null references clinicas (id) on delete cascade,
  cargo_id              bigint not null,
  paciente_id           bigint not null,
  tipo                  text not null default 'pago' check (tipo in ('pago', 'devolucion')),
  devuelve_pago_id      bigint references pagos (id),
  importe_centimos      int not null check (importe_centimos > 0),
  metodo                text not null check (metodo in ('efectivo', 'tarjeta', 'transferencia', 'bizum', 'enlace', 'otro')),
  fecha                 date not null,
  recibo_serie          text not null,
  recibo_numero         int not null,
  nota                  text check (length(nota) <= 300),
  proveedor_ref         text,           -- referencia del proveedor de pago (nunca datos de la tarjeta)
  registrado_por        uuid,
  registrado_por_nombre text,
  clave_idempotencia    text,
  creado_en             timestamptz not null default now(),
  unique (clinica_id, id),
  unique (clinica_id, recibo_serie, recibo_numero),
  unique (clinica_id, clave_idempotencia),
  unique (proveedor_ref),
  foreign key (clinica_id, cargo_id) references cargos (clinica_id, id) on delete cascade,
  foreign key (clinica_id, paciente_id) references pacientes (clinica_id, id) on delete cascade
);
create index pagos_cargo on pagos (cargo_id);
create index pagos_fecha on pagos (clinica_id, fecha);

create table enlaces_pago (
  id                 bigint generated always as identity primary key,
  clinica_id         uuid not null references clinicas (id) on delete cascade,
  cargo_id           bigint not null,
  paciente_id        bigint not null,
  importe_centimos   int not null check (importe_centimos > 0),
  proveedor          text not null check (proveedor in ('stripe')),
  modo               text not null check (modo in ('prueba', 'real')),
  estado             text not null default 'solicitado'
                     check (estado in ('solicitado', 'creado', 'pagado', 'caducado', 'fallido', 'cancelado')),
  enviar             boolean not null default true,
  url                text,
  proveedor_id       text unique,      -- id de la sesión de pago en el proveedor
  error              text,
  reclamado_en       timestamptz,      -- el adaptador lo ha cogido para crearlo
  creado_por         uuid,
  creado_en          timestamptz not null default now(),
  url_creada_en      timestamptz,
  caduca_en          timestamptz,
  pagado_en          timestamptz,
  unique (clinica_id, id),
  foreign key (clinica_id, cargo_id) references cargos (clinica_id, id) on delete cascade,
  foreign key (clinica_id, paciente_id) references pacientes (clinica_id, id) on delete cascade
);
create unique index enlace_pago_vivo on enlaces_pago (cargo_id) where estado in ('solicitado', 'creado');

-- Avisos del proveedor ya procesados (el proveedor puede mandar el mismo varias veces). Sin el contenido del aviso.
create table pago_eventos (
  proveedor   text not null,
  evento_id   text not null,
  tipo        text not null,
  resultado   text,
  recibido_en timestamptz not null default now(),
  primary key (proveedor, evento_id)
);

-- ---------------------------------------------------------------- asistente de voz

create table ordenes_voz (
  id           bigint generated always as identity primary key,
  clinica_id   uuid not null references clinicas (id) on delete cascade,
  miembro_id   bigint not null,
  texto        text check (length(texto) <= 500),      -- lo dictado; se borra a los 30 días
  accion       text not null,
  datos        jsonb not null default '{}'::jsonb,
  paciente_id  bigint,
  estado       text not null check (estado in ('aclarar', 'propuesta', 'ejecutada', 'descartada', 'fallida', 'consulta')),
  resumen      text,
  resultado    jsonb,
  creado_en    timestamptz not null default now(),
  resuelta_en  timestamptz,
  unique (clinica_id, id),
  foreign key (clinica_id, paciente_id) references pacientes (clinica_id, id) on delete cascade
);
create index ordenes_voz_miembro on ordenes_voz (miembro_id, creado_en desc);

alter table cargos       enable row level security;
alter table contadores   enable row level security;
alter table pagos        enable row level security;
alter table enlaces_pago enable row level security;
alter table pago_eventos enable row level security;
alter table ordenes_voz  enable row level security;

-- Los pagos no se tocan: un error se corrige con una devolución.
create function _pago_inmutable() returns trigger language plpgsql as $$
begin
  raise exception 'pago_inmutable' using errcode = '42501';
end;
$$;
create trigger pago_inmutable before update or delete on pagos for each row execute function _pago_inmutable();

-- ---------------------------------------------------------------- plantillas

create function _plantillas_fase5(p_clinica uuid) returns void
language sql security definer set search_path = nutricion, extensions, pg_temp as $$
  insert into plantillas_mensaje (clinica_id, clave, texto) values
    (p_clinica, 'enlace_pago', 'Hola {paciente}, aquí tienes el enlace para pagar "{texto}" ({importe}) de forma segura: {url_pago} . El pago se hace en la página de nuestro proveedor; {clinica} no ve los datos de tu tarjeta.')
  on conflict do nothing;
$$;
create function _clinica_nueva_fase5() returns trigger
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
begin
  perform _plantillas_fase5(new.id);
  return null;
end;
$$;
create trigger clinica_nueva_fase5 after insert on clinicas for each row execute function _clinica_nueva_fase5();
select _plantillas_fase5(id) from clinicas;

-- ---------------------------------------------------------------- auxiliares

create function _euros(p_centimos bigint) returns text language sql immutable as $$
  select translate(to_char(p_centimos / 100.0, 'FM999G999G990D00'), ',.', '.,') || ' €'
$$;

-- Lo cobrado de un cargo (pagos menos devoluciones).
create function _cobrado(p_cargo bigint) returns bigint language sql stable security definer
set search_path = nutricion, extensions, pg_temp as $$
  select coalesce(sum(case tipo when 'pago' then importe_centimos else -importe_centimos end), 0)
  from pagos where cargo_id = p_cargo
$$;

create function _estado_cargo(p_cargo bigint) returns text language sql stable security definer
set search_path = nutricion, extensions, pg_temp as $$
  select case when c.estado = 'anulado' then 'anulado'
              when _cobrado(c.id) >= c.importe_centimos then 'pagado'
              when _cobrado(c.id) > 0 then 'parcial'
              when exists (select 1 from pagos p where p.cargo_id = c.id and p.tipo = 'devolucion') then 'devuelto'
              else 'pendiente' end
  from cargos c where c.id = p_cargo
$$;

create function _pago_json(p_pago bigint) returns jsonb
language sql stable security definer set search_path = nutricion, extensions, pg_temp as $$
  select jsonb_build_object('id', p.id, 'cargo_id', p.cargo_id, 'tipo', p.tipo, 'importe', round(p.importe_centimos / 100.0, 2),
    'metodo', p.metodo, 'fecha', p.fecha, 'recibo', p.recibo_serie || '-' || p.recibo_numero, 'nota', p.nota,
    'registrado_por', p.registrado_por_nombre, 'devuelve_pago_id', p.devuelve_pago_id, 'creado', _local(p.creado_en, cl.zona_horaria),
    'devuelto', round((select coalesce(sum(d.importe_centimos), 0) from pagos d where d.devuelve_pago_id = p.id) / 100.0, 2))
  from pagos p join clinicas cl on cl.id = p.clinica_id where p.id = p_pago
$$;

create function _cargo_json(p_cargo bigint) returns jsonb
language sql stable security definer set search_path = nutricion, extensions, pg_temp as $$
  select jsonb_build_object('id', c.id, 'paciente_id', c.paciente_id,
    'paciente', (select trim(nombre || ' ' || coalesce(apellidos, '')) from pacientes where id = c.paciente_id),
    'tipo', c.tipo, 'concepto', c.concepto, 'cita_id', c.cita_id, 'bono_id', c.bono_id,
    'importe', round(c.importe_centimos / 100.0, 2), 'cobrado', round(_cobrado(c.id) / 100.0, 2),
    'pendiente', round(greatest(c.importe_centimos - _cobrado(c.id), 0) / 100.0, 2),
    'estado', _estado_cargo(c.id), 'motivo_anulacion', c.motivo_anulacion,
    'creado', _local(c.creado_en, cl.zona_horaria),
    'factura_estado', c.factura_estado, 'factura_datos', c.factura_datos, 'factura_numero', c.factura_numero,
    'pagos', (select coalesce(jsonb_agg(_pago_json(p.id) order by p.id), '[]'::jsonb) from pagos p where p.cargo_id = c.id),
    'enlace', (select jsonb_build_object('id', e.id, 'estado', e.estado, 'url', e.url, 'modo', e.modo,
                 'importe', round(e.importe_centimos / 100.0, 2), 'creado', _local(e.creado_en, cl.zona_horaria),
                 'caduca', _local(e.caduca_en, cl.zona_horaria), 'error', e.error)
               from enlaces_pago e where e.cargo_id = c.id order by e.id desc limit 1))
  from cargos c join clinicas cl on cl.id = c.clinica_id where c.id = p_cargo
$$;

-- Siguiente número de recibo de la serie de la consulta (sin huecos: se bloquea la fila del contador).
create function _siguiente_recibo(p_clinica uuid, out o_serie text, out o_numero int)
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
begin
  select c.serie_recibos into o_serie from clinicas c where c.id = p_clinica;
  insert into contadores as k (clinica_id, serie, ultimo) values (p_clinica, o_serie, 1)
  on conflict (clinica_id, serie) do update set ultimo = k.ultimo + 1
  returning k.ultimo into o_numero;
end;
$$;

-- El estado de pago del bono sale de su cargo.
create function _sincronizar_bono(p_cargo bigint) returns void
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare c cargos; v text;
begin
  select * into c from cargos where id = p_cargo;
  if c.bono_id is null then return; end if;
  v := _estado_cargo(c.id);
  update bonos set pago_estado = case v when 'pagado' then 'pagado' when 'parcial' then 'parcial' else 'pendiente' end
  where id = c.bono_id and c.estado = 'abierto';
end;
$$;

create function _registrar_pago(p_cargo bigint, p_importe int, p_metodo text, p_fecha date, p_nota text,
                                p_ref text, p_clave text, p_nombre text) returns bigint
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare c cargos; r record; v_id bigint;
begin
  select * into c from cargos where id = p_cargo;
  select * into r from _siguiente_recibo(c.clinica_id);
  insert into pagos (clinica_id, cargo_id, paciente_id, importe_centimos, metodo, fecha, recibo_serie, recibo_numero, nota,
                     proveedor_ref, registrado_por, registrado_por_nombre, clave_idempotencia)
  values (c.clinica_id, c.id, c.paciente_id, p_importe, p_metodo, p_fecha, r.o_serie, r.o_numero, p_nota, p_ref, auth.uid(),
          p_nombre, p_clave)
  returning id into v_id;
  perform _sincronizar_bono(c.id);
  -- Ya no hace falta el enlace de pago si el cargo queda pagado de otra forma.
  if _estado_cargo(c.id) = 'pagado' then
    update enlaces_pago set estado = 'cancelado', error = 'pagado por otra vía'
    where cargo_id = c.id and estado in ('solicitado', 'creado') and p_metodo <> 'enlace';
  end if;
  return v_id;
end;
$$;

create function _crear_cargo(p_clinica uuid, p_paciente bigint, p_tipo text, p_concepto text, p_importe int,
                             p_cita bigint default null, p_bono bigint default null, p_clave text default null) returns bigint
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare v_id bigint;
begin
  insert into cargos (clinica_id, paciente_id, tipo, concepto, cita_id, bono_id, importe_centimos, clave_idempotencia, creado_por)
  values (p_clinica, p_paciente, p_tipo, left(p_concepto, 200), p_cita, p_bono, p_importe, p_clave, auth.uid())
  on conflict do nothing
  returning id into v_id;
  return coalesce(v_id, (select id from cargos where estado = 'abierto' and
    ((p_cita is not null and cita_id = p_cita) or (p_bono is not null and bono_id = p_bono)
     or (p_clave is not null and clinica_id = p_clinica and clave_idempotencia = p_clave)) limit 1));
end;
$$;

create function _concepto_cita(p_cita bigint) returns text language sql stable security definer
set search_path = nutricion, extensions, pg_temp as $$
  select s.nombre || ' · ' || to_char(c.inicio at time zone _tz(c.clinica_id), 'DD/MM/YYYY')
  from citas c join servicios s on s.id = c.servicio_id where c.id = p_cita
$$;

-- Una consulta realizada que no va con bono y tiene precio queda por cobrar. Si se deshace, el cargo se anula
-- (solo si no se ha cobrado nada).
create function _citas_cobro() returns trigger
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
begin
  if new.estado = 'realizada' and old.estado <> 'realizada' and new.bono_id is null and coalesce(new.precio_centimos, 0) > 0 then
    perform _crear_cargo(new.clinica_id, new.paciente_id, 'cita', _concepto_cita(new.id), new.precio_centimos, new.id);
  elsif old.estado = 'realizada' and new.estado <> 'realizada' then
    update cargos set estado = 'anulado', anulado_en = now(), motivo_anulacion = 'La consulta dejó de estar realizada'
    where cita_id = new.id and estado = 'abierto' and _cobrado(id) = 0
      and not exists (select 1 from pagos p where p.cargo_id = cargos.id);
  end if;
  return null;
end;
$$;
create trigger citas_cobro after update of estado on citas for each row execute function _citas_cobro();

-- ---------------------------------------------------------------- API: cobros

create function cobros_paciente(p_clinica uuid, p_paciente bigint) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
begin
  perform _miembro(p_clinica);
  return jsonb_build_object('ok', true,
    'cargos', (select coalesce(jsonb_agg(_cargo_json(c.id) order by c.creado_en desc, c.id desc), '[]'::jsonb)
               from cargos c where c.paciente_id = p_paciente and c.clinica_id = p_clinica),
    'pendiente', (select round(coalesce(sum(greatest(c.importe_centimos - _cobrado(c.id), 0)), 0) / 100.0, 2)
                  from cargos c where c.paciente_id = p_paciente and c.clinica_id = p_clinica and c.estado = 'abierto'),
    'cobrado', (select round(coalesce(sum(case p.tipo when 'pago' then p.importe_centimos else -p.importe_centimos end), 0) / 100.0, 2)
                from pagos p where p.paciente_id = p_paciente and p.clinica_id = p_clinica));
end;
$$;

-- d: {paciente_id, concepto, importe} o {cita_id} (cobrar una consulta antes de hacerla); clave? para reintentos.
create function crear_cargo(p_clinica uuid, d jsonb) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare ci citas; v_id bigint; v_imp numeric;
begin
  perform _miembro(p_clinica);
  if d->>'cita_id' is not null then
    select * into ci from citas where id = (d->>'cita_id')::bigint and clinica_id = p_clinica;
    if ci.id is null then return jsonb_build_object('ok', false, 'motivo', 'cita_no_existe'); end if;
    if ci.estado = 'cancelada' then return jsonb_build_object('ok', false, 'motivo', 'cita_cancelada'); end if;
    if ci.bono_id is not null then return jsonb_build_object('ok', false, 'motivo', 'cita_con_bono'); end if;
    if coalesce(ci.precio_centimos, 0) = 0 then return jsonb_build_object('ok', false, 'motivo', 'sin_precio'); end if;
    v_id := _crear_cargo(p_clinica, ci.paciente_id, 'cita', _concepto_cita(ci.id), ci.precio_centimos, ci.id);
  else
    if not exists (select 1 from pacientes where id = (d->>'paciente_id')::bigint and clinica_id = p_clinica) then
      return jsonb_build_object('ok', false, 'motivo', 'paciente_no_existe');
    end if;
    if nullif(trim(coalesce(d->>'concepto', '')), '') is null then return jsonb_build_object('ok', false, 'motivo', 'falta_concepto'); end if;
    begin v_imp := replace(d->>'importe', ',', '.')::numeric; exception when others then v_imp := null; end;
    if v_imp is null or v_imp <= 0 or v_imp > 100000 then return jsonb_build_object('ok', false, 'motivo', 'importe_no_valido'); end if;
    v_id := _crear_cargo(p_clinica, (d->>'paciente_id')::bigint, 'otro', trim(d->>'concepto'), round(v_imp * 100)::int,
                         null, null, nullif(d->>'clave', ''));
  end if;
  perform _auditar(p_clinica, 'crear_cargo', 'cargo', v_id::text, (select paciente_id from cargos where id = v_id));
  return jsonb_build_object('ok', true, 'cargo', _cargo_json(v_id));
end;
$$;

-- d: {cargo_id, importe? (por defecto, lo pendiente), metodo, fecha?, nota?, clave?}
create function registrar_pago(p_clinica uuid, d jsonb) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare m miembros := _miembro(p_clinica); c cargos; v_pend bigint; v_imp numeric; v_cent int; v_id bigint; v_fecha date;
begin
  if d->>'clave' is not null then
    select id into v_id from pagos where clinica_id = p_clinica and clave_idempotencia = d->>'clave';
    if v_id is not null then return jsonb_build_object('ok', true, 'repetida', true, 'pago', _pago_json(v_id),
                                                       'cargo', _cargo_json((select cargo_id from pagos where id = v_id))); end if;
  end if;
  select * into c from cargos where id = (d->>'cargo_id')::bigint and clinica_id = p_clinica for update;
  if c.id is null then return jsonb_build_object('ok', false, 'motivo', 'cargo_no_existe'); end if;
  if c.estado = 'anulado' then return jsonb_build_object('ok', false, 'motivo', 'cargo_anulado'); end if;
  if coalesce(d->>'metodo', '') not in ('efectivo', 'tarjeta', 'transferencia', 'bizum', 'otro') then
    return jsonb_build_object('ok', false, 'motivo', 'metodo_no_valido');
  end if;
  v_pend := c.importe_centimos - _cobrado(c.id);
  if v_pend <= 0 then return jsonb_build_object('ok', false, 'motivo', 'ya_pagado'); end if;
  if nullif(d->>'importe', '') is null then v_cent := v_pend;
  else
    begin v_imp := replace(d->>'importe', ',', '.')::numeric; exception when others then v_imp := null; end;
    if v_imp is null or v_imp <= 0 then return jsonb_build_object('ok', false, 'motivo', 'importe_no_valido'); end if;
    v_cent := round(v_imp * 100)::int;
    if v_cent > v_pend then return jsonb_build_object('ok', false, 'motivo', 'importe_mayor_que_pendiente',
                                                      'pendiente', round(v_pend / 100.0, 2)); end if;
  end if;
  v_fecha := coalesce(nullif(d->>'fecha', '')::date, _hoy(_tz(p_clinica)));
  if v_fecha > _hoy(_tz(p_clinica)) then return jsonb_build_object('ok', false, 'motivo', 'fecha_futura'); end if;
  begin
    v_id := _registrar_pago(c.id, v_cent, d->>'metodo', v_fecha, left(nullif(trim(coalesce(d->>'nota', '')), ''), 300), null,
                            nullif(d->>'clave', ''), m.nombre);
  exception when unique_violation then
    select id into v_id from pagos where clinica_id = p_clinica and clave_idempotencia = d->>'clave';
    return jsonb_build_object('ok', true, 'repetida', true, 'pago', _pago_json(v_id), 'cargo', _cargo_json(c.id));
  end;
  perform _auditar(p_clinica, 'registrar_pago', 'pago', v_id::text, c.paciente_id,
                   jsonb_build_object('importe', v_cent, 'metodo', d->>'metodo'));
  return jsonb_build_object('ok', true, 'pago', _pago_json(v_id), 'cargo', _cargo_json(c.id));
end;
$$;

-- Devolución (total o parcial) de un pago. Solo el propietario. d: {pago_id, importe?, motivo, metodo?}
create function registrar_devolucion(p_clinica uuid, d jsonb) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare m miembros := _miembro(p_clinica, array['propietario']); p pagos; v_max bigint; v_cent int; v_imp numeric; r record;
        v_id bigint;
begin
  select * into p from pagos where id = (d->>'pago_id')::bigint and clinica_id = p_clinica and tipo = 'pago';
  if p.id is null then return jsonb_build_object('ok', false, 'motivo', 'pago_no_existe'); end if;
  perform 1 from cargos where id = p.cargo_id for update;
  if nullif(trim(coalesce(d->>'motivo', '')), '') is null then return jsonb_build_object('ok', false, 'motivo', 'falta_motivo'); end if;
  v_max := p.importe_centimos - (select coalesce(sum(importe_centimos), 0) from pagos where devuelve_pago_id = p.id);
  if v_max <= 0 then return jsonb_build_object('ok', false, 'motivo', 'ya_devuelto'); end if;
  if nullif(d->>'importe', '') is null then v_cent := v_max;
  else
    begin v_imp := replace(d->>'importe', ',', '.')::numeric; exception when others then v_imp := null; end;
    if v_imp is null or v_imp <= 0 then return jsonb_build_object('ok', false, 'motivo', 'importe_no_valido'); end if;
    v_cent := round(v_imp * 100)::int;
    if v_cent > v_max then return jsonb_build_object('ok', false, 'motivo', 'importe_mayor_que_pagado'); end if;
  end if;
  select * into r from _siguiente_recibo(p_clinica);
  insert into pagos (clinica_id, cargo_id, paciente_id, tipo, devuelve_pago_id, importe_centimos, metodo, fecha, recibo_serie,
                     recibo_numero, nota, registrado_por, registrado_por_nombre)
  values (p_clinica, p.cargo_id, p.paciente_id, 'devolucion', p.id, v_cent,
          coalesce(nullif(d->>'metodo', ''), case when p.metodo = 'enlace' then 'tarjeta' else p.metodo end),
          _hoy(_tz(p_clinica)), r.o_serie, r.o_numero, left(trim(d->>'motivo'), 300), auth.uid(), m.nombre)
  returning id into v_id;
  perform _sincronizar_bono(p.cargo_id);
  perform _auditar(p_clinica, 'registrar_devolucion', 'pago', v_id::text, p.paciente_id, jsonb_build_object('importe', v_cent));
  return jsonb_build_object('ok', true, 'pago', _pago_json(v_id), 'cargo', _cargo_json(p.cargo_id),
    'aviso', case when p.metodo = 'enlace' then 'La devolución de un pago con tarjeta se hace en el panel del proveedor; aquí solo queda apuntada.' end);
end;
$$;

-- Anular lo que se debe (no lo cobrado). Solo el propietario.
create function anular_cargo(p_clinica uuid, p_cargo bigint, p_motivo text) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare c cargos;
begin
  perform _miembro(p_clinica, array['propietario']);
  select * into c from cargos where id = p_cargo and clinica_id = p_clinica for update;
  if c.id is null then return jsonb_build_object('ok', false, 'motivo', 'cargo_no_existe'); end if;
  if c.estado = 'anulado' then return jsonb_build_object('ok', true, 'repetida', true); end if;
  if nullif(trim(coalesce(p_motivo, '')), '') is null then return jsonb_build_object('ok', false, 'motivo', 'falta_motivo'); end if;
  if _cobrado(c.id) > 0 then return jsonb_build_object('ok', false, 'motivo', 'cargo_con_pagos'); end if;
  update cargos set estado = 'anulado', anulado_en = now(), motivo_anulacion = left(trim(p_motivo), 300) where id = c.id;
  update enlaces_pago set estado = 'cancelado', error = 'cargo anulado' where cargo_id = c.id and estado in ('solicitado', 'creado');
  if c.bono_id is not null then update bonos set pago_estado = 'pendiente' where id = c.bono_id; end if;
  perform _auditar(p_clinica, 'anular_cargo', 'cargo', c.id::text, c.paciente_id);
  return jsonb_build_object('ok', true, 'cargo', _cargo_json(c.id));
end;
$$;

-- Recibo de un pago o devolución (no es una factura).
create function recibo(p_clinica uuid, p_pago bigint) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare p pagos; cl clinicas; c cargos; pa pacientes;
begin
  perform _miembro(p_clinica);
  select * into p from pagos where id = p_pago and clinica_id = p_clinica;
  if p.id is null then return jsonb_build_object('ok', false, 'motivo', 'pago_no_existe'); end if;
  select * into cl from clinicas where id = p_clinica;
  select * into c from cargos where id = p.cargo_id;
  select * into pa from pacientes where id = p.paciente_id;
  return jsonb_build_object('ok', true, 'numero', p.recibo_serie || '-' || p.recibo_numero, 'tipo', p.tipo,
    'fecha', p.fecha, 'importe', round(p.importe_centimos / 100.0, 2), 'importe_texto', _euros(p.importe_centimos),
    'metodo', p.metodo, 'concepto', c.concepto, 'nota', p.nota,
    'paciente', trim(pa.nombre || ' ' || coalesce(pa.apellidos, '')),
    'emisor', jsonb_build_object('nombre', coalesce(cl.razon_social, cl.nombre), 'comercial', cl.nombre, 'nif', cl.nif,
                                 'direccion', cl.direccion, 'telefono', cl.telefono, 'email', cl.email),
    'devuelve', case when p.devuelve_pago_id is not null then
      (select recibo_serie || '-' || recibo_numero from pagos where id = p.devuelve_pago_id) end);
end;
$$;

-- d: {nombre, nif, direccion}. Se apunta que lo quiere con factura; se emite en el programa de facturación.
create function pedir_factura(p_clinica uuid, p_cargo bigint, d jsonb) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare c cargos;
begin
  perform _miembro(p_clinica);
  select * into c from cargos where id = p_cargo and clinica_id = p_clinica for update;
  if c.id is null or c.estado = 'anulado' then return jsonb_build_object('ok', false, 'motivo', 'cargo_no_existe'); end if;
  if c.factura_estado = 'emitida' then return jsonb_build_object('ok', false, 'motivo', 'factura_ya_emitida'); end if;
  if nullif(trim(coalesce(d->>'nombre', '')), '') is null or nullif(trim(coalesce(d->>'nif', '')), '') is null then
    return jsonb_build_object('ok', false, 'motivo', 'faltan_datos_factura');
  end if;
  update cargos set factura_estado = 'pedida', factura_pedida_en = coalesce(factura_pedida_en, now()),
    factura_datos = jsonb_build_object('nombre', left(trim(d->>'nombre'), 160), 'nif', upper(left(trim(d->>'nif'), 20)),
                                       'direccion', left(nullif(trim(coalesce(d->>'direccion', '')), ''), 300))
  where id = c.id;
  perform _auditar(p_clinica, 'pedir_factura', 'cargo', c.id::text, c.paciente_id);
  return jsonb_build_object('ok', true, 'cargo', _cargo_json(c.id));
end;
$$;

create function registrar_factura(p_clinica uuid, p_cargo bigint, p_numero text) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare c cargos;
begin
  perform _miembro(p_clinica, array['propietario', 'recepcion']);
  select * into c from cargos where id = p_cargo and clinica_id = p_clinica for update;
  if c.id is null or c.estado = 'anulado' then return jsonb_build_object('ok', false, 'motivo', 'cargo_no_existe'); end if;
  if nullif(trim(coalesce(p_numero, '')), '') is null then return jsonb_build_object('ok', false, 'motivo', 'falta_numero'); end if;
  if c.factura_estado = 'emitida' and c.factura_numero = trim(p_numero) then return jsonb_build_object('ok', true, 'repetida', true); end if;
  update cargos set factura_estado = 'emitida', factura_numero = left(trim(p_numero), 40), factura_emitida_en = now(),
    factura_pedida_en = coalesce(factura_pedida_en, now())
  where id = c.id;
  perform _auditar(p_clinica, 'registrar_factura', 'cargo', c.id::text, c.paciente_id);
  return jsonb_build_object('ok', true, 'cargo', _cargo_json(c.id));
end;
$$;

-- Listados para la pantalla de cobros. p_vista: 'pendientes' | 'pagos' | 'facturas'.
create function lista_cobros(p_clinica uuid, p_vista text default 'pendientes', p_desde date default null,
                             p_hasta date default null) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare m miembros := _miembro(p_clinica); v_tz text := _tz(p_clinica);
        v_desde date := coalesce(p_desde, _hoy(_tz(p_clinica)) - 30); v_hasta date := coalesce(p_hasta, _hoy(_tz(p_clinica)));
begin
  if p_vista = 'pendientes' then
    return (select coalesce(jsonb_agg(_cargo_json(c.id) order by c.creado_en), '[]'::jsonb) from cargos c
            where c.clinica_id = p_clinica and c.estado = 'abierto' and _cobrado(c.id) < c.importe_centimos);
  elsif p_vista = 'pagos' then
    if m.rol <> 'propietario' then
      -- El resto del equipo ve los cobros de hoy (cuadrar la caja), no la facturación del negocio.
      v_desde := greatest(v_desde, _hoy(v_tz)); v_hasta := greatest(v_hasta, _hoy(v_tz));
    end if;
    return (select coalesce(jsonb_agg(_pago_json(p.id) || jsonb_build_object('concepto', c.concepto, 'paciente',
              trim(pa.nombre || ' ' || coalesce(pa.apellidos, '')), 'paciente_id', pa.id) order by p.fecha, p.id), '[]'::jsonb)
            from pagos p join cargos c on c.id = p.cargo_id join pacientes pa on pa.id = p.paciente_id
            where p.clinica_id = p_clinica and p.fecha between v_desde and v_hasta);
  elsif p_vista = 'facturas' then
    return (select coalesce(jsonb_agg(_cargo_json(c.id) order by c.factura_pedida_en), '[]'::jsonb) from cargos c
            where c.clinica_id = p_clinica and c.factura_estado = 'pedida' and c.estado = 'abierto');
  end if;
  return '[]'::jsonb;
end;
$$;

-- Pagos de un periodo para la gestoría o el programa de facturación (CSV en la aplicación). Solo el propietario.
create function exportar_pagos(p_clinica uuid, p_desde date, p_hasta date) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
begin
  perform _miembro(p_clinica, array['propietario']);
  perform _auditar(p_clinica, 'exportar_pagos', 'clinica', p_clinica::text, null,
                   jsonb_build_object('desde', p_desde, 'hasta', p_hasta));
  return (select coalesce(jsonb_agg(jsonb_build_object('recibo', p.recibo_serie || '-' || p.recibo_numero, 'fecha', p.fecha,
      'tipo', p.tipo, 'paciente', trim(pa.nombre || ' ' || coalesce(pa.apellidos, '')), 'concepto', c.concepto,
      'importe', round(case p.tipo when 'pago' then p.importe_centimos else -p.importe_centimos end / 100.0, 2),
      'metodo', p.metodo, 'factura', c.factura_numero, 'factura_nif', c.factura_datos->>'nif') order by p.fecha, p.id), '[]'::jsonb)
    from pagos p join cargos c on c.id = p.cargo_id join pacientes pa on pa.id = p.paciente_id
    where p.clinica_id = p_clinica and p.fecha between p_desde and p_hasta);
end;
$$;

-- ---------------------------------------------------------------- bonos: su cobro

-- Vender un bono crea lo que se debe por él. Si se cobra en el momento: pago_estado 'pagado' (y metodo), o
-- 'parcial' con importe_pagado.
alter function vender_bono(uuid, jsonb) rename to _vender_bono_fase4;
create function vender_bono(p_clinica uuid, d jsonb) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare r jsonb; b bonos; v_cargo bigint; v_metodo text := coalesce(nullif(d->>'metodo', ''), 'otro'); v_cent int; v_imp numeric;
begin
  if v_metodo not in ('efectivo', 'tarjeta', 'transferencia', 'bizum', 'otro') then
    return jsonb_build_object('ok', false, 'motivo', 'metodo_no_valido');
  end if;
  if d->>'pago_estado' = 'parcial' and nullif(d->>'importe_pagado', '') is not null then
    begin v_imp := replace(d->>'importe_pagado', ',', '.')::numeric; exception when others then v_imp := null; end;
    if v_imp is null or v_imp <= 0 then return jsonb_build_object('ok', false, 'motivo', 'importe_no_valido'); end if;
  end if;
  r := _vender_bono_fase4(p_clinica, d);
  if not (r->>'ok')::boolean or coalesce((r->>'repetida')::boolean, false) then return r; end if;
  select * into b from bonos where id = (r->'bono'->>'id')::bigint;
  if coalesce(b.precio_centimos, 0) = 0 then return r; end if;
  v_cargo := _crear_cargo(p_clinica, b.paciente_id, 'bono', 'Bono: ' || b.nombre, b.precio_centimos, null, b.id);
  v_cent := case when d->>'pago_estado' = 'pagado' then b.precio_centimos
                 when v_imp is not null then least(round(v_imp * 100)::int, b.precio_centimos) end;
  if v_cent is not null then
    perform _registrar_pago(v_cargo, v_cent, v_metodo, b.fecha_compra, null, null, null, (_miembro(p_clinica)).nombre);
  end if;
  return r || jsonb_build_object('cargo', _cargo_json(v_cargo));
end;
$$;

-- El estado de pago de un bono con cargo ya no se cambia a mano: se registran pagos. Anular el bono anula lo que se
-- debía (si no se había cobrado nada).
alter function editar_bono(uuid, bigint, jsonb) rename to _editar_bono_fase4;
create function editar_bono(p_clinica uuid, p_id bigint, d jsonb) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare r jsonb; v_cargo bigint;
begin
  perform _miembro(p_clinica);
  select id into v_cargo from cargos where bono_id = p_id and clinica_id = p_clinica and estado = 'abierto';
  if v_cargo is not null and d ? 'pago_estado' and d->>'pago_estado' is distinct from (select pago_estado from bonos where id = p_id) then
    return jsonb_build_object('ok', false, 'motivo', 'usar_cobros');
  end if;
  r := _editar_bono_fase4(p_clinica, p_id, d - case when v_cargo is not null then 'pago_estado' else '' end);
  if (r->>'ok')::boolean and d->>'estado' = 'anulado' and v_cargo is not null and _cobrado(v_cargo) = 0 then
    update cargos set estado = 'anulado', anulado_en = now(), motivo_anulacion = 'Bono anulado' where id = v_cargo;
    update enlaces_pago set estado = 'cancelado', error = 'bono anulado' where cargo_id = v_cargo and estado in ('solicitado', 'creado');
  end if;
  return r;
end;
$$;

-- ---------------------------------------------------------------- enlaces de pago (proveedor)

-- Pide al proveedor un enlace de pago por lo pendiente del cargo. Lo crea el adaptador (fuera de la base de datos,
-- con la clave secreta del proveedor) y, si p_enviar, se le manda al paciente.
create function solicitar_enlace_pago(p_clinica uuid, p_cargo bigint, p_enviar boolean default true) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare c cargos; cl clinicas; v_pend bigint; v_id bigint;
begin
  perform _miembro(p_clinica);
  select * into cl from clinicas where id = p_clinica;
  if cl.pago_proveedor = 'ninguno' then return jsonb_build_object('ok', false, 'motivo', 'sin_proveedor_pago'); end if;
  select * into c from cargos where id = p_cargo and clinica_id = p_clinica for update;
  if c.id is null or c.estado = 'anulado' then return jsonb_build_object('ok', false, 'motivo', 'cargo_no_existe'); end if;
  v_pend := c.importe_centimos - _cobrado(c.id);
  if v_pend <= 0 then return jsonb_build_object('ok', false, 'motivo', 'ya_pagado'); end if;
  select id into v_id from enlaces_pago where cargo_id = c.id and estado in ('solicitado', 'creado');
  if v_id is not null then
    if (select importe_centimos from enlaces_pago where id = v_id) = v_pend then
      return jsonb_build_object('ok', true, 'repetida', true, 'cargo', _cargo_json(c.id));
    end if;
    -- Lo pendiente ha cambiado (un pago parcial): el enlace anterior ya no vale.
    update enlaces_pago set estado = 'cancelado', error = 'importe cambiado' where id = v_id;
  end if;
  if p_enviar and not exists (select 1 from pacientes where id = c.paciente_id and (telefono is not null or email is not null)) then
    return jsonb_build_object('ok', false, 'motivo', 'falta_contacto');
  end if;
  insert into enlaces_pago (clinica_id, cargo_id, paciente_id, importe_centimos, proveedor, modo, enviar, creado_por)
  values (p_clinica, c.id, c.paciente_id, v_pend, cl.pago_proveedor, cl.pago_modo, p_enviar, auth.uid())
  returning id into v_id;
  perform _auditar(p_clinica, 'solicitar_enlace_pago', 'cargo', c.id::text, c.paciente_id, jsonb_build_object('importe', v_pend));
  return jsonb_build_object('ok', true, 'cargo', _cargo_json(c.id));
end;
$$;

create function cancelar_enlace_pago(p_clinica uuid, p_cargo bigint) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
begin
  perform _miembro(p_clinica);
  update enlaces_pago set estado = 'cancelado', error = 'cancelado por el equipo'
  where cargo_id = p_cargo and clinica_id = p_clinica and estado in ('solicitado', 'creado');
  perform _auditar(p_clinica, 'cancelar_enlace_pago', 'cargo', p_cargo::text);
  return jsonb_build_object('ok', true, 'cargo', _cargo_json(p_cargo));
end;
$$;

-- Para el adaptador (service_role): enlaces por crear. Solo lo necesario para el proveedor: importe, concepto y
-- nombre de la consulta; ningún dato de salud ni de contacto del paciente.
create function motor_pagos_pendientes(p_limite int default 20) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare v jsonb;
begin
  with x as (
    select e.id from enlaces_pago e
    where e.estado = 'solicitado' and (e.reclamado_en is null or e.reclamado_en < now() - interval '2 minutes')
    order by e.id limit p_limite for update skip locked),
  u as (update enlaces_pago e set reclamado_en = now() from x where e.id = x.id returning e.id)
  select coalesce(jsonb_agg(jsonb_build_object('enlace_id', e.id, 'proveedor', e.proveedor, 'modo', e.modo,
      'importe_centimos', e.importe_centimos, 'moneda', 'eur', 'concepto', c.concepto, 'clinica', cl.nombre,
      'clave', 'corvex-enlace-' || e.id) order by e.id), '[]'::jsonb) into v
  from u join enlaces_pago e on e.id = u.id join cargos c on c.id = e.cargo_id join clinicas cl on cl.id = e.clinica_id;
  return v;
end;
$$;

-- El proveedor ha creado la sesión de pago: se guarda el enlace y se le manda al paciente.
create function motor_pago_creado(p_enlace bigint, p_url text, p_ref text, p_caduca timestamptz default null) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare e enlaces_pago; c cargos;
begin
  select * into e from enlaces_pago where id = p_enlace for update;
  if e.id is null then return jsonb_build_object('ok', false, 'motivo', 'enlace_no_existe'); end if;
  if e.estado <> 'solicitado' then return jsonb_build_object('ok', true, 'repetida', true, 'estado', e.estado); end if;
  -- Solo enlaces seguros; http únicamente para el simulador local del adaptador.
  if p_url !~ '^https://' and p_url !~ '^http://(127\.0\.0\.1|localhost)[:/]' then
    return jsonb_build_object('ok', false, 'motivo', 'url_no_valida');
  end if;
  update enlaces_pago set estado = 'creado', url = p_url, proveedor_id = p_ref, url_creada_en = now(),
    caduca_en = coalesce(p_caduca, now() + interval '24 hours'), error = null
  where id = e.id;
  select * into c from cargos where id = e.cargo_id;
  if e.enviar then
    perform _encolar(e.clinica_id, 'enlace_pago', 'pago:' || e.id, e.paciente_id, c.cita_id,
      jsonb_build_object('paciente', (select split_part(trim(nombre), ' ', 1) from pacientes where id = e.paciente_id),
        'clinica', (select nombre from clinicas where id = e.clinica_id), 'texto', c.concepto,
        'importe', _euros(e.importe_centimos), 'url_pago', p_url));
  end if;
  return jsonb_build_object('ok', true);
end;
$$;

create function motor_pago_fallido(p_enlace bigint, p_error text) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare e enlaces_pago;
begin
  select * into e from enlaces_pago where id = p_enlace for update;
  if e.id is null or e.estado <> 'solicitado' then return jsonb_build_object('ok', true, 'repetida', true); end if;
  update enlaces_pago set estado = 'fallido', error = left(coalesce(p_error, 'error del proveedor'), 300) where id = e.id;
  perform _solicitud(e.clinica_id, 'pago_revisar', 'No se pudo crear el enlace de pago de "' ||
    (select concepto from cargos where id = e.cargo_id) || '". Cobra por otra vía o vuelve a intentarlo.', e.paciente_id);
  return jsonb_build_object('ok', true);
end;
$$;

-- Aviso del proveedor (webhook ya verificado por el adaptador). p_tipo: 'pagado' | 'caducado'. Procesar el mismo
-- aviso dos veces no hace nada.
create function motor_pago_evento(p_proveedor text, p_evento text, p_tipo text, p_ref text, p_importe int default null,
                                  p_moneda text default 'eur') returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare e enlaces_pago; c cargos; v_pend bigint; v_pago bigint; v_res text;
begin
  insert into pago_eventos (proveedor, evento_id, tipo) values (p_proveedor, p_evento, p_tipo) on conflict do nothing;
  if not found then return jsonb_build_object('ok', true, 'repetida', true); end if;
  select * into e from enlaces_pago where proveedor_id = p_ref and proveedor = p_proveedor for update;
  if e.id is null then
    update pago_eventos set resultado = 'enlace_desconocido' where proveedor = p_proveedor and evento_id = p_evento;
    return jsonb_build_object('ok', false, 'motivo', 'enlace_no_existe');
  end if;
  if p_tipo = 'caducado' then
    update enlaces_pago set estado = 'caducado' where id = e.id and estado = 'creado';
    v_res := 'caducado';
  elsif p_tipo = 'pagado' then
    if e.estado = 'pagado' then v_res := 'ya_pagado';
    elsif p_importe is distinct from e.importe_centimos or lower(p_moneda) <> 'eur' then
      -- No cuadra: no se apunta nada solo; lo revisa el equipo.
      v_res := 'importe_distinto';
      perform _solicitud(e.clinica_id, 'pago_revisar', 'El proveedor de pago informa de un cobro que no coincide con el enlace ('
        || coalesce(_euros(p_importe), '?') || ' frente a ' || _euros(e.importe_centimos) || '). Revísalo en su panel.', e.paciente_id);
    else
      select * into c from cargos where id = e.cargo_id for update;
      v_pend := c.importe_centimos - _cobrado(c.id);
      -- El dinero ha llegado: se apunta siempre. Si ya estaba pagado por otra vía, el equipo decide si devolver.
      v_pago := _registrar_pago(c.id, e.importe_centimos, 'enlace', _hoy(_tz(c.clinica_id)), 'Pagado con el enlace del proveedor',
                                p_ref, null, 'Proveedor de pago');
      update enlaces_pago set estado = 'pagado', pagado_en = now() where id = e.id;
      if v_pend < e.importe_centimos or c.estado = 'anulado' then
        perform _solicitud(e.clinica_id, 'pago_revisar', 'Ha pagado con el enlace "' || c.concepto ||
          '" pero ya estaba pagado (o anulado). Revisa si hay que devolver la diferencia.', e.paciente_id);
      end if;
      v_res := 'pagado';
    end if;
  else
    v_res := 'ignorado';
  end if;
  update pago_eventos set resultado = v_res where proveedor = p_proveedor and evento_id = p_evento;
  return jsonb_build_object('ok', true, 'resultado', v_res);
end;
$$;

-- ---------------------------------------------------------------- ajustes y plantillas

alter function guardar_clinica(uuid, jsonb) rename to _guardar_clinica_fase4;
create function guardar_clinica(p_clinica uuid, d jsonb) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare r jsonb;
begin
  r := _guardar_clinica_fase4(p_clinica, d);
  if not coalesce((r->>'ok')::boolean, false) then return r; end if;
  begin
    update clinicas set
      razon_social = case when d ? 'razon_social' then nullif(trim(d->>'razon_social'), '') else razon_social end,
      nif = case when d ? 'nif' then upper(nullif(trim(d->>'nif'), '')) else nif end,
      serie_recibos = coalesce(upper(nullif(trim(d->>'serie_recibos'), '')), serie_recibos),
      pago_proveedor = coalesce(d->>'pago_proveedor', pago_proveedor),
      pago_modo = coalesce(d->>'pago_modo', pago_modo),
      dictado_permitido = coalesce((d->>'dictado_permitido')::boolean, dictado_permitido)
    where id = p_clinica;
  exception when check_violation then
    raise exception 'valor_no_valido' using errcode = '22023';
  end;
  return r;
end;
$$;

create or replace function guardar_plantilla(p_clinica uuid, p_clave text, d jsonb) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare v_desconocidas text[];
begin
  perform _miembro(p_clinica, array['propietario']);
  select array_agg(distinct m[1]) into v_desconocidas
  from regexp_matches(coalesce(d->>'texto', ''), '\{([a-z_]+)\}', 'g') m
  where m[1] not in ('paciente', 'fecha', 'servicio', 'profesional', 'clinica', 'lugar', 'enlace', 'comprobacion', 'caduca',
                     'tipo', 'texto', 'desde', 'hasta', 'programa', 'fechas', 'importe', 'url_pago');
  if v_desconocidas is not null then
    return jsonb_build_object('ok', false, 'motivo', 'variable_desconocida', 'variables', to_jsonb(v_desconocidas));
  end if;
  if p_clave in ('formulario_pendiente', 'formulario_recordatorio', 'plan_entregado', 'documento_pendiente',
                 'documento_recordatorio') and d ? 'texto' and d->>'texto' not like '%{enlace}%' then
    return jsonb_build_object('ok', false, 'motivo', 'falta_enlace');
  end if;
  if p_clave = 'enlace_pago' and d ? 'texto' and d->>'texto' not like '%{url_pago}%' then
    return jsonb_build_object('ok', false, 'motivo', 'falta_enlace');
  end if;
  if p_clave in ('propuesta_sesiones', 'confirmacion_sesiones') and d ? 'texto' and d->>'texto' not like '%{fechas}%' then
    return jsonb_build_object('ok', false, 'motivo', 'falta_fechas');
  end if;
  update plantillas_mensaje set
    texto = coalesce(nullif(trim(d->>'texto'), ''), texto),
    activa = coalesce((d->>'activa')::boolean, activa),
    plantilla_meta = case when d ? 'plantilla_meta' then nullif(trim(d->>'plantilla_meta'), '') else plantilla_meta end
  where clinica_id = p_clinica and clave = p_clave;
  if not found then return jsonb_build_object('ok', false, 'motivo', 'plantilla_no_existe'); end if;
  perform _auditar(p_clinica, 'guardar_plantilla', 'plantilla', p_clave);
  return jsonb_build_object('ok', true);
end;
$$;

-- ---------------------------------------------------------------- panel y listas

alter function panel(uuid, date, date, bigint) rename to _panel_fase4;
create function panel(p_clinica uuid, p_desde date default null, p_hasta date default null,
                      p_profesional bigint default null) returns jsonb
language plpgsql stable security definer set search_path = nutricion, extensions, pg_temp as $$
declare m miembros := _miembro(p_clinica); r jsonb := _panel_fase4(p_clinica, p_desde, p_hasta, p_profesional);
        v_tz text := _tz(p_clinica);
begin
  r := jsonb_set(r, '{tareas,pagos_pendientes}', to_jsonb((select count(*) from cargos c
          where c.clinica_id = p_clinica and c.estado = 'abierto' and _cobrado(c.id) < c.importe_centimos)));
  -- Los ingresos son información del negocio: solo para el propietario. Cobrado = pagos menos devoluciones, por fecha
  -- del pago, de toda la consulta (un pago no siempre es de un profesional).
  if m.rol = 'propietario' then
    r := jsonb_set(r, '{indicadores,ingresos}', to_jsonb((select round(coalesce(sum(case p.tipo when 'pago' then p.importe_centimos
            else -p.importe_centimos end), 0) / 100.0, 2) from pagos p
          where p.clinica_id = p_clinica and p.fecha between coalesce(p_desde, _hoy(v_tz) - 30) and coalesce(p_hasta, _hoy(v_tz)))));
  else
    r := jsonb_set(r, '{indicadores,ingresos}', '"sin_permiso"'::jsonb);
  end if;
  return r;
end;
$$;

alter function lista_pacientes(uuid, text, date, date) rename to _lista_pacientes_fase4;
create function lista_pacientes(p_clinica uuid, p_filtro text default 'todos', p_desde date default null,
                                p_hasta date default null) returns jsonb
language plpgsql stable security definer set search_path = nutricion, extensions, pg_temp as $$
begin
  if p_filtro = 'pago_pendiente' then
    perform _miembro(p_clinica);
    return (select coalesce(jsonb_agg(_paciente_json(p.id) order by p.nombre, p.id), '[]'::jsonb) from pacientes p
            where p.clinica_id = p_clinica and exists (select 1 from cargos c where c.paciente_id = p.id
              and c.estado = 'abierto' and _cobrado(c.id) < c.importe_centimos));
  end if;
  return _lista_pacientes_fase4(p_clinica, p_filtro, p_desde, p_hasta);
end;
$$;

-- ---------------------------------------------------------------- estadísticas

-- Mes a mes, con datos reales de la agenda, los pacientes y los cobros. Nada se estima: si no hay datos, sale 0.
-- Ingresos solo para el propietario.
create function estadisticas(p_clinica uuid, p_desde date default null, p_hasta date default null,
                             p_profesional bigint default null) returns jsonb
language plpgsql stable security definer set search_path = nutricion, extensions, pg_temp as $$
declare m miembros := _miembro(p_clinica); v_tz text := _tz(p_clinica);
        v_hasta date := coalesce(p_hasta, _hoy(_tz(p_clinica)));
        v_desde date := coalesce(p_desde, (date_trunc('month', coalesce(p_hasta, _hoy(_tz(p_clinica)))) - interval '11 months')::date);
        v_dinero boolean := m.rol = 'propietario';
        -- La ocupación cuenta desde que la consulta empieza a usar Corvex (su primer paciente o su primera cita): antes no
        -- había agenda que llenar y contarla bajaría el porcentaje sin motivo.
        v_inicio date := least((select min((creado_en at time zone _tz(p_clinica))::date) from pacientes where clinica_id = p_clinica),
                               (select min((inicio at time zone _tz(p_clinica))::date) from citas where clinica_id = p_clinica));
begin
  if v_hasta < v_desde or v_hasta - v_desde > 1100 then return jsonb_build_object('ok', false, 'motivo', 'fechas_no_validas'); end if;
  return jsonb_build_object('ok', true, 'desde', v_desde, 'hasta', v_hasta, 've_ingresos', v_dinero,
    'meses', (select coalesce(jsonb_agg(x order by x->>'mes'), '[]'::jsonb) from (
      select jsonb_build_object('mes', to_char(mes, 'YYYY-MM'),
        'desde', greatest(mes::date, v_desde), 'hasta', least((mes + interval '1 month - 1 day')::date, v_hasta),
        'consultas', count(c.id) filter (where c.estado in ('realizada', 'reservada', 'no_asistida')),
        'realizadas', count(c.id) filter (where c.estado = 'realizada'),
        'primeras_visitas', count(c.id) filter (where c.estado = 'realizada' and s.tipo = 'primera_visita'),
        'revisiones', count(c.id) filter (where c.estado = 'realizada' and s.tipo in ('revision', 'sesion_programa')),
        'canceladas', count(c.id) filter (where c.estado = 'cancelada'),
        'no_asistidas', count(c.id) filter (where c.estado = 'no_asistida'),
        'minutos_ocupados', coalesce(sum(extract(epoch from c.fin - c.inicio) / 60) filter (where c.estado <> 'cancelada'), 0)::int,
        'minutos_disponibles', (select coalesce(sum(_minutos_disponibles(pr.id, dd::date)), 0) from profesionales pr,
             generate_series(greatest(mes::date, v_desde, v_inicio), least((mes + interval '1 month - 1 day')::date, v_hasta), '1 day') dd
             where pr.clinica_id = p_clinica and pr.activo and (p_profesional is null or pr.id = p_profesional)),
        'pacientes_nuevos', (select count(*) from pacientes pa where pa.clinica_id = p_clinica
             and date_trunc('month', pa.creado_en at time zone v_tz) = mes
             and (pa.creado_en at time zone v_tz)::date between v_desde and v_hasta
             and (p_profesional is null or pa.profesional_id = p_profesional)),
        'bonos_vendidos', (select count(*) from bonos b where b.clinica_id = p_clinica and b.estado <> 'anulado'
             and date_trunc('month', b.fecha_compra) = mes and b.fecha_compra between v_desde and v_hasta),
        'ingresos', case when v_dinero then (select round(coalesce(sum(case p.tipo when 'pago' then p.importe_centimos
             else -p.importe_centimos end), 0) / 100.0, 2) from pagos p where p.clinica_id = p_clinica
             and date_trunc('month', p.fecha) = mes and p.fecha between v_desde and v_hasta) end) x
      from generate_series(date_trunc('month', v_desde), date_trunc('month', v_hasta), '1 month') mes
      left join citas c on c.clinica_id = p_clinica and date_trunc('month', c.inicio at time zone v_tz) = mes
        and (c.inicio at time zone v_tz)::date between v_desde and v_hasta
        and (p_profesional is null or c.profesional_id = p_profesional)
      left join servicios s on s.id = c.servicio_id
      group by mes) t(x)),
    -- Continuidad: de quien hizo su primera visita en el periodo, cuántos tienen después otra consulta (hecha o reservada).
    'continuidad', (select jsonb_build_object('primeras', count(*), 'con_otra', count(*) filter (where otra))
      from (select c.paciente_id, exists (select 1 from citas c2 where c2.paciente_id = c.paciente_id and c2.inicio > c.inicio
                   and c2.estado in ('realizada', 'reservada')) otra
            from citas c join servicios s on s.id = c.servicio_id
            where c.clinica_id = p_clinica and c.estado = 'realizada' and s.tipo = 'primera_visita'
              and (c.inicio at time zone v_tz)::date between v_desde and v_hasta
              and (p_profesional is null or c.profesional_id = p_profesional)) z),
    'por_profesional', (select coalesce(jsonb_agg(jsonb_build_object('id', pr.id, 'nombre', pr.nombre,
        'realizadas', (select count(*) from citas c where c.profesional_id = pr.id and c.estado = 'realizada'
                         and (c.inicio at time zone v_tz)::date between v_desde and v_hasta),
        'no_asistidas', (select count(*) from citas c where c.profesional_id = pr.id and c.estado = 'no_asistida'
                         and (c.inicio at time zone v_tz)::date between v_desde and v_hasta),
        'canceladas', (select count(*) from citas c where c.profesional_id = pr.id and c.estado = 'cancelada'
                         and (c.inicio at time zone v_tz)::date between v_desde and v_hasta)) order by pr.orden, pr.id), '[]'::jsonb)
      from profesionales pr where pr.clinica_id = p_clinica and (p_profesional is null or pr.id = p_profesional)),
    'por_metodo', case when v_dinero then (select coalesce(jsonb_agg(jsonb_build_object('metodo', metodo, 'importe', imp) order by imp desc), '[]'::jsonb)
      from (select p.metodo, round(sum(case p.tipo when 'pago' then p.importe_centimos else -p.importe_centimos end) / 100.0, 2) imp
            from pagos p where p.clinica_id = p_clinica and p.fecha between v_desde and v_hasta group by p.metodo) y) end);
end;
$$;

-- ---------------------------------------------------------------- asistente de voz del profesional
--
-- La aplicación convierte lo dictado (o escrito) en una acción con sus datos ({accion, paciente, dias, ...}) y la
-- manda aquí. voz_preparar busca al paciente, comprueba permisos y reglas y devuelve qué se va a hacer, sin hacerlo.
-- voz_confirmar lo ejecuta con las mismas funciones que la aplicación. Las consultas (ver pacientes, abrir una
-- ficha) no cambian nada y no piden confirmación.

create function _normal(p text) returns text language sql immutable as $$
  select lower(translate(coalesce(p, ''), 'ÁÀÉÈÍÌÓÒÚÙÜÑÇáàéèíìóòúùüñç', 'AAEEIIOOUUUNCaaeeiioouuunc'))
$$;

-- Pacientes cuyo nombre y apellidos contienen todas las palabras dichas (al principio de una palabra).
create function _buscar_por_nombre(p_clinica uuid, p_texto text) returns bigint[]
language sql stable security definer set search_path = nutricion, extensions, pg_temp as $$
  select coalesce(array_agg(p.id order by p.nombre, p.apellidos, p.id), '{}') from pacientes p
  where p.clinica_id = p_clinica and length(trim(coalesce(p_texto, ''))) >= 2
    and not exists (select 1 from regexp_split_to_table(_normal(trim(p_texto)), '\s+') w
                    where w <> '' and w not in ('de', 'del', 'la', 'las', 'los', 'y')
                      and not (' ' || _normal(p.nombre || ' ' || coalesce(p.apellidos, ''))) like '% ' || w || '%')
$$;

create function _candidato(p_id bigint) returns jsonb
language sql stable security definer set search_path = nutricion, extensions, pg_temp as $$
  select jsonb_build_object('id', p.id, 'nombre', trim(p.nombre || ' ' || coalesce(p.apellidos, '')),
    'detalle', concat_ws(' · ', case when p.fecha_nacimiento is not null then 'nacida/o en ' || extract(year from p.fecha_nacimiento) end,
                         case when p.telefono is not null then 'móvil acabado en ' || right(p.telefono, 3) end, pr.nombre))
  from pacientes p left join profesionales pr on pr.id = p.profesional_id where p.id = p_id
$$;

-- Planifica una orden: resuelve paciente y opciones y redacta la vista previa. No cambia nada.
create function _voz_planificar(p_clinica uuid, m miembros, p_accion text, d jsonb) returns jsonb
language plpgsql stable security definer set search_path = nutricion, extensions, pg_temp as $$
declare v_ids bigint[]; v_pac bigint := nullif(d->>'paciente_id', '')::bigint; pa pacientes; v_nombre text; v_tz text := _tz(p_clinica);
        v_n int; v_op jsonb; v_id bigint; v_dias int; v_fecha date; v_ini timestamptz; v_fin timestamptz; v_prof bigint;
        v_imp numeric; v_cent int; v_metodo text; v_citas int; v_salud boolean := _puede_salud(m.rol);
begin
  if p_accion not in ('programar_revision', 'anadir_bono', 'ver_pacientes', 'bloquear_agenda', 'entregar_plan',
                      'registrar_pago', 'abrir_ficha') then
    return jsonb_build_object('estado', 'fallida', 'motivo', 'orden_no_entendida');
  end if;
  -- Paciente (todas menos ver_pacientes y bloquear_agenda)
  if p_accion not in ('ver_pacientes', 'bloquear_agenda') then
    if v_pac is null then
      v_ids := _buscar_por_nombre(p_clinica, d->>'paciente');
      if cardinality(v_ids) = 0 then
        return jsonb_build_object('estado', 'fallida', 'motivo', 'paciente_no_encontrado', 'buscado', d->>'paciente');
      elsif cardinality(v_ids) > 1 then
        return jsonb_build_object('estado', 'aclarar', 'pregunta', '¿A qué paciente te refieres?',
          'candidatos', (select jsonb_agg(_candidato(x)) from unnest(v_ids[1:8]) x), 'datos', d);
      end if;
      v_pac := v_ids[1];
    end if;
    select * into pa from pacientes where id = v_pac and clinica_id = p_clinica;
    if pa.id is null then return jsonb_build_object('estado', 'fallida', 'motivo', 'paciente_no_existe'); end if;
    v_nombre := trim(pa.nombre || ' ' || coalesce(pa.apellidos, ''));
    d := d || jsonb_build_object('paciente_id', v_pac);
  end if;

  if p_accion = 'abrir_ficha' then
    return jsonb_build_object('estado', 'consulta', 'resumen', 'Ficha de ' || v_nombre, 'datos', d);

  elsif p_accion = 'ver_pacientes' then
    if coalesce(d->>'filtro', '') not in ('sin_proxima', 'con_bono', 'con_programa', 'pago_pendiente', 'formulario_pendiente',
                                          'plan_por_entregar', 'documento_pendiente', 'nuevos', 'activos') then
      return jsonb_build_object('estado', 'fallida', 'motivo', 'orden_no_entendida');
    end if;
    return jsonb_build_object('estado', 'consulta', 'datos', d, 'resumen', case d->>'filtro'
      when 'sin_proxima' then 'Pacientes sin próxima revisión' when 'con_bono' then 'Pacientes con bono activo'
      when 'con_programa' then 'Pacientes con sesiones de programa pendientes' when 'pago_pendiente' then 'Pacientes con pagos pendientes'
      when 'formulario_pendiente' then 'Pacientes con formularios sin completar' when 'plan_por_entregar' then 'Pacientes con un plan por entregar'
      when 'documento_pendiente' then 'Pacientes con documentos por firmar' when 'nuevos' then 'Pacientes nuevos (últimos 30 días)'
      else 'Pacientes activos' end);

  elsif p_accion = 'programar_revision' then
    if not v_salud then return jsonb_build_object('estado', 'fallida', 'motivo', 'solo_profesional'); end if;
    v_dias := nullif(d->>'dias', '')::int;
    if v_dias is null or v_dias < 1 or v_dias > 365 then return jsonb_build_object('estado', 'fallida', 'motivo', 'falta_plazo'); end if;
    return jsonb_build_object('estado', 'propuesta', 'datos', d, 'resumen',
      'Indicar una revisión para ' || v_nombre || ' dentro de ' || v_dias || ' días (hacia el ' ||
      fecha_dia_es(_hoy(v_tz) + v_dias) || ', con ' || (select seguimiento_margen_dias from clinicas where id = p_clinica) ||
      ' días de margen). Queda pendiente de reservar: no ocupa la agenda hasta que el paciente elija hora.');

  elsif p_accion = 'anadir_bono' then
    if d->>'bono_tipo_id' is null then
      select count(*), jsonb_agg(jsonb_build_object('id', t.id, 'nombre', t.nombre || ' · ' || t.sesiones || ' sesiones · ' ||
               coalesce(_euros(t.precio_centimos), 'sin precio')) order by t.nombre)
        into v_n, v_op
      from bono_tipos t where t.clinica_id = p_clinica and t.activo
        and (nullif(d->>'sesiones', '') is null or t.sesiones = (d->>'sesiones')::int);
      if v_n = 0 then
        return jsonb_build_object('estado', 'fallida', 'motivo', 'bono_tipo_no_existe',
          'opciones', (select jsonb_agg(t.nombre || ' (' || t.sesiones || ' sesiones)') from bono_tipos t where t.clinica_id = p_clinica and t.activo));
      elsif v_n > 1 then
        return jsonb_build_object('estado', 'aclarar', 'pregunta', '¿Qué bono?', 'opciones', v_op, 'clave_opcion', 'bono_tipo_id', 'datos', d);
      end if;
      d := d || jsonb_build_object('bono_tipo_id', (v_op->0->>'id')::bigint);
    end if;
    select jsonb_build_object('nombre', nombre, 'precio', precio_centimos, 'sesiones', sesiones) into v_op
    from bono_tipos where id = (d->>'bono_tipo_id')::bigint and clinica_id = p_clinica and activo;
    if v_op is null then return jsonb_build_object('estado', 'fallida', 'motivo', 'bono_tipo_no_existe'); end if;
    return jsonb_build_object('estado', 'propuesta', 'datos', d, 'resumen',
      'Añadir a ' || v_nombre || ' el bono «' || (v_op->>'nombre') || '» (' || (v_op->>'sesiones') || ' sesiones, ' ||
      coalesce(_euros((v_op->>'precio')::int), 'sin precio') || '). Queda pendiente de cobro.');

  elsif p_accion = 'bloquear_agenda' then
    v_prof := coalesce(nullif(d->>'profesional_id', '')::bigint, m.profesional_id);
    if v_prof is null then return jsonb_build_object('estado', 'fallida', 'motivo', 'sin_profesional'); end if;
    if m.rol = 'nutricionista' and v_prof is distinct from m.profesional_id then
      return jsonb_build_object('estado', 'fallida', 'motivo', 'sin_permiso');
    end if;
    if m.rol = 'recepcion' then return jsonb_build_object('estado', 'fallida', 'motivo', 'sin_permiso'); end if;
    begin v_fecha := (d->>'fecha')::date; exception when others then v_fecha := null; end;
    if v_fecha is null then return jsonb_build_object('estado', 'fallida', 'motivo', 'falta_fecha'); end if;
    if v_fecha < _hoy(v_tz) then return jsonb_build_object('estado', 'fallida', 'motivo', 'fecha_pasada'); end if;
    v_ini := _desde_local(v_fecha || 'T' || coalesce(nullif(d->>'desde', ''), '00:00'), v_tz);
    v_fin := _desde_local(v_fecha || 'T' || coalesce(nullif(d->>'hasta', ''), '23:59'), v_tz);
    if v_ini is null or v_fin is null or v_fin <= v_ini then return jsonb_build_object('estado', 'fallida', 'motivo', 'fechas_no_validas'); end if;
    select count(*) into v_citas from citas c where c.profesional_id = v_prof and c.estado = 'reservada'
      and tstzrange(c.inicio, c.fin) && tstzrange(v_ini, v_fin);
    d := d || jsonb_build_object('profesional_id', v_prof, 'inicio', _local(v_ini, v_tz), 'fin', _local(v_fin, v_tz));
    return jsonb_build_object('estado', 'propuesta', 'datos', d, 'citas_afectadas', v_citas, 'resumen',
      'Bloquear la agenda de ' || (select nombre from profesionales where id = v_prof) || ' el ' || fecha_dia_es(v_fecha) ||
      case when nullif(d->>'desde', '') is null and nullif(d->>'hasta', '') is null then ' (todo el día)'
           else ' de ' || to_char(v_ini at time zone v_tz, 'HH24:MI') || ' a ' || to_char(v_fin at time zone v_tz, 'HH24:MI') end ||
      '.' || case when v_citas > 0 then ' Hay ' || v_citas || ' cita(s) en ese tramo: no se mueven solas, tendrás que avisar o cambiarlas.' else '' end);

  elsif p_accion = 'entregar_plan' then
    if not v_salud then return jsonb_build_object('estado', 'fallida', 'motivo', 'solo_profesional'); end if;
    if d->>'plan_id' is null then
      select count(*), jsonb_agg(jsonb_build_object('id', pl.id, 'nombre', pl.titulo || ' · versión ' || v.numero) order by pl.creado_en desc)
        into v_n, v_op
      from planes pl join plan_versiones v on v.plan_id = pl.id
      where pl.paciente_id = v_pac and pl.estado = 'activo' and v.estado = 'aprobada' and v.entregada_en is null;
      if v_n = 0 then
        return jsonb_build_object('estado', 'fallida', 'motivo', case when exists (select 1 from planes where paciente_id = v_pac
          and estado = 'activo') then 'plan_sin_aprobar_o_ya_entregado' else 'plan_no_existe' end);
      elsif v_n > 1 then
        return jsonb_build_object('estado', 'aclarar', 'pregunta', '¿Qué plan?', 'opciones', v_op, 'clave_opcion', 'plan_id', 'datos', d);
      end if;
      d := d || jsonb_build_object('plan_id', (v_op->0->>'id')::bigint);
    end if;
    return jsonb_build_object('estado', 'propuesta', 'datos', d, 'resumen',
      'Marcar como entregado en mano el plan «' || (select titulo from planes where id = (d->>'plan_id')::bigint) || '» de ' ||
      v_nombre || '. No se le manda ningún mensaje.');

  elsif p_accion = 'registrar_pago' then
    v_metodo := coalesce(nullif(d->>'metodo', ''), 'otro');
    if v_metodo not in ('efectivo', 'tarjeta', 'transferencia', 'bizum', 'otro') then v_metodo := 'otro'; end if;
    begin v_imp := replace(nullif(d->>'importe', ''), ',', '.')::numeric; exception when others then v_imp := null; end;
    v_cent := round(v_imp * 100)::int;
    if d->>'cargo_id' is null then
      select count(*), jsonb_agg(jsonb_build_object('id', c.id, 'nombre', c.concepto || ' · pendiente ' ||
               _euros(c.importe_centimos - _cobrado(c.id))) order by c.creado_en)
        into v_n, v_op
      from cargos c where c.paciente_id = v_pac and c.estado = 'abierto' and _cobrado(c.id) < c.importe_centimos
        and (v_cent is null or c.importe_centimos - _cobrado(c.id) >= v_cent);
      if v_n = 0 then return jsonb_build_object('estado', 'fallida', 'motivo', 'sin_pagos_pendientes'); end if;
      if v_n > 1 then
        return jsonb_build_object('estado', 'aclarar', 'pregunta', '¿Qué cobro?', 'opciones', v_op, 'clave_opcion', 'cargo_id', 'datos', d);
      end if;
      d := d || jsonb_build_object('cargo_id', (v_op->0->>'id')::bigint);
    end if;
    select c.importe_centimos - _cobrado(c.id) into v_n from cargos c where c.id = (d->>'cargo_id')::bigint and c.paciente_id = v_pac;
    if v_n is null or v_n <= 0 then return jsonb_build_object('estado', 'fallida', 'motivo', 'sin_pagos_pendientes'); end if;
    if v_cent is not null and v_cent > v_n then return jsonb_build_object('estado', 'fallida', 'motivo', 'importe_mayor_que_pendiente'); end if;
    d := d || jsonb_build_object('metodo', v_metodo, 'importe', round(coalesce(v_cent, v_n) / 100.0, 2));
    return jsonb_build_object('estado', 'propuesta', 'datos', d, 'resumen',
      'Apuntar un pago de ' || _euros(coalesce(v_cent, v_n)) || ' de ' || v_nombre || ' (' ||
      (select concepto from cargos where id = (d->>'cargo_id')::bigint) || '), ' ||
      case v_metodo when 'efectivo' then 'en efectivo' when 'tarjeta' then 'con tarjeta' when 'transferencia' then 'por transferencia'
                    when 'bizum' then 'por Bizum' else 'sin indicar cómo' end || '. Se hará su recibo.');
  end if;
  return jsonb_build_object('estado', 'fallida', 'motivo', 'orden_no_entendida');
end;
$$;

create function _voz_respuesta(p_orden bigint, p jsonb) returns jsonb
language sql stable security definer set search_path = nutricion, extensions, pg_temp as $$
  select jsonb_build_object('ok', true, 'orden_id', p_orden) || (p - 'datos') ||
         jsonb_build_object('accion', (select accion from ordenes_voz where id = p_orden),
                            'paciente_id', (select paciente_id from ordenes_voz where id = p_orden),
                            'datos', p->'datos')
$$;

-- d: {texto (lo dictado, opcional), accion, paciente?, paciente_id?, ...datos de la acción}
create function voz_preparar(p_clinica uuid, d jsonb) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare m miembros := _miembro(p_clinica); p jsonb; v_id bigint;
begin
  p := _voz_planificar(p_clinica, m, coalesce(d->>'accion', ''), d - 'texto' - 'accion');
  insert into ordenes_voz (clinica_id, miembro_id, texto, accion, datos, paciente_id, estado, resumen, resuelta_en)
  values (p_clinica, m.id, left(nullif(trim(coalesce(d->>'texto', '')), ''), 500), coalesce(nullif(d->>'accion', ''), 'desconocida'),
          coalesce(p->'datos', '{}'::jsonb), nullif(p->'datos'->>'paciente_id', '')::bigint, p->>'estado', p->>'resumen',
          case when p->>'estado' in ('consulta', 'fallida') then now() end)
  returning id into v_id;
  if p->>'estado' = 'consulta' then
    perform _auditar(p_clinica, 'voz_consulta', 'orden_voz', v_id::text, nullif(p->'datos'->>'paciente_id', '')::bigint,
                     jsonb_build_object('accion', d->>'accion'));
  end if;
  if p->>'estado' = 'consulta' and d->>'accion' = 'ver_pacientes' then
    p := p || jsonb_build_object('lista', lista_pacientes(p_clinica, p->'datos'->>'filtro'));
  end if;
  return _voz_respuesta(v_id, p);
end;
$$;

-- Elegir entre los candidatos u opciones. d: {paciente_id?} o {<clave_opcion>: id}
create function voz_aclarar(p_clinica uuid, p_orden bigint, d jsonb) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare m miembros := _miembro(p_clinica); o ordenes_voz; p jsonb;
begin
  select * into o from ordenes_voz where id = p_orden and clinica_id = p_clinica and miembro_id = m.id for update;
  if o.id is null then return jsonb_build_object('ok', false, 'motivo', 'orden_no_existe'); end if;
  if o.estado <> 'aclarar' then return jsonb_build_object('ok', false, 'motivo', 'orden_ya_resuelta'); end if;
  p := _voz_planificar(p_clinica, m, o.accion, o.datos || (d - 'texto' - 'accion'));
  update ordenes_voz set estado = p->>'estado', datos = coalesce(p->'datos', datos), resumen = p->>'resumen',
    paciente_id = coalesce(nullif(p->'datos'->>'paciente_id', '')::bigint, paciente_id),
    resuelta_en = case when p->>'estado' in ('consulta', 'fallida') then now() end
  where id = o.id;
  if p->>'estado' = 'consulta' and o.accion = 'ver_pacientes' then
    p := p || jsonb_build_object('lista', lista_pacientes(p_clinica, p->'datos'->>'filtro'));
  end if;
  return _voz_respuesta(o.id, p);
end;
$$;

-- Ejecuta una orden propuesta. Solo quien la dictó; dos confirmaciones no la hacen dos veces.
create function voz_confirmar(p_clinica uuid, p_orden bigint) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare m miembros := _miembro(p_clinica); o ordenes_voz; r jsonb; d jsonb;
begin
  select * into o from ordenes_voz where id = p_orden and clinica_id = p_clinica and miembro_id = m.id for update;
  if o.id is null then return jsonb_build_object('ok', false, 'motivo', 'orden_no_existe'); end if;
  if o.estado = 'ejecutada' then return jsonb_build_object('ok', true, 'repetida', true, 'resultado', o.resultado); end if;
  if o.estado <> 'propuesta' then return jsonb_build_object('ok', false, 'motivo', 'orden_ya_resuelta'); end if;
  d := o.datos;
  begin
    r := case o.accion
      when 'programar_revision' then indicar_seguimiento(p_clinica, jsonb_build_object('paciente_id', d->'paciente_id',
                                       'en_dias', d->'dias', 'indicacion', 'Indicada por voz'))
      when 'anadir_bono' then vender_bono(p_clinica, jsonb_build_object('paciente_id', d->'paciente_id',
                                'bono_tipo_id', d->'bono_tipo_id', 'pago_estado', 'pendiente', 'clave', 'voz:' || o.id))
      when 'bloquear_agenda' then crear_ausencia(p_clinica, jsonb_build_object('profesional_id', d->'profesional_id',
                                    'inicio', d->>'inicio', 'fin', d->>'fin', 'motivo', coalesce(d->>'motivo', 'Bloqueo por voz')))
      when 'entregar_plan' then entregar_plan(p_clinica, (d->>'plan_id')::bigint, 'en_mano')
      when 'registrar_pago' then registrar_pago(p_clinica, jsonb_build_object('cargo_id', d->'cargo_id', 'importe', d->>'importe',
                                   'metodo', d->>'metodo', 'clave', 'voz:' || o.id))
      end;
  exception when insufficient_privilege then
    r := jsonb_build_object('ok', false, 'motivo', 'sin_permiso');
  end;
  if r is null then r := jsonb_build_object('ok', false, 'motivo', 'orden_no_entendida'); end if;
  update ordenes_voz set estado = case when coalesce((r->>'ok')::boolean, false) then 'ejecutada' else 'fallida' end,
    resultado = jsonb_build_object('ok', r->'ok', 'motivo', r->'motivo'), resuelta_en = now()
  where id = o.id;
  perform _auditar(p_clinica, 'voz_ejecutar', 'orden_voz', o.id::text, o.paciente_id,
                   jsonb_build_object('accion', o.accion, 'ok', r->'ok'));
  return jsonb_build_object('ok', coalesce((r->>'ok')::boolean, false), 'motivo', r->'motivo', 'orden_id', o.id,
                            'accion', o.accion, 'paciente_id', o.paciente_id, 'resumen', o.resumen);
end;
$$;

create function voz_descartar(p_clinica uuid, p_orden bigint) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare m miembros := _miembro(p_clinica);
begin
  update ordenes_voz set estado = 'descartada', resuelta_en = now()
  where id = p_orden and clinica_id = p_clinica and miembro_id = m.id and estado in ('propuesta', 'aclarar');
  return jsonb_build_object('ok', true);
end;
$$;

create function voz_historial(p_clinica uuid) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare m miembros := _miembro(p_clinica);
begin
  return (select coalesce(jsonb_agg(jsonb_build_object('id', o.id, 'accion', o.accion, 'estado', o.estado, 'resumen', o.resumen,
      'texto', o.texto, 'motivo', o.resultado->>'motivo', 'creado', _local(o.creado_en, _tz(p_clinica))) order by o.id desc), '[]'::jsonb)
    from (select * from ordenes_voz where clinica_id = p_clinica and miembro_id = m.id order by id desc limit 15) o);
end;
$$;

-- ---------------------------------------------------------------- motor

alter function motor_tick() rename to _motor_tick_fase4;
create function motor_tick() returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare r jsonb := _motor_tick_fase4(); x record; n_fall int := 0; n_cad int := 0; n_voz int;
begin
  -- Enlaces que el adaptador no ha creado en 15 minutos (adaptador parado o sin configurar): se avisa al equipo.
  for x in select id from enlaces_pago where estado = 'solicitado' and creado_en < now() - interval '15 minutes'
           for update skip locked loop
    perform motor_pago_fallido(x.id, 'El proveedor de pago no ha respondido');
    n_fall := n_fall + 1;
  end loop;
  update enlaces_pago set estado = 'caducado' where estado = 'creado' and caduca_en < now();
  get diagnostics n_cad = row_count;
  -- Lo dictado no se guarda más de 30 días (queda la acción y su resumen).
  update ordenes_voz set texto = null where texto is not null and creado_en < now() - interval '30 days';
  get diagnostics n_voz = row_count;
  -- Órdenes que nadie confirmó en un día: descartadas.
  update ordenes_voz set estado = 'descartada', resuelta_en = now()
  where estado in ('propuesta', 'aclarar') and creado_en < now() - interval '1 day';
  return r || jsonb_build_object('enlaces_pago_fallidos', n_fall, 'enlaces_pago_caducados', n_cad, 'dictados_borrados', n_voz);
end;
$$;

select _aplicar_permisos();


-- Endurecimiento antes de publicar: toda función del esquema con search_path fijo (lo pide el asesor de seguridad de
-- Supabase: con search_path variable, una función podría resolver un objeto de otro esquema). Las security definer ya
-- lo tenían; aquí se fija en las auxiliares (inmutables, triggers, formato de fechas…). No cambia lo que hacen.
set search_path = nutricion, extensions, public;

do $$
declare f record;
begin
  for f in
    select p.oid::regprocedure as firma from pg_proc p join pg_namespace n on n.oid = p.pronamespace
    where n.nspname in ('nutricion', 'nutricion_storage') and p.prokind = 'f'
      and (p.proconfig is null or not exists (select 1 from unnest(p.proconfig) c where c like 'search_path=%'))
  loop
    execute format('alter function %s set search_path = nutricion, extensions, pg_temp', f.firma);
  end loop;
end;
$$;

select _aplicar_permisos();


-- =====================================================================
-- Corvex Nutrición · Fase 6: servicios para los asistentes, contabilidad, facturación (preparación), agenda por
-- meses y más órdenes para el asistente del profesional.
--
-- Principios:
--  * Una sola fuente para el catálogo: la tabla `servicios` (y `bono_tipos`). La agenda, el asistente de WhatsApp y el
--    de teléfono leen de aquí en cada turno (canal_contexto). Nada de precios ni duraciones copiados en los prompts.
--  * Un servicio sin un dato (precio, qué incluye...) no se inventa: llega como null y el asistente dice que no lo sabe.
--  * Contabilidad cuenta lo cobrado de verdad (pagos menos devoluciones), nunca una cita por estar reservada.
--  * Las facturas son una PREPARACIÓN: numeradas sin huecos, con los datos que exige el Reglamento de facturación y
--    con rectificativas, pero sin VERI*FACTU (sin huella encadenada, QR ni envío a la AEAT). No se pueden usar como
--    facturas reales hasta integrar un servicio de VERI*FACTU; cada documento lo dice.
-- =====================================================================

set search_path = nutricion, extensions, public;

-- ---------------------------------------------------------------- servicios: la ficha completa

alter table servicios
  add column categoria               text check (length(categoria) <= 60),
  add column incluye                 text check (length(incluye) <= 2000),
  add column preparacion             text check (length(preparacion) <= 2000),   -- qué debe saber o traer el paciente
  add column requiere_primera        boolean not null default false,            -- solo si ya ha tenido una primera consulta
  add column requiere_aprobacion     boolean not null default false,            -- lo valora el equipo antes de dar cita
  add column condiciones_cancelacion text check (length(condiciones_cancelacion) <= 1000),
  add column disponibilidad          text check (length(disponibilidad) <= 300),  -- "martes y jueves por la tarde"
  add column preguntas               jsonb not null default '[]'::jsonb check (jsonb_typeof(preguntas) = 'array'),
  add column info_asistente          text check (length(info_asistente) <= 2000), -- lo que la IA debe comunicar
  -- IVA: no se presupone la exención. 'exento' = art. 20.Uno.3º LIVA (asistencia sanitaria con finalidad de prevenir,
  -- diagnosticar o tratar una enfermedad); 'iva21' = tipo general (por ejemplo, fines estéticos o de rendimiento).
  -- null = sin revisar: no se puede facturar hasta decidirlo.
  add column iva_tratamiento         text check (iva_tratamiento in ('exento', 'iva21')),
  add column actualizado_en          timestamptz not null default now();

alter table bono_tipos
  add column categoria       text not null default 'bono' check (categoria in ('bono', 'programa', 'mensual')),
  add column iva_tratamiento text check (iva_tratamiento in ('exento', 'iva21'));

create function _servicio_json(p_id bigint) returns jsonb
language sql stable security definer set search_path = nutricion, extensions, pg_temp as $$
  select jsonb_build_object(
    'id', s.id, 'nombre', s.nombre, 'descripcion', s.descripcion, 'tipo', s.tipo, 'especialidad', s.especialidad,
    'categoria', s.categoria, 'duracion_min', s.duracion_min, 'precio', round(s.precio_centimos / 100.0, 2),
    'presencial', s.presencial, 'online', s.online, 'reservable_canales', s.reservable_canales, 'activo', s.activo,
    'orden', s.orden, 'incluye', s.incluye, 'preparacion', s.preparacion, 'requiere_primera', s.requiere_primera,
    'requiere_aprobacion', s.requiere_aprobacion, 'condiciones_cancelacion', s.condiciones_cancelacion,
    'disponibilidad', s.disponibilidad, 'preguntas', s.preguntas, 'info_asistente', s.info_asistente,
    'iva_tratamiento', s.iva_tratamiento, 'actualizado', _local(s.actualizado_en, _tz(s.clinica_id)),
    'citas_futuras', (select count(*) from citas c where c.servicio_id = s.id and c.estado = 'reservada' and c.inicio > now()))
  from servicios s where s.id = p_id
$$;

alter function configuracion(uuid) rename to _configuracion_fase1;
create function configuracion(p_clinica uuid) returns jsonb
language plpgsql stable security definer set search_path = nutricion, extensions, pg_temp as $$
declare r jsonb := _configuracion_fase1(p_clinica);
begin
  return jsonb_set(r, '{servicios}', (select coalesce(jsonb_agg(_servicio_json(s.id) order by s.orden, s.id), '[]'::jsonb)
                                      from servicios s where s.clinica_id = p_clinica));
end;
$$;

-- Guarda también la ficha nueva. Si cambia el precio, las citas futuras ya reservadas (sin bono) pasan a ese precio:
-- lo que se cobra al hacerlas es lo que dice el catálogo. La duración no mueve citas ya dadas; vale para las nuevas.
alter function guardar_servicio(uuid, jsonb) rename to _guardar_servicio_fase1;
create function guardar_servicio(p_clinica uuid, d jsonb) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare r jsonb; v_id bigint; antes servicios; v_preg jsonb;
begin
  perform _miembro(p_clinica, array['propietario']);
  if d ? 'id' then
    select * into antes from servicios where id = (d->>'id')::bigint and clinica_id = p_clinica;
    if antes.id is null then return jsonb_build_object('ok', false, 'motivo', 'servicio_no_existe'); end if;
  elsif nullif(trim(coalesce(d->>'nombre', '')), '') is null then
    return jsonb_build_object('ok', false, 'motivo', 'falta_nombre');
  end if;
  if d ? 'duracion_min' and ((d->>'duracion_min')::int not between 10 and 240) then
    return jsonb_build_object('ok', false, 'motivo', 'valor_no_valido');
  end if;
  if d ? 'precio' and nullif(d->>'precio', '') is not null then
    begin
      if replace(d->>'precio', ',', '.')::numeric < 0 or replace(d->>'precio', ',', '.')::numeric > 10000 then
        return jsonb_build_object('ok', false, 'motivo', 'importe_no_valido');
      end if;
    exception when others then return jsonb_build_object('ok', false, 'motivo', 'importe_no_valido'); end;
  end if;
  -- Preguntas frecuentes: [{pregunta, respuesta}], las dos con texto.
  if d ? 'preguntas' then
    if jsonb_typeof(d->'preguntas') <> 'array' or jsonb_array_length(d->'preguntas') > 30 or exists (
         select 1 from jsonb_array_elements(d->'preguntas') q
         where jsonb_typeof(q) <> 'object' or length(trim(coalesce(q->>'pregunta', ''))) not between 3 and 300
            or length(trim(coalesce(q->>'respuesta', ''))) not between 1 and 1500) then
      return jsonb_build_object('ok', false, 'motivo', 'preguntas_no_validas');
    end if;
    v_preg := (select coalesce(jsonb_agg(jsonb_build_object('pregunta', trim(q->>'pregunta'), 'respuesta', trim(q->>'respuesta'))), '[]')
               from jsonb_array_elements(d->'preguntas') q);
  end if;
  if (d->>'presencial')::boolean is false and (d->>'online')::boolean is false then
    return jsonb_build_object('ok', false, 'motivo', 'falta_modalidad');
  end if;
  begin
    r := _guardar_servicio_fase1(p_clinica, d);
  exception
    when unique_violation then return jsonb_build_object('ok', false, 'motivo', 'nombre_repetido');
    when check_violation then return jsonb_build_object('ok', false, 'motivo', 'valor_no_valido');
  end;
  if not coalesce((r->>'ok')::boolean, false) then return r; end if;
  v_id := (r->>'id')::bigint;
  begin
    update servicios set
      categoria = case when d ? 'categoria' then nullif(trim(d->>'categoria'), '') else categoria end,
      incluye = case when d ? 'incluye' then nullif(trim(d->>'incluye'), '') else incluye end,
      preparacion = case when d ? 'preparacion' then nullif(trim(d->>'preparacion'), '') else preparacion end,
      requiere_primera = coalesce((d->>'requiere_primera')::boolean, requiere_primera),
      requiere_aprobacion = coalesce((d->>'requiere_aprobacion')::boolean, requiere_aprobacion),
      condiciones_cancelacion = case when d ? 'condiciones_cancelacion' then nullif(trim(d->>'condiciones_cancelacion'), '') else condiciones_cancelacion end,
      disponibilidad = case when d ? 'disponibilidad' then nullif(trim(d->>'disponibilidad'), '') else disponibilidad end,
      preguntas = coalesce(v_preg, preguntas),
      info_asistente = case when d ? 'info_asistente' then nullif(trim(d->>'info_asistente'), '') else info_asistente end,
      iva_tratamiento = case when d ? 'iva_tratamiento' then nullif(d->>'iva_tratamiento', '') else iva_tratamiento end,
      actualizado_en = now()
    where id = v_id;
  exception when check_violation then
    raise exception 'valor_no_valido' using errcode = '22023';
  end;
  if antes.id is not null and antes.precio_centimos is distinct from (select precio_centimos from servicios where id = v_id) then
    update citas set precio_centimos = (select precio_centimos from servicios where id = v_id), actualizada_en = now()
    where servicio_id = v_id and estado = 'reservada' and inicio > now() and bono_id is null;
  end if;
  return jsonb_build_object('ok', true, 'id', v_id, 'servicio', _servicio_json(v_id));
end;
$$;

alter function lista_bono_tipos(uuid) rename to _lista_bono_tipos_fase3;
create function lista_bono_tipos(p_clinica uuid) returns jsonb
language plpgsql stable security definer set search_path = nutricion, extensions, pg_temp as $$
begin
  return (select coalesce(jsonb_agg(x || jsonb_build_object('categoria', t.categoria, 'iva_tratamiento', t.iva_tratamiento)
                                    order by t.orden, t.id), '[]'::jsonb)
          from jsonb_array_elements(_lista_bono_tipos_fase3(p_clinica)) x join bono_tipos t on t.id = (x->>'id')::bigint);
end;
$$;

alter function guardar_bono_tipo(uuid, jsonb) rename to _guardar_bono_tipo_fase3;
create function guardar_bono_tipo(p_clinica uuid, d jsonb) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare r jsonb := _guardar_bono_tipo_fase3(p_clinica, d);
begin
  if not coalesce((r->>'ok')::boolean, false) then return r; end if;
  begin
    update bono_tipos set categoria = coalesce(nullif(d->>'categoria', ''), categoria),
      iva_tratamiento = case when d ? 'iva_tratamiento' then nullif(d->>'iva_tratamiento', '') else iva_tratamiento end
    where id = (r->>'id')::bigint;
  exception when check_violation then raise exception 'valor_no_valido' using errcode = '22023';
  end;
  return r;
end;
$$;

-- ---------------------------------------------------------------- lo que ven los asistentes en cada turno

-- El catálogo que se ofrece por los canales (activo y marcado para la recepción automática; lo interno, como una reunión,
-- no sale), con su ficha completa, y los bonos y programas. Lo que necesita aprobación del equipo se ve pero no se
-- reserva por aquí. Si un dato falta, va null: el prompt dice que entonces no se sabe y se ofrece preguntar.
alter function canal_contexto(bigint) rename to _canal_contexto_fase4;
create function canal_contexto(p_conversacion bigint) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare r jsonb := _canal_contexto_fase4(p_conversacion); v conversaciones := _conv(p_conversacion); c clinicas;
begin
  select * into c from clinicas where id = v.clinica_id;
  r := jsonb_set(r, '{servicios}', (select coalesce(jsonb_agg(jsonb_build_object(
      'servicio_id', s.id, 'nombre', s.nombre, 'categoria', s.categoria, 'tipo', s.tipo, 'descripcion', s.descripcion,
      'duracion_min', s.duracion_min,
      'precio_euros', case when c.precios_confirmados then round(s.precio_centimos / 100.0, 2) end,
      'presencial', s.presencial, 'online', s.online, 'incluye', s.incluye, 'que_saber_antes', s.preparacion,
      'requiere_primera_consulta', s.requiere_primera,
      'se_reserva_por_aqui', not s.requiere_aprobacion,
      'requiere_aprobacion_del_equipo', s.requiere_aprobacion,
      'condiciones_cancelacion', s.condiciones_cancelacion, 'disponibilidad', s.disponibilidad,
      'preguntas_frecuentes', case when jsonb_array_length(s.preguntas) > 0 then s.preguntas end,
      'informacion_adicional', s.info_asistente,
      'profesionales', (select jsonb_agg(ps.profesional_id) from profesional_servicios ps where ps.servicio_id = s.id))
    order by s.orden, s.id), '[]'::jsonb) from servicios s where s.clinica_id = c.id and s.activo and s.reservable_canales));
  r := r || jsonb_build_object('bonos_y_programas', (select coalesce(jsonb_agg(jsonb_build_object(
      'nombre', t.nombre, 'categoria', t.categoria, 'descripcion', t.descripcion, 'sesiones', t.sesiones,
      'precio_euros', case when c.precios_confirmados then round(t.precio_centimos / 100.0, 2) end,
      'validez_dias', t.validez_dias, 'condiciones', t.condiciones,
      'servicios', (select jsonb_agg(s.nombre order by s.orden) from servicios s where s.id = any (t.servicios) and s.activo),
      'como_se_contrata', 'Lo vende el equipo en la consulta; las sesiones se reservan una a una salvo que el profesional proponga las fechas.')
    order by t.orden, t.id), '[]'::jsonb) from bono_tipos t where t.clinica_id = c.id and t.activo));
  return r;
end;
$$;

-- ¿Ha tenido (o tiene reservada antes) una primera consulta, o alguna consulta hecha?
create function _tiene_primera(p_paciente bigint, p_antes timestamptz) returns boolean
language sql stable security definer set search_path = nutricion, extensions, pg_temp as $$
  select p_paciente is not null and exists (
    select 1 from citas c join servicios s on s.id = c.servicio_id
    where c.paciente_id = p_paciente and c.inicio < coalesce(p_antes, 'infinity')
      and (c.estado = 'realizada' or (c.estado = 'reservada' and s.tipo = 'primera_visita')))
$$;

alter function canal_huecos(bigint, bigint, text, int, bigint, text, text) rename to _canal_huecos_fase2;
create function canal_huecos(p_conversacion bigint, p_servicio bigint, p_desde text default null, p_dias int default 7,
                             p_profesional bigint default null, p_modalidad text default null,
                             p_franja text default 'cualquiera') returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare v conversaciones := _conv(p_conversacion); s servicios;
begin
  select * into s from servicios where id = p_servicio and clinica_id = v.clinica_id;
  if s.id is not null and s.activo and s.requiere_aprobacion then
    return jsonb_build_object('ok', false, 'motivo', 'requiere_aprobacion', 'servicio', s.nombre);
  end if;
  return _canal_huecos_fase2(p_conversacion, p_servicio, p_desde, p_dias, p_profesional, p_modalidad, p_franja);
end;
$$;

alter function canal_reservar(bigint, bigint, text, bigint, text, text, text, text, boolean, text, text) rename to _canal_reservar_fase2;
create function canal_reservar(p_conversacion bigint, p_servicio bigint, p_inicio text, p_profesional bigint default null,
                               p_modalidad text default null, p_nombre text default null, p_apellidos text default null,
                               p_fecha_nacimiento text default null, p_para_otra boolean default false,
                               p_motivo text default null, p_clave text default null) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare v conversaciones := _conv(p_conversacion); s servicios; v_pac bigint; v_fecha date;
begin
  select * into s from servicios where id = p_servicio and clinica_id = v.clinica_id;
  if s.id is not null and s.activo and s.requiere_aprobacion then
    return jsonb_build_object('ok', false, 'motivo', 'requiere_aprobacion', 'servicio', s.nombre);
  end if;
  if s.id is not null and s.activo and s.requiere_primera then
    if not coalesce(p_para_otra, false) then v_pac := _verificado(v); end if;
    if v_pac is null and nullif(trim(coalesce(p_nombre, '')), '') is not null then
      begin v_fecha := nullif(p_fecha_nacimiento, '')::date; exception when others then v_fecha := null; end;
      select min(id) into v_pac from pacientes where clinica_id = v.clinica_id and telefono = v.contacto
        and fecha_nacimiento = v_fecha and lower(split_part(trim(nombre), ' ', 1)) = lower(split_part(trim(p_nombre), ' ', 1));
    end if;
    if not _tiene_primera(v_pac, _desde_local(p_inicio, _tz(v.clinica_id))) then
      return jsonb_build_object('ok', false, 'motivo', 'requiere_primera_consulta', 'servicio', s.nombre,
        'primeras_consultas', (select jsonb_agg(jsonb_build_object('servicio_id', x.id, 'nombre', x.nombre))
                               from servicios x where x.clinica_id = v.clinica_id and x.activo and x.tipo = 'primera_visita'));
    end if;
  end if;
  return _canal_reservar_fase2(p_conversacion, p_servicio, p_inicio, p_profesional, p_modalidad, p_nombre, p_apellidos,
                               p_fecha_nacimiento, p_para_otra, p_motivo, p_clave);
end;
$$;

-- ---------------------------------------------------------------- agenda por meses

-- Las citas de un mes (más los días de las semanas que lo completan) en forma corta, para la vista Mes. Los mismos
-- datos que la agenda de día y semana: misma tabla y mismas reglas.
create function agenda_mes(p_clinica uuid, p_mes date, p_profesional bigint default null) returns jsonb
language plpgsql stable security definer set search_path = nutricion, extensions, pg_temp as $$
declare v_tz text := _tz(p_clinica); v_ini date; v_fin date;
begin
  perform _miembro(p_clinica);
  v_ini := date_trunc('month', p_mes)::date;
  v_ini := v_ini - (extract(isodow from v_ini)::int - 1);
  v_fin := (date_trunc('month', p_mes) + interval '1 month - 1 day')::date;
  v_fin := v_fin + (7 - extract(isodow from v_fin)::int);
  return jsonb_build_object('ok', true, 'desde', v_ini, 'hasta', v_fin,
    'citas', (select coalesce(jsonb_agg(jsonb_build_object('id', c.id, 'dia', (c.inicio at time zone v_tz)::date,
        'hora', to_char(c.inicio at time zone v_tz, 'HH24:MI'), 'fin', to_char(c.fin at time zone v_tz, 'HH24:MI'),
        'paciente', trim(pa.nombre || ' ' || coalesce(pa.apellidos, '')), 'servicio', s.nombre, 'tipo', s.tipo,
        'estado', c.estado, 'origen', c.origen, 'profesional_id', c.profesional_id) order by c.inicio), '[]'::jsonb)
      from citas c join pacientes pa on pa.id = c.paciente_id join servicios s on s.id = c.servicio_id
      where c.clinica_id = p_clinica and (p_profesional is null or c.profesional_id = p_profesional)
        and (c.inicio at time zone v_tz)::date between v_ini and v_fin),
    'ausencias', (select coalesce(jsonb_agg(jsonb_build_object('dia', d::date, 'motivo', a.motivo)), '[]'::jsonb)
      from ausencias a cross join lateral generate_series((a.inicio at time zone v_tz)::date,
                                                          ((a.fin - interval '1 second') at time zone v_tz)::date, '1 day') d
      where a.clinica_id = p_clinica and (a.profesional_id is null or p_profesional is null or a.profesional_id = p_profesional)
        and tstzrange(a.inicio, a.fin) && tstzrange(v_ini::timestamp at time zone v_tz, (v_fin + 1)::timestamp at time zone v_tz)),
    'dias_con_horario', (select coalesce(jsonb_agg(distinct h.dia_semana), '[]'::jsonb) from horarios h
      join profesionales pr on pr.id = h.profesional_id and pr.activo
      where h.clinica_id = p_clinica and (p_profesional is null or h.profesional_id = p_profesional)));
end;
$$;

-- Una cita por su id (para abrirla desde la vista Mes o el panel).
create function ver_cita(p_clinica uuid, p_cita bigint) returns jsonb
language plpgsql stable security definer set search_path = nutricion, extensions, pg_temp as $$
begin
  perform _miembro(p_clinica);
  if not exists (select 1 from citas where id = p_cita and clinica_id = p_clinica) then
    return jsonb_build_object('ok', false, 'motivo', 'cita_no_existe');
  end if;
  return jsonb_build_object('ok', true, 'cita', _cita_json(p_cita),
    'cargo', (select _cargo_json(g.id) from cargos g where g.cita_id = p_cita and g.estado = 'abierto' limit 1));
end;
$$;

-- ---------------------------------------------------------------- contabilidad

-- Día al que pertenece un cobro: el de la consulta si es de una cita; si no, el día en que se creó.
create function _dia_cargo(p_cargo bigint) returns date
language sql stable security definer set search_path = nutricion, extensions, pg_temp as $$
  select coalesce((ci.inicio at time zone _tz(g.clinica_id))::date, (g.creado_en at time zone _tz(g.clinica_id))::date)
  from cargos g left join citas ci on ci.id = g.cita_id where g.id = p_cargo
$$;

-- Hora del movimiento para la vista de un día: la de la consulta si el pago es de ese día; si no, la de registro.
create function _hora_pago(p_pago bigint) returns int
language sql stable security definer set search_path = nutricion, extensions, pg_temp as $$
  select extract(hour from case when ci.id is not null and (ci.inicio at time zone _tz(p.clinica_id))::date = p.fecha
                                then ci.inicio else p.creado_en end at time zone _tz(p.clinica_id))::int
  from pagos p join cargos g on g.id = p.cargo_id left join citas ci on ci.id = g.cita_id where p.id = p_pago
$$;

create function _servicio_de_cargo(p_cargo bigint) returns text
language sql stable security definer set search_path = nutricion, extensions, pg_temp as $$
  select case g.tipo when 'cita' then coalesce(s.nombre, 'Consulta') when 'bono' then 'Bonos y programas' else 'Otros conceptos' end
  from cargos g left join citas ci on ci.id = g.cita_id left join servicios s on s.id = ci.servicio_id where g.id = p_cargo
$$;

-- Indicadores, evolución, desglose y movimientos de un periodo. Solo el propietario (es información del negocio).
create function contabilidad(p_clinica uuid, p_desde date, p_hasta date) returns jsonb
language plpgsql stable security definer set search_path = nutricion, extensions, pg_temp as $$
declare v_tz text := _tz(p_clinica); v_n int; v_pdesde date; v_phasta date; v_g text; v_inicio date;
begin
  perform _miembro(p_clinica, array['propietario']);
  if p_desde is null or p_hasta is null or p_hasta < p_desde or p_hasta - p_desde > 3660 then
    return jsonb_build_object('ok', false, 'motivo', 'fechas_no_validas');
  end if;
  v_n := p_hasta - p_desde + 1;
  v_phasta := p_desde - 1; v_pdesde := p_desde - v_n;
  v_g := case when v_n = 1 then 'hora' when v_n <= 31 then 'dia' when v_n <= 120 then 'semana' else 'mes' end;
  v_inicio := least((select min(fecha) from pagos where clinica_id = p_clinica),
                    (select min((inicio at time zone v_tz)::date) from citas where clinica_id = p_clinica and estado = 'realizada'));
  return jsonb_build_object('ok', true, 'desde', p_desde, 'hasta', p_hasta, 'granularidad', v_g, 'inicio_actividad', v_inicio,
    'actual', _conta_resumen(p_clinica, p_desde, p_hasta),
    'anterior', _conta_resumen(p_clinica, v_pdesde, v_phasta) || jsonb_build_object('desde', v_pdesde, 'hasta', v_phasta),
    'pendiente_total', (select round(coalesce(sum(greatest(g.importe_centimos - _cobrado(g.id), 0)), 0) / 100.0, 2)
                        from cargos g where g.clinica_id = p_clinica and g.estado = 'abierto'),
    'serie', _conta_serie(p_clinica, p_desde, p_hasta, v_g),
    'por_servicio', (select coalesce(jsonb_agg(jsonb_build_object('servicio', x.servicio, 'importe', x.imp, 'pagos', x.n)
                                               order by x.imp desc), '[]'::jsonb)
      from (select _servicio_de_cargo(p.cargo_id) servicio, count(*) filter (where p.tipo = 'pago') n,
                   round(sum(case p.tipo when 'pago' then p.importe_centimos else -p.importe_centimos end) / 100.0, 2) imp
            from pagos p where p.clinica_id = p_clinica and p.fecha between p_desde and p_hasta group by 1) x),
    'por_paciente', (select coalesce(jsonb_agg(jsonb_build_object('paciente_id', x.paciente_id, 'paciente', x.nombre,
                                               'importe', x.imp, 'pagos', x.n) order by x.imp desc), '[]'::jsonb)
      from (select p.paciente_id, trim(pa.nombre || ' ' || coalesce(pa.apellidos, '')) nombre, count(*) filter (where p.tipo = 'pago') n,
                   round(sum(case p.tipo when 'pago' then p.importe_centimos else -p.importe_centimos end) / 100.0, 2) imp
            from pagos p join pacientes pa on pa.id = p.paciente_id
            where p.clinica_id = p_clinica and p.fecha between p_desde and p_hasta group by 1, 2 order by imp desc limit 15) x),
    'por_metodo', (select coalesce(jsonb_agg(jsonb_build_object('metodo', x.metodo, 'importe', x.imp) order by x.imp desc), '[]'::jsonb)
      from (select p.metodo, round(sum(case p.tipo when 'pago' then p.importe_centimos else -p.importe_centimos end) / 100.0, 2) imp
            from pagos p where p.clinica_id = p_clinica and p.fecha between p_desde and p_hasta group by 1) x),
    'movimientos', _conta_movimientos(p_clinica, p_desde, p_hasta));
end;
$$;

create function _conta_resumen(p_clinica uuid, p_desde date, p_hasta date) returns jsonb
language sql stable security definer set search_path = nutricion, extensions, pg_temp as $$
  select jsonb_build_object(
    'cobrado', (select round(coalesce(sum(case p.tipo when 'pago' then p.importe_centimos else -p.importe_centimos end), 0) / 100.0, 2)
                from pagos p where p.clinica_id = p_clinica and p.fecha between p_desde and p_hasta),
    'devuelto', (select round(coalesce(sum(p.importe_centimos), 0) / 100.0, 2) from pagos p
                 where p.clinica_id = p_clinica and p.tipo = 'devolucion' and p.fecha between p_desde and p_hasta),
    'num_pagos', (select count(*) from pagos p where p.clinica_id = p_clinica and p.tipo = 'pago' and p.fecha between p_desde and p_hasta),
    'pendiente', (select round(coalesce(sum(greatest(g.importe_centimos - _cobrado(g.id), 0)), 0) / 100.0, 2) from cargos g
                  where g.clinica_id = p_clinica and g.estado = 'abierto' and _dia_cargo(g.id) between p_desde and p_hasta),
    'consultas_cobradas', (select count(*) from cargos g where g.clinica_id = p_clinica and g.tipo = 'cita' and g.estado = 'abierto'
                           and _estado_cargo(g.id) = 'pagado' and _dia_cargo(g.id) between p_desde and p_hasta),
    'consultas_pendientes', (select count(*) from cargos g where g.clinica_id = p_clinica and g.tipo = 'cita' and g.estado = 'abierto'
                             and _estado_cargo(g.id) in ('pendiente', 'parcial') and _dia_cargo(g.id) between p_desde and p_hasta),
    'consultas_con_bono', (select count(*) from citas c where c.clinica_id = p_clinica and c.estado = 'realizada' and c.bono_id is not null
                           and (c.inicio at time zone _tz(p_clinica))::date between p_desde and p_hasta))
$$;

create function _conta_serie(p_clinica uuid, p_desde date, p_hasta date, p_g text) returns jsonb
language plpgsql stable security definer set search_path = nutricion, extensions, pg_temp as $$
declare v_tz text := _tz(p_clinica);
begin
  if p_g = 'hora' then
    return (select jsonb_agg(jsonb_build_object('clave', lpad(h::text, 2, '0') || ':00', 'desde', p_desde, 'hasta', p_desde,
        'cobrado', (select round(coalesce(sum(case p.tipo when 'pago' then p.importe_centimos else -p.importe_centimos end), 0) / 100.0, 2)
                    from pagos p where p.clinica_id = p_clinica and p.fecha = p_desde and _hora_pago(p.id) = h),
        'pendiente', (select round(coalesce(sum(greatest(g.importe_centimos - _cobrado(g.id), 0)), 0) / 100.0, 2)
                      from cargos g left join citas ci on ci.id = g.cita_id
                      where g.clinica_id = p_clinica and g.estado = 'abierto' and _dia_cargo(g.id) = p_desde
                        and extract(hour from coalesce(ci.inicio, g.creado_en) at time zone v_tz) = h)) order by h)
      from generate_series(
        least(8, coalesce((select min(_hora_pago(p.id)) from pagos p where p.clinica_id = p_clinica and p.fecha = p_desde), 8)),
        greatest(20, coalesce((select max(_hora_pago(p.id)) from pagos p where p.clinica_id = p_clinica and p.fecha = p_desde), 20))) h);
  end if;
  return (select jsonb_agg(jsonb_build_object('clave', b.ini, 'desde', greatest(b.ini, p_desde), 'hasta', least(b.fin, p_hasta),
      'cobrado', (select round(coalesce(sum(case p.tipo when 'pago' then p.importe_centimos else -p.importe_centimos end), 0) / 100.0, 2)
                  from pagos p where p.clinica_id = p_clinica and p.fecha between greatest(b.ini, p_desde) and least(b.fin, p_hasta)),
      'pendiente', (select round(coalesce(sum(greatest(g.importe_centimos - _cobrado(g.id), 0)), 0) / 100.0, 2) from cargos g
                    where g.clinica_id = p_clinica and g.estado = 'abierto'
                      and _dia_cargo(g.id) between greatest(b.ini, p_desde) and least(b.fin, p_hasta))) order by b.ini)
    from (select d::date ini,
                 case p_g when 'dia' then d::date when 'semana' then (d + interval '6 days')::date
                          else (d + interval '1 month - 1 day')::date end fin
          from generate_series(case p_g when 'dia' then p_desde::timestamp when 'semana' then date_trunc('week', p_desde)
                                        else date_trunc('month', p_desde) end,
                               p_hasta::timestamp,
                               case p_g when 'dia' then interval '1 day' when 'semana' then interval '1 week' else interval '1 month' end) d) b);
end;
$$;

-- ---------------------------------------------------------------- facturación (preparación, sin VERI*FACTU)

alter table clinicas
  add column fiscal_direccion   text check (length(fiscal_direccion) <= 200),
  add column fiscal_cp          text check (fiscal_cp ~ '^[0-9]{5}$'),
  add column fiscal_municipio   text check (length(fiscal_municipio) <= 80),
  add column fiscal_provincia   text check (length(fiscal_provincia) <= 80),
  add column fiscal_forma       text not null default 'autonomo' check (fiscal_forma in ('autonomo', 'sociedad')),
  add column serie_facturas     text not null default 'F' check (serie_facturas ~ '^[A-Z0-9]{1,6}$'),
  add column serie_simplificadas text not null default 'FS' check (serie_simplificadas ~ '^[A-Z0-9]{1,6}$'),
  add column serie_rectificativas text not null default 'FR' check (serie_rectificativas ~ '^[A-Z0-9]{1,6}$'),
  add column texto_exencion     text not null default 'Operación exenta de IVA en virtud del artículo 20.Uno.3º de la Ley 37/1992 del IVA (asistencia sanitaria).'
                                check (length(texto_exencion) <= 300);

create table facturas (
  id                   bigint generated always as identity primary key,
  clinica_id           uuid not null references clinicas (id) on delete cascade,
  tipo                 text not null check (tipo in ('completa', 'simplificada', 'rectificativa')),
  serie                text not null,
  numero               int not null,
  numero_texto         text not null,          -- "2026-0001"
  fecha_expedicion     date not null,
  fecha_operacion      date,
  paciente_id          bigint,
  emisor               jsonb not null,         -- copia de los datos fiscales al emitir
  destinatario         jsonb not null default '{}'::jsonb,
  base_centimos        int not null,
  cuota_centimos       int not null,
  total_centimos       int not null,
  rectifica_id         bigint references facturas (id),
  motivo_rectificacion text check (length(motivo_rectificacion) <= 500),
  estado               text not null default 'emitida' check (estado in ('emitida', 'rectificada')),
  notas                text check (length(notas) <= 500),
  creada_por           uuid,
  creada_por_nombre    text,
  creada_en            timestamptz not null default now(),
  clave_idempotencia   text,
  unique (clinica_id, id),
  unique (clinica_id, serie, numero_texto),
  unique (clinica_id, clave_idempotencia),
  foreign key (clinica_id, paciente_id) references pacientes (clinica_id, id)
);
create index facturas_fecha on facturas (clinica_id, fecha_expedicion desc);

create table factura_lineas (
  id               bigint generated always as identity primary key,
  clinica_id       uuid not null,
  factura_id       bigint not null references facturas (id) on delete cascade,
  cargo_id         bigint,
  concepto         text not null check (length(trim(concepto)) between 2 and 200),
  base_centimos    int not null,
  iva_tratamiento  text not null check (iva_tratamiento in ('exento', 'iva21')),
  iva_pct          numeric(4,2) not null,
  cuota_centimos   int not null,
  total_centimos   int not null,
  vigente          boolean not null default true,   -- false cuando la factura se rectifica
  orden            int not null default 0,
  foreign key (clinica_id, cargo_id) references cargos (clinica_id, id)
);
-- Un cobro solo puede estar en una factura vigente: no se factura dos veces lo mismo.
create unique index factura_cargo_vigente on factura_lineas (cargo_id) where vigente and cargo_id is not null;

alter table facturas       enable row level security;
alter table factura_lineas enable row level security;

-- Una factura emitida no se cambia ni se borra: se corrige con una rectificativa. Solo puede pasar a 'rectificada'.
create function _factura_inmutable() returns trigger language plpgsql as $$
begin
  if tg_op = 'DELETE' then raise exception 'factura_inmutable' using errcode = '42501'; end if;
  if tg_table_name = 'facturas' then
    if (to_jsonb(new) - 'estado') <> (to_jsonb(old) - 'estado') or not (old.estado = 'emitida' and new.estado in ('emitida', 'rectificada')) then
      raise exception 'factura_inmutable' using errcode = '42501';
    end if;
  elsif (to_jsonb(new) - 'vigente') <> (to_jsonb(old) - 'vigente') or (old.vigente = false and new.vigente = true) then
    raise exception 'factura_inmutable' using errcode = '42501';
  end if;
  return new;
end;
$$;
create trigger factura_inmutable before update or delete on facturas for each row execute function _factura_inmutable();
create trigger factura_linea_inmutable before update or delete on factura_lineas for each row execute function _factura_inmutable();

create function _nif_valido(p text) returns boolean language sql immutable as $$
  -- Forma de un NIF (DNI), NIE o CIF españoles. No comprueba que exista.
  select upper(regexp_replace(coalesce(p, ''), '[\s.-]', '', 'g')) ~ '^([0-9]{8}[A-Z]|[XYZ][0-9]{7}[A-Z]|[ABCDEFGHJKLMNPQRSUVW][0-9]{7}[0-9A-J])$'
$$;

create function _factura_json(p_id bigint) returns jsonb
language sql stable security definer set search_path = nutricion, extensions, pg_temp as $$
  select jsonb_build_object('id', f.id, 'tipo', f.tipo, 'serie', f.serie, 'numero', f.numero_texto,
    'codigo', f.serie || '-' || f.numero_texto, 'fecha', f.fecha_expedicion, 'fecha_operacion', f.fecha_operacion,
    'paciente_id', f.paciente_id, 'emisor', f.emisor, 'destinatario', f.destinatario,
    'base', round(f.base_centimos / 100.0, 2), 'cuota', round(f.cuota_centimos / 100.0, 2), 'total', round(f.total_centimos / 100.0, 2),
    'estado', f.estado, 'rectifica', (select r.serie || '-' || r.numero_texto from facturas r where r.id = f.rectifica_id),
    'rectifica_id', f.rectifica_id, 'motivo_rectificacion', f.motivo_rectificacion,
    'rectificada_por', (select r.serie || '-' || r.numero_texto from facturas r where r.rectifica_id = f.id limit 1),
    'notas', f.notas, 'creada_por', f.creada_por_nombre, 'creada', _local(f.creada_en, _tz(f.clinica_id)),
    -- Estado del pago: lo que falta por cobrar de los cobros de la factura (una rectificativa no se cobra).
    'pendiente', case when f.tipo = 'rectificativa' then 0 else (select round(coalesce(sum(greatest(g.importe_centimos - _cobrado(g.id), 0)), 0) / 100.0, 2)
                 from factura_lineas l join cargos g on g.id = l.cargo_id where l.factura_id = f.id) end,
    'lineas', (select coalesce(jsonb_agg(jsonb_build_object('concepto', l.concepto, 'base', round(l.base_centimos / 100.0, 2),
                 'iva_tratamiento', l.iva_tratamiento, 'iva_pct', l.iva_pct, 'cuota', round(l.cuota_centimos / 100.0, 2),
                 'total', round(l.total_centimos / 100.0, 2), 'cargo_id', l.cargo_id) order by l.orden, l.id), '[]'::jsonb)
               from factura_lineas l where l.factura_id = f.id),
    'aviso', 'Documento de demostración preparado por Corvex. No es una factura válida: falta el sistema VERI*FACTU (registro con huella, código QR y envío a la AEAT).')
  from facturas f where f.id = p_id
$$;

-- Tratamiento de IVA de un cobro según su origen (servicio de la cita o tipo de bono). null = sin decidir.
create function _iva_de_cargo(p_cargo bigint) returns text
language sql stable security definer set search_path = nutricion, extensions, pg_temp as $$
  select case g.tipo when 'cita' then s.iva_tratamiento when 'bono' then t.iva_tratamiento end
  from cargos g left join citas ci on ci.id = g.cita_id left join servicios s on s.id = ci.servicio_id
  left join bonos b on b.id = g.bono_id left join bono_tipos t on t.id = b.bono_tipo_id where g.id = p_cargo
$$;

-- Cobros que se pueden facturar (no anulados y sin factura vigente), de un paciente o de todos.
create function cobros_por_facturar(p_clinica uuid, p_paciente bigint default null) returns jsonb
language plpgsql stable security definer set search_path = nutricion, extensions, pg_temp as $$
begin
  perform _miembro(p_clinica, array['propietario', 'recepcion']);
  return (select coalesce(jsonb_agg(_cargo_json(g.id) || jsonb_build_object('iva_tratamiento', _iva_de_cargo(g.id), 'dia', _dia_cargo(g.id),
                                    'servicio', _servicio_de_cargo(g.id)) order by _dia_cargo(g.id) desc, g.id desc), '[]'::jsonb)
    from cargos g where g.clinica_id = p_clinica and g.estado = 'abierto' and (p_paciente is null or g.paciente_id = p_paciente)
      and not exists (select 1 from factura_lineas l where l.cargo_id = g.id and l.vigente));
end;
$$;

-- Siguiente número de una serie en un año (sin huecos: se bloquea la fila del contador).
create function _siguiente_factura(p_clinica uuid, p_serie text, p_anio int) returns int
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare v int;
begin
  insert into contadores as k (clinica_id, serie, ultimo) values (p_clinica, 'factura:' || p_serie || ':' || p_anio, 1)
  on conflict (clinica_id, serie) do update set ultimo = k.ultimo + 1 returning k.ultimo into v;
  return v;
end;
$$;

-- d: {cargo_ids: [..], tipo: completa|simplificada, destinatario: {nombre, nif, direccion, cp, municipio, provincia},
--     ivas?: {cargo_id: 'exento'|'iva21'} (para cobros sin tratamiento decidido), fecha_operacion?, notas?, clave?}
create function crear_factura(p_clinica uuid, d jsonb) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare m miembros := _miembro(p_clinica, array['propietario', 'recepcion']); cl clinicas; v_tz text := _tz(p_clinica);
        v_ids bigint[]; v_pac bigint; v_tipo text := coalesce(nullif(d->>'tipo', ''), 'completa'); v_dest jsonb; v_serie text;
        v_anio int; v_num int; v_id bigint; g record; v_iva text; v_base int; v_cuota int; v_tot int; n int := 0;
        v_total bigint := 0; v_hoy date := _hoy(_tz(p_clinica)); v_lineas jsonb := '[]'::jsonb;
begin
  if d->>'clave' is not null then
    select id into v_id from facturas where clinica_id = p_clinica and clave_idempotencia = d->>'clave';
    if v_id is not null then return jsonb_build_object('ok', true, 'repetida', true, 'factura', _factura_json(v_id)); end if;
  end if;
  select * into cl from clinicas where id = p_clinica;
  if cl.nif is null or not _nif_valido(cl.nif) or cl.fiscal_direccion is null or cl.fiscal_cp is null or cl.fiscal_municipio is null then
    return jsonb_build_object('ok', false, 'motivo', 'faltan_datos_fiscales');
  end if;
  if v_tipo not in ('completa', 'simplificada') then return jsonb_build_object('ok', false, 'motivo', 'valor_no_valido'); end if;
  select array_agg(distinct x::bigint) into v_ids from jsonb_array_elements_text(coalesce(d->'cargo_ids', '[]')) x;
  if v_ids is null then return jsonb_build_object('ok', false, 'motivo', 'sin_cobros'); end if;
  -- Se bloquean los cobros: dos personas facturando lo mismo a la vez no crean dos facturas.
  perform 1 from cargos where id = any (v_ids) for update;
  if (select count(*) from cargos where id = any (v_ids) and clinica_id = p_clinica and estado = 'abierto') <> cardinality(v_ids) then
    return jsonb_build_object('ok', false, 'motivo', 'cargo_no_existe');
  end if;
  if (select count(distinct paciente_id) from cargos where id = any (v_ids)) > 1 then
    return jsonb_build_object('ok', false, 'motivo', 'varios_pacientes');
  end if;
  if exists (select 1 from factura_lineas where cargo_id = any (v_ids) and vigente) then
    return jsonb_build_object('ok', false, 'motivo', 'ya_facturado');
  end if;
  select paciente_id into v_pac from cargos where id = v_ids[1];
  for g in select id from cargos where id = any (v_ids) loop
    if coalesce(_iva_de_cargo(g.id), d->'ivas'->>(g.id::text)) is null then
      return jsonb_build_object('ok', false, 'motivo', 'falta_tratamiento_iva', 'cargo_id', g.id);
    end if;
  end loop;
  v_dest := jsonb_strip_nulls(jsonb_build_object(
    'nombre', nullif(trim(coalesce(d->'destinatario'->>'nombre', '')), ''),
    'nif', nullif(upper(regexp_replace(coalesce(d->'destinatario'->>'nif', ''), '[\s.-]', '', 'g')), ''),
    'direccion', nullif(trim(coalesce(d->'destinatario'->>'direccion', '')), ''),
    'cp', nullif(trim(coalesce(d->'destinatario'->>'cp', '')), ''),
    'municipio', nullif(trim(coalesce(d->'destinatario'->>'municipio', '')), ''),
    'provincia', nullif(trim(coalesce(d->'destinatario'->>'provincia', '')), '')));
  -- Factura completa: nombre y NIF del destinatario (art. 6 del Reglamento de facturación). Simplificada: hasta 400 €.
  if v_tipo = 'completa' and (v_dest->>'nombre' is null or v_dest->>'nif' is null) then
    return jsonb_build_object('ok', false, 'motivo', 'faltan_datos_destinatario');
  end if;
  if v_dest->>'nif' is not null and not _nif_valido(v_dest->>'nif') then
    return jsonb_build_object('ok', false, 'motivo', 'nif_no_valido');
  end if;
  select sum(importe_centimos) into v_total from cargos where id = any (v_ids);
  if v_tipo = 'simplificada' and v_total > 40000 then
    return jsonb_build_object('ok', false, 'motivo', 'simplificada_limite');
  end if;
  -- Líneas: el precio al paciente lleva el IVA incluido, así que con IVA la base es total / 1,21.
  for g in select c.id, c.concepto, c.importe_centimos from cargos c where c.id = any (v_ids) order by _dia_cargo(c.id), c.id loop
    v_iva := coalesce(_iva_de_cargo(g.id), d->'ivas'->>(g.id::text));
    if v_iva not in ('exento', 'iva21') then return jsonb_build_object('ok', false, 'motivo', 'valor_no_valido'); end if;
    v_tot := g.importe_centimos;
    v_base := case v_iva when 'iva21' then round(v_tot / 1.21)::int else v_tot end;
    v_cuota := v_tot - v_base;
    v_lineas := v_lineas || jsonb_build_object('cargo_id', g.id, 'concepto', g.concepto, 'base', v_base, 'iva', v_iva,
                                               'pct', case v_iva when 'iva21' then 21 else 0 end, 'cuota', v_cuota, 'total', v_tot, 'orden', n);
    n := n + 1;
  end loop;
  v_serie := case v_tipo when 'completa' then cl.serie_facturas else cl.serie_simplificadas end;
  v_anio := extract(year from v_hoy)::int;
  v_num := _siguiente_factura(p_clinica, v_serie, v_anio);
  insert into facturas (clinica_id, tipo, serie, numero, numero_texto, fecha_expedicion, fecha_operacion, paciente_id, emisor,
                        destinatario, base_centimos, cuota_centimos, total_centimos, notas, creada_por, creada_por_nombre,
                        clave_idempotencia)
  values (p_clinica, v_tipo, v_serie, v_num, v_anio || '-' || lpad(v_num::text, 4, '0'), v_hoy,
          coalesce(nullif(d->>'fecha_operacion', '')::date, (select max(_dia_cargo(id)) from cargos where id = any (v_ids))),
          v_pac, jsonb_strip_nulls(jsonb_build_object('nombre', coalesce(cl.razon_social, cl.nombre), 'comercial', cl.nombre,
                   'nif', cl.nif, 'direccion', cl.fiscal_direccion, 'cp', cl.fiscal_cp, 'municipio', cl.fiscal_municipio,
                   'provincia', cl.fiscal_provincia, 'telefono', cl.telefono, 'email', cl.email, 'texto_exencion', cl.texto_exencion)),
          v_dest, (select sum((x->>'base')::int) from jsonb_array_elements(v_lineas) x),
          (select sum((x->>'cuota')::int) from jsonb_array_elements(v_lineas) x),
          (select sum((x->>'total')::int) from jsonb_array_elements(v_lineas) x),
          left(nullif(trim(coalesce(d->>'notas', '')), ''), 500), auth.uid(), m.nombre, nullif(d->>'clave', ''))
  returning id into v_id;
  insert into factura_lineas (clinica_id, factura_id, cargo_id, concepto, base_centimos, iva_tratamiento, iva_pct, cuota_centimos,
                              total_centimos, orden)
  select p_clinica, v_id, (x->>'cargo_id')::bigint, x->>'concepto', (x->>'base')::int, x->>'iva', (x->>'pct')::numeric,
         (x->>'cuota')::int, (x->>'total')::int, (x->>'orden')::int
  from jsonb_array_elements(v_lineas) x;
  update cargos set factura_estado = 'emitida', factura_numero = v_serie || '-' || v_anio || '-' || lpad(v_num::text, 4, '0'),
    factura_emitida_en = now(), factura_pedida_en = coalesce(factura_pedida_en, now()),
    factura_datos = case when v_dest ? 'nif' then jsonb_build_object('nombre', v_dest->>'nombre', 'nif', v_dest->>'nif',
                                                                      'direccion', v_dest->>'direccion') else factura_datos end
  where id = any (v_ids);
  perform _auditar(p_clinica, 'crear_factura', 'factura', v_id::text, v_pac, jsonb_build_object('tipo', v_tipo, 'cobros', cardinality(v_ids)));
  return jsonb_build_object('ok', true, 'factura', _factura_json(v_id));
end;
$$;

-- Rectificativa por anulación total (importes en negativo). La original queda 'rectificada' y sus cobros vuelven a
-- poder facturarse (por ejemplo, con los datos corregidos). d: {motivo, clave?}
create function rectificar_factura(p_clinica uuid, p_factura bigint, d jsonb) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare m miembros := _miembro(p_clinica, array['propietario']); f facturas; cl clinicas; v_id bigint; v_num int; v_anio int;
        v_hoy date := _hoy(_tz(p_clinica));
begin
  if d->>'clave' is not null then
    select id into v_id from facturas where clinica_id = p_clinica and clave_idempotencia = d->>'clave';
    if v_id is not null then return jsonb_build_object('ok', true, 'repetida', true, 'factura', _factura_json(v_id)); end if;
  end if;
  select * into f from facturas where id = p_factura and clinica_id = p_clinica for update;
  if f.id is null then return jsonb_build_object('ok', false, 'motivo', 'factura_no_existe'); end if;
  if f.tipo = 'rectificativa' or f.estado <> 'emitida' then return jsonb_build_object('ok', false, 'motivo', 'factura_no_rectificable'); end if;
  if nullif(trim(coalesce(d->>'motivo', '')), '') is null then return jsonb_build_object('ok', false, 'motivo', 'falta_motivo'); end if;
  select * into cl from clinicas where id = p_clinica;
  v_anio := extract(year from v_hoy)::int;
  v_num := _siguiente_factura(p_clinica, cl.serie_rectificativas, v_anio);
  insert into facturas (clinica_id, tipo, serie, numero, numero_texto, fecha_expedicion, fecha_operacion, paciente_id, emisor,
                        destinatario, base_centimos, cuota_centimos, total_centimos, rectifica_id, motivo_rectificacion,
                        creada_por, creada_por_nombre, clave_idempotencia)
  values (p_clinica, 'rectificativa', cl.serie_rectificativas, v_num, v_anio || '-' || lpad(v_num::text, 4, '0'), v_hoy,
          f.fecha_operacion, f.paciente_id, f.emisor, f.destinatario, -f.base_centimos, -f.cuota_centimos, -f.total_centimos,
          f.id, left(trim(d->>'motivo'), 500), auth.uid(), m.nombre, nullif(d->>'clave', ''))
  returning id into v_id;
  insert into factura_lineas (clinica_id, factura_id, cargo_id, concepto, base_centimos, iva_tratamiento, iva_pct, cuota_centimos,
                              total_centimos, vigente, orden)
  select p_clinica, v_id, null, 'Anula: ' || left(l.concepto, 190), -l.base_centimos, l.iva_tratamiento, l.iva_pct, -l.cuota_centimos,
         -l.total_centimos, false, l.orden
  from factura_lineas l where l.factura_id = f.id;
  update factura_lineas set vigente = false where factura_id = f.id;
  update facturas set estado = 'rectificada' where id = f.id;
  update cargos set factura_estado = 'no_pedida', factura_numero = null, factura_emitida_en = null
  where id in (select cargo_id from factura_lineas where factura_id = f.id);
  perform _auditar(p_clinica, 'rectificar_factura', 'factura', v_id::text, f.paciente_id, jsonb_build_object('rectifica', f.id));
  return jsonb_build_object('ok', true, 'factura', _factura_json(v_id));
end;
$$;

-- p_buscar: número, nombre o NIF. p_tipo / p_estado opcionales.
create function lista_facturas(p_clinica uuid, p_desde date, p_hasta date, p_buscar text default null) returns jsonb
language plpgsql stable security definer set search_path = nutricion, extensions, pg_temp as $$
begin
  perform _miembro(p_clinica, array['propietario', 'recepcion']);
  return (select coalesce(jsonb_agg(_factura_json(f.id) order by f.fecha_expedicion desc, f.id desc), '[]'::jsonb)
    from facturas f left join pacientes pa on pa.id = f.paciente_id
    where f.clinica_id = p_clinica and f.fecha_expedicion between coalesce(p_desde, '1900-01-01') and coalesce(p_hasta, '2999-12-31')
      and (nullif(trim(coalesce(p_buscar, '')), '') is null
           or _normal(f.serie || '-' || f.numero_texto || ' ' || coalesce(f.destinatario->>'nombre', '') || ' ' ||
                      coalesce(f.destinatario->>'nif', '') || ' ' || coalesce(pa.nombre, '') || ' ' || coalesce(pa.apellidos, ''))
              like '%' || _normal(trim(p_buscar)) || '%'));
end;
$$;

create function ver_factura(p_clinica uuid, p_factura bigint) returns jsonb
language plpgsql stable security definer set search_path = nutricion, extensions, pg_temp as $$
begin
  perform _miembro(p_clinica, array['propietario', 'recepcion']);
  if not exists (select 1 from facturas where id = p_factura and clinica_id = p_clinica) then
    return jsonb_build_object('ok', false, 'motivo', 'factura_no_existe');
  end if;
  return jsonb_build_object('ok', true, 'factura', _factura_json(p_factura));
end;
$$;

-- Libro de facturas expedidas para la gestoría: una fila por factura y tipo de IVA.
create function exportar_facturas(p_clinica uuid, p_desde date, p_hasta date) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
begin
  perform _miembro(p_clinica, array['propietario']);
  perform _auditar(p_clinica, 'exportar_facturas', 'clinica', p_clinica::text, null, jsonb_build_object('desde', p_desde, 'hasta', p_hasta));
  return (select coalesce(jsonb_agg(jsonb_build_object('fecha', f.fecha_expedicion, 'fecha_operacion', f.fecha_operacion,
      'factura', f.serie || '-' || f.numero_texto, 'tipo', f.tipo,
      'rectifica', (select r.serie || '-' || r.numero_texto from facturas r where r.id = f.rectifica_id),
      'destinatario', f.destinatario->>'nombre', 'nif', f.destinatario->>'nif',
      'iva', x.iva_tratamiento, 'iva_pct', x.iva_pct, 'base', round(x.base / 100.0, 2), 'cuota', round(x.cuota / 100.0, 2),
      'total', round(x.total / 100.0, 2), 'estado', f.estado) order by f.fecha_expedicion, f.serie, f.numero), '[]'::jsonb)
    from facturas f join lateral (select l.iva_tratamiento, l.iva_pct, sum(l.base_centimos) base, sum(l.cuota_centimos) cuota,
                                         sum(l.total_centimos) total
                                  from factura_lineas l where l.factura_id = f.id group by 1, 2) x on true
    where f.clinica_id = p_clinica and f.fecha_expedicion between p_desde and p_hasta);
end;
$$;

-- Movimientos: cada pago o devolución, y cada cobro que sigue pendiente (lo que se debe todavía).
create function _conta_movimientos(p_clinica uuid, p_desde date, p_hasta date) returns jsonb
language sql stable security definer set search_path = nutricion, extensions, pg_temp as $$
  select coalesce(jsonb_agg(m order by m->>'fecha' desc, m->>'orden' desc), '[]'::jsonb) from (
    select jsonb_build_object('tipo', p.tipo, 'orden', lpad(p.id::text, 12, '0'), 'fecha', p.fecha, 'pago_id', p.id, 'cargo_id', g.id,
      'paciente_id', p.paciente_id, 'paciente', trim(pa.nombre || ' ' || coalesce(pa.apellidos, '')),
      'servicio', _servicio_de_cargo(g.id), 'concepto', g.concepto,
      'importe', round(case p.tipo when 'pago' then p.importe_centimos else -p.importe_centimos end / 100.0, 2),
      'estado', _estado_cargo(g.id), 'metodo', p.metodo, 'recibo', p.recibo_serie || '-' || p.recibo_numero,
      'factura', (select f.serie || '-' || f.numero_texto from factura_lineas l join facturas f on f.id = l.factura_id
                  where l.cargo_id = g.id and l.vigente limit 1)) m
    from pagos p join cargos g on g.id = p.cargo_id join pacientes pa on pa.id = p.paciente_id
    where p.clinica_id = p_clinica and p.fecha between p_desde and p_hasta
    union all
    select jsonb_build_object('tipo', 'pendiente', 'orden', 'z' || lpad(g.id::text, 12, '0'), 'fecha', _dia_cargo(g.id), 'cargo_id', g.id,
      'paciente_id', g.paciente_id, 'paciente', trim(pa.nombre || ' ' || coalesce(pa.apellidos, '')),
      'servicio', _servicio_de_cargo(g.id), 'concepto', g.concepto,
      'importe', round(greatest(g.importe_centimos - _cobrado(g.id), 0) / 100.0, 2),
      'estado', _estado_cargo(g.id), 'metodo', null, 'recibo', null,
      'factura', (select f.serie || '-' || f.numero_texto from factura_lineas l join facturas f on f.id = l.factura_id
                  where l.cargo_id = g.id and l.vigente limit 1))
    from cargos g join pacientes pa on pa.id = g.paciente_id
    where g.clinica_id = p_clinica and g.estado = 'abierto' and _cobrado(g.id) < g.importe_centimos
      and _dia_cargo(g.id) between p_desde and p_hasta) x(m)
$$;

-- Datos fiscales en los ajustes de la consulta.
alter function guardar_clinica(uuid, jsonb) rename to _guardar_clinica_fase5;
create function guardar_clinica(p_clinica uuid, d jsonb) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare r jsonb;
begin
  if d ? 'nif' and nullif(trim(d->>'nif'), '') is not null and not _nif_valido(d->>'nif') then
    return jsonb_build_object('ok', false, 'motivo', 'nif_no_valido');
  end if;
  r := _guardar_clinica_fase5(p_clinica, d);
  if not coalesce((r->>'ok')::boolean, false) then return r; end if;
  begin
    update clinicas set
      fiscal_direccion = case when d ? 'fiscal_direccion' then nullif(trim(d->>'fiscal_direccion'), '') else fiscal_direccion end,
      fiscal_cp = case when d ? 'fiscal_cp' then nullif(trim(d->>'fiscal_cp'), '') else fiscal_cp end,
      fiscal_municipio = case when d ? 'fiscal_municipio' then nullif(trim(d->>'fiscal_municipio'), '') else fiscal_municipio end,
      fiscal_provincia = case when d ? 'fiscal_provincia' then nullif(trim(d->>'fiscal_provincia'), '') else fiscal_provincia end,
      fiscal_forma = coalesce(nullif(d->>'fiscal_forma', ''), fiscal_forma),
      serie_facturas = coalesce(upper(nullif(trim(d->>'serie_facturas'), '')), serie_facturas),
      serie_simplificadas = coalesce(upper(nullif(trim(d->>'serie_simplificadas'), '')), serie_simplificadas),
      serie_rectificativas = coalesce(upper(nullif(trim(d->>'serie_rectificativas'), '')), serie_rectificativas),
      texto_exencion = coalesce(nullif(trim(d->>'texto_exencion'), ''), texto_exencion),
      nif = case when d ? 'nif' then upper(regexp_replace(nullif(trim(d->>'nif'), ''), '[\s.-]', '', 'g')) else nif end
    where id = p_clinica;
  exception when check_violation then
    raise exception 'valor_no_valido' using errcode = '22023';
  end;
  return r;
end;
$$;

-- ---------------------------------------------------------------- panel: cambios recientes

-- Lo último que ha pasado en la agenda sin que lo hiciera quien mira: reservas por WhatsApp o teléfono, cambios y
-- cancelaciones de los últimos días.
create function cambios_recientes(p_clinica uuid, p_dias int default 7) returns jsonb
language plpgsql stable security definer set search_path = nutricion, extensions, pg_temp as $$
declare v_tz text := _tz(p_clinica);
begin
  perform _miembro(p_clinica);
  return (select coalesce(jsonb_agg(x order by x->>'cuando' desc), '[]'::jsonb) from (
    select jsonb_build_object('cuando', _local(a.cuando, v_tz), 'accion', a.accion, 'actor', a.actor_tipo,
             'quien', coalesce(a.actor_nombre, case a.actor_tipo when 'whatsapp' then 'WhatsApp' when 'telefono' then 'Teléfono' else a.actor_tipo end),
             'cita', _cita_json(a.entidad_id::bigint), 'antes', a.detalle->>'antes') x
    from auditoria a
    where a.clinica_id = p_clinica and a.entidad = 'cita' and a.cuando > now() - make_interval(days => least(greatest(p_dias, 1), 60))
      and a.accion in ('reservar_cita', 'cambiar_cita', 'cancelar_cita')
      and (a.accion <> 'reservar_cita' or a.actor_tipo <> 'usuario' or a.actor_id is distinct from auth.uid())
      and exists (select 1 from citas c where c.id = a.entidad_id::bigint)
    order by a.cuando desc limit 15) t);
end;
$$;

-- ---------------------------------------------------------------- estadísticas: más detalle de la actividad

alter function estadisticas(uuid, date, date, bigint) rename to _estadisticas_fase5;
create function estadisticas(p_clinica uuid, p_desde date default null, p_hasta date default null,
                             p_profesional bigint default null) returns jsonb
language plpgsql stable security definer set search_path = nutricion, extensions, pg_temp as $$
declare r jsonb := _estadisticas_fase5(p_clinica, p_desde, p_hasta, p_profesional); v_tz text := _tz(p_clinica);
        v_desde date; v_hasta date;
begin
  if not coalesce((r->>'ok')::boolean, false) then return r; end if;
  v_desde := (r->>'desde')::date; v_hasta := (r->>'hasta')::date;
  return r || jsonb_build_object(
    -- Recurrentes: con dos o más consultas realizadas en el periodo.
    'pacientes_recurrentes', (select count(*) from (select c.paciente_id from citas c where c.clinica_id = p_clinica
        and c.estado = 'realizada' and (c.inicio at time zone v_tz)::date between v_desde and v_hasta
        and (p_profesional is null or c.profesional_id = p_profesional) group by 1 having count(*) >= 2) z),
    'pacientes_atendidos', (select count(distinct c.paciente_id) from citas c where c.clinica_id = p_clinica
        and c.estado = 'realizada' and (c.inicio at time zone v_tz)::date between v_desde and v_hasta
        and (p_profesional is null or c.profesional_id = p_profesional)),
    'servicios', (select coalesce(jsonb_agg(jsonb_build_object('servicio', z.nombre, 'tipo', z.tipo, 'citas', z.n, 'realizadas', z.r)
                                            order by z.n desc), '[]'::jsonb)
      from (select s.nombre, s.tipo, count(*) n, count(*) filter (where c.estado = 'realizada') r from citas c join servicios s on s.id = c.servicio_id
            where c.clinica_id = p_clinica and c.estado <> 'cancelada' and (c.inicio at time zone v_tz)::date between v_desde and v_hasta
              and (p_profesional is null or c.profesional_id = p_profesional) group by 1, 2) z),
    -- Reservas hechas cada mes (por el día en que se reservaron) y por dónde llegaron.
    'reservas', (select coalesce(jsonb_agg(jsonb_build_object('mes', to_char(z.mes, 'YYYY-MM'), 'app', z.app, 'whatsapp', z.wa,
                                              'telefono', z.tel, 'portal', z.por) order by z.mes), '[]'::jsonb)
      from (select m.mes, count(c.id) filter (where c.origen = 'app') app, count(c.id) filter (where c.origen = 'whatsapp') wa,
                   count(c.id) filter (where c.origen = 'telefono') tel, count(c.id) filter (where c.origen = 'portal') por
            from generate_series(date_trunc('month', v_desde), date_trunc('month', v_hasta), '1 month') m(mes)
            left join citas c on c.clinica_id = p_clinica and date_trunc('month', c.creada_en at time zone v_tz) = m.mes
              and (c.creada_en at time zone v_tz)::date between v_desde and v_hasta
              and (p_profesional is null or c.profesional_id = p_profesional)
            group by m.mes) z));
end;
$$;

-- ---------------------------------------------------------------- asistente: más órdenes

-- Servicios cuyo nombre contiene todas las palabras dichas (sin contar las de relleno), del que menos sobra al que más.
create function _buscar_servicio(p_clinica uuid, p_texto text) returns bigint[]
language sql stable security definer set search_path = nutricion, extensions, pg_temp as $$
  with w as (select x from regexp_split_to_table(_normal(trim(coalesce(p_texto, ''))), '\s+') x
             where x <> '' and x not in ('de', 'del', 'la', 'el', 'las', 'los', 'y', 'servicio', 'precio', 'duracion')),
  c as (select s.id, s.orden,
               (select count(*) from regexp_split_to_table(_normal(s.nombre), '\s+') y) - (select count(*) from w) sobra,
               _normal(s.nombre) = (select string_agg(x, ' ') from w) exacto
        from servicios s
        where s.clinica_id = p_clinica and (select count(*) from w) > 0
          and not exists (select 1 from w where not (' ' || _normal(s.nombre)) like '% ' || w.x || '%'))
  select coalesce(array_agg(id order by exacto desc, sobra, orden, id), '{}') from c
  where exacto or not exists (select 1 from c c2 where c2.exacto)
$$;

alter function _voz_planificar(uuid, miembros, text, jsonb) rename to _voz_planificar_fase5;
create function _voz_planificar(p_clinica uuid, m miembros, p_accion text, d jsonb) returns jsonb
language plpgsql stable security definer set search_path = nutricion, extensions, pg_temp as $$
declare v_tz text := _tz(p_clinica); v_ids bigint[]; v_pac bigint := nullif(d->>'paciente_id', '')::bigint; pa pacientes;
        v_nombre text; ci citas; s servicios; v_ini timestamptz; v_fin timestamptz; v_n int; v_op jsonb; v_cent int; v_imp numeric;
        v_dur int; v_cambios text[] := '{}'; v_desde date;
begin
  if p_accion not in ('cambiar_cita', 'anadir_nota', 'cambiar_servicio') then
    return _voz_planificar_fase5(p_clinica, m, p_accion, d);
  end if;

  if p_accion = 'cambiar_servicio' then
    if m.rol <> 'propietario' then return jsonb_build_object('estado', 'fallida', 'motivo', 'sin_permiso'); end if;
    if d->>'servicio_id' is null then
      v_ids := _buscar_servicio(p_clinica, d->>'servicio');
      if cardinality(v_ids) = 0 then
        return jsonb_build_object('estado', 'fallida', 'motivo', 'servicio_no_encontrado', 'buscado', d->>'servicio');
      elsif cardinality(v_ids) > 1 then
        return jsonb_build_object('estado', 'aclarar', 'pregunta', '¿Qué servicio?', 'clave_opcion', 'servicio_id', 'datos', d,
          'opciones', (select jsonb_agg(jsonb_build_object('id', y.id, 'nombre', y.nombre || ' · ' || coalesce(_euros(y.precio_centimos), 'sin precio')
                        || ' · ' || y.duracion_min || ' min') order by array_position(v_ids, y.id)) from servicios y where y.id = any (v_ids[1:8])));
      end if;
      d := d || jsonb_build_object('servicio_id', v_ids[1]);
    end if;
    select * into s from servicios where id = (d->>'servicio_id')::bigint and clinica_id = p_clinica;
    if s.id is null then return jsonb_build_object('estado', 'fallida', 'motivo', 'servicio_no_existe'); end if;
    if nullif(d->>'precio', '') is not null then
      begin v_imp := replace(d->>'precio', ',', '.')::numeric; exception when others then v_imp := null; end;
      if v_imp is null or v_imp < 0 or v_imp > 10000 then return jsonb_build_object('estado', 'fallida', 'motivo', 'importe_no_valido'); end if;
      v_cent := round(v_imp * 100)::int;
      if v_cent is distinct from s.precio_centimos then
        v_cambios := v_cambios || ('precio de ' || coalesce(_euros(s.precio_centimos), 'sin precio') || ' a ' || _euros(v_cent));
      end if;
      d := d || jsonb_build_object('precio', round(v_cent / 100.0, 2));
    end if;
    if nullif(d->>'duracion_min', '') is not null then
      v_dur := (d->>'duracion_min')::int;
      if v_dur not between 10 and 240 then return jsonb_build_object('estado', 'fallida', 'motivo', 'valor_no_valido'); end if;
      if v_dur <> s.duracion_min then v_cambios := v_cambios || ('duración de ' || s.duracion_min || ' a ' || v_dur || ' minutos'); end if;
    end if;
    if d ? 'activo' and (d->>'activo')::boolean is distinct from s.activo then
      v_cambios := v_cambios || case when (d->>'activo')::boolean then 'volver a ofrecerlo' else 'dejar de ofrecerlo (desactivarlo)' end;
    end if;
    if cardinality(v_cambios) = 0 then
      return jsonb_build_object('estado', 'fallida', 'motivo', case when nullif(d->>'precio', '') is null and nullif(d->>'duracion_min', '') is null
        and not d ? 'activo' then 'falta_cambio_servicio' else 'sin_cambios' end);
    end if;
    return jsonb_build_object('estado', 'propuesta', 'datos', d, 'resumen',
      'Cambiar en «' || s.nombre || '» el ' || array_to_string(v_cambios, ' y la ') || '. La agenda y los asistentes de WhatsApp y '
      || 'teléfono lo usan desde ese momento' || case when v_cent is not null and v_cent is distinct from s.precio_centimos
           then '; las citas ya reservadas de este servicio pasan al nuevo precio.' else '.' end
      || case when v_dur is not null and v_dur <> s.duracion_min then ' Las citas ya dadas no se mueven.' else '' end);
  end if;

  -- Paciente
  if v_pac is null then
    v_ids := _buscar_por_nombre(p_clinica, d->>'paciente');
    if cardinality(v_ids) = 0 then
      return jsonb_build_object('estado', 'fallida', 'motivo', 'paciente_no_encontrado', 'buscado', d->>'paciente');
    elsif cardinality(v_ids) > 1 then
      return jsonb_build_object('estado', 'aclarar', 'pregunta', '¿A qué paciente te refieres?',
        'candidatos', (select jsonb_agg(_candidato(x)) from unnest(v_ids[1:8]) x), 'datos', d);
    end if;
    v_pac := v_ids[1];
  end if;
  select * into pa from pacientes where id = v_pac and clinica_id = p_clinica;
  if pa.id is null then return jsonb_build_object('estado', 'fallida', 'motivo', 'paciente_no_existe'); end if;
  v_nombre := trim(pa.nombre || ' ' || coalesce(pa.apellidos, ''));
  d := d || jsonb_build_object('paciente_id', v_pac);

  if p_accion = 'anadir_nota' then
    if not _puede_salud(m.rol) then return jsonb_build_object('estado', 'fallida', 'motivo', 'solo_profesional'); end if;
    if nullif(trim(coalesce(d->>'nota', '')), '') is null then return jsonb_build_object('estado', 'fallida', 'motivo', 'falta_texto'); end if;
    -- El resumen no copia la nota (que queda en datos solo hasta confirmar o descartar).
    return jsonb_build_object('estado', 'propuesta', 'datos', d, 'editable', 'nota', 'resumen',
      'Añadir una nota a la ficha de ' || v_nombre || ' con fecha de hoy. Revisa el texto antes de guardarlo.');
  end if;

  -- cambiar_cita: la cita (reservada y futura) de ese paciente; si se dijo de qué día u hora, la de ese día u hora.
  if d->>'cita_id' is null then
    begin v_desde := nullif(d->>'desde_fecha', '')::date; exception when others then v_desde := null; end;
    select count(*), jsonb_agg(jsonb_build_object('id', c.id, 'nombre', fecha_es(c.inicio, v_tz) || ' · ' || s2.nombre) order by c.inicio)
      into v_n, v_op
    from citas c join servicios s2 on s2.id = c.servicio_id
    where c.paciente_id = v_pac and c.estado = 'reservada' and c.inicio > now()
      and (v_desde is null or (c.inicio at time zone v_tz)::date = v_desde)
      and (nullif(d->>'desde_hora', '') is null or to_char(c.inicio at time zone v_tz, 'HH24:MI') = d->>'desde_hora');
    if v_n = 0 then return jsonb_build_object('estado', 'fallida', 'motivo', 'cita_no_encontrada', 'buscado', v_nombre); end if;
    if v_n > 1 then
      return jsonb_build_object('estado', 'aclarar', 'pregunta', '¿Qué cita de ' || v_nombre || '?', 'opciones', v_op,
                                'clave_opcion', 'cita_id', 'datos', d);
    end if;
    select c.id into v_n from citas c where c.paciente_id = v_pac and c.estado = 'reservada' and c.inicio > now()
      and (v_desde is null or (c.inicio at time zone v_tz)::date = v_desde)
      and (nullif(d->>'desde_hora', '') is null or to_char(c.inicio at time zone v_tz, 'HH24:MI') = d->>'desde_hora');
    d := d || jsonb_build_object('cita_id', v_n);
  end if;
  select * into ci from citas where id = (d->>'cita_id')::bigint and paciente_id = v_pac and clinica_id = p_clinica;
  if ci.id is null or ci.estado <> 'reservada' then return jsonb_build_object('estado', 'fallida', 'motivo', 'cita_no_encontrada'); end if;
  if nullif(d->>'fecha', '') is null or nullif(d->>'hora', '') is null then
    return jsonb_build_object('estado', 'fallida', 'motivo', 'falta_nueva_hora');
  end if;
  v_ini := _desde_local((d->>'fecha') || 'T' || (d->>'hora'), v_tz);
  if v_ini is null or v_ini < now() then return jsonb_build_object('estado', 'fallida', 'motivo', 'fecha_pasada'); end if;
  select * into s from servicios where id = ci.servicio_id;
  v_fin := v_ini + make_interval(mins => s.duracion_min);
  if not _libre(ci.profesional_id, v_ini, v_fin, ci.modalidad, ci.id) then
    return jsonb_build_object('estado', 'fallida', 'motivo', 'hueco_no_disponible_voz',
      'resumen', fecha_es(v_ini, v_tz) || ' no está libre para ' || (select nombre from profesionales where id = ci.profesional_id)
                 || ' (fuera de su horario, en un bloqueo o con otra cita).');
  end if;
  d := d || jsonb_build_object('inicio', _local(v_ini, v_tz), 'profesional_id', ci.profesional_id);
  return jsonb_build_object('estado', 'propuesta', 'datos', d, 'resumen',
    'Cambiar la cita de ' || v_nombre || ' (' || s.nombre || ') del ' || fecha_es(ci.inicio, v_tz) || ' al ' || fecha_es(v_ini, v_tz)
    || ' con ' || (select nombre from profesionales where id = ci.profesional_id) || '. Le llega el aviso del cambio.');
end;
$$;

-- Confirmar admite cambios en lo editable (el texto de una nota, ya revisado). Las órdenes nuevas se ejecutan aquí con
-- las mismas funciones que la aplicación; el resto, como antes.
alter function voz_confirmar(uuid, bigint) rename to _voz_confirmar_fase5;
create function voz_confirmar(p_clinica uuid, p_orden bigint, p_cambios jsonb default null) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare m miembros := _miembro(p_clinica); o ordenes_voz; r jsonb; d jsonb;
begin
  select * into o from ordenes_voz where id = p_orden and clinica_id = p_clinica and miembro_id = m.id for update;
  if o.id is null then return jsonb_build_object('ok', false, 'motivo', 'orden_no_existe'); end if;
  if o.accion not in ('cambiar_cita', 'anadir_nota', 'cambiar_servicio') then return _voz_confirmar_fase5(p_clinica, p_orden); end if;
  if o.estado = 'ejecutada' then return jsonb_build_object('ok', true, 'repetida', true, 'resultado', o.resultado); end if;
  if o.estado <> 'propuesta' then return jsonb_build_object('ok', false, 'motivo', 'orden_ya_resuelta'); end if;
  d := o.datos;
  if o.accion = 'anadir_nota' and nullif(trim(coalesce(p_cambios->>'nota', '')), '') is not null then
    d := d || jsonb_build_object('nota', left(trim(p_cambios->>'nota'), 5000));
  end if;
  begin
    r := case o.accion
      when 'cambiar_cita' then cambiar_cita(p_clinica, (d->>'cita_id')::bigint,
                                 jsonb_build_object('inicio', d->>'inicio', 'profesional_id', d->'profesional_id'))
      when 'anadir_nota' then anadir_nota(p_clinica, jsonb_build_object('paciente_id', d->'paciente_id', 'texto', d->>'nota'))
      when 'cambiar_servicio' then guardar_servicio(p_clinica, jsonb_strip_nulls(jsonb_build_object('id', d->'servicio_id',
                                     'precio', d->>'precio', 'duracion_min', d->'duracion_min', 'activo', d->'activo')))
    end;
  exception when insufficient_privilege then
    r := jsonb_build_object('ok', false, 'motivo', 'sin_permiso');
  end;
  if r is null then r := jsonb_build_object('ok', false, 'motivo', 'orden_no_entendida'); end if;
  -- Lo clínico no se queda en la orden: la nota está ya en la ficha (o no se ha guardado).
  update ordenes_voz set estado = case when coalesce((r->>'ok')::boolean, false) then 'ejecutada' else 'fallida' end,
    datos = d - 'nota', texto = case when o.accion = 'anadir_nota' then null else texto end,
    resultado = jsonb_build_object('ok', r->'ok', 'motivo', r->'motivo'), resuelta_en = now()
  where id = o.id;
  perform _auditar(p_clinica, 'voz_ejecutar', 'orden_voz', o.id::text, o.paciente_id, jsonb_build_object('accion', o.accion, 'ok', r->'ok'));
  return jsonb_build_object('ok', coalesce((r->>'ok')::boolean, false), 'motivo', r->'motivo', 'orden_id', o.id,
                            'accion', o.accion, 'paciente_id', o.paciente_id, 'resumen', o.resumen);
end;
$$;

-- Descartar una nota tampoco deja su texto guardado.
alter function voz_descartar(uuid, bigint) rename to _voz_descartar_fase5;
create function voz_descartar(p_clinica uuid, p_orden bigint) returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare m miembros := _miembro(p_clinica); r jsonb := _voz_descartar_fase5(p_clinica, p_orden);
begin
  update ordenes_voz set datos = datos - 'nota', texto = null
  where id = p_orden and clinica_id = p_clinica and miembro_id = m.id and accion = 'anadir_nota';
  return r;
end;
$$;

-- La propuesta de una nota devuelve su texto (para revisarlo) solo a quien la dictó.
alter function _voz_respuesta(bigint, jsonb) rename to _voz_respuesta_fase5;
create function _voz_respuesta(p_orden bigint, p jsonb) returns jsonb
language sql stable security definer set search_path = nutricion, extensions, pg_temp as $$
  select _voz_respuesta_fase5(p_orden, p) || case when p ? 'editable' then jsonb_build_object('editable', p->'editable') else '{}'::jsonb end
$$;

