-- =====================================================================
-- Corvex Nutrición · ajustes de los canales tras probar los asistentes con la IA real
--
--  * canal_huecos: la franja (mañana / tarde) se aplicaba después de limitar los huecos por día, así que en un día
--    con la mañana libre no llegaba ningún hueco de tarde y el asistente decía que «por la tarde no hay nada».
--    Ahora se filtra la franja primero y después se reparten hasta 6 por día y 8 en total, como antes.
--  * canal_cambiar: devuelve también la fecha de antes, para que el asistente confirme el cambio («de… a…») sin
--    confundirse al ver la cita ya en su hora nueva.
-- =====================================================================

set search_path = nutricion, extensions, public;

alter function canal_huecos(bigint, bigint, text, int, bigint, text, text) rename to _canal_huecos_fase6;
create function canal_huecos(p_conversacion bigint, p_servicio bigint, p_desde text default null, p_dias int default 7,
                             p_profesional bigint default null, p_modalidad text default null,
                             p_franja text default 'cualquiera') returns jsonb
language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare v conversaciones := _conv(p_conversacion); c clinicas; s servicios; v_desde date; v_mod text; v_pref bigint;
        v_franja text := coalesce(nullif(p_franja, ''), 'cualquiera');
begin
  -- Las comprobaciones de siempre (servicio, aprobación previa, modalidad) las hace la versión anterior; si no hay
  -- franja, todo queda igual.
  if v_franja = 'cualquiera' then
    return _canal_huecos_fase6(p_conversacion, p_servicio, p_desde, p_dias, p_profesional, p_modalidad, p_franja);
  end if;
  select * into c from clinicas where id = v.clinica_id;
  select * into s from servicios where id = p_servicio and clinica_id = c.id and activo and reservable_canales;
  if s.id is null then return jsonb_build_object('ok', false, 'motivo', 'servicio_no_existe'); end if;
  if s.requiere_aprobacion then return jsonb_build_object('ok', false, 'motivo', 'requiere_aprobacion', 'servicio', s.nombre); end if;
  v_mod := coalesce(nullif(p_modalidad, ''), case when s.presencial then 'presencial' else 'online' end);
  if (v_mod = 'presencial' and not s.presencial) or (v_mod = 'online' and not s.online) then
    return jsonb_build_object('ok', false, 'motivo', 'modalidad_no_disponible');
  end if;
  v_desde := coalesce(nullif(p_desde, '')::date, _hoy(c.zona_horaria));
  select profesional_id into v_pref from pacientes where id = _verificado(v);
  return jsonb_build_object('ok', true, 'servicio', s.nombre, 'duracion_min', s.duracion_min, 'modalidad', v_mod, 'franja', v_franja,
    'huecos', (select coalesce(jsonb_agg(jsonb_build_object('inicio', _local(h.inicio, c.zona_horaria),
                  'fecha_texto', fecha_es(h.inicio, c.zona_horaria), 'profesional_id', h.profesional_id,
                  'profesional', h.profesional) order by h.inicio), '[]'::jsonb)
               from (select x.* from (
                       select h0.*, row_number() over (partition by (h0.inicio at time zone c.zona_horaria)::date order by h0.inicio) n
                       from _huecos(c.id, s.id, nullif(p_profesional, 0), v_desde::timestamp at time zone c.zona_horaria,
                                    (v_desde + least(greatest(coalesce(p_dias, 7), 1), 30))::timestamp at time zone c.zona_horaria,
                                    v_mod, v_pref, 200, 100, true) h0
                       where (v_franja = 'manana' and (h0.inicio at time zone c.zona_horaria)::time < '14:00')
                          or (v_franja = 'tarde' and (h0.inicio at time zone c.zona_horaria)::time >= '14:00')) x
                     where x.n <= 6 order by x.inicio limit 8) h));
end;
$$;

alter function canal_cambiar(bigint, bigint, text, bigint) rename to _canal_cambiar_fase3;
create function canal_cambiar(p_conversacion bigint, p_cita bigint, p_inicio text, p_profesional bigint default null)
returns jsonb language plpgsql security definer set search_path = nutricion, extensions, pg_temp as $$
declare v conversaciones := _conv(p_conversacion); v_antes timestamptz; r jsonb;
begin
  select inicio into v_antes from citas where id = p_cita and clinica_id = v.clinica_id;
  r := _canal_cambiar_fase3(p_conversacion, p_cita, p_inicio, p_profesional);
  if coalesce((r->>'ok')::boolean, false) and v_antes is not null then
    r := r || jsonb_build_object('antes', fecha_es(v_antes, _tz(v.clinica_id)), 'ahora', r->'cita'->>'fecha_texto');
  end if;
  return r;
end;
$$;

select _aplicar_permisos();

do $$
declare f record;
begin
  for f in
    select p.oid::regprocedure as firma from pg_proc p join pg_namespace n on n.oid = p.pronamespace
    where n.nspname = 'nutricion' and p.prokind = 'f'
      and (p.proconfig is null or not exists (select 1 from unnest(p.proconfig) c where c like 'search_path=%'))
  loop
    execute format('alter function %s set search_path = nutricion, extensions, pg_temp', f.firma);
  end loop;
end;
$$;


