INSERT INTO nutricion.servicios (id, clinica_id, nombre, descripcion, tipo, especialidad, duracion_min, precio_centimos, presencial, online, reservable_canales, activo, orden, categoria, incluye, preparacion, requiere_primera, requiere_aprobacion, condiciones_cancelacion, disponibilidad, preguntas, info_asistente, iva_tratamiento, actualizado_en) OVERRIDING SYSTEM VALUE VALUES (1, '07e8bd8c-9e82-4059-a4ff-b4c7a8596b7d', 'Primera consulta nutricional', 'Primera valoración completa: hábitos, objetivos y un plan de trabajo adaptado.', 'primera_visita', 'general', 60, 6500, true, false, true, true, 0, 'Consulta presencial', 'Entrevista sobre hábitos y salud, medidas básicas (peso, altura, cintura) y unas primeras pautas por escrito.', 'Trae, si las tienes, tus últimas analíticas y una lista de la medicación o suplementos que tomes. Te llegará un cuestionario previo por WhatsApp.', false, false, 'Se puede cambiar o cancelar sin coste hasta 24 horas antes.', 'De lunes a viernes, mañanas y tardes.', '[{"pregunta": "¿Tengo que ir en ayunas?", "respuesta": "No hace falta."}, {"pregunta": "¿Hacéis dietas cerradas?", "respuesta": "No: el plan se adapta a tus horarios y gustos."}]', 'Si la persona no sabe qué servicio reservar, es el punto de partida recomendado.', 'exento', '2026-10-22 17:08:03.287486+02');
INSERT INTO nutricion.servicios (id, clinica_id, nombre, descripcion, tipo, especialidad, duracion_min, precio_centimos, presencial, online, reservable_canales, activo, orden, categoria, incluye, preparacion, requiere_primera, requiere_aprobacion, condiciones_cancelacion, disponibilidad, preguntas, info_asistente, iva_tratamiento, actualizado_en) OVERRIDING SYSTEM VALUE VALUES (2, '07e8bd8c-9e82-4059-a4ff-b4c7a8596b7d', 'Consulta de seguimiento', 'Revisión de la evolución y ajuste de las pautas.', 'revision', NULL, 30, 3500, true, false, true, true, 1, 'Seguimiento', 'Revisión de cómo te ha ido, nuevas medidas y ajuste del plan.', 'Si puedes, anota durante la semana lo que te ha costado más.', true, false, 'Se puede cambiar o cancelar sin coste hasta 24 horas antes.', NULL, '[]', NULL, 'exento', '2026-10-22 17:08:03.300771+02');
INSERT INTO nutricion.servicios (id, clinica_id, nombre, descripcion, tipo, especialidad, duracion_min, precio_centimos, presencial, online, reservable_canales, activo, orden, categoria, incluye, preparacion, requiere_primera, requiere_aprobacion, condiciones_cancelacion, disponibilidad, preguntas, info_asistente, iva_tratamiento, actualizado_en) OVERRIDING SYSTEM VALUE VALUES (3, '07e8bd8c-9e82-4059-a4ff-b4c7a8596b7d', 'Primera consulta online', 'La primera consulta por videollamada, para quien no puede venir a la consulta.', 'primera_visita', NULL, 60, 6000, false, true, true, true, 2, 'Online', 'Lo mismo que la presencial salvo las medidas, que se toman en casa con una guía.', 'Ten a mano un metro de costura y una báscula si tienes. El enlace de la videollamada llega con la confirmación.', false, false, 'Se puede cambiar o cancelar sin coste hasta 24 horas antes.', NULL, '[]', NULL, 'exento', '2026-10-22 17:08:03.302894+02');
