INSERT INTO nutricion.formularios (id, clinica_id, nombre, descripcion, campos, version, activo, actualizado_en, envio, dias_antes, avisar_si_falta) OVERRIDING SYSTEM VALUE VALUES (1, '07e8bd8c-9e82-4059-a4ff-b4c7a8596b7d', 'Cuestionario de primera visita', 'Nos ayuda a preparar tu primera consulta. Responde lo que sepas; lo revisaremos juntos en la cita.', '[{"tipo": "texto_largo", "clave": "motivo", "destino": "motivo_consulta", "etiqueta": "¿Por qué quieres venir a consulta?", "obligatorio": true}, {"tipo": "texto_largo", "clave": "objetivos", "destino": "objetivos", "etiqueta": "¿Qué te gustaría conseguir?"}, {"tipo": "texto_largo", "clave": "antecedentes", "destino": "antecedentes", "etiqueta": "Enfermedades o problemas de salud que tengas o hayas tenido"}, {"tipo": "texto", "clave": "alergias", "destino": "alergias", "etiqueta": "Alergias alimentarias"}, {"tipo": "texto", "clave": "intolerancias", "destino": "intolerancias", "etiqueta": "Intolerancias"}, {"tipo": "texto", "clave": "medicacion", "destino": "medicacion", "etiqueta": "Medicación que tomas"}, {"tipo": "texto", "clave": "suplementos", "destino": "suplementos", "etiqueta": "Suplementos que tomas"}, {"tipo": "opcion", "clave": "actividad", "destino": "actividad_fisica", "etiqueta": "Actividad física", "opciones": ["Casi ninguna", "Ligera (1-2 días)", "Moderada (3-4 días)", "Alta (5 o más días)"]}, {"max": 10, "min": 1, "tipo": "numero", "clave": "comidas", "destino": "extra", "etiqueta": "¿Cuántas comidas haces al día?"}, {"tipo": "texto_largo", "clave": "habitos", "destino": "habitos_alimentarios", "etiqueta": "Cuéntanos un día normal de comidas"}, {"max": 350, "min": 20, "tipo": "numero", "ayuda": "Si no lo sabes, déjalo en blanco: te pesaremos en consulta.", "clave": "peso", "unidad": "kg", "destino": "extra", "etiqueta": "Peso aproximado"}, {"max": 250, "min": 100, "tipo": "numero", "clave": "altura", "unidad": "cm", "destino": "extra", "etiqueta": "Altura"}]', 1, true, '2026-10-22 17:08:03.325778+02', 'al_reservar', 3, true);
INSERT INTO nutricion.formularios (id, clinica_id, nombre, descripcion, campos, version, activo, actualizado_en, envio, dias_antes, avisar_si_falta) OVERRIDING SYSTEM VALUE VALUES (2, '07e8bd8c-9e82-4059-a4ff-b4c7a8596b7d', 'Antes de tu revisión', 'Unas preguntas para preparar la revisión. Lo que no sepas, déjalo en blanco y lo vemos en consulta.', '[{"tipo": "texto_largo", "clave": "evolucion", "etiqueta": "¿Cómo te has encontrado desde la última consulta?", "importante": true}, {"tipo": "texto_largo", "clave": "dificultades", "etiqueta": "¿Qué te ha costado más seguir?"}, {"tipo": "texto_largo", "clave": "cambios", "etiqueta": "¿Qué cambios de hábitos has conseguido mantener?"}, {"tipo": "texto_largo", "clave": "preguntas", "etiqueta": "¿Qué quieres preguntar en la consulta?"}, {"max": 350, "min": 20, "tipo": "numero", "ayuda": "Solo si te pesas en casa.", "clave": "peso", "unidad": "kg", "destino": "medicion:peso", "etiqueta": "Tu peso de esta semana", "importante": true}, {"max": 250, "min": 30, "tipo": "numero", "ayuda": "Si te lo has medido.", "clave": "cintura", "unidad": "cm", "destino": "medicion:cintura", "etiqueta": "Perímetro de cintura"}]', 1, true, '2026-10-22 17:08:03.328336+02', 'antes_de_cada_cita', 3, true);


