-- Data for Name: plantillas_mensaje; Type: TABLE DATA; Schema: nutricion; Owner: postgres
--

ALTER TABLE nutricion.plantillas_mensaje DISABLE TRIGGER ALL;

INSERT INTO nutricion.plantillas_mensaje (clinica_id, clave, texto, activa, plantilla_meta) VALUES ('07e8bd8c-9e82-4059-a4ff-b4c7a8596b7d', 'confirmacion_cita', 'Hola {paciente}, tu cita en {clinica} queda reservada: {servicio} el {fecha} con {profesional}{lugar}. Si necesitas cambiarla, responde a este mensaje.', true, NULL);
INSERT INTO nutricion.plantillas_mensaje (clinica_id, clave, texto, activa, plantilla_meta) VALUES ('07e8bd8c-9e82-4059-a4ff-b4c7a8596b7d', 'recordatorio_cita', 'Hola {paciente}, te recordamos tu cita de {servicio} el {fecha} con {profesional}{lugar}. ¿Nos confirmas que vienes? Responde SÍ, o escríbenos si necesitas cambiarla.', true, NULL);
INSERT INTO nutricion.plantillas_mensaje (clinica_id, clave, texto, activa, plantilla_meta) VALUES ('07e8bd8c-9e82-4059-a4ff-b4c7a8596b7d', 'cambio_cita', 'Hola {paciente}, tu cita ha cambiado: {servicio} el {fecha} con {profesional}{lugar}.', true, NULL);
INSERT INTO nutricion.plantillas_mensaje (clinica_id, clave, texto, activa, plantilla_meta) VALUES ('07e8bd8c-9e82-4059-a4ff-b4c7a8596b7d', 'cancelacion_cita', 'Hola {paciente}, tu cita de {servicio} del {fecha} está cancelada. Si quieres otra, escríbenos por aquí.', true, NULL);
INSERT INTO nutricion.plantillas_mensaje (clinica_id, clave, texto, activa, plantilla_meta) VALUES ('07e8bd8c-9e82-4059-a4ff-b4c7a8596b7d', 'formulario_pendiente', 'Hola {paciente}, para preparar tu cita del {fecha} rellena este cuestionario: {enlace} . Te pedirá {comprobacion} para comprobar que eres tú.', true, NULL);
INSERT INTO nutricion.plantillas_mensaje (clinica_id, clave, texto, activa, plantilla_meta) VALUES ('07e8bd8c-9e82-4059-a4ff-b4c7a8596b7d', 'formulario_recordatorio', 'Hola {paciente}, aún no has rellenado el cuestionario para tu cita del {fecha}. Aquí lo tienes: {enlace} . Te pedirá {comprobacion}.', true, NULL);
INSERT INTO nutricion.plantillas_mensaje (clinica_id, clave, texto, activa, plantilla_meta) VALUES ('07e8bd8c-9e82-4059-a4ff-b4c7a8596b7d', 'oferta_lista_espera', 'Hola {paciente}, se ha quedado libre un hueco de {servicio} el {fecha} con {profesional}. ¿Lo quieres? Responde SÍ antes de las {caduca} y te lo reservo.', true, NULL);
INSERT INTO nutricion.plantillas_mensaje (clinica_id, clave, texto, activa, plantilla_meta) VALUES ('07e8bd8c-9e82-4059-a4ff-b4c7a8596b7d', 'aviso_equipo', 'Tienes una solicitud nueva en {clinica}: {tipo}. Mírala en la aplicación.', true, NULL);
INSERT INTO nutricion.plantillas_mensaje (clinica_id, clave, texto, activa, plantilla_meta) VALUES ('07e8bd8c-9e82-4059-a4ff-b4c7a8596b7d', 'mensaje_equipo', '{texto}', true, NULL);
INSERT INTO nutricion.plantillas_mensaje (clinica_id, clave, texto, activa, plantilla_meta) VALUES ('07e8bd8c-9e82-4059-a4ff-b4c7a8596b7d', 'recordatorio_seguimiento', 'Hola {paciente}, {profesional} quiere verte para tu {servicio} entre el {desde} y el {hasta}. ¿Te busco hora? Contesta a este mensaje y te paso los huecos libres.', true, NULL);
INSERT INTO nutricion.plantillas_mensaje (clinica_id, clave, texto, activa, plantilla_meta) VALUES ('07e8bd8c-9e82-4059-a4ff-b4c7a8596b7d', 'propuesta_sesiones', 'Hola {paciente}, para "{programa}" te proponemos estas citas:
{fechas}
¿Te vienen bien? Responde SÍ y las reservamos todas, o dinos cuál quieres cambiar.', true, NULL);
INSERT INTO nutricion.plantillas_mensaje (clinica_id, clave, texto, activa, plantilla_meta) VALUES ('07e8bd8c-9e82-4059-a4ff-b4c7a8596b7d', 'confirmacion_sesiones', 'Hola {paciente}, quedan reservadas tus citas de "{programa}":
{fechas}
Si necesitas cambiar alguna, responde a este mensaje.', true, NULL);
INSERT INTO nutricion.plantillas_mensaje (clinica_id, clave, texto, activa, plantilla_meta) VALUES ('07e8bd8c-9e82-4059-a4ff-b4c7a8596b7d', 'plan_entregado', 'Hola {paciente}, {profesional} te ha preparado tu plan "{texto}". Puedes verlo aquí: {enlace} . Te pedirá {comprobacion} para comprobar que eres tú.', true, NULL);
INSERT INTO nutricion.plantillas_mensaje (clinica_id, clave, texto, activa, plantilla_meta) VALUES ('07e8bd8c-9e82-4059-a4ff-b4c7a8596b7d', 'documento_pendiente', 'Hola {paciente}, {clinica} te envía "{texto}" para que lo leas{tipo}: {enlace} . Te pedirá {comprobacion} para comprobar que eres tú.', true, NULL);
INSERT INTO nutricion.plantillas_mensaje (clinica_id, clave, texto, activa, plantilla_meta) VALUES ('07e8bd8c-9e82-4059-a4ff-b4c7a8596b7d', 'documento_recordatorio', 'Hola {paciente}, tienes pendiente leer{tipo} "{texto}". Aquí lo tienes: {enlace} . Te pedirá {comprobacion}.', true, NULL);
INSERT INTO nutricion.plantillas_mensaje (clinica_id, clave, texto, activa, plantilla_meta) VALUES ('07e8bd8c-9e82-4059-a4ff-b4c7a8596b7d', 'enlace_pago', 'Hola {paciente}, aquí tienes el enlace para pagar "{texto}" ({importe}) de forma segura: {url_pago} . El pago se hace en la página de nuestro proveedor; {clinica} no ve los datos de tu tarjeta.', true, NULL);


ALTER TABLE nutricion.plantillas_mensaje ENABLE TRIGGER ALL;

